INSERT INTO `campuses` (`id`, `organisation_id`, `campus_name`, `slug`, `campus_type`, `established_year`, `city`, `state`, `country`, `pincode`, `full_address`, `google_map_url`, `nearest_transport_hub`, `campus_area_acres`, `campus_area_unit`, `academic_blocks_count`, `classrooms_count`, `smart_classrooms`, `laboratories_count`, `library_available`, `library_books_count`, `digital_library_access`, `research_centers_count`, `hostel_available`, `hostel_type`, `hostel_capacity`, `food_facility`, `medical_facility_available`, `sports_facilities`, `transport_available`, `bus_routes_count`, `bus_routes`, `parking_available`, `cctv_coverage`, `security_staff_count`, `fire_safety_certified`, `disaster_management_plan`, `campus_contact_numbers`, `campus_email`, `campus_website`, `verification_status`, `status`, `exams_prepared_for`, `target_classes`, `about_institute`, `last_updated_on`, `created_at`, `updated_at`, `deleted_at`, `ownership_model`, `franchise_partner_name`, `franchise_start_year`, `brand_compliance_verified`, `nearest_landmark`, `science_labs_available`, `computer_labs_available`, `playground_available`, `bus_fleet_size`, `gps_enabled_buses`, `brand_type`, `visitor_management_system`, `class_profile`, `facilities`) VALUES
('bab4483e-6161-460f-be1a-3abfe5752de8', 83, 'SRM University', 'srm-university-2ooj', 'Main', '1985', 'Gangtok', 'sikkim', 'India', '737 102', 'SRM University Sikkim 5th Mile, Tadong Gangtok -737 102 , East Sikkim', NULL, NULL, 250.00, 'Acres', 0, 0, 1, 0, 0, 0, 0, 0, 0, NULL, 0, NULL, 0, NULL, 1, 0, '[null]', 0, 1, 0, 0, 0, '\"+91 44 27417000, +91 44 27417777\"', 'infodesk@srmist.edu.in', NULL, 0, 1, NULL, NULL, '<p data-start=\"18\" data-end=\"635\">The <strong data-start=\"22\" data-end=\"47\">SRM University campus</strong> offers a dynamic and future-focused learning environment designed to support academic excellence, innovation, research, and overall student development. Spread across a vast and well-planned campus, the university provides modern infrastructure that combines advanced technology with world-class educational facilities. From smart classrooms and specialized laboratories to research centers and collaborative learning spaces, every aspect of the campus is designed to enhance the student learning experience and prepare graduates for successful careers in a competitive global landscape.</p>\r\n<p data-start=\"637\" data-end=\"1143\">The campus features a comprehensive range of academic and student support facilities, including a well-equipped central library, innovation and entrepreneurship centers, high-speed digital resources, computer labs, seminar halls, auditoriums, and industry-oriented research facilities. Students have access to practical learning opportunities, interdisciplinary projects, workshops, guest lectures, and industry interactions that help bridge the gap between classroom education and real-world applications.</p>\r\n<p data-start=\"1145\" data-end=\"1658\">Beyond academics, SRM University promotes a vibrant campus life through sports complexes, fitness centers, cultural clubs, student organizations, recreational spaces, and various extracurricular activities. The university regularly hosts technical festivals, cultural events, leadership programs, competitions, and international collaborations that encourage creativity, teamwork, leadership, and personal growth. These opportunities help students develop both professional competencies and essential life skills.</p>\r\n<p data-start=\"1660\" data-end=\"2179\">The residential facilities at SRM University are designed to provide a safe, comfortable, and inclusive environment for students from across India and around the world. Modern hostels, dining facilities, healthcare services, transportation support, and campus security contribute to a student-friendly atmosphere where learners can focus on their academic and personal development. The diverse student community further enriches campus life by fostering cultural exchange, global perspectives, and lifelong connections.</p>\r\n<p data-start=\"2181\" data-end=\"2736\" data-is-last-node=\"\" data-is-only-node=\"\">With its strong emphasis on innovation, research, industry engagement, and holistic development, the SRM University campus serves as more than just a place of learning. It is an ecosystem where students gain knowledge, build professional networks, develop leadership qualities, and prepare themselves to become skilled professionals and responsible global citizens. This combination of academic excellence, modern infrastructure, and vibrant student life makes the SRM University campus one of the most sought-after higher education destinations in India.</p>', '2026-04-24 12:54:18', '2026-04-24 07:24:18', '2026-06-21 03:52:29', NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, NULL, 0, '[{\"year\":\"2025\",\"total_students\":null,\"total_faculty\":null,\"total_male_students\":null,\"total_female_students\":null,\"total_outside_state\":null}]', '[\"96fd453e-51c1-4cd7-8895-f923463908c3\",\"8e446392-3a73-4c80-a81a-e640a3804847\",\"63c7d429-a553-4965-9f01-5ec7f36da71e\",\"04d613a1-3db6-4eeb-90dd-c7cdf834b45f\",\"186d252b-2c01-4f4b-a3e3-3ed5653b0ea3\",\"9844a1cd-8d0e-44b0-be83-3094b4c31319\",\"7870bf92-24e4-4fc9-b4f0-6d8d780809e1\",\"b520d97d-8cf9-495a-b8e2-0ecd000578d4\",\"d7872157-54b6-4ab2-a183-391991e9a598\",\"1a1416cc-4474-4687-b870-0ae09cee9e6a\",\"c7cf7e57-ab50-4178-85ea-d47d1a696432\",\"4d3310db-54c3-4c5f-b35c-e42a3ec40af5\",\"8f12fd56-6df8-4935-a963-e9b07ab995ae\",\"074d8dab-6fd9-4a55-a5f1-f9ad4d53d413\",\"dd48d1b1-47c9-40ff-b84c-42fb509c0433\",\"8733a3c8-46ef-4e6a-b794-29cfbaa7f463\"]'),
('bacfdf6a-2ecf-4c2d-b585-1616765b934a', 93, 'CHRIST', 'christ-eesd', 'Main', '1969', 'Bengaluru', 'Karnataka', 'India', '560029', 'Dharmaram College Post, Hosur Road, Near Dairy Circle, Bengaluru, Karnataka 560029, India', 'https://maps.google.com/?q=Christ+University+Bangalore+Central+Campus', NULL, 25.00, 'Acres', 0, 0, 1, 0, 0, 0, 0, 0, 0, NULL, 0, NULL, 0, NULL, 1, 0, NULL, 0, 1, 0, 0, 0, '\"+91 8040129100, +91 8040129600, +91 8040129000\"', 'admissions@christuniversity.in', 'https://christuniversity.in', 0, 1, NULL, NULL, NULL, '2026-06-22 05:30:00', '2026-06-22 00:00:00', '2026-06-22 00:14:19', NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 'Independent', 0, '[{\"year\":\"2025\",\"total_students\":\"29169\",\"total_faculty\":\"1735\",\"total_male_students\":\"13368\",\"total_female_students\":\"15801\",\"total_outside_state\":\"22475\"}]', '[\"96fd453e-51c1-4cd7-8895-f923463908c3\",\"8e446392-3a73-4c80-a81a-e640a3804847\",\"63c7d429-a553-4965-9f01-5ec7f36da71e\",\"04d613a1-3db6-4eeb-90dd-c7cdf834b45f\",\"186d252b-2c01-4f4b-a3e3-3ed5653b0ea3\",\"9844a1cd-8d0e-44b0-be83-3094b4c31319\",\"7870bf92-24e4-4fc9-b4f0-6d8d780809e1\",\"b520d97d-8cf9-495a-b8e2-0ecd000578d4\",\"d7872157-54b6-4ab2-a183-391991e9a598\",\"1a1416cc-4474-4687-b870-0ae09cee9e6a\",\"c7cf7e57-ab50-4178-85ea-d47d1a696432\",\"4d3310db-54c3-4c5f-b35c-e42a3ec40af5\",\"8f12fd56-6df8-4935-a963-e9b07ab995ae\",\"074d8dab-6fd9-4a55-a5f1-f9ad4d53d413\",\"dd48d1b1-47c9-40ff-b84c-42fb509c0433\",\"8733a3c8-46ef-4e6a-b794-29cfbaa7f463\"]'),
('cb1d0e55-4d52-4f8e-a95d-1e010c5143ea', 73, 'GLA University', 'gla-university-dvvt', 'Main', '2010', 'Mathura', 'Uttar pradesh', 'India', '281 406', '17km Stone, NH-19,\r\nMathura-Delhi Road\r\nP.O. Chaumuhan,\r\nMathura-281 406 (U.P.)\r\nIndia', NULL, NULL, 110.00, 'Acres', 0, 0, 0, 0, 0, 0, 0, 0, 0, NULL, 0, NULL, 0, NULL, 1, 0, '[null]', 0, 1, 0, 0, 0, '\"9027068068, 9027068069, 5662297000\"', 'info@gla.ac.in', NULL, 0, 1, NULL, NULL, '<p>GLA University is located in Mathura, Uttar Pradesh, and operates from a modern <strong data-start=\"98\" data-end=\"129\">110-acre residential campus</strong> designed to support academic excellence, research, innovation, and student development. The campus features smart classrooms, advanced laboratories, a central library, innovation and research centers, hostels, sports complexes, auditoriums, cafeterias, healthcare facilities, and high-speed internet connectivity. With a technology-enabled learning environment and industry-oriented infrastructure, the university provides students with opportunities for academics, research, entrepreneurship, cultural activities, and holistic growth within a vibrant campus community.</p>', '2026-05-07 12:43:44', '2026-05-07 07:13:44', '2026-06-22 01:30:13', NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 'Independent', 0, '[{\"year\":\"2025\",\"total_students\":null,\"total_faculty\":null,\"total_male_students\":null,\"total_female_students\":null,\"total_outside_state\":null}]', '[\"96fd453e-51c1-4cd7-8895-f923463908c3\",\"8e446392-3a73-4c80-a81a-e640a3804847\",\"63c7d429-a553-4965-9f01-5ec7f36da71e\",\"04d613a1-3db6-4eeb-90dd-c7cdf834b45f\",\"186d252b-2c01-4f4b-a3e3-3ed5653b0ea3\",\"9844a1cd-8d0e-44b0-be83-3094b4c31319\",\"7870bf92-24e4-4fc9-b4f0-6d8d780809e1\",\"b520d97d-8cf9-495a-b8e2-0ecd000578d4\",\"d7872157-54b6-4ab2-a183-391991e9a598\",\"1a1416cc-4474-4687-b870-0ae09cee9e6a\",\"c7cf7e57-ab50-4178-85ea-d47d1a696432\",\"4d3310db-54c3-4c5f-b35c-e42a3ec40af5\",\"8f12fd56-6df8-4935-a963-e9b07ab995ae\",\"074d8dab-6fd9-4a55-a5f1-f9ad4d53d413\",\"dd48d1b1-47c9-40ff-b84c-42fb509c0433\",\"8733a3c8-46ef-4e6a-b794-29cfbaa7f463\"]'),
('cdb58585-8964-437a-ac11-333f9095f63e', 71, 'Jain University', 'jain-university-8cic', 'Main', '2009', 'Bengaluru', 'Karnataka', 'India', '560069', '#44/4, District Fund Road, behind Big Bazaar, Jayanagar 9th Block, Bengaluru, Karnataka, 560069.', NULL, NULL, 305.00, 'Acres', 0, 0, 1, 0, 0, 0, 0, 0, 0, NULL, 0, NULL, 0, NULL, 1, 0, '[null]', 0, 1, 0, 0, 0, '\"080-46840400, 080-46501738, 080-46650100\"', 'info@jainuniversity.ac.in', NULL, 0, 1, NULL, NULL, '<div class=\"qMYqUG_convSearchResultHighlightRoot\">\r\n<div class=\"\" data-turn-id-container=\"request-WEB:56a471cd-1069-46ac-958f-0071cd01bf72-29\" data-is-intersecting=\"true\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:56a471cd-1069-46ac-958f-0071cd01bf72-29\" data-turn-id-container=\"request-WEB:56a471cd-1069-46ac-958f-0071cd01bf72-29\" data-testid=\"conversation-turn-10\" data-scroll-anchor=\"false\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" data-conversation-screenshot-content=\"\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"d07aea30-5f40-424f-ab4a-b2ee57a44738\" data-message-model-slug=\"gpt-5-5\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\">\r\n<p data-start=\"18\" data-end=\"729\" data-is-last-node=\"\" data-is-only-node=\"\">JAIN (Deemed-to-be University) offers a vibrant and modern academic environment across multiple campuses in Bengaluru. The university is equipped with smart classrooms, advanced laboratories, innovation and research centers, digital libraries, sports facilities, auditoriums, and collaborative learning spaces. Designed to support academic excellence and holistic development, the campuses provide students with opportunities for research, entrepreneurship, industry interaction, cultural activities, and extracurricular engagement. Its strategic location in Bengaluru, India\'s leading technology and startup hub, enables students to benefit from strong industry exposure, internships, and career opportunities.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n<div class=\"mt-3 w-full empty:hidden\">\r\n<div class=\"text-center\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n</div>\r\n<div class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\" aria-hidden=\"true\">&nbsp;</div>', '2026-05-04 11:45:03', '2026-05-04 06:15:03', '2026-06-22 01:26:38', NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 'Independent', 0, '[{\"year\":\"2025\",\"total_students\":\"12698\",\"total_faculty\":\"1389\",\"total_male_students\":\"6927\",\"total_female_students\":\"577