(3, 1, NULL, 'Olympiad / talent', 'olympiad-talent', NULL, 'NTSE • NSO • IMO • KVPY', NULL, '{\"alert_message\":\"Here is a complete roadmap to pursue a career in Olympiad \\/ talent. Early preparation and consistency will give you the best chance of success.\"}', 1, '2026-06-19 23:41:50', '2026-06-20 00:00:11'),
(4, 1, NULL, 'Still exploring', 'still-exploring', NULL, 'Keep all options open', NULL, '{\"alert_message\":\"Here is a complete roadmap to pursue a career in Still exploring. Early preparation and consistency will give you the best chance of success.\"}', 1, '2026-06-19 23:41:50', '2026-06-20 00:00:11'),
