(354, 7, 353, 'JEE Main', 'jee-main', NULL, 'Educational Qualification  -  Passed or appearing in Class 12 (10+2)\r\nRequired Subjects (B.E./B.Tech.)  -  Physics and Mathematics (compulsory) with one of Chemistry/Biology/Biotechnology/Technical Vocational Subject\r\nAge Limit  -  No upper age limit (subject to institute-specific rules)\r\nNumber of Attempts  -  Candidates can appear in the year they pass Class 12 and the next two consecutive years\r\nNationality  -  Indian Citizens, NRIs, OCIs, PIOs and Foreign Nationals can apply\r\n\r\nNote: Individual institutes may have additional admission requirements', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"Fee -\"}', 1, '2026-06-26 01:59:17', '2026-06-26 02:29:17'),
(355, 7, 353, 'NEET UG', 'neet-ug', NULL, 'Educational Qualification  -  Passed or appearing in Class 12 (10+2)\r\nRequired Subjects  -  Physics, Chemistry, Biology/Biotechnology and English\r\nMinimum Age  -  17 years on or before 31 December of the admission year\r\nMaximum Age  -   No upper age limit\r\nNationality  -  Indian Citizens, NRIs, OCIs, PIOs and Foreign Nationals\r\nMinimum Qualifying Marks   -   General – 50%, General-PwBD – 45%, SC/ST/OBC-NCL – 40% (PCB aggregate in Class 12)', NULL, '{\"Badge\":\"Fee\"}', 1, '2026-06-26 02:00:19', '2026-06-26 02:31:20'),
(356, 7, 353, 'CUET UG', 'cuet-ug', NULL, 'Educational Qualification  -  Passed or appearing in Class 12 (10+2) from a recognized board\r\nAge Limit  - No age limit prescribed by NTA\r\nMinimum Percentage  -  No minimum marks fixed by NTA; participating universities may prescribe minimum qualifying marks\r\nNationality  -  Indian Citizens, NRIs, OCIs, PIOs and Foreign Nationals can apply\r\n\r\nNote: Every university may have its own eligibility requirements regarding Class 12 marks and subject combinations', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"Fee -  General (UR)  -  \\u20b91,000\\r\\nOBC-NCL \\/ EWS  -  \\u20b9900\\r\\nSC \\/ ST \\/ PwBD \\/ Third Gender  -  \\u20b9800\"}', 1, '2026-06-26 02:04:00', '2026-06-26 02:34:21'),
(357, 7, 353, 'NDA', 'nda', NULL, 'Educational Qualification (Army Wing)  -  Passed or appearing in Class 12 (10+2) from a recognized board\r\nEducational Qualification (Air Force & Navy)   -   Passed or appearing in Class 12 with Physics and Mathematics\r\nAge Limit  -  Generally 16.5 to 19.5 years (exact date of birth range is specified in each UPSC notification)\r\nGender  -  Male and Female candidates\r\nMarital Status  -  Unmarried candidates only\r\nNationality  -  Indian Citizens, certain categories of Nepalese/Bhutanese citizens, and other eligible categories specified by UPSC', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"Fee -  General \\/ OBC \\/ EWS -  \\u20b9100\\r\\nSC \\/ ST  -  No Fee\\r\\nFemale Candidates -  No Fee\"}', 1, '2026-06-26 02:05:01', '2026-06-26 02:38:00'),
(358, 7, 353, 'CLAT UG', 'clat-ug', NULL, 'Educational Qualification  -  Passed or appearing in Class 12 (10+2) or equivalent from a recognized board\r\nMinimum Marks  -  General/OBC/PwD/NRI/OCI/PIO: 45% marks; SC/ST: 40% marks\r\nAge Limit	  -  No upper age limit\r\nNationality   -   Indian Citizens, NRIs, OCIs, PIOs and Foreign Nationals (subject to admission policies)', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"Fee - General \\/ OBC \\/ PWD \\/ NRI \\/ PIO \\/ OCI  -  \\u20b94,000\\r\\nSC \\/ ST \\/ BPL  -   \\u20b93,500\"}', 1, '2026-06-26 02:06:52', '2026-06-26 02:41:03'),
