(361, 7, 360, 'International English Language Testing System (IELTS)', 'international-english-language-testing-system-ielts', NULL, 'Minimum Qualification	No minimum educational qualification\r\nMinimum Age	No official age limit (16+ years is generally recommended)\r\nNationality	Open to all nationalities\r\nNumber of Attempts	Unlimited\r\nExam Mode\r\n\r\nCandidates can choose:\r\n\r\nComputer-delivered IELTS\r\nPaper-based IELTS\r\n\r\nThe Speaking test is conducted face-to-face with a certified examiner.', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"\\u20b919,000\"}', 1, '2026-06-26 02:43:57', '2026-06-26 07:11:46'),
(362, 7, 360, 'Cambridge English Qualifications', 'cambridge-english-qualifications', NULL, 'Minimum Qualification - No minimum educational qualification\r\nMinimum Age -  No official age limit\r\nNationality  - Open to candidates worldwide\r\nAttempts  -   Unlimited', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"amount may differ\"}', 1, '2026-06-26 02:45:01', '2026-06-26 07:14:38'),
(363, 7, 360, 'Test of English as a Foreign Language (TOEFL iBT)', 'test-of-english-as-a-foreign-language-toefl-ibt', NULL, 'Minimum Qualification  -  No minimum educational qualification required\r\nMinimum Age  -  No official age limit (generally recommended for students aged 16 years or above)\r\nNationality  -  Open to candidates from all countries\r\nNumber of Attempts -  Unlimited \r\nPassport Requirement  -  A valid passport or other accepted ID is generally required for identification at the test centre', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"\\u20b918,000, including applicable GST.\"}', 1, '2026-06-26 02:45:43', '2026-06-26 07:17:06'),
(364, 7, 360, 'Scholastic Assessment Test (SAT)', 'scholastic-assessment-test-sat', NULL, 'Minimum Qualification -  No minimum educational qualification required\r\nRecommended Class  -  Class 11 or Class 12 students (or equivalent) planning for undergraduate admissions\r\nMinimum Age  -  No official age limit\r\nNationality  -  Open to students of all nationalities\r\nNumber of Attempts  -  No limit on the number of attempts\r\nPassport/ID  -  A valid passport or other accepted identification is generally required for international test-takers', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"Total Fee (including applicable taxes)\\tUSD 130.98 (around \\u20b912,000\\u2013\\u20b912,500)\"}', 1, '2026-06-26 02:46:31', '2026-06-26 07:19:34'),
