(373, 7, 372, 'Khelo India Youth Games', 'khelo-india-youth-games-1', NULL, 'Nationality  - Indian citizens\r\nAge Categories - Under-17 and Under-21 (or as specified in the official notification for that edition/sport)\r\nQualificatio -  Selection through recognized school competitions, state championships, National Sports Federations, or other approved qualification pathways\r\nMedical Fitness  -  Must meet the required fitness standards', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"No direct registration fee for athletes\"}', 1, '2026-06-26 02:59:28', '2026-06-26 07:32:00'),
(374, 7, 372, 'School Games Federation of India (SGFI) Championships', 'school-games-federation-of-india-sgfi-championships', NULL, 'Educational Qualification  - Must be studying in a recognized school\r\nNationality  -  Indian citizens studying in eligible schools\r\nAge Categories  -  Under-14, Under-17, and Under-19 (age eligibility as per SGFI rules for the session)\r\nQualification  -  Selection through school, district, and state-level competitions', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"No direct fee\"}', 1, '2026-06-26 03:00:26', '2026-06-26 07:35:48'),
(376, 7, 372, 'State School Sports Championships', 'state-school-sports-championships-1', NULL, 'Educational Qualification  -  Must be studying in a recognized school\r\nNationality  -  Indian citizen studying in the respective state\r\nAge Categories  - Usually Under-14, Under-17, and Under-19 (may vary by state)\r\nQualification -  Must qualify through school, block, district, or divisional competitions', NULL, '{\"Badge\":\"Fee\",\"Salary\":\"No direct fee for students\"}', 1, '2026-06-26 03:00:54', '2026-06-26 07:38:10'),
