(1, 1, 1, 'Purpose of AI', NULL, 1, 'approved', 1, 2, '2026-01-02 03:37:10', '2026-01-02 03:38:19'),
(2, 12, 2, 'is mba worth it ?', NULL, 0, 'approved', 1, 0, '2026-06-22 02:16:10', '2026-06-22 02:52:09'),
(3, 12, 1, 'How Is Artificial Intelligence Changing Career Opportunities?', NULL, 0, 'approved', 1, 0, '2026-06-22 02:51:38', '2026-06-22 02:52:02'),
(4, 12, 1, 'Is online learning as effective as offline classes?', NULL, 0, 'approved', 1, 0, '2026-06-22 04:02:34', '2026-06-22 04:03:56'),
(5, 12, 1, 'Is studying abroad really worth the money?', NULL, 0, 'approved', 1, 0, '2026-06-22 04:07:16', '2026-06-22 04:10:52'),
(6, 12, 1, 'Is using AI tools for studying making students less independent thinkers?', NULL, 0, 'approved', 1, 0, '2026-06-22 04:54:31', '2026-06-22 05:29:37'),
(7, 12, 1, 'Should I choose a high-paying career or one I\'m passionate about?', NULL, 0, 'approved', 1, 0, '2026-06-22 05:04:54', '2026-06-22 05:29:28'),
(8, 12, 1, 'Which skills should every student learn to stay relevant with AI?', NULL, 0, 'approved', 1, 0, '2026-06-22 05:24:33', '2026-06-22 05:29:45'),
(9, 12, 1, 'Is social media affecting student mental health more than we realize?', NULL, 0, 'approved', 1, 0, '2026-06-22 05:43:37', '2026-06-22 05:47:36'),
(10, 12, 1, 'Should every student be required to do an internship before graduating?', NULL, 0, 'approved', 1, 0, '2026-06-22 06:15:20', '2026-06-22 06:23:51'),
(11, 12, 1, 'Should online degrees be treated equally to traditional degrees by employers?', NULL, 0, 'approved', 1, 0, '2026-06-22 06:20:08', '2026-06-22 06:23:40');

