INSERT INTO `counsellings` (`id`, `exam_id`, `dynamic_exam_id`, `counselling_name`, `slug`, `counselling_type`, `counselling_mode`, `conducting_authority_name`, `conducting_authority_type`, `official_counselling_website`, `applicable_course_levels`, `applicable_quotas`, `applicable_categories`, `domicile_required`, `state_applicability`, `minimum_exam_qualification_required`, `minimum_score_or_rank_required`, `category_wise_eligibility`, `attempts_allowed`, `age_criteria_for_counselling`, `eligibility_notes`, `number_of_rounds`, `rounds`, `registration_process_steps`, `choice_filling_process`, `choice_locking_required`, `seat_allotment_process`, `reporting_process`, `document_verification_process`, `upgradation_rules`, `exit_and_refund_rules`, `counselling_year`, `registration_start_date`, `registration_end_date`, `choice_filling_start_date`, `choice_filling_end_date`, `seat_allotment_result_date`, `reporting_start_date`, `reporting_end_date`, `round_wise_schedule`, `important_dates`, `seat_allocation_basis`, `tie_breaking_rules`, `reservation_policy_reference`, `seat_matrix_source`, `seat_conversion_rules`, `documents_required`, `document_format_requirements`, `original_documents_required_at_reporting`, `participating_institutions_count`, `participating_institutions_note`, `institution_type_supported`, `helpdesk_contact_number`, `helpdesk_email`, `faq_url`, `grievance_redressal_process`, `official_notifications_urls`, `information_source`, `last_verified_on`, `data_confidence_score`, `disclaimer_text`, `meta_title`, `meta_description`, `focus_keywords`, `schema_type`, `canonical_url`, `indexing_status`, `status`, `visibility`, `created_by`, `last_updated_by`, `created_at`, `updated_at`, `deleted_at`, `registration_fee_required`, `registration_fee_structure`, `late_registration_allowed`, `late_fee_rules`, `security_deposit_required`, `partial_refund_allowed`, `security_deposit_structure`, `round_specific_fee_rules`, `refund_policy_summary`, `refund_timeline`, `refund_mode`, `forfeiture_scenarios`, `payment_modes_allowed`, `transaction_charges_applicable`, `transaction_charge_borne_by`, `payment_gateway_name`) VALUES
('18d18257-dc60-4158-ab3f-81c148d372a5', 19, NULL, 'XAT Counselling', 'xat-counselling-gwkrf9', 'Institute-Level', 'Online', 'XLRI – Xavier School of Management', 'University Body', 'https://xatonline.in/', '[\"PG\"]', '[\"All India Quota\",\"Institutional Quota\",\"NRI Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, 'Not Applicable (All India Level Process)', 1, 'Cutoffs vary by institute:  XLRI Jamshedpur: ~90–96+ percentile  Other institutes: ~70–90 percentile  👉 Final selection depends on shortlist + GD/PI performance', NULL, 'No restriction', 'No age limit', '<ul><li>Bachelor’s degree (minimum 3 years) from a recognized university</li><li>Final-year students can apply</li><li>Percentage criteria may vary by institute</li><li>Admission includes additional rounds (GD/PI/WAT) after shortlisting</li><li>Each participating institute applies its own eligibility + selection criteria</li></ul>', 3, '[{\"round_name\":\"Shortlisting\",\"round_type\":\"Regular\"},{\"round_name\":\"GD\\/PI\\/WAT\",\"round_type\":\"Regular\"},{\"round_name\":\"Final Selection\",\"round_type\":\"Regular\"}]', '[\"\\\"Appear for XAT exam conducted by XLRI\\\",\\r\\n  \\\"Check XAT result and download scorecard\\\",\\r\\n  \\\"Apply separately to participating institutes (e.g., XLRI, XIM, IMT, etc.)\\\",\\r\\n  \\\"Fill application form with academic and personal details\\\",\\r\\n  \\\"Upload required documents\\\",\\r\\n  \\\"Pay institute-specific application fee\\\",\\r\\n  \\\"Submit application and wait for shortlisting\\\"\"]', '<ul><li><strong>Not Applicable (No centralized choice filling)</strong></li><li>Candidates apply <strong>separately to each institute</strong></li><li>Course/branch preference is selected <strong>within individual institute forms</strong></li></ul>', 0, '<ul><li><strong>No centralized seat allotment</strong></li><li>Institutes shortlist candidates based on XAT score</li><li>Final selection after GD/PI/WAT</li><li>Offer letter issued by individual institute</li></ul>', '<ul><li>Accept admission offer within deadline</li><li>Pay admission/seat confirmation fee</li><li>Report to institute (online/offline as instructed)</li><li>Complete joining formalities</li></ul>', '<ul><li>Conducted by individual institutes during admission</li><li>Common documents:</li></ul><ol><li>XAT scorecard</li><li>Graduation marksheets &amp; certificates</li><li>ID proof</li><li>Category certificate (if applicable)</li><li>Work experience proof (if applicable)</li></ol>', '<ul><li><strong>Not Applicable</strong></li><li>No upgrade/sliding system</li><li>Once selected, candidate accepts/rejects offer</li></ul>', '<ul><li>Depends on institute policy (AICTE guidelines usually followed)</li><li>Key points:</li></ul><ol><li>Refund allowed within specified deadline</li><li>Deduction of processing fee (if applicable)</li><li>No refund after course commencement (in most cases)</li></ol>', '2026-03', '2025-12-10', '2026-01-10', NULL, NULL, NULL, NULL, NULL, '\"\\\"stage\\\": \\\"XAT Exam\\\",\\r\\n    \\\"date\\\": \\\"January 2026 (First Sunday)\\\"\\r\\n    \\\"stage\\\": \\\"Result Declaration\\\",\\r\\n    \\\"date\\\": \\\"Last week of January 2026\\\"\\r\\n    \\\"stage\\\": \\\"Institute Application Window\\\",\\r\\n    \\\"date\\\": \\\"December 2025 \\u2013 January\\/February 2026\\r\\n    \\\"stage\\\": \\\"Shortlisting for GD\\/PI\\\",\\r\\n    \\\"date\\\": \\\"February 2026\\\"\\r\\n    \\\"stage\\\": \\\"GD\\/PI\\/WAT Rounds\\\",\\r\\n    \\\"date\\\": \\\"February \\u2013 March 2026\\r\\n    \\\"stage\\\": \\\"Final Result by Institutes\\\",\\r\\n    \\\"date\\\": \\\"March \\u2013 April 2026\\r\\n    \\\"stage\\\": \\\"Admission & Reporting\\\",\\r\\n    \\\"date\\\": \\\"April \\u2013 June 2026\"', '{\"note\":\"<ul><li>XAT is typically conducted on the <strong>first Sunday of January<\\/strong><\\/li><li>No centralized counselling calendar exists<\\/li><li>Each institute releases <strong>its own admission schedule<\\/strong><\\/li><li>Dates may slightly vary every year<\\/li><\\/ul>\"}', 'Score', 'Common criteria used by top institutes:\r\nHigher XAT percentile/sectional scores\r\nBetter GD/PI performance\r\nHigher academic scores\r\nWork experience quality\r\nDiversity factors (gender/academic background)\r\nSeat Conversion Rules\r\nApplicable as per Institute Policies\r\nTypical patterns:\r\nUnfilled reserved seats → converted to General category (as per norms)\r\nCategory conversion follows government/AICTE guidelines (if applicable)\r\nSome private institutes may have flexible internal policies\r\nImportant Note\r\nNo centralized seat matrix or conversion system\r\nAll rules vary across institutes like XLRI Jamshedpur and others\r\nIf you want, I can next provide reservation policy (category-wise seats) or college-wise selection weightage.', NULL, NULL, '<ul><li><strong>Applicable as per Institute Policies</strong></li><li>Typical patterns:</li></ul><ol><li>Unfilled reserved seats → converted to General category (as per norms)</li><li>Category conversion follows <strong>government/AICTE guidelines (if applicable)</strong></li><li>Some private institutes may have flexible internal policies</li></ol>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul><li><strong>File Format:</strong><br>PDF / JPG / JPEG / PNG (as specified by institute)</li><li><strong>File Size:</strong><br>Typically <strong>50 KB – 500 KB</strong> per document <i>(may vary by institute)</i></li><li><strong>Image Resolution:</strong><br>Clear and legible (generally <strong>200–300 DPI</strong> recommended)</li><li><strong>Color Mode:</strong></li></ul><p>Color scan preferred for certificates</p><p>Passport photo: color with white/light background</p><ul><li><strong>File Naming Convention:</strong><br>Use simple names (e.g., Name_DocumentType.pdf)</li><li><strong>Scan Quality:</strong></li></ul><p>No blur, shadows, or cropping errors</p><p>All details (marks, signatures, seals) must be visible</p><ul><li><strong>Signature Upload:</strong></li></ul><p>Black/blue ink on white paper</p><p>Scanned clearly without distortion</p><ul><li><strong>Photograph Requirements:</strong></li></ul><p>Recent passport-size photo</p><p>Front-facing, no sunglasses/caps</p><p>Plain background</p>', 1, NULL, NULL, NULL, '+91-657-6653203 +91-657-6653204', 'admis@xlri.ac.in', NULL, '<ul><li>Visit the official XAT website (<a href=\"https://xatonline.in/\"><strong>https://xatonline.in/</strong></a>)</li><li>Use the <strong>Contact Us / Query Form</strong> section</li><li>Submit query with:</li></ul><ol><li>XAT ID</li><li>Registered Email ID</li><li>Issue details</li></ol><ul><li>For admission-related issues, contact <strong>respective institutes directly</strong></li><li>Follow up via email or helpline if no response within 2–3 working days</li></ul><h4>Important Note</h4><ul><li>XAT helpdesk handles <strong>exam-related queries only</strong></li><li>For counselling/admissions, each institute (e.g., XLRI Jamshedpur) has its <strong>own helpdesk system</strong></li><li>If you want, I can provide <strong>college-wise helpdesk contacts</strong> or <strong>official complaint portal links</strong>.</li></ul><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>', NULL, NULL, NULL, 100.00, NULL, 'XAT Counselling : Dates, Process, Fees, Eligibility & Top Colleges', 'Check complete details of XAT Counselling 2026 including registration dates, eligibility, fees, admission process, participating colleges, cutoff, and selection rounds. Conducted by XLRI, admissions are institute-level.', NULL, 'EducationalOccupationalProgram', 'https://www.yourwebsite.com/xat-counselling-2026', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-20 06:16:36', '2026-03-21 03:36:18', NULL, 1, '[{\"categories\":[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"],\"amount\":\"2100\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 1, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":\"500\",\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 1, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"Not applicable\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'XAT Exam Fee: Non-refundable\r\nInstitute Application Fees: Non-refundable\r\nAdmission Fee (after selection): Refundable as per institute rules (generally AICTE guidelines)', '15–30 working days', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple gateways (e.g., BillDesk / PayU / integrated banking gateways)'),
('5f3c2815-3589-4f83-b05d-5e705d23d3c4', 19, NULL, 'segdgd', 'segdgd-padrry', 'Centralised', 'Online', 'gdgd', 'Central Government', NULL, NULL, NULL, NULL, 0, NULL, 1, NULL, NULL, NULL, NULL, NULL, 1, '[{\"round_name\":null,\"round_type\":\"Regular\"}]', '[null]', NULL, 0, NULL, NULL, NULL, NULL, NULL, '2026-03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"note\":null}', 'Exam Rank', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100.00, NULL, NULL, NULL, NULL, 'EducationalOccupationalProgram', NULL, 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-21 03:35:14', '2026-03-21 03:35:22', '2026-03-21 03:35:22', 1, '[{\"categories\":[\"OBC\"],\"amount\":\"499\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"ttt\",\"fresh_registration_fee\":\"gvhgvg\",\"additional_security_deposit\":\"hbhjbh\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', NULL, NULL, 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', NULL, 0, 'Candidate', NULL),
('80ceff28-68a8-4f2d-ba40-c581132329bc', 18, NULL, 'CUET PG Counselling 2026', 'cuet-pg-counselling-2026-c1rlwm', 'Centralised', 'Online', 'National Testing Agency', 'Central Government', 'https://exams.nta.nic.in/cuet-pg', '[\"PG\",\"Diploma\"]', '[\"All India Quota\",\"Institutional Quota\",\"NRI Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'No Fixed Minimum (Varies by University & Course)', NULL, 'No Restriction', 'No Age Limit', '<ul><li>Candidate must have a <strong>Bachelor’s degree (or equivalent)</strong> from a recognized university</li><li>Final-year students are <strong>also eligible</strong> (subject to result submission)</li><li>Eligibility (marks %, subject requirements) <strong>varies by university &amp; course</strong></li><li>Admission is based on:<ul><li>CUET PG score</li><li>University-specific criteria (if any)</li></ul></li><li>Reservation policies follow <strong>Government of India norms</strong> in central universities</li></ul>', 5, '[{\"round_name\":\"Round 1\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"},{\"round_name\":\"Round 2\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 3\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Mop up round\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"},{\"round_name\":\"Spot round\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"}]', '[\"\\\"Visit the official website of the participating university\\\",\\r\\n  \\\"Register using CUET PG application number and personal details\\\",\\r\\n  \\\"Fill in academic and personal information\\\",\\r\\n  \\\"Upload required documents (photo, signature, certificates)\\\",\\r\\n  \\\"Pay the registration\\/application fee\\\",\\r\\n  \\\"Submit the form and download confirmation page\\\"\"]', '<ul><li>Log in to the university counselling portal</li><li>Select preferred <strong>courses and colleges (if applicable)</strong></li><li>Arrange choices in <strong>order of preference</strong></li><li>Lock choices before deadline</li><li>Modify choices within allowed period</li></ul>', 0, '<ul><li>Based on <strong>CUET PG score, rank, category, and preferences</strong></li><li>Universities release <strong>merit lists / allotment lists</strong></li><li>Candidates can:<ul><li>Accept seat</li><li>Opt for upgrade</li><li>Wait for next round</li></ul></li></ul>', '<ul><li>Based on <strong>CUET PG score, rank, category, and preferences</strong></li><li>Universities release <strong>merit lists / allotment lists</strong></li><li>Candidates can:<ul><li>Accept seat</li><li>Opt for upgrade</li><li>Wait for next round</li></ul></li></ul>', '<ul><li>CUET PG Scorecard</li><li>Graduation Marksheet/Degree</li><li>Class 10 &amp; 12 Certificates</li><li>Category Certificate (if applicable)</li><li>PwD Certificate (if applicable)</li><li>ID Proof (Aadhaar, etc.)</li><li>Passport-size photographs &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Verification is usually <strong>online first</strong>, then <strong>physical at institute (if required)</strong></li></ul>', '<ul><li>Candidates selecting <strong>“Upgrade”</strong> are considered in next rounds</li><li>Upgraded seat = <strong>previous seat automatically cancelled</strong></li><li>If no upgrade → <strong>previous seat retained</strong></li><li>Upgrade option may be <strong>limited to certain rounds</strong></li></ul>', '<ul><li>Candidates can <strong>withdraw before final admission deadline</strong></li><li>Refund policy:<ul><li><strong>Partial refund</strong> after deduction (varies by university)</li><li><strong>No refund</strong> after final round or seat confirmation deadline</li></ul></li><li>If seat allotted but not joined → <strong>fee may be forfeited</strong></li></ul>', '2026-03', '2026-05-15', '2026-06-10', '2026-05-18', '2026-06-12', '2026-06-20', '2026-06-22', '2026-07-31', '\"\\\"Round 1\\\": \\r\\n    \\\"result_date\\\": \\\"20-06-2026\\\",\\r\\n    \\\"reporting\\\": \\\"22-06-2026 to 27-06-2026\\\"\\r\\n  \\r\\n  \\\"Round 2\\\": \\r\\n    \\\"result_date\\\": \\\"30-06-2026\\\",\\r\\n    \\\"reporting\\\": \\\"01-07-2026 to 05-07-2026\\\"\\r\\n  \\r\\n  \\\"Round 3\\\": \\r\\n    \\\"result_date\\\": \\\"10-07-2026\\\",\\r\\n    \\\"reporting\\\": \\\"11-07-2026 to 15-07-2026\\\"\\r\\n  \\\"Mop-up Round\\\": \\r\\n    \\\"result_date\\\": \\\"20-07-2026\\\",\\r\\n    \\\"reporting\\\": \\\"21-07-2026 to 25-07-2026\\\"\\r\\n \\r\\n  \\\"Spot Round\\\": \\r\\n    \\\"result_date\\\": \\\"28-07-2026\\\",\\r\\n    \\\"reporting\\\": \\\"28-07-2026 to 31-07-2026\\\"\"', '{\"note\":\"<ul><li>Dates are <strong>tentative<\\/strong> and depend on:<ul><li>CUET PG result declaration<\\/li><li>Individual university schedules (DU, BHU, JNU, etc.)<\\/li><\\/ul><\\/li><li>Counselling usually starts <strong>within 1\\u20132 weeks after result<\\/strong><\\/li><li>Not all universities follow all rounds (mop-up\\/spot optional)<\\/li><li>Candidates must track <strong>separate university portals regularly<\\/strong><\\/li><\\/ul>\"}', 'Exam Rank', 'Higher CUET PG score in relevant subject\r\nHigher marks in qualifying degree (graduation)\r\nHigher marks in Class 12\r\nHigher marks in Class 10\r\nAge factor (older candidate preferred in some cases)', NULL, NULL, '<p><strong>Applicable as per Government of India reservation norms</strong></p><p>&nbsp;Common rules:</p><ul><li>If reserved category seats remain vacant:<ul><li><strong>SC/ST → General (last stage)</strong></li><li><strong>EWS/OBC → General (as per rules)</strong></li></ul></li><li><strong>PwD seats</strong> may be filled within same category first</li><li>Conversion happens <strong>only after all rounds are completed</strong></li><li>&nbsp;Note:</li><li>Exact conversion rules may differ slightly by university</li><li>Central universities follow <strong>strict reservation policy guidelines</strong></li></ul>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul><li><strong>File Format:</strong><br>JPG / JPEG / PNG / PDF</li><li><strong>File Size:</strong><ul><li>Images: <strong>10 KB – 200 KB</strong> (may vary)</li><li>PDFs (certificates/marksheets): <strong>100 KB – 1 MB</strong></li></ul></li><li><strong>Image Quality:</strong><ul><li>Clear, readable, and <strong>not blurred</strong></li><li>Proper lighting, no shadows</li></ul></li><li><strong>Scan Type:</strong><ul><li><strong>Color scanned copies preferred</strong></li><li>Avoid black &amp; white if details are unclear</li></ul></li><li><strong>Orientation:</strong><ul><li>Must be <strong>upright (not rotated)</strong></li><li>Full document visible (no cropping of edges)</li></ul></li><li><strong>File Naming Convention:</strong><ul><li>Use simple names (e.g., Name_DocumentType.pdf)</li><li>Avoid special characters</li></ul></li><li><strong>Signature &amp; Photo:</strong><ul><li>Recent passport-size photograph</li><li>Signature on white paper with dark ink</li><li>Must match details used in CUET PG application</li></ul></li><li><strong>Certificates:</strong><ul><li>Must be <strong>issued by competent authority</strong></li><li>Should be <strong>valid as per latest guidelines</strong> (especially caste/EWS/PwD)</li></ul></li></ul><h4>Important Notes</h4><ul><li>Mismatch in documents can lead to <strong>rejection of candidature</strong></li><li>Original documents are required during <strong>final/physical verification</strong></li><li>Each university may define <strong>slightly different size limits</strong></li></ul><h2>&nbsp;</h2><p>&nbsp;</p>', 1, NULL, NULL, NULL, '011-40759000', 'helpdesk-cuetpg@nta.ac.in', NULL, '<ul><li>Visit the official CUET PG website:<br><a href=\"https://exams.nta.nic.in/cuet-pg/\"><strong>https://exams.nta.nic.in/cuet-pg/</strong></a></li><li>Use the <strong>“Contact Us / Helpdesk”</strong> section</li><li>Steps to raise grievance:<ol><li>Login using application number &amp; password</li><li>Submit query via helpdesk/email</li><li>Provide details:<ul><li>Application number</li><li>Candidate name</li><li>Issue description</li></ul></li><li>Attach supporting documents (if required)</li></ol></li><li>Alternatively:<ul><li>Email directly to helpdesk</li><li>Call helpline during working hours</li></ul></li></ul>', NULL, NULL, NULL, 100.00, NULL, 'CUET PG Counselling 2026: Registration, Dates, Fees & Admission Process', 'CUET PG Counselling 2026 details including registration dates, eligibility, fees, seat allotment, and admission process. Check complete university-wise counselling procedure and important guidelines.', NULL, 'EducationalOccupationalProgram', 'https://www.yourwebsite.com/cuet-pg-counselling-2026', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-21 01:00:36', '2026-03-21 01:00:36', NULL, 1, '[{\"categories\":[\"General\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"OBC\",\"EWS\"],\"amount\":\"800\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"PwD\"],\"amount\":\"500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 1, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"1000\",\"additional_security_deposit\":\"5000\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 3\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Mop up round\",\"fresh_registration_fee\":\"1000\",\"additional_security_deposit\":\"5000\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"spot round\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'Registration/Application fee: Non-refundable\r\nSeat acceptance / admission fee:\r\nRefundable (partial/full) depending on withdrawal timing\r\nRefund rules are defined by individual universities', '15 – 30 Working Days', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple (varies per session, provided on official portal)'),
('8738fc14-326e-47ff-b49b-8c4c1945440d', 21, NULL, 'CLAT Counselling', 'clat-counselling-ehvnvi', 'Centralised', 'Online', 'Consortium of National Law Universities', 'University Body', 'https://consortiumofnlus.ac.in', '[\"UG\"]', '[\"All India Quota\",\"NRI Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'Admission is based on All India Rank (AIR) and seat availability in participating NLUs', NULL, 'no limit', 'No age criteria', NULL, 5, '[{\"round_name\":\"Round 1\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 2\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 3\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 4\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 5\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"}]', '[null]', NULL, 0, NULL, NULL, NULL, NULL, NULL, '2026-01', '2025-12-15', '2025-12-20', NULL, NULL, '2025-12-26', '2025-12-26', NULL, '\"round: Round 1\\r\\n    result date: 26-12-2025\\r\\n    action deadline : 30-12-2025\\r\\n    round : Round 2\\r\\n    result date : 05-01-2026\\r\\n    action deadline : 08-01-2026\\r\\n    round : Round 3\\r\\n    result date : 15-01-2026\\r\\n    action deadline : 18-01-2026\\r\\n    round : Round 4\\r\\n    result date : 25-01-2026\\r\\n    action deadline : 28-01-2026\\r\\n    round : Round 5\\r\\n    result date : 10-05-2026\\r\\n    final admission deadline : 15-05-2026\"', '{\"note\":\"<ul>\\r\\n<li>Dates are <strong>tentative<\\/strong>, based on previous year trends of <strong>CLAT<\\/strong><\\/li>\\r\\n<li>Actual schedule is released on:<br>&nbsp;<a href=\\\"https:\\/\\/consortiumofnlus.ac.in\\\">https:\\/\\/consortiumofnlus.ac.in<\\/a><\\/li>\\r\\n<li>Counselling starts <strong>immediately after CLAT result (December)<\\/strong><\\/li>\\r\\n<li>Final admissions may extend till <strong>May&ndash;June depending on vacancies<\\/strong><\\/li>\\r\\n<\\/ul>\"}', 'Exam Rank', 'If two or more candidates have the same CLAT score:\r\n\r\nFor UG (5-year LL.B):\r\nHigher marks in Legal Aptitude/Legal Reasoning section\r\nHigher age candidate gets preference\r\nComputerized draw of lots (if tie still persists)\r\n\r\nFor PG (LL.M):\r\nHigher marks in Legal Aptitude\r\nHigher age\r\nDraw of lots', NULL, NULL, '<ul>\r\n<li>If reserved category seats remain vacant:</li>\r\n</ul>\r\n<ol>\r\n<li>They may be <strong>converted to other categories</strong> as per NLU-specific rules</li>\r\n</ol>\r\n<ul>\r\n<li>Typical flow:</li>\r\n</ul>\r\n<ol>\r\n<li>SC/ST &rarr; OBC/EWS &rarr; General <em>(varies by NLU)</em></li>\r\n</ol>\r\n<ul>\r\n<li><strong>Domicile seats</strong> may convert to <strong>All India seats</strong> if unfilled</li>\r\n<li>Final conversion rules are <strong>decided individually by each NLU</strong> but executed through central counselling</li>\r\n</ul>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul>\r\n<li>Documents must be <strong>scanned clearly (no blur)</strong></li>\r\n<li>Accepted formats: <strong>PDF / JPG / JPEG</strong></li>\r\n<li>File size: usually <strong>200 KB &ndash; 2 MB (as per portal limits)</strong></li>\r\n<li>All details must be <strong>legible and match application data</strong></li>\r\n<li>Certificates (Category/Domicile) must be:</li>\r\n<li><strong>Issued by competent authority</strong></li>\r\n<li><strong>In prescribed format (Govt. of India / State format)</strong></li>\r\n<li>Name &amp; DOB must be <strong>consistent across all documents</strong></li>\r\n<li>Self-attestation may be required during upload</li>\r\n<li>Original documents must be produced at <strong>final reporting in allotted NLU</strong></li>\r\n</ul>', 1, NULL, NULL, NULL, '91 80689 70000', 'clat@consortiumofnlus.ac.in', NULL, '<ul>\r\n<li>Visit the official website of<br>Consortium of National Law Universities</li>\r\n<li>Use <strong>Login Dashboard &rarr; Support/Query section</strong></li>\r\n<li>Submit grievance with:</li>\r\n</ul>\r\n<ol>\r\n<li>Application number</li>\r\n<li>Issue details</li>\r\n<li>Supporting documents (if required)</li>\r\n</ol>\r\n<ul>\r\n<li>Track status through portal/email communication</li>\r\n<li>Issues are resolved within <strong>defined response timelines</strong></li>\r\n</ul>', NULL, NULL, NULL, 100.00, NULL, 'CLAT Counselling – Dates, Process, Fees, Seat Allotment & NLU Admission', 'Check CLAT Counselling 2026 details including registration, seat allotment, fees, documents, and admission process for NLUs. Get complete guidance on counselling rounds, eligibility, and refund rules.', NULL, 'EducationalOccupationalProgram', 'https://consortiumofnlus.ac.in/clat-counselling', 'index, follow', 'Upcoming', 'Public', NULL, NULL, '2026-03-20 03:29:17', '2026-04-10 05:29:06', NULL, 1, '[{\"categories\":[\"General\",\"OBC\",\"EWS\"],\"amount\":\"30000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":\"Exact amount may vary slightly year to year as per Consortium of National Law Universities notification)\"},{\"categories\":[\"SC\",\"ST\",\"PwD\"],\"amount\":\"20000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":\"Exact amount may vary slightly year to year as per Consortium of National Law Universities notification)\"}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 1, 1, '[{\"candidate_categories\":[\"General\",\"OBC\",\"EWS\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"30000\",\"refundable\":\"Yes\",\"refund_conditions\":\"Exit from counselling within allowed rounds  Non-acceptance of seat within timeline  Refund after standard deduction as per Consortium of National Law Universities\",\"forfeiture_conditions\":\"No response after seat allotment  Exit after final round\\/deadline  Failure to complete admission after seat acceptance  Submission of invalid\\/false documents\"},{\"candidate_categories\":[\"SC\",\"ST\",\"PwD\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"20000\",\"refundable\":\"Yes\",\"refund_conditions\":\"Exit from counselling within allowed rounds  Non-acceptance of seat within timeline  Refund after standard deduction as per Consortium of National Law Universities\",\"forfeiture_conditions\":\"No response after seat allotment  Exit after final round\\/deadline  Failure to complete admission after seat acceptance  Submission of invalid\\/false documents\"}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"30000\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":\"One-time counselling fee; no fresh registration in later rounds\"},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 3\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 4\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 5\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'Single counselling fee (acts as registration + security deposit)\r\nPartial refund allowed based on exit timing\r\nManaged by Consortium of National Law Universities', '15–30 working days (approx.)', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple Payment Gateways (Razorpay / BillDesk / Bank Gateway)”'),
('88d7e958-79ab-445e-a960-40484744fcd1', 20, NULL, 'CMAT Counselling', 'cmat-counselling-03d138', 'Centralised', 'Online', 'National Testing Agency', 'Central Government', 'https://cmat.nta.nic.in', '[\"PG\"]', '[\"All India Quota\",\"State Quota\",\"Institutional Quota\",\"Management Quota\",\"NRI Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, 'Maharashtra (DTE CAP Counselling)  Uttar Pradesh  Madhya Pradesh  Rajasthan  Gujarat', 1, 'No fixed minimum (varies by institute)  Top institutes: 90–99+ percentile  Mid-tier institutes: 70–85 percentile  Tier-3 colleges: 50–70 percentile', NULL, 'no limit', 'No age limit', '<ol><li>Candidate must have a <strong>Bachelor’s degree (any discipline)</strong> from a recognized university</li><li>Final-year students are also eligible (admission subject to completion)</li><li>Admission criteria (GD/PI/WAT, academics, work experience) vary by institute</li><li>Reservation and eligibility rules follow <strong>AICTE / State Government / Institute norms</strong></li></ol>', 3, '[{\"round_name\":\"Regural admission\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Upgrade\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"fresh\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"}]', '[\"\\\"Step 1: Appear in CMAT conducted by National Testing Agency (NTA)\\\",\\r\\n  \\\"Step 2: Check CMAT result and download scorecard\\\",\\r\\n  \\\"Step 3: Apply separately to preferred AICTE-approved institutes or state counselling portals\\\",\\r\\n  \\\"Step 4: Fill application forms of institutes and upload required documents\\\",\\r\\n  \\\"Step 5: Pay application fees for each institute\\\",\\r\\n  \\\"Step 6: Participate in selection rounds (GD\\/PI\\/WAT) if applicable\\\",\\r\\n  \\\"Step 7: Wait for merit list \\/ shortlist release by institutes\\\",\\r\\n  \\\"Step 8: Accept offer and pay admission\\/seat confirmation fee\\\"\"]', '<ul><li>No centralized choice filling system</li><li>Candidates <strong>apply individually to multiple institutes</strong></li><li>In state counselling (e.g., Maharashtra), candidates fill <strong>college preferences in CAP portal</strong></li></ul>', 0, '<ul><li>Institutes prepare <strong>merit lists based on CMAT percentile + selection criteria</strong></li><li>Seats allotted based on:</li></ul><ol><li>Rank/percentile</li><li>Category</li><li>Availability of seats</li></ol><ul><li>State counselling bodies allot seats via <strong>centralized CAP rounds</strong></li></ul>', '<ul><li>Candidates must <strong>accept the offer within deadline</strong></li><li>Pay admission fee</li><li>Report to institute:</li></ul><ol><li><strong>Online (document upload)</strong> or</li><li><strong>Offline (campus reporting)</strong></li></ol>', '<ul><li>Conducted by:</li></ul><ol><li>Individual institutes OR</li><li>State counselling authorities</li></ol><ul><li>Documents required:</li></ul><ol><li>CMAT scorecard</li><li>Graduation marksheets</li><li>ID proof</li><li>Category certificate (if applicable)</li><li>Domicile (for state quota)</li></ol>', '<ul><li>Available mainly in <strong>state counselling systems (like CAP)</strong></li><li>Candidates can opt for:</li></ul><ol><li><strong>Float/Upgrade option</strong> to get better college in next round</li></ol><ul><li>Not applicable in most <strong>direct institute admissions</strong></li></ul>', '<ul><li>If candidate withdraws before final admission deadline:</li></ul><ol><li>Partial refund may be allowed (depends on institute)</li></ol><ul><li>After course commencement:</li></ul><ol><li><strong>Fees may be non-refundable</strong> (as per AICTE norms)</li></ol><ul><li>Refund policies vary <strong>institute to institute / state authority</strong></li></ul>', '2026-03', '2026-03-15', '2026-04-30', '2026-03-20', '2026-05-05', NULL, NULL, NULL, '\"\\\"phase\\\": \\\"Application to Institutes\\\",\\r\\n    \\\"timeline\\\": \\\"March \\u2013 April 2026\\\",\\r\\n    \\\"details\\\": \\\"Candidates apply individually to AICTE-approved colleges using CMAT score\\r\\n    \\\"phase\\\": \\\"Shortlisting & Selection Rounds\\\",\\r\\n    \\\"timeline\\\": \\\"April \\u2013 June 2026\\\",\\r\\n    \\\"details\\\": \\\"Institutes conduct GD\\/PI\\/WAT or direct merit-based selection\\\"\\r\\n    \\\"phase\\\": \\\"Merit List \\/ Seat Allotment\\\",\\r\\n    \\\"timeline\\\": \\\"May \\u2013 July 2026\\\",\\r\\n    \\\"details\\\": \\\"Multiple merit lists released by institutes or CAP rounds by states\\\"\\r\\n    \\\"phase\\\": \\\"Reporting & Admission\\\",\\r\\n    \\\"timeline\\\": \\\"May \\u2013 July 2026\\\",\\r\\n    \\\"details\\\": \\\"Candidates confirm seats by paying fees and verifying documents\\r\\n    \\\"phase\\\": \\\"Spot \\/ Vacancy Round\\\",\\r\\n    \\\"timeline\\\": \\\"July \\u2013 August 2026\\\",\\r\\n    \\\"details\\\": \\\"Remaining seats filled through institute-level admission\\\"\"', '{\"note\":\"<ul><li>CMAT counselling has <strong>no single fixed national schedule<\\/strong><\\/li><li>Dates vary across:<\\/li><\\/ul><ol><li>Institutes (e.g., private B-schools)<\\/li><li>State portals (like Maharashtra CAP)<\\/li><\\/ol><ul><li>Candidates should regularly check:<\\/li><\\/ul><ol><li><strong>National Testing Agency official CMAT website<\\/strong><\\/li><li>Respective institute websites<\\/li><\\/ol>\"}', 'Exam Rank', 'When two candidates have the same CMAT score/percentile, institutes may use:\r\nHigher Graduation marks\r\nHigher 12th marks\r\nHigher 10th marks\r\nCandidate with relevant work experience (in some institutes)\r\nAge preference (older candidate may be preferred)', NULL, NULL, '<ul><li><strong>Unfilled reserved category seats</strong> may be converted as per government norms:</li></ul><ol><li>SC/ST → OBC/General</li><li>OBC → General</li></ol><ul><li><strong>State Quota seats</strong> may convert to <strong>All India seats</strong> if vacant</li><li><strong>NRI/Management quota seats</strong> may convert to General category (in some institutes)</li><li>Final conversion rules depend on:</li></ul><ol><li>State counselling authority</li><li>Institute policies</li><li><strong>All India Council for Technical Education guidelines</strong></li></ol>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul><li>Documents must be <strong>clear and legible scanned copies</strong></li><li>Accepted formats: <strong>PDF / JPEG / PNG</strong></li><li>File size limits: usually <strong>100 KB – 1 MB</strong> <i>(varies by institute/portal)</i></li><li>Certificates (category/domicile) must be in <strong>prescribed government format</strong></li><li>Name and details must <strong>match across all documents</strong></li></ul>', 1, NULL, NULL, NULL, '011-40759000   011-69227700', 'cmat@nta.ac.in', NULL, '<ul><li>Visit the official website of<br><strong>National Testing Agency</strong></li><li>Go to <strong>“Contact Us / Helpdesk”</strong> section</li><li>Submit query via:</li></ul><ol><li>Email (cmat@nta.ac.in)</li><li>Helpline number (call support)</li></ol><ul><li>For issue tracking, use:</li></ul><ol><li><strong>Candidate login portal (if applicable)</strong></li></ol><ul><li>For admission-related grievances:</li></ul><ol><li>Contact <strong>respective institute / state counselling authority</strong> directly</li></ol>', NULL, NULL, NULL, 100.00, NULL, 'CMAT Counselling : Dates, Process, Fees, Colleges & Admission Guide', 'Complete guide to CMAT Counselling 2026 including dates, registration process, eligibility, fees, seat allotment, documents, and top colleges. Learn how MBA/PGDM admissions are conducted through CMAT score.', NULL, 'EducationalOccupationalProgram', 'https://www.yourwebsite.com/cmat-counselling-2026', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-20 04:43:14', '2026-03-20 04:43:14', NULL, 1, '[{\"categories\":[\"General\",\"OBC\",\"EWS\"],\"amount\":\"2000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\",\"PwD\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 1, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"Regural admission\",\"fresh_registration_fee\":\"2000\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":\"Candidates pay application fee directly to each institute; non-refundable in most cases\"},{\"round_name\":\"Upgrade\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"20000\",\"refund_applicable\":\"Yes\",\"remarks\":\"Fee already paid is adjusted if candidate upgrades or remains in waitlist\"},{\"round_name\":\"Fresh\",\"fresh_registration_fee\":\"1500\",\"additional_security_deposit\":null,\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'Application/registration fees are non-refundable in most cases\r\nAdmission/seat confirmation fees may be refundable as per institute or state rules\r\n\r\nPolicies vary by:\r\nIndividual institutes\r\nState counselling authorities\r\n                                                                                                                                                                                         Broad guidelines may follow norms of\r\nAll India Council for Technical Education', '15 – 30 working days', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', NULL),
