INSERT INTO `counsellings` (`id`, `exam_id`, `dynamic_exam_id`, `counselling_name`, `slug`, `counselling_type`, `counselling_mode`, `conducting_authority_name`, `conducting_authority_type`, `official_counselling_website`, `applicable_course_levels`, `applicable_quotas`, `applicable_categories`, `domicile_required`, `state_applicability`, `minimum_exam_qualification_required`, `minimum_score_or_rank_required`, `category_wise_eligibility`, `attempts_allowed`, `age_criteria_for_counselling`, `eligibility_notes`, `number_of_rounds`, `rounds`, `registration_process_steps`, `choice_filling_process`, `choice_locking_required`, `seat_allotment_process`, `reporting_process`, `document_verification_process`, `upgradation_rules`, `exit_and_refund_rules`, `counselling_year`, `registration_start_date`, `registration_end_date`, `choice_filling_start_date`, `choice_filling_end_date`, `seat_allotment_result_date`, `reporting_start_date`, `reporting_end_date`, `round_wise_schedule`, `important_dates`, `seat_allocation_basis`, `tie_breaking_rules`, `reservation_policy_reference`, `seat_matrix_source`, `seat_conversion_rules`, `documents_required`, `document_format_requirements`, `original_documents_required_at_reporting`, `participating_institutions_count`, `participating_institutions_note`, `institution_type_supported`, `helpdesk_contact_number`, `helpdesk_email`, `faq_url`, `grievance_redressal_process`, `official_notifications_urls`, `information_source`, `last_verified_on`, `data_confidence_score`, `disclaimer_text`, `meta_title`, `meta_description`, `focus_keywords`, `schema_type`, `canonical_url`, `indexing_status`, `status`, `visibility`, `created_by`, `last_updated_by`, `created_at`, `updated_at`, `deleted_at`, `registration_fee_required`, `registration_fee_structure`, `late_registration_allowed`, `late_fee_rules`, `security_deposit_required`, `partial_refund_allowed`, `security_deposit_structure`, `round_specific_fee_rules`, `refund_policy_summary`, `refund_timeline`, `refund_mode`, `forfeiture_scenarios`, `payment_modes_allowed`, `transaction_charges_applicable`, `transaction_charge_borne_by`, `payment_gateway_name`) VALUES
('cd5f3d51-9707-4dbd-a2ae-3c3a34674786', 15, NULL, 'Common Admission Test', 'common-admission-test-lauldd', 'Centralised', 'Online', 'Indian Institutes of Management', 'Central Government', 'https://iimcat.ac.in', '[\"PG\"]', '[\"All India Quota\",\"Institutional Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'No fixed score or rank', NULL, 'No limit', 'No age limit', '<ul><li>Candidates must have <strong>minimum 50% marks (45% for SC/ST/PwD)</strong> in graduation</li><li>Final year students are also eligible</li><li>Professional degrees (CA/CS/ICWA) are accepted</li><li>Reservation applicable as per Government of India norms</li><li>Meeting CAT eligibility <strong>does not guarantee admission</strong> (separate institute-level selection process)</li></ul>', 3, '[{\"round_name\":\"Shortlisting\",\"round_type\":\"Regular\"},{\"round_name\":\"WAT\\/PI Round\",\"round_type\":\"Regular\"},{\"round_name\":\"Final Selection\",\"round_type\":\"Regular\"}]', '[\"\\\"Register on the official CAT website\\\",\\r\\n  \\\"Fill personal, academic, and work experience details\\\",\\r\\n  \\\"Upload required documents (photo, signature, certificates)\\\",\\r\\n  \\\"Select preferred exam cities\\\",\\r\\n  \\\"Pay application fee online\\\",\\r\\n  \\\"Submit and download confirmation page\\\",\\r\\n  \\\"Appear for CAT exam\\\",\\r\\n  \\\"Check result and download scorecard\\\",\\r\\n  \\\"Apply separately to IIMs and other B-schools\\\"\"]', '<ul><li>No centralized choice filling ❌</li><li>Candidates apply <strong>individually to each IIM/B-school</strong></li><li>Preferences are filled in <strong>institute-specific application forms</strong></li></ul>', 0, '<ul><li>No central seat allotment ❌</li><li>Each institute releases <strong>shortlists and final merit lists</strong></li><li>Admission offers are sent <strong>individually by institutes</strong></li></ul>', '<ul><li>Accept offer through institute portal</li><li>Pay admission/acceptance fee</li><li>Report to allotted institute (online/offline as required)</li></ul>', '<ul><li>Conducted by individual institutes during PI/admission</li><li>Common documents:<ul><li>CAT Scorecard</li><li>Graduation Marksheet/Certificate</li><li>Class 10 &amp; 12 Certificates</li><li>Category Certificate (if applicable)</li><li>Work Experience Proof (if any)</li></ul></li></ul>', '<ul><li>Not applicable centrally ❌</li><li>Some institutes may offer <strong>waitlist movement/upgrade internally</strong></li></ul>', '<ul><li>Defined by individual institutes ❗</li><li>Generally:<ul><li>Refund with deduction before deadline</li><li>No refund after program commencement</li></ul></li><li>Follows <strong>AICTE/UGC guidelines (where applicable)</strong></li></ul>', '2026-03', '2026-08-01', '2026-09-20', NULL, NULL, NULL, NULL, NULL, '\"\\\"stage\\\": \\\"Registration\\\",\\r\\n    \\\"timeline\\\": \\\"August - September 2026\\\"\\r\\n    \\\"stage\\\": \\\"Admit Card\\\",\\r\\n    \\\"timeline\\\": \\\"October 2026\\\"\\r\\n    \\\"stage\\\": \\\"Exam\\\",\\r\\n    \\\"timeline\\\": \\\"November 2026 (Last Sunday)\\\"\\r\\n    \\\"stage\\\": \\\"Result Declaration\\\",\\r\\n    \\\"timeline\\\": \\\"December 2026\\\"\\r\\n    \\\"stage\\\": \\\"Shortlisting by IIMs\\\",\\r\\n    \\\"timeline\\\": \\\"January 2027\\\"\\r\\n    \\\"stage\\\": \\\"WAT\\/PI Rounds\\\",\\r\\n    \\\"timeline\\\": \\\"February - March 2027\\\"\\r\\n    \\\"stage\\\": \\\"Final Admission Offers\\\",\\r\\n    \\\"timeline\\\": \\\"April - May 2027\\r\\n    \\\"stage\\\": \\\"Reporting\\/Joining\\\",\\r\\n    \\\"timeline\\\": \\\"June - July 2027\\\"\"', '{\"note\":\"<ul><li>No centralized counselling schedule (unlike NEET\\/JEE)<\\/li><li>Each IIM\\/B-school releases <strong>its own admission timeline<\\/strong><\\/li><li>CAT exam is usually held on the <strong>last Sunday of November<\\/strong><\\/li><li>Admission process continues till <strong>mid-2027<\\/strong><\\/li><\\/ul>\"}', 'Exam Rank', 'Higher CAT percentile/sectional scores\r\nBetter academic scores (Graduation/12th/10th)\r\nWork experience relevance\r\nPerformance in PI/WAT', NULL, NULL, '<ul><li>Follows <strong>Government of India reservation policy</strong></li><li>If reserved category seats remain vacant:<ul><li>ST → SC → OBC → General <i>(varies by institute)</i></li></ul></li><li>Final decision taken by <strong>respective IIM/B-school</strong></li></ul>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul><li>Scanned copies in <strong>PDF/JPG format</strong></li><li>File size as per institute guidelines (usually <strong>100 KB – 1 MB</strong>)</li><li>Clear and legible documents (no blur/cut edges)</li><li>Certificates must be <strong>issued by competent authority</strong></li><li>Name/details must match application form</li></ul>', 1, NULL, NULL, NULL, '+91-800-210-8720', 'cathelpdesk@iimcat.ac.in', NULL, '<ul><li>Visit the official website: <a href=\"https://iimcat.ac.in\">https://iimcat.ac.in</a></li><li>Use the <strong>“Contact Us / Helpdesk”</strong> section</li><li>Submit query via <strong>online form or email</strong></li><li>Track response via registered email ID</li><li>Issues related to application, admit card, or payment are handled by CAT helpdesk</li></ul>', NULL, NULL, NULL, 100.00, NULL, 'CAT 2026 Exam Details | Registration, Eligibility, Dates & Admission Process', 'Get complete details of CAT 2026 including registration dates, eligibility, exam pattern, fees, and admission process for IIMs and top MBA colleges in India.', NULL, 'EducationalOccupationalProgram', 'https://yourwebsite.com/exams/cat-2026', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-21 05:56:46', '2026-03-21 05:56:46', NULL, 1, '[{\"categories\":[\"General\",\"OBC\",\"EWS\"],\"amount\":\"2400\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\",\"PwD\"],\"amount\":\"1200\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 3\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'CAT registration fee is non-refundable under all circumstances\r\nOnce payment is made, it cannot be cancelled or transferred', '15 – 30 working days', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 0, 'Candidate', NULL),
('d035b079-25c6-4e5b-bc14-ec1f0ad990d6', 16, NULL, 'GATE 2026 Counselling', 'gate-2026-counselling-zibe3m', 'Centralised', 'Online', 'Common Offer Acceptance Portal', 'Central Government', 'https://ccmt.admissions.nic.in', '[\"PG\"]', '[\"All India Quota\",\"Institutional Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'No fixed score or rank', NULL, 'No restriction', 'No Age Limit', '<p data-start=\"156\" data-end=\"329\">Admission into postgraduate engineering programmes through GATE is open only to candidates who satisfy the basic national-level requirements set by participating institutes.</p>\r\n<ul data-start=\"331\" data-end=\"519\">\r\n<li data-section-id=\"1nebmdk\" data-start=\"331\" data-end=\"398\">Applicants must belong to the category of <strong data-start=\"375\" data-end=\"395\">Indian nationals</strong>.</li>\r\n<li data-section-id=\"19r33fc\" data-start=\"399\" data-end=\"519\">Eligibility is confirmed only when a candidate holds a <strong data-start=\"456\" data-end=\"516\">valid GATE qualification obtained in 2024, 2025, or 2026</strong>.</li>\r\n</ul>', 10, '[{\"round_name\":\"Round 1\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"},{\"round_name\":\"Round 2\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 3\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 4\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 5\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 6\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 7\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 8\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 9\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Round 10\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"}]', '[\"\\\"Register on CCMT portal (for NITs\\/IIITs\\/GFTIs) or COAP portal (for IITs) using GATE details\\\",\\r\\n  \\\"Fill personal, academic, and GATE score details\\\",\\r\\n  \\\"Create login credentials and verify email\\/mobile\\\",\\r\\n  \\\"Pay registration fee (only for CCMT)\\\",\\r\\n  \\\"Lock and confirm registration\\\",\\r\\n  \\\"Participate in COAP separately if applying for IITs\\\"\"]', '<ul>\r\n<li>Login to counselling portal (CCMT)</li>\r\n<li>Select preferred institutes and branches in order</li>\r\n<li>Arrange choices based on priority</li>\r\n<li>Save and <strong>lock choices before deadline</strong></li>\r\n<li>Choices once locked are used for all rounds</li>\r\n</ul>', 0, '<ul>\r\n<li>Based on <strong>GATE score, rank, category, and preferences</strong></li>\r\n<li>Separate systems:\r\n<ul>\r\n<li><strong>COAP</strong> &rarr; Candidates choose among multiple IIT offers</li>\r\n<li><strong>CCMT</strong> &rarr; System-generated allotment</li>\r\n</ul>\r\n</li>\r\n<li>Result published round-wise</li>\r\n<li>Candidates can choose: <strong>Accept / Float / Slide / Reject (CCMT)</strong></li>\r\n</ul>', '<ul>\r\n<li>Pay <strong>seat acceptance fee</strong> after allotment</li>\r\n<li>Select willingness option (Freeze/Float/Slide)</li>\r\n<li>Complete online reporting on portal</li>\r\n<li>Download provisional allotment letter</li>\r\n<li>Final physical reporting at allotted institute (if required)</li>\r\n</ul>', '<ul>\r\n<li>Conducted <strong>online (CCMT)</strong> and later at institute level</li>\r\n<li>Required documents:\r\n<ul>\r\n<li>GATE scorecard</li>\r\n<li>Degree/Provisional certificate</li>\r\n<li>Mark sheets</li>\r\n<li>Category certificate (if applicable)</li>\r\n<li>Photo ID proof</li>\r\n</ul>\r\n</li>\r\n<li>Admission confirmed only after successful verification</li>\r\n</ul>', '<ul>\r\n<li><strong>Float</strong> &rarr; Upgrade to better institute in next rounds</li>\r\n<li><strong>Slide</strong> &rarr; Upgrade within same institute (branch change)</li>\r\n<li><strong>Freeze</strong> &rarr; Accept and stop further upgradation</li>\r\n<li>Upgradation depends on <strong>vacancy and merit</strong></li>\r\n</ul>', '<ul>\r\n<li>Exit allowed after any round (as per schedule)</li>\r\n<li>Refund applicable after <strong>deductions (processing fee)</strong></li>\r\n<li>No refund if candidate:\r\n<ul>\r\n<li>Fails to report after final allotment</li>\r\n<li>Withdraws after final deadline</li>\r\n</ul>\r\n</li>\r\n<li>Refund processed to <strong>original payment mode</strong></li>\r\n</ul>', '2026-03', '2026-03-15', '2026-04-24', '2026-03-15', '2026-04-30', '2026-05-15', '2026-05-15', '2026-07-30', '\"\\\"Round\\\": \\\"Round 1\\\",\\r\\n    \\\"Result Date\\\": \\\"15-05-2026\\\",\\r\\n    \\\"Reporting\\\": \\\"15-05-2026 to 20-05-2026\\\"\\r\\n    \\\"Round\\\": \\\"Round 2\\\",\\r\\n    \\\"Result Date\\\": \\\"25-05-2026\\\",\\r\\n    \\\"Reporting\\\": \\\"25-05-2026 to 30-05-2026\\\"\\r\\n    \\\"Round\\\": \\\"Round 3\\\",\\r\\n    \\\"Result Date\\\": \\\"05-06-2026\\\",\\r\\n    \\\"Reporting\\\": \\\"05-06-2026 to 10-06-2026\\r\\n    \\\"Round\\\": \\\"Special Round 1\\\",\\r\\n    \\\"Result Date\\\": \\\"01-07-2026\\\",\\r\\n    \\\"Reporting\\\": \\\"01-07-2026 to 05-07-2026\\r\\n    \\\"Round\\\": \\\"Special Round 2\\\",\\r\\n    \\\"Result Date\\\": \\\"10-07-2026\\\",\\r\\n    \\\"Reporting\\\": \\\"10-07-2026 to 15-07-2026\\\"\"', '{\"note\":\"<ul>\\r\\n<li>COAP (IITs) rounds usually start <strong>mid-May and run parallel<\\/strong> with CCMT<\\/li>\\r\\n<li>CCMT has <strong>3 main rounds + 2 special rounds<\\/strong><\\/li>\\r\\n<li>Exact dates vary yearly depending on organizing IIT (e.g., Indian Institute of Technology)<\\/li>\\r\\n<li>Candidates must regularly check <strong>COAP &amp; CCMT portals<\\/strong> for updates<\\/li>\\r\\n<li>Delay in reporting may lead to <strong>seat cancellation<\\/strong><\\/li>\\r\\n<\\/ul>\"}', 'Exam Rank', 'Higher GATE Score → Candidate with higher normalized score gets preference\r\nMarks in Qualifying Degree → Higher %/CGPA preferred\r\nGATE Exam Year → More recent GATE score may be preferred (in some institutes)\r\nCategory Priority → As per reservation norms (if applicable)\r\nAge Factor (Rare cases) → Older candidate may be given preference\r\nRandom/Software-Based Allocation → Final fallback if all above are same', NULL, NULL, '<ul>\r\n<li>If reserved category seats remain vacant, they may be converted as per hierarchy:</li>\r\n</ul>\r\n<h4>Standard Conversion Flow:</h4>\r\n<ul>\r\n<li><strong>ST &rarr; SC</strong></li>\r\n<li><strong>SC &rarr; OBC-NCL</strong></li>\r\n<li><strong>OBC-NCL &rarr; General (Open)</strong></li>\r\n<li><strong>PwD seats</strong> convert within same category first, then to respective parent category</li>\r\n</ul>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<ul>\r\n<li><strong>File Format:</strong><br>PDF / JPG / JPEG (as specified on portal)</li>\r\n<li><strong>File Size Limit:</strong><br>Typically <strong>50 KB &ndash; 500 KB per document</strong> <em>(may vary slightly in CCMT portal)</em></li>\r\n<li><strong>Image Quality:</strong>\r\n<ul>\r\n<li>Clear and legible</li>\r\n<li>No blur, glare, or shadow</li>\r\n<li>All text must be readable</li>\r\n</ul>\r\n</li>\r\n<li><strong>Color Format:</strong>\r\n<ul>\r\n<li>Preferably <strong>color scanned copies</strong></li>\r\n<li>Black &amp; white acceptable if clearly visible</li>\r\n</ul>\r\n</li>\r\n<li><strong>Orientation:</strong>\r\n<ul>\r\n<li>Properly aligned (no rotation or उल्टा scan)</li>\r\n<li>Full document visible (no cropping of edges)</li>\r\n</ul>\r\n</li>\r\n<li><strong>Naming Convention:</strong>\r\n<ul>\r\n<li>Use simple names (e.g., GATE_Scorecard.pdf, Marksheet.pdf)</li>\r\n<li>Avoid special characters or spaces</li>\r\n</ul>\r\n</li>\r\n<li><strong>Certificate Requirements:</strong>\r\n<ul>\r\n<li>Category/EWS/PwD certificates must be in <strong>Government of India prescribed format</strong></li>\r\n<li>Must be <strong>valid and up-to-date</strong></li>\r\n</ul>\r\n</li>\r\n<li><strong>Self-Attestation:</strong>\r\n<ul>\r\n<li>Some documents may require <strong>self-attestation before upload</strong></li>\r\n</ul>\r\n</li>\r\n<li><strong>Multiple Pages:</strong>\r\n<ul>\r\n<li>Merge into <strong>single PDF file</strong> (if required)</li>\r\n</ul>\r\n</li>\r\n</ul>', 1, NULL, NULL, NULL, '+', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, NULL, 'GATE 2026 Counselling', 'Get complete details on Graduate Aptitude Test in Engineering (GATE) 2026 counselling including COAP & CCMT registration, important dates, eligibility, fees, seat allotment process, and admission guidelines for IITs, NITs, IIITs, and GFTIs.', NULL, 'EducationalOccupationalProgram', 'https://www.yourwebsite.com/gate-2026-counselling', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-21 06:42:38', '2026-04-10 05:01:46', NULL, 1, '[{\"categories\":[\"General\",\"OBC\",\"EWS\"],\"amount\":\"3000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\",\"PwD\"],\"amount\":\"2500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 1, 1, '[{\"candidate_categories\":[\"General\",\"OBC\",\"EWS\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"30000\",\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null},{\"candidate_categories\":[\"SC\",\"ST\",\"PwD\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"10000\",\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"3000\",\"additional_security_deposit\":\"30000\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 3\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 4\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 5\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'Registration fee is non-refundable\r\nSeat Acceptance Fee is refundable with deductions if withdrawn within deadline\r\nRefund depends on stage of withdrawal\r\nNo refund after final reporting deadline or no-show', '15 – 30 working days', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple gateways (e.g., BillDesk / PayU / integrated banking gateways)'),
('e101b15c-f387-47a1-9840-8dd96da4cf55', NULL, 11, 'NEET UG Counselling', 'neet-ug-counselling-fdq2j0', 'Centralised', 'Online', 'National Testing Agency', 'Central Government', 'https://mcc.nic.in', NULL, NULL, NULL, 0, NULL, 1, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Exam Rank', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100.00, NULL, NULL, NULL, NULL, 'EducationalOccupationalProgram', NULL, 'index, follow', 'Active', 'Public', NULL, NULL, '2026-04-18 06:18:31', '2026-04-18 06:18:31', NULL, 0, NULL, 0, NULL, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
('ea87d06d-1ee1-4f87-b1fa-6a5992576e59', 14, NULL, 'CUET UG Counselling', 'cuet-ug-counselling-elakif', 'Centralised', 'Online', 'National Testing Agency (NTA)', 'Central Government', 'https://cuet.nta.nic.in', '[\"UG\"]', '[\"All India Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'No fixed score or rank', NULL, 'No limit', 'No age limit', '<ol>\n<li>Must have <strong>passed or appearing in Class 12 (or equivalent)</strong></li>\n<li>Eligibility (subjects, marks, etc.) may vary by university</li>\n<li>Admission is based on <strong>CUET score + university criteria</strong></li>\n<li>Some courses require <strong>specific subject combinations in CUET</strong></li>\n</ol>', 5, '[{\"round_name\":\"Round 1\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\",\"fresh_reg\":\"0\"}]', '[\"Step 1: Appear for CUET UG exam conducted by NTA\\r\\n  Step 2: Check CUET result on official website\\r\\n  Step 3: Register on the desired university admission portal (e.g., DU, BHU)\\r\\n  Step 4: Fill personal, academic, and CUET score details\\r\\n  Step 5: Upload required documents\\r\\n  Step 6: Pay application\\/registration fee\\r\\n  Step 7: Submit the application form\"]', '<ol>\n<li>Select <strong>course + college/university preferences</strong></li>\n<li>Arrange them in <strong>priority order</strong></li>\n<li>Choices can usually be <strong>edited before deadline</strong></li>\n<li>Must match <strong>CUET subjects with course eligibility</strong></li>\n</ol>', 0, '<ol>\n<li>Based on <strong>CUET score + preferences + reservation criteria</strong></li>\n<li>Universities release <strong>merit lists / seat allotment lists</strong></li>\n<li>Candidates must <strong>accept/freeze the allotted seat</strong> within deadline</li>\n</ol>', '<ol>\n<li>Accept the seat online</li>\n<li>Pay <strong>admission/seat confirmation fee</strong></li>\n<li>Report to the allotted institute (online/offline as required)</li>\n</ol>', '<ol>\n<li>CUET Scorecard</li>\n<li>Class 10 &amp; 12 Marksheet</li>\n<li>Category Certificate (if applicable)</li>\n<li>ID Proof</li>\n<li>Passport size photographs</li>\n<li>Verification is usually <strong>online first, then physical at institute</strong></li>\n</ol>', '<ol>\n<li>If opted, seat can be <strong>upgraded in next rounds</strong></li>\n<li>Upgrade depends on <strong>availability + higher preference choices</strong></li>\n<li>Previous seat may be <strong>auto-cancelled after upgrade</strong></li>\n</ol>', '<ol>\n<li>Candidates can <strong>withdraw before final admission deadline</strong></li>\n<li>Refund policy varies by university</li>\n<li>Partial deduction of fee may apply as per rules</li>\n<li>No refund after final cutoff (depends on institution policy)</li>\n</ol>', '2026-03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"note\":null}', 'Exam Rank', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100.00, NULL, NULL, NULL, NULL, 'EducationalOccupationalProgram', NULL, 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-19 04:42:52', '2026-05-16 01:16:25', NULL, 1, '[{\"categories\":[\"General\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"OBC\",\"EWS\"],\"amount\":\"900\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\",\"PwD\"],\"amount\":\"800\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"No\",\"remarks\":null},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"No\",\"remarks\":null},{\"round_name\":\"Round 3\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"No\",\"remarks\":null},{\"round_name\":\"Special round\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"No\",\"remarks\":null},{\"round_name\":\"Mop up round\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"No\",\"remarks\":null}]', 'CUET application fee is non-refundable', 'Not applicable', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":\"Refund rules for admission fees depend on individual universities, not CUET\"}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'SBIePay / HDFC / ICICI / Paytm (varies per session)');
INSERT INTO `counsellings` (`id`, `exam_id`, `dynamic_exam_id`, `counselling_name`, `slug`, `counselling_type`, `counselling_mode`, `conducting_authority_name`, `conducting_authority_type`, `official_counselling_website`, `applicable_course_levels`, `applicable_quotas`, `applicable_categories`, `domicile_required`, `state_applicability`, `minimum_exam_qualification_required`, `minimum_score_or_rank_required`, `category_wise_eligibility`, `attempts_allowed`, `age_criteria_for_counselling`, `eligibility_notes`, `number_of_rounds`, `rounds`, `registration_process_steps`, `choice_filling_process`, `choice_locking_required`, `seat_allotment_process`, `reporting_process`, `document_verification_process`, `upgradation_rules`, `exit_and_refund_rules`, `counselling_year`, `registration_start_date`, `registration_end_date`, `choice_filling_start_date`, `choice_filling_end_date`, `seat_allotment_result_date`, `reporting_start_date`, `reporting_end_date`, `round_wise_schedule`, `important_dates`, `seat_allocation_basis`, `tie_breaking_rules`, `reservation_policy_reference`, `seat_matrix_source`, `seat_conversion_rules`, `documents_required`, `document_format_requirements`, `original_documents_required_at_reporting`, `participating_institutions_count`, `participating_institutions_note`, `institution_type_supported`, `helpdesk_contact_number`, `helpdesk_email`, `faq_url`, `grievance_redressal_process`, `official_notifications_urls`, `information_source`, `last_verified_on`, `data_confidence_score`, `disclaimer_text`, `meta_title`, `meta_description`, `focus_keywords`, `schema_type`, `canonical_url`, `indexing_status`, `status`, `visibility`, `created_by`, `last_updated_by`, `created_at`, `updated_at`, `deleted_at`, `registration_fee_required`, `registration_fee_structure`, `late_registration_allowed`, `late_fee_rules`, `security_deposit_required`, `partial_refund_allowed`, `security_deposit_structure`, `round_specific_fee_rules`, `refund_policy_summary`, `refund_timeline`, `refund_mode`, `forfeiture_scenarios`, `payment_modes_allowed`, `transaction_charges_applicable`, `transaction_charge_borne_by`, `payment_gateway_name`) VALUES
('fab8e4bc-7f53-45a4-84a0-7cb8d7466077', 13, NULL, 'NEET UG Counselling', 'neet-ug-counselling-jcotny', 'Centralised', 'Online', 'Medical Counselling Committee', 'Central Government', 'https://mcc.nic.in', '[\"UG\"]', '[\"All India Quota\",\"State Quota\",\"Institutional Quota\",\"Management Quota\",\"NRI Quota\"]', '[\"General\",\"OBC\",\"SC\",\"ST\",\"EWS\",\"PwD\"]', 0, NULL, 1, 'General (UR/EWS): 50th Percentile     OBC/SC/ST: 40th Percentile    PwD (UR): 45th Percentile', NULL, 'no limit', 'Minimum Age: 17 years \nMaximum Age: No upper age limit (as per latest rules)', '<p data-start=\"64\" data-end=\"316\">To be eligible for <strong data-start=\"83\" data-end=\"99\">NEET UG 2026</strong>, candidates must meet the academic qualification standards prescribed by the <strong data-start=\"177\" data-end=\"214\">National Medical Commission (NMC)</strong> and <strong data-start=\"219\" data-end=\"252\">Dental Council of India (DCI)</strong> along with qualifying requirements in the entrance examination.</p>\n<h3 data-section-id=\"1p1jjjm\" data-start=\"318\" data-end=\"344\">Academic Qualification</h3>\n<p data-start=\"345\" data-end=\"428\">Candidates must have passed the qualifying examination with the following subjects:</p>\n<ul data-start=\"429\" data-end=\"513\">\n<li data-section-id=\"tim97n\" data-start=\"429\" data-end=\"438\">Physics</li>\n<li data-section-id=\"4mkvi\" data-start=\"439\" data-end=\"450\">Chemistry</li>\n<li data-section-id=\"1md5fuk\" data-start=\"451\" data-end=\"476\">Biology / Biotechnology</li>\n<li data-section-id=\"1lbxcyb\" data-start=\"477\" data-end=\"513\">English (as an individual subject)</li>\n</ul>\n<h3 data-section-id=\"a7tjrd\" data-start=\"515\" data-end=\"544\">Minimum Marks Requirement</h3>\n<ul data-start=\"545\" data-end=\"942\">\n<li data-section-id=\"1ee4xv3\" data-start=\"545\" data-end=\"673\">General / General-EWS candidates must obtain <strong data-start=\"592\" data-end=\"623\">at least 50% marks combined</strong> in Physics, Chemistry, and Biology/Biotechnology.</li>\n<li data-section-id=\"f8gvtn\" data-start=\"674\" data-end=\"797\">Candidates belonging to <strong data-start=\"700\" data-end=\"725\">SC, ST, and OBC (NCL)</strong> categories must secure <strong data-start=\"749\" data-end=\"780\">at least 40% marks combined</strong> in PCB subjects.</li>\n<li data-section-id=\"1mz488k\" data-start=\"798\" data-end=\"942\">Candidates with <strong data-start=\"816\" data-end=\"849\">benchmark disabilities (PwBD)</strong> are also eligible with <strong data-start=\"873\" data-end=\"894\">minimum 40% marks</strong> in PCB subjects, as per applicable regulations.</li>\n</ul>\n<h3 data-section-id=\"db8i2a\" data-start=\"944\" data-end=\"978\">NEET Qualification Requirement</h3>\n<ul data-start=\"979\" data-end=\"1129\">\n<li data-section-id=\"1mel3mv\" data-start=\"979\" data-end=\"1129\">Candidates must <strong data-start=\"997\" data-end=\"1066\">qualify in NEET UG 2026 and secure a valid rank in the merit list</strong> to be eligible for admission to undergraduate medical courses.</li>\n</ul>', 4, '[{\"round_name\":\"Round 1\",\"round_type\":\"Regular\",\"fresh_reg\":\"1\"},{\"round_name\":\"Round 2\",\"round_type\":\"Regular\",\"upgrade_allowed\":\"1\"},{\"round_name\":\"Mop up round\",\"round_type\":\"Special\",\"fresh_reg\":\"1\"},{\"round_name\":\"stray vacancy round\",\"round_type\":\"Special\"}]', '[\"Candidates must register using the same email ID and mobile number used during NEET application.\\r\\nAll communication (OTP, updates, alerts) is sent only to the registered contact details.\\r\\nRegistration is completed by:\\r\\nFilling basic details\\r\\nPaying non-refundable registration fee\\r\\nPaying refundable security deposit\\r\\nCandidates must use a laptop\\/desktop with updated browsers to avoid technical issues.\\r\\nSeat allotment is strictly online; no manual or direct admission is allowed.\"]', '<ul>\r\n<li data-section-id=\"kbcqye\" data-start=\"1125\" data-end=\"1258\">After registration, candidates must:\r\n<ul data-start=\"1166\" data-end=\"1258\">\r\n<li data-section-id=\"172rc7s\" data-start=\"1166\" data-end=\"1207\">Select preferred colleges and courses</li>\r\n<li data-section-id=\"1bt5fto\" data-start=\"1210\" data-end=\"1258\">Lock their choices within the given deadline</li>\r\n</ul>\r\n</li>\r\n<li data-section-id=\"1i4bid9\" data-start=\"1259\" data-end=\"1312\">Once choices are locked, <strong data-start=\"1286\" data-end=\"1312\">no changes are allowed</strong></li>\r\n</ul>', 0, '<p data-start=\"41\" data-end=\"293\">The seat allotment result is released online after each counselling round based on the candidate&rsquo;s <strong data-start=\"140\" data-end=\"209\">NEET rank, selected preferences, and applicable reservation rules</strong>. Candidates can check their result by logging into the official counselling portal.</p>\r\n<ul data-start=\"295\" data-end=\"486\">\r\n<li data-section-id=\"b1p28z\" data-start=\"295\" data-end=\"349\">The result shows the <strong data-start=\"318\" data-end=\"349\">allotted college and course</strong></li>\r\n<li data-section-id=\"1uxmw7m\" data-start=\"350\" data-end=\"406\">It is published <strong data-start=\"368\" data-end=\"406\">round-wise on the official website</strong></li>\r\n<li data-section-id=\"xl41kj\" data-start=\"407\" data-end=\"486\">Candidates must download the <strong data-start=\"438\" data-end=\"458\">allotment letter</strong> for further admission steps</li>\r\n</ul>', '<p data-start=\"530\" data-end=\"638\">After seat allotment, candidates must complete the admission process by reporting to the assigned institute.</p>\r\n<ul data-start=\"640\" data-end=\"943\">\r\n<li data-section-id=\"goyz8i\" data-start=\"640\" data-end=\"714\">Candidates are required to <strong data-start=\"669\" data-end=\"714\">report physically to the allotted college</strong></li>\r\n<li data-section-id=\"e9us7p\" data-start=\"715\" data-end=\"766\">Carry all <strong data-start=\"727\" data-end=\"766\">original documents for verification</strong></li>\r\n<li data-section-id=\"32amu3\" data-start=\"767\" data-end=\"851\">Admission is confirmed only after <strong data-start=\"803\" data-end=\"851\">successful document verification and joining</strong></li>\r\n<li data-section-id=\"y90wns\" data-start=\"852\" data-end=\"943\">Reporting must be done <strong data-start=\"877\" data-end=\"906\">within the given deadline</strong>, otherwise the seat may be cancelled</li>\r\n</ul>', '<p data-start=\"123\" data-end=\"265\">Admission through NEET UG Counselling is provisional and is confirmed only after successful document verification at the allotted institution.</p>\r\n<h3 data-section-id=\"aysooe\" data-start=\"267\" data-end=\"293\">Verification Authority</h3>\r\n<ul data-start=\"294\" data-end=\"447\">\r\n<li data-section-id=\"1teyfgn\" data-start=\"294\" data-end=\"373\">The allotted Medical/Dental College is responsible for verifying documents.</li>\r\n<li data-section-id=\"gew2s9\" data-start=\"374\" data-end=\"447\">The counselling authority (MCC) does not conduct document verification.</li>\r\n</ul>\r\n<h3 data-section-id=\"1h0jc47\" data-start=\"449\" data-end=\"474\">Reporting Requirement</h3>\r\n<ul data-start=\"475\" data-end=\"644\">\r\n<li data-section-id=\"17gnicf\" data-start=\"475\" data-end=\"568\">Candidates must report physically to the allotted college within the prescribed timeline.</li>\r\n<li data-section-id=\"7sske5\" data-start=\"569\" data-end=\"644\">Admission is finalized only after completion of the verification process.</li>\r\n</ul>\r\n<h3 data-section-id=\"1xse8z1\" data-start=\"646\" data-end=\"669\">Mandatory Documents</h3>\r\n<ul data-start=\"670\" data-end=\"833\">\r\n<li data-section-id=\"8s89ga\" data-start=\"670\" data-end=\"770\">Candidates must carry all original certificates and required documents at the time of reporting.</li>\r\n<li data-section-id=\"1ejhylp\" data-start=\"771\" data-end=\"833\">Photocopies without original documents will not be accepted.</li>\r\n</ul>\r\n<h3 data-section-id=\"gcd3ay\" data-start=\"835\" data-end=\"863\">Conditions for Rejection</h3>\r\n<ul data-start=\"864\" data-end=\"1100\">\r\n<li data-section-id=\"3h5b4e\" data-start=\"864\" data-end=\"946\">Failure to produce original documents may result in cancellation of admission.</li>\r\n<li data-section-id=\"1d9hjgk\" data-start=\"947\" data-end=\"1100\">Candidates presenting a certificate stating that their original documents are deposited with another institution will not be allowed to take admission.</li>\r\n</ul>', '<p data-start=\"225\" data-end=\"367\">Upgradation in NEET UG Counselling allows candidates to move to a better preferred seat in subsequent rounds based on their choices and merit.</p>\r\n<h3 data-section-id=\"qjaabh\" data-start=\"369\" data-end=\"392\">Round 1 Upgradation</h3>\r\n<ul data-start=\"393\" data-end=\"750\">\r\n<li data-section-id=\"79ylf2\" data-start=\"393\" data-end=\"508\">Candidates allotted a seat in Round 1 must report to the allotted institute and complete admission formalities.</li>\r\n<li data-section-id=\"1rxl947\" data-start=\"509\" data-end=\"560\">A <strong data-start=\"513\" data-end=\"533\">free exit option</strong> is available in Round 1.</li>\r\n<li data-section-id=\"1ktu2fi\" data-start=\"561\" data-end=\"647\">Candidates can choose <strong data-start=\"585\" data-end=\"618\">&ldquo;Willingness for Upgradation&rdquo;</strong> to participate in Round 2.</li>\r\n<li data-section-id=\"18udar6\" data-start=\"648\" data-end=\"750\">If a candidate opts for upgradation, their current seat is considered for upgrade in the next round.</li>\r\n</ul>\r\n<h3 data-section-id=\"1ybsb9e\" data-start=\"752\" data-end=\"777\">Transition to Round 2</h3>\r\n<ul data-start=\"778\" data-end=\"1024\">\r\n<li data-section-id=\"fxt9qd\" data-start=\"778\" data-end=\"866\">Fresh choice filling is required for Round 2; previous choices become null and void.</li>\r\n<li data-section-id=\"wrdpy\" data-start=\"867\" data-end=\"950\">New candidates and those who opted for free exit in Round 1 can register again.</li>\r\n<li data-section-id=\"100dekc\" data-start=\"951\" data-end=\"1024\">Candidates already registered in Round 1 do not need to register again.</li>\r\n</ul>\r\n<h3 data-section-id=\"18sl69v\" data-start=\"1026\" data-end=\"1055\">Round 2 Upgradation Rules</h3>\r\n<ul data-start=\"1056\" data-end=\"1364\">\r\n<li data-section-id=\"1kpni5\" data-start=\"1056\" data-end=\"1163\">If a candidate is upgraded, they must <strong data-start=\"1096\" data-end=\"1122\">leave the Round 1 seat</strong> and join the newly allotted institute.</li>\r\n<li data-section-id=\"m44nid\" data-start=\"1164\" data-end=\"1278\">If a seat is allotted in Round 2 and the candidate <strong data-start=\"1217\" data-end=\"1236\">does not report</strong>, the <strong data-start=\"1242\" data-end=\"1275\">security deposit is forfeited</strong>.</li>\r\n<li data-section-id=\"1q8m40n\" data-start=\"1279\" data-end=\"1364\">Candidates who join the allotted seat can still opt for <strong data-start=\"1337\" data-end=\"1363\">upgradation to Round 3</strong>.</li>\r\n</ul>\r\n<h3 data-section-id=\"1y64myq\" data-start=\"1366\" data-end=\"1395\">Round 3 Upgradation Rules</h3>\r\n<ul data-start=\"1396\" data-end=\"1744\">\r\n<li data-section-id=\"11rjno9\" data-start=\"1396\" data-end=\"1517\">Candidates opting for upgradation and getting a new seat must <strong data-start=\"1460\" data-end=\"1487\">vacate the Round 2 seat</strong> and join the upgraded seat.</li>\r\n<li data-section-id=\"qe1k0d\" data-start=\"1518\" data-end=\"1618\">Once a candidate joins a seat in Round 3, <strong data-start=\"1562\" data-end=\"1615\">further upgradation or resignation is not allowed</strong>.</li>\r\n<li data-section-id=\"1htt67p\" data-start=\"1619\" data-end=\"1744\">Non-joining of an allotted seat in Round 3 leads to <strong data-start=\"1673\" data-end=\"1743\">forfeiture of fees and elimination from further counselling rounds</strong>.</li>\r\n</ul>\r\n<h3 data-section-id=\"942dig\" data-start=\"1746\" data-end=\"1769\">Stray Vacancy Round</h3>\r\n<ul data-start=\"1770\" data-end=\"1981\">\r\n<li data-section-id=\"3bx5sb\" data-start=\"1770\" data-end=\"1909\">Candidates who are allotted a seat but do not join in earlier rounds may be eligible for the <strong data-start=\"1865\" data-end=\"1888\">Stray Vacancy Round</strong>, subject to rules.</li>\r\n<li data-section-id=\"1yy1gdr\" data-start=\"1910\" data-end=\"1981\">Fresh registration and choice filling are required for participation.</li>\r\n</ul>', '<p data-start=\"47\" data-end=\"216\">The Exit and Refund Policy in NEET UG Counselling explains the conditions for withdrawal from counselling and the rules for refund or forfeiture of the security deposit.</p>\r\n<hr data-start=\"218\" data-end=\"221\">\r\n<h3 data-section-id=\"nig1xk\" data-start=\"223\" data-end=\"267\">Round 1 (Free Exit + Refund Eligibility)</h3>\r\n<ul data-start=\"268\" data-end=\"507\">\r\n<li data-section-id=\"kpwms\" data-start=\"268\" data-end=\"343\">Candidates allotted a seat in Round 1 can exit <strong data-start=\"317\" data-end=\"340\">without any penalty</strong>.</li>\r\n<li data-section-id=\"1oey53z\" data-start=\"344\" data-end=\"436\">The <strong data-start=\"350\" data-end=\"383\">security deposit remains safe</strong> and is eligible for refund after counselling ends.</li>\r\n<li data-section-id=\"8mhnv4\" data-start=\"437\" data-end=\"507\">Candidates can participate in subsequent rounds as fresh applicants.</li>\r\n</ul>\r\n<hr data-start=\"509\" data-end=\"512\">\r\n<h3 data-section-id=\"13wwsxe\" data-start=\"514\" data-end=\"548\">Round 2 (Exit with Forfeiture)</h3>\r\n<ul data-start=\"549\" data-end=\"775\">\r\n<li data-section-id=\"rrr6gg\" data-start=\"549\" data-end=\"590\">There is <strong data-start=\"560\" data-end=\"576\">no free exit</strong> in Round 2.</li>\r\n<li data-section-id=\"s56r11\" data-start=\"591\" data-end=\"700\">If a candidate is allotted a seat and <strong data-start=\"631\" data-end=\"658\">does not report or join</strong>, the <strong data-start=\"664\" data-end=\"697\">security deposit is forfeited</strong>.</li>\r\n<li data-section-id=\"103bvpr\" data-start=\"701\" data-end=\"775\">Candidates who join can still opt for <strong data-start=\"741\" data-end=\"774\">upgradation to the next round</strong>.</li>\r\n</ul>\r\n<hr data-start=\"777\" data-end=\"780\">\r\n<h3 data-section-id=\"snq4ps\" data-start=\"782\" data-end=\"813\">Round 3 (Strict Exit Rules)</h3>\r\n<ul data-start=\"814\" data-end=\"1105\">\r\n<li data-section-id=\"1kmgqaq\" data-start=\"814\" data-end=\"982\">If a candidate is allotted a seat and <strong data-start=\"854\" data-end=\"871\">fails to join</strong>, it results in:\r\n<ul data-start=\"890\" data-end=\"982\">\r\n<li data-section-id=\"1lrei0w\" data-start=\"890\" data-end=\"928\"><strong data-start=\"892\" data-end=\"926\">Forfeiture of security deposit</strong></li>\r\n<li data-section-id=\"1uzerpv\" data-start=\"931\" data-end=\"982\"><strong data-start=\"933\" data-end=\"980\">Elimination from further counselling rounds</strong></li>\r\n</ul>\r\n</li>\r\n<li data-section-id=\"3joezm\" data-start=\"983\" data-end=\"1105\">Once a candidate joins a seat in Round 3:\r\n<ul data-start=\"1029\" data-end=\"1105\">\r\n<li data-section-id=\"bqpzdn\" data-start=\"1029\" data-end=\"1071\"><strong data-start=\"1031\" data-end=\"1069\">Exit or resignation is not allowed</strong></li>\r\n<li data-section-id=\"lomk1p\" data-start=\"1074\" data-end=\"1105\">Admission is considered final</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1107\" data-end=\"1110\">\r\n<h3 data-section-id=\"19tq1vm\" data-start=\"1112\" data-end=\"1136\">After Joining a Seat</h3>\r\n<ul data-start=\"1137\" data-end=\"1290\">\r\n<li data-section-id=\"4x2orn\" data-start=\"1137\" data-end=\"1230\">Candidates who have joined a seat (especially in later rounds) <strong data-start=\"1202\" data-end=\"1227\">cannot resign or exit</strong>.</li>\r\n<li data-section-id=\"awhg1y\" data-start=\"1231\" data-end=\"1290\">The allotted seat becomes final as per counselling rules.</li>\r\n</ul>\r\n<hr data-start=\"1292\" data-end=\"1295\">\r\n<h3 data-section-id=\"1hhuq6f\" data-start=\"1297\" data-end=\"1327\">Refund of Security Deposit</h3>\r\n<ul data-start=\"1328\" data-end=\"1513\">\r\n<li data-section-id=\"1ks1kio\" data-start=\"1328\" data-end=\"1417\">The security deposit is refunded <strong data-start=\"1363\" data-end=\"1414\">only after completion of all counselling rounds</strong>.</li>\r\n<li data-section-id=\"5ebp8t\" data-start=\"1418\" data-end=\"1513\">The counselling authority will issue an official notification once the process is complete.</li>\r\n</ul>\r\n<h4 data-start=\"1515\" data-end=\"1535\">Refund Timeline</h4>\r\n<ul data-start=\"1536\" data-end=\"1676\">\r\n<li data-section-id=\"vxn76n\" data-start=\"1536\" data-end=\"1620\">Refund process starts <strong data-start=\"1560\" data-end=\"1578\">within 15 days</strong> of counselling completion notification.</li>\r\n<li data-section-id=\"1d4avg\" data-start=\"1621\" data-end=\"1676\">The refund is generally completed <strong data-start=\"1657\" data-end=\"1675\">within 30 days</strong>.</li>\r\n</ul>\r\n<h4 data-start=\"1678\" data-end=\"1697\">Mode of Refund</h4>\r\n<ul data-start=\"1698\" data-end=\"1846\">\r\n<li data-section-id=\"1vddi8n\" data-start=\"1698\" data-end=\"1846\">Refund is processed <strong data-start=\"1720\" data-end=\"1759\">only to the original payment source</strong>, such as:\r\n<ul data-start=\"1772\" data-end=\"1846\">\r\n<li data-section-id=\"3wdpd7\" data-start=\"1772\" data-end=\"1802\">Same debit/credit card, or</li>\r\n<li data-section-id=\"gmauff\" data-start=\"1805\" data-end=\"1846\">Same bank account used during payment</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h4 data-start=\"1848\" data-end=\"1873\">Important Conditions</h4>\r\n<ul data-start=\"1874\" data-end=\"2109\">\r\n<li data-section-id=\"1rbho8y\" data-start=\"1874\" data-end=\"1960\">Candidates must keep their <strong data-start=\"1903\" data-end=\"1931\">bank account/card active</strong> until refund is processed.</li>\r\n<li data-section-id=\"1df99eg\" data-start=\"1961\" data-end=\"2109\">If the original account is closed or inactive:\r\n<ul data-start=\"2012\" data-end=\"2109\">\r\n<li data-section-id=\"34w53l\" data-start=\"2012\" data-end=\"2031\">Refund may fail</li>\r\n<li data-section-id=\"mqaqln\" data-start=\"2034\" data-end=\"2109\">Reprocessing will take longer due to verification and legal formalities</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h4 data-start=\"2111\" data-end=\"2137\">Responsibility Clause</h4>\r\n<ul data-start=\"2138\" data-end=\"2305\">\r\n<li data-section-id=\"53oo3m\" data-start=\"2138\" data-end=\"2305\">The counselling authority and financial custodian are <strong data-start=\"2194\" data-end=\"2224\">not responsible for delays</strong> caused due to:\r\n<ul data-start=\"2242\" data-end=\"2305\">\r\n<li data-section-id=\"1dyi6ta\" data-start=\"2242\" data-end=\"2273\">Inactive or closed accounts</li>\r\n<li data-section-id=\"8xrx9l\" data-start=\"2276\" data-end=\"2305\">Incorrect payment details</li>\r\n</ul>\r\n</li>\r\n</ul>', '2026-03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"note\":null}', 'Exam Rank', 'In case two or more candidates secure the same marks or percentile score in NEET UG 2026, the merit position is determined using a step-by-step tie-breaking system as prescribed by the competent authority.\r\n\r\nTie-Breaking Criteria (Priority Order)\r\nBiology Score Priority\r\nCandidate with higher marks/percentile in Biology (Botany & Zoology) will be ranked higher.\r\nChemistry Score Priority\r\nIf the tie still exists, the candidate with higher marks/percentile in Chemistry will be preferred.\r\nPhysics Score Priority\r\nIf still unresolved, higher marks/percentile in Physics will be considered.\r\nFewer Incorrect Attempts (Overall Subjects)\r\nIf the tie persists, candidates with a lower proportion of incorrect answers across all subjects will be ranked higher.\r\nBiology Accuracy Factor\r\nIf still tied, the candidate with fewer incorrect attempts in Biology will be given preference.\r\nChemistry Accuracy Factor\r\nIf required, preference is given to candidates with fewer incorrect attempts in Chemistry.\r\nPhysics Accuracy Factor\r\nIf still unresolved, candidates with fewer incorrect attempts in Physics are considered.\r\nRandom Selection (Final Step)\r\nIf all above criteria fail to resolve the tie, the merit will be decided through a random process supervised by an independent expert committee.', NULL, NULL, '<p data-start=\"49\" data-end=\"199\">Seat conversion in NEET UG Counselling is a mechanism used to fill vacant seats by changing their category when eligible candidates are not available.</p>\r\n<h3 data-section-id=\"eh6jzq\" data-start=\"201\" data-end=\"236\">When Seat Conversion is Applied</h3>\r\n<ul data-start=\"237\" data-end=\"432\">\r\n<li data-section-id=\"16ihnz0\" data-start=\"237\" data-end=\"338\">Seat conversion is implemented in the <strong data-start=\"277\" data-end=\"308\">later stages of counselling</strong>, mainly in advanced rounds.</li>\r\n<li data-section-id=\"17dooys\" data-start=\"339\" data-end=\"432\">It takes place only when <strong data-start=\"366\" data-end=\"399\">no eligible candidates remain</strong> in a specific reserved category.</li>\r\n</ul>\r\n<h3 data-section-id=\"hq27pb\" data-start=\"434\" data-end=\"463\">How Seat Conversion Works</h3>\r\n<ul data-start=\"464\" data-end=\"820\">\r\n<li data-section-id=\"exn6k0\" data-start=\"464\" data-end=\"547\">Unfilled reserved seats are <strong data-start=\"494\" data-end=\"525\">shifted to other categories</strong> to avoid vacancies.</li>\r\n<li data-section-id=\"j3fp3q\" data-start=\"548\" data-end=\"707\">The process follows a <strong data-start=\"572\" data-end=\"608\">step-by-step conversion approach</strong>, ultimately allowing seats to be filled under the <strong data-start=\"659\" data-end=\"692\">General (Unreserved) category</strong> if required.</li>\r\n<li data-section-id=\"bbfxgy\" data-start=\"708\" data-end=\"820\">The exact conversion pattern may differ based on:\r\n<ul data-start=\"762\" data-end=\"820\">\r\n<li data-section-id=\"1tvgmlp\" data-start=\"762\" data-end=\"785\">Type of institution</li>\r\n<li data-section-id=\"t9s0eo\" data-start=\"788\" data-end=\"820\">Applicable reservation norms</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h3 data-section-id=\"1po6vr9\" data-start=\"822\" data-end=\"858\">Institution-Specific Application</h3>\r\n<ul data-start=\"859\" data-end=\"1052\">\r\n<li data-section-id=\"1pp0e43\" data-start=\"859\" data-end=\"965\">In certain institutions like Deemed Universities, conversion is generally applied in <strong data-start=\"946\" data-end=\"962\">final rounds</strong>.</li>\r\n<li data-section-id=\"7wghi6\" data-start=\"966\" data-end=\"1052\">Vacant seats may be opened to broader categories to ensure maximum seat utilization.</li>\r\n</ul>\r\n<h3 data-section-id=\"1od1ws1\" data-start=\"1054\" data-end=\"1072\">Key Conditions</h3>\r\n<ul data-start=\"1073\" data-end=\"1359\">\r\n<li data-section-id=\"2f2yg\" data-start=\"1073\" data-end=\"1175\">Conversion happens <strong data-start=\"1094\" data-end=\"1172\">only after all eligible candidates of the original category are considered</strong>.</li>\r\n<li data-section-id=\"1vk3iag\" data-start=\"1176\" data-end=\"1244\">The process is <strong data-start=\"1193\" data-end=\"1219\">automatically executed</strong> during seat allotment.</li>\r\n<li data-section-id=\"19sogdk\" data-start=\"1245\" data-end=\"1359\">Candidates should fill choices strategically, as <strong data-start=\"1296\" data-end=\"1358\">converted seats are allotted based on merit and preference</strong>.</li>\r\n</ul>', '[\"Admit Card\",\"Score Card\",\"10th Marksheet\",\"12th Marksheet\",\"Category Certificate\",\"Domicile Certificate\",\"Photo ID\"]', '<p data-start=\"66\" data-end=\"387\">Candidates who are allotted a seat through <strong data-start=\"109\" data-end=\"137\">NEET UG 2026 counselling</strong> must carry the required documents at the time of reporting to the allotted college. Both <strong data-start=\"227\" data-end=\"274\">original documents and attested photocopies</strong> are necessary for verification. Failure to produce the required documents may lead to cancellation of admission.</p>\r\n<h3 data-section-id=\"1xse8z1\" data-start=\"389\" data-end=\"412\">Mandatory Documents</h3>\r\n<ul data-start=\"413\" data-end=\"827\">\r\n<li data-section-id=\"1bx6jnl\" data-start=\"413\" data-end=\"459\">Allotment Letter issued during counselling</li>\r\n<li data-section-id=\"jnxrgh\" data-start=\"460\" data-end=\"482\">NEET UG Admit Card</li>\r\n<li data-section-id=\"wtjw5q\" data-start=\"483\" data-end=\"515\">NEET UG Result / Rank Letter</li>\r\n<li data-section-id=\"udtkr8\" data-start=\"516\" data-end=\"569\">Class 10 Certificate (for proof of qualification)</li>\r\n<li data-section-id=\"49qf1s\" data-start=\"570\" data-end=\"594\">Class 12 Certificate</li>\r\n<li data-section-id=\"17vfufz\" data-start=\"595\" data-end=\"617\">Class 12 Marksheet</li>\r\n<li data-section-id=\"1bnh3ft\" data-start=\"618\" data-end=\"684\">Date of Birth Proof (if not mentioned in Class 10 certificate)</li>\r\n<li data-section-id=\"1vqu7ku\" data-start=\"685\" data-end=\"764\">Valid Photo ID Proof (Aadhaar Card / PAN Card / Driving Licence / Passport)</li>\r\n<li data-section-id=\"1gkufy\" data-start=\"765\" data-end=\"827\">Passport-size photographs (same as used in application form)</li>\r\n</ul>\r\n<h3 data-section-id=\"14s39v8\" data-start=\"829\" data-end=\"880\">Category &amp; Special Certificates (If Applicable)</h3>\r\n<ul data-start=\"881\" data-end=\"1226\">\r\n<li data-section-id=\"cld6qq\" data-start=\"881\" data-end=\"1017\"><strong data-start=\"883\" data-end=\"904\">SC/ST Certificate</strong> (issued by competent authority, preferably in English/Hindi; translated copy required if in regional language)</li>\r\n<li data-section-id=\"1oar0nh\" data-start=\"1018\" data-end=\"1103\"><strong data-start=\"1020\" data-end=\"1043\">OBC-NCL Certificate</strong> (must be as per Central List and non-creamy layer status)</li>\r\n<li data-section-id=\"a16690\" data-start=\"1104\" data-end=\"1154\"><strong data-start=\"1106\" data-end=\"1125\">EWS Certificate</strong> (as per prescribed format)</li>\r\n<li data-section-id=\"1hby8rz\" data-start=\"1155\" data-end=\"1226\"><strong data-start=\"1157\" data-end=\"1197\">OCI/PIO/Foreign National Certificate</strong> (citizenship proof/document)</li>\r\n</ul>\r\n<h3 data-section-id=\"1bhiq8b\" data-start=\"1228\" data-end=\"1254\">Important Instructions</h3>\r\n<ul data-start=\"1255\" data-end=\"1520\">\r\n<li data-section-id=\"1vy9f7\" data-start=\"1255\" data-end=\"1348\">Candidates must ensure all documents are <strong data-start=\"1298\" data-end=\"1320\">original and valid</strong> at the time of admission.</li>\r\n<li data-section-id=\"sh40mg\" data-start=\"1349\" data-end=\"1446\">Additional documents, if required, should be confirmed from the <strong data-start=\"1415\" data-end=\"1443\">allotted college website</strong>.</li>\r\n<li data-section-id=\"t7wxfg\" data-start=\"1447\" data-end=\"1520\">Admission will <strong data-start=\"1464\" data-end=\"1482\">not be granted</strong> without proper document verification.</li>\r\n</ul>\r\n<p>&nbsp;</p>', 1, NULL, NULL, NULL, 'Phone No. : 0120-4073500  TOLL FREE NUMBER : 1800 102 7637', 'adgme@nic.in', NULL, '<p data-start=\"39\" data-end=\"203\">Candidates facing issues during the counselling process must follow the official grievance communication guidelines to ensure their concerns are addressed properly.</p>\r\n<h3 data-section-id=\"km6ucm\" data-start=\"205\" data-end=\"233\">How to Raise a Grievance</h3>\r\n<ul data-start=\"234\" data-end=\"426\">\r\n<li data-section-id=\"epo6pm\" data-start=\"234\" data-end=\"348\">Queries or complaints must be sent <strong data-start=\"271\" data-end=\"316\">only to the designated official email IDs</strong> provided for specific issues.</li>\r\n<li data-section-id=\"m3x4ei\" data-start=\"349\" data-end=\"426\">Emails sent to incorrect or unrelated email IDs <strong data-start=\"399\" data-end=\"425\">will not be considered</strong>.</li>\r\n</ul>\r\n<h3 data-section-id=\"1crg14d\" data-start=\"428\" data-end=\"450\">Response Timelines</h3>\r\n<ul data-start=\"451\" data-end=\"594\">\r\n<li data-section-id=\"mjop2b\" data-start=\"451\" data-end=\"523\">Grievance emails are handled <strong data-start=\"482\" data-end=\"520\">only during official working hours</strong>.</li>\r\n<li data-section-id=\"vednnb\" data-start=\"524\" data-end=\"594\">Response time is limited to <strong data-start=\"554\" data-end=\"577\">10:00 AM to 6:00 PM</strong> on working days.</li>\r\n</ul>\r\n<h3 data-section-id=\"1bhiq8b\" data-start=\"596\" data-end=\"622\">Important Instructions</h3>\r\n<ul data-start=\"623\" data-end=\"815\">\r\n<li data-section-id=\"oyygs3\" data-start=\"623\" data-end=\"714\">Candidates should ensure they are contacting the <strong data-start=\"674\" data-end=\"711\">correct authority for their issue</strong>.</li>\r\n<li data-section-id=\"wp9o36\" data-start=\"715\" data-end=\"815\">Delays or no response may occur if emails are sent outside working hours or to the wrong email ID.</li>\r\n</ul>', NULL, NULL, NULL, 100.00, NULL, 'NEET UG Counselling 2026 – Dates, Process, Rounds, Fees & Seat Allotment', 'Get complete details of NEET UG Counselling 2026 including registration process, eligibility, seat allotment, rounds, fees, and documents required. Conducted by Medical Counselling Committee.', NULL, 'EducationalOccupationalProgram', 'https://mcc.nic.in/ug-medical-counselling', 'index, follow', 'Active', 'Public', NULL, NULL, '2026-03-19 05:41:22', '2026-04-10 06:01:07', NULL, 1, '[{\"categories\":[\"General\",\"EWS\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"OBC\",\"SC\",\"ST\",\"PwD\"],\"amount\":\"500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 1, 1, '[{\"candidate_categories\":[\"General\",\"EWS\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"10000\",\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null},{\"candidate_categories\":[\"OBC\",\"SC\",\"ST\",\"PwD\"],\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":\"5500\",\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', '[{\"round_name\":\"round 1\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"Round 2\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"mop up round\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null},{\"round_name\":\"stray vacancy\",\"fresh_registration_fee\":\"0\",\"additional_security_deposit\":\"0\",\"refund_applicable\":\"Yes\",\"remarks\":null}]', 'Registration Fee:  Non-refundable\r\nSecurity Deposit: Refundable as per counselling rules\r\nRefund depends on round, joining status, and exit option', '15–30 working days after completion of counselling process', 'Original Payment Method', '[{\"scenario\":\"Seat allotted but not joined\",\"remarks\":null}]', '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'SBIePay / HDFC / ICICI / Paytm (varies per session)');

