INSERT INTO `dynamic_exams` (`id`, `name`, `short_name`, `exam_type`, `exam_category`, `conducting_body_type`, `exam_frequency`, `conducting_authority_name`, `logo`, `cover_image`, `exam_source_type`, `owning_organisation_id`, `about_exam`, `official_website`, `visibility`, `featured_exam`, `has_stages`, `selected_stages`, `slug`, `status`, `created_at`, `updated_at`) VALUES
(4, 'Joint Entrance Examination MAINS', 'JEE MAINS', 'National', '[\"Engineering\"]', 'Government', 'Twice a Year', 'National Testing Agency', 'media/exams/logos/1773656796_5yVAKe18OXFf_XvuMPJO61GQVsc.svg', 'media/exams/covers/1773656796_jee cover image.webp', 'External', NULL, '<div class=\"flex flex-col text-sm pb-25\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:4ac67ee3-432a-4156-83bf-035e5fccaceb-7\" data-testid=\"conversation-turn-16\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"7b2914e1-09e8-4221-a058-2f92c04fd424\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\r\n<p data-start=\"175\" data-end=\"518\">JEE Main 2026 is a national-level entrance exam conducted for students who wish to take admission into undergraduate courses after Class 12, mainly in engineering, architecture, and planning fields. It is widely accepted by top institutes such as NITs, IIITs, centrally funded institutions, and many state-recognized universities across India.</p>\r\n<p data-start=\"520\" data-end=\"701\">The exam is designed to assess students&rsquo; understanding and application skills, making it an important step for those aiming to build a career in technical and design-related fields.</p>\r\n<p data-start=\"703\" data-end=\"938\">JEE Main consists of two different papers based on the course a student wants to pursue. <strong data-start=\"792\" data-end=\"803\">Paper 1</strong> is meant for students interested in B.E. or B.Tech programs, while <strong data-start=\"871\" data-end=\"882\">Paper 2</strong> is for students planning to study B.Arch or B.Planning.</p>\r\n<p data-start=\"940\" data-end=\"1269\">To make the exam more student-friendly, JEE Main 2026 is conducted in <strong data-start=\"1010\" data-end=\"1047\">two sessions during the same year</strong>. This allows students to attempt the exam more than once and improve their performance. Students can choose to appear in one or both sessions, and if they take both, the <strong data-start=\"1218\" data-end=\"1268\">best score is considered for the final ranking</strong>.</p>\r\n<p data-start=\"1271\" data-end=\"1577\" data-is-last-node=\"\" data-is-only-node=\"\">The exam schedule is planned in a way that it does not clash with board exams, giving students enough flexibility and reducing stress. Overall, JEE Main provides a fair opportunity for students to demonstrate their abilities and secure admission to reputed institutions without losing a full academic year.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n<div class=\"mt-3 w-full empty:hidden\">\r\n<div class=\"text-center\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n<div class=\"pointer-events-none h-px w-px absolute bottom-0\" aria-hidden=\"true\" data-edge=\"true\">&nbsp;</div>', 'https://jeemain.nta.nic.in', 'Public', 0, 0, NULL, 'joint-entrance-examination-mains', 'Active', '2026-03-16 04:56:36', '2026-04-08 01:43:34'),
(5, 'National Eligibility cum Entrance Test (Undergraduate)', 'NEET UG', 'National', '[\"Medical\"]', 'Government', 'Once a Year', 'National Testing Agency', NULL, NULL, 'External', NULL, '<p dir=\"ltr\">The NEET (UG) 2026 is India&rsquo;s single national-level entrance examination for undergraduate medical and allied health science education. It acts as the unified selection system through which students gain admission into courses such as MBBS, BDS, and several AYUSH programs after completing their Class 12 education. The examination represents a standardized academic gateway that connects school-level biology and science education&nbsp;</p>\r\n<p dir=\"ltr\">Unlike earlier systems where multiple medical entrance exams existed across states and institutions, NEET (UG) has been designed to bring all admissions under one common evaluation process. The responsibility of conducting this examination lies with the National Testing Agency, which has been entrusted with this role since 2019. The NTA functions as an independent testing body under the Government of India and ensures that large-scale national examinations are conducted in a structured, transparent, and uniform manner.</p>\r\n<p dir=\"ltr\">The foundation of NEET is strongly rooted in national legislation and judicial direction. It is mandated under major regulatory frameworks such as the National Medical Commission Act, 2019, which makes NEET compulsory for admission into undergraduate medical education in India. Similar provisions extend to dental education and traditional medicine systems, ensuring that admissions across disciplines like Ayurveda, Unani, Siddha, and Homeopathy follow a single merit-based pathway. Over time, the validity and necessity of NEET as a unified entrance system have also been upheld through judicial interpretations, reinforcing its position as the core selection mechanism for medical education in India.</p>\r\n<p dir=\"ltr\">The scope of NEET (UG) is broad and inclusive, covering admissions to a wide range of undergraduate medical programs. These include MBBS for modern medicine, BDS for dental studies, and AYUSH courses such as BAMS, BUMS, BSMS, and BHMS. Additionally, performance in NEET is required for admission to premier national medical institutions such as the All India Institute of Medical Sciences and the Jawaharlal Institute of Postgraduate Medical Education and Research, which are among the most competitive and prestigious medical institutes in India.</p>\r\n<p dir=\"ltr\">The core idea behind introducing a single examination system was to create uniformity in medical admissions across the country. Before NEET, students often had to appear for multiple entrance tests conducted by different states and institutions, leading to inconsistencies in evaluation standards. NEET resolved this by establishing a common merit-based ranking system, where every candidate is assessed through the same question paper, marking scheme, and evaluation process. This approach promotes fairness, reduces duplication of effort, and ensures that selection is based purely on academic performance.</p>\r\n<p dir=\"ltr\">In terms of operation, NEET (UG) follows a highly organized national testing framework. The entire examination cycle&mdash;from application to result declaration&mdash;is managed centrally by NTA. This includes releasing information bulletins, conducting the exam on a single day across thousands of centers, and publishing results based on standardized evaluation methods. The centralized system ensures transparency and minimizes regional disparities in the admission process.</p>\r\n<p dir=\"ltr\">All official and authentic information regarding NEET (UG), including notifications, application procedures, admit cards, answer keys, results, and counselling-related updates, is made available exclusively on the official portal of NTA for NEET. Candidates are advised to rely only on this official source for accurate and updated information, as it serves as the primary communication channel between the examination authority and applicants.</p>\r\n<p dir=\"ltr\">Overall, NEET (UG) functions as more than just an entrance test; it is a national academic framework that governs the transition of students from secondary education into professional medical training. By establishing a single, uniform, and merit-driven system, it plays a key role in shaping the future healthcare workforce of India.</p>\r\n<p>&nbsp;</p>', 'https://neet.nta.nic.in', 'Public', 1, 0, '[]', 'national-eligibility-cum-entrance-test-undergraduate', 'Active', '2026-03-17 04:39:21', '2026-04-13 05:42:41'),
(6, 'Graduate Aptitude Test in Engineering', 'GATE', 'National', '[\"Engineering\"]', 'Government', 'Once a Year', 'Indian Institute of Science (IISc)  Indian Institutes of Technology (IITs)', NULL, NULL, 'External', NULL, NULL, 'https://gate2026.iitg.ac.in', 'Public', 0, 0, NULL, 'graduate-aptitude-test-in-engineering', 'Active', '2026-03-19 23:46:28', '2026-04-09 07:20:24'),
(7, 'National Eligibility cum Entrance Test – Postgraduate', 'NEET PG', 'National', '[\"Medical\"]', 'Government', 'Once a Year', 'National Board of Examinations in Medical Sciences', NULL, NULL, 'External', NULL, NULL, 'https://natboard.edu.in', 'Public', 0, 0, NULL, 'national-eligibility-cum-entrance-test-postgraduate', 'Active', '2026-03-20 00:05:24', '2026-04-09 07:19:24'),
(8, 'Common University Entrance Test – Postgraduate', 'CUET PG', 'National', '[\"Management\",\"Law\",\"School Admission\"]', 'Government', 'Once a Year', 'National Testing Agency (NTA)', NULL, NULL, 'External', NULL, NULL, 'https://exams.nta.nic.in/cuet-pg/', 'Public', 0, 0, NULL, 'common-university-entrance-test-postgraduate', 'Active', '2026-03-20 00:29:21', '2026-04-09 07:12:33'),
(9, 'Xavier Aptitude Test', 'XAT', 'National', '[\"Management\"]', 'Private Body', 'Once a Year', 'XLRI – Xavier School of Management', NULL, NULL, 'External', NULL, '<p>.</p>', 'https://xatonline.in', 'Public', 0, 0, NULL, 'xavier-aptitude-test', 'Active', '2026-03-20 01:00:36', '2026-04-09 07:11:24'),
(10, 'Common University Entrance Test', 'CUET', 'National', '[\"Management\",\"Law\"]', 'Government', 'Once a Year', 'National Testing Agency', NULL, NULL, 'External', NULL, '<p data-start=\"57\" data-end=\"296\">The <strong data-start=\"61\" data-end=\"103\">Common University Entrance Test (CUET)</strong> is a national-level entrance exam conducted by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">National Testing Agency</span></span> for admission to undergraduate programmes in central and other participating universities across India.</p>\r\n<p data-start=\"298\" data-end=\"584\">CUET serves as a <strong data-start=\"315\" data-end=\"344\">single-window examination</strong> for students seeking admission to multiple universities, including central, state, deemed, and private institutions. It helps streamline the admission process by allowing candidates to apply to various universities through one common test.</p>\r\n<p data-start=\"586\" data-end=\"891\">The exam is designed to provide <strong data-start=\"618\" data-end=\"670\">equal opportunities to students from all regions</strong>, especially those from rural and remote areas, by offering a standardized platform for evaluation. This ensures a fair and transparent admission process while also improving access to higher education across the country.</p>', 'https://cuet.nta', 'Public', 0, 0, '[]', 'common-university-entrance-test', 'Active', '2026-03-17 05:30:02', '2026-05-15 06:07:55'),
(11, 'Common Admission Test', 'CAT', 'National', '[\"Management\"]', 'University', 'Once a Year', 'Indian Institutes of Management', NULL, NULL, 'External', NULL, NULL, 'https://iimcat.ac.in', 'Public', 0, 0, '[]', 'common-admission-test', 'Active', '2026-03-19 05:06:22', '2026-04-20 06:52:20'),
(12, 'Common Law Admission Test', 'CLAT', 'National', '[\"Law\"]', 'Government', 'Once a Year', 'Consortium of National Law Universities', NULL, NULL, 'External', NULL, '<p data-start=\"446\" data-end=\"760\">The <strong data-start=\"450\" data-end=\"486\">Common Law Admission Test (CLAT)</strong> is a national-level entrance examination conducted in India for students aspiring to build a career in law. It is the primary gateway for admission into <strong data-start=\"640\" data-end=\"695\">5-year integrated LL.B. programs and LL.M. programs</strong> offered by the prestigious <strong data-start=\"723\" data-end=\"759\">National Law Universities (NLUs)</strong>.</p>\r\n<p data-start=\"762\" data-end=\"952\">CLAT is organized by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Consortium of National Law Universities</span></span>, which is a collective body of participating NLUs responsible for conducting the exam in a centralized and standardized manner.</p>\r\n<p data-start=\"954\" data-end=\"1167\">This examination plays a crucial role in law admissions across India, as it is accepted by <strong data-start=\"1045\" data-end=\"1077\">24 National Law Universities</strong> along with several other affiliated universities and institutions for admission purposes.</p>\r\n<p data-start=\"1169\" data-end=\"1355\">Apart from admissions, CLAT scores are also used by certain organizations for recruitment processes, making it an important national-level competitive exam in the legal education domain.</p>\r\n<p data-start=\"1357\" data-end=\"1560\">&nbsp;</p>', 'https://consortiumofnlus.ac.in', 'Public', 0, 0, '[]', 'common-law-admission-test', 'Active', '2026-03-20 01:51:15', '2026-04-13 07:13:48'),
(13, 'Common Management Admission Test', 'CMAT', 'National', '[\"Management\"]', 'Government', 'Once a Year', 'National Testing Agency (NTA)', NULL, NULL, 'External', NULL, '<div class=\"flex flex-col text-sm pb-25\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:5257aa28-50a7-487d-8694-0688d8380a4a-33\" data-testid=\"conversation-turn-12\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"336b794d-4f1c-4967-8406-0d13274fa3f2\" data-message-model-slug=\"gpt-5-mini\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\r\n<p data-start=\"51\" data-end=\"342\">The <strong data-start=\"55\" data-end=\"98\">Common Management Admission Test (CMAT)</strong> is a national-level entrance examination conducted for students who wish to pursue management and business administration programmes in India. It serves as a gateway for admission into MBA and related courses across participating institutions.</p>\r\n<p data-start=\"344\" data-end=\"567\">CMAT scores are widely accepted by <strong data-start=\"379\" data-end=\"408\">AICTE-approved institutes</strong>, along with university departments, constituent colleges, and affiliated colleges across the country, making it one of the key exams for management aspirants.</p>\r\n<p data-start=\"569\" data-end=\"786\">The exam is designed to assess a candidate&rsquo;s overall aptitude required for management education. CMAT is conducted in a <strong data-start=\"689\" data-end=\"725\">Computer-Based Test (CBT) format</strong>, ensuring a standardized and transparent evaluation process.</p>\r\n<p data-start=\"788\" data-end=\"851\">It evaluates candidates across multiple skill areas, including:</p>\r\n<ul data-start=\"852\" data-end=\"1007\">\r\n<li data-section-id=\"cklqwm\" data-start=\"852\" data-end=\"900\">Quantitative Ability and Data Interpretation</li>\r\n<li data-section-id=\"61bg6n\" data-start=\"901\" data-end=\"922\">Logical Reasoning</li>\r\n<li data-section-id=\"1eozt0\" data-start=\"923\" data-end=\"949\">Language Comprehension</li>\r\n<li data-section-id=\"4zh6lx\" data-start=\"950\" data-end=\"971\">General Awareness</li>\r\n<li data-section-id=\"17wzv1r\" data-start=\"972\" data-end=\"1007\">Innovation and Entrepreneurship</li>\r\n</ul>\r\n<p data-start=\"1009\" data-end=\"1221\" data-is-last-node=\"\" data-is-only-node=\"\">Through these sections, CMAT measures both analytical thinking and managerial potential, helping institutions select candidates suitable for professional management programmes in the academic session <strong data-start=\"1209\" data-end=\"1220\">2026&ndash;27</strong>.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n<div class=\"mt-3 w-full empty:hidden\">\r\n<div class=\"text-center\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n<div class=\"pointer-events-none h-px w-px absolute bottom-0\" aria-hidden=\"true\" data-edge=\"true\">&nbsp;</div>', 'https://cmat.nta.nic.in', 'Public', 0, 0, NULL, 'common-management-admission-test', 'Active', '2026-03-20 01:25:02', '2026-04-09 07:02:41'),
(19, 'Management Aptitude Test', 'MAT', 'National', '[\"Management\"]', 'Private Body', 'Multiple Times', 'All India Management Association', NULL, NULL, 'External', NULL, '<p dir=\"ltr\">The Management Aptitude Test (MAT) is a national-level entrance examination conducted by All India Management Association for admission to MBA and allied postgraduate management programmes across a wide network of Business Schools in India. Recognised by the Government of India, the examination serves as a standardised screening mechanism to evaluate candidates&rsquo; aptitude for management education through a balanced assessment of analytical ability, language skills, reasoning, and awareness of the business environment.</p>\r\n<p dir=\"ltr\">MAT is conducted multiple times in a year, typically in February, May, September, and December, which provides candidates with the flexibility to attempt the examination more than once and improve their performance. The exam is offered in both paper-based and computer-based modes, enabling candidates to choose a format that aligns with their convenience and familiarity. This multi-attempt and multi-mode structure significantly reduces the pressure associated with single-attempt examinations and allows for a more strategic preparation approach.</p>\r\n<p dir=\"ltr\">The examination comprises five core sections: Language Comprehension, Intelligence and Critical Reasoning, Mathematical Skills, Data Analysis and Sufficiency, and Economic and Business Environment. These sections are designed to collectively assess a candidate&rsquo;s readiness for management studies by evaluating both quantitative and qualitative competencies. While most sections contribute directly to the overall percentile, the business awareness section is typically used by institutions for reference during the selection process.</p>\r\n<p dir=\"ltr\">MAT functions as a qualifying examination rather than a direct admission pathway. Candidates must apply separately to participating institutions using their MAT scores, after which colleges conduct their own selection processes, including group discussions, written assessments, and personal interviews. As a result, performance in the examination is important, but final admission decisions also depend on overall profile evaluation and communication skills.</p>\r\n<p dir=\"ltr\">With acceptance across hundreds of B-Schools, MAT provides broad access to management education opportunities, particularly in private institutions. However, candidates should make informed decisions while selecting colleges, as the quality of institutions varies significantly. A well-planned strategy involves not only achieving a competitive score but also carefully evaluating participating institutes and preparing for subsequent selection stages.</p>', 'https://mat.aima.in', 'Public', 0, 0, '[]', 'management-aptitude-test', 'Active', '2026-04-15 07:02:35', '2026-04-16 05:37:13'),
(20, 'Narsee Monjee Aptitude Test', 'NMAT', 'National', '[\"Management\"]', 'Private Body', 'Once a Year', 'Graduate Management Admission Council', NULL, NULL, 'External', NULL, 'The NMAT (NMAT by GMAC) is a national-level MBA entrance exam conducted by the Graduate Management Admission Council (GMAC). It is one of the most student-friendly management exams in India, designed to assess a candidate’s aptitude for business and management studies', NULL, 'Public', 0, 0, NULL, 'narsee-monjee-aptitude-test', 'Active', '2026-04-16 00:42:00', '2026-04-16 00:42:00');

