INSERT INTO `exams` (`id`, `exam_id`, `name`, `short_name`, `slug`, `logo`, `cover_image`, `exam_type`, `exam_category`, `conducting_authority_name`, `conducting_body_type`, `official_website`, `about_exam`, `exam_purpose`, `exam_source_type`, `owning_organisation_id`, `owning_organisation_name`, `minimum_qualification`, `minimum_marks_required`, `subjects_required`, `minimum_age`, `maximum_age`, `attempt_limit`, `gap_year_allowed`, `nationality_criteria`, `reservation_applicable`, `eligibility_notes`, `exam_mode`, `exam_format`, `total_questions`, `total_marks`, `negative_marking`, `negative_marking_scheme`, `sections`, `duration_minutes`, `languages_available`, `syllabus_source`, `syllabus_url`, `subjects_covered`, `difficulty_level`, `recommended_classes`, `previous_year_question_papers_available`, `admit_card_download_procedure`, `result_check_procedure`, `score_type`, `rank_type`, `normalization_applied`, `tie_breaking_rules`, `score_validity_period`, `result_format_url`, `cutoff_type`, `cutoff_year_wise`, `cutoff_reference_note`, `counselling_conducted`, `counselling_authority`, `counselling_mode`, `number_of_rounds`, `seat_allocation_basis`, `reservation_policy_reference`, `official_counselling_website`, `accepting_organization_count`, `accepting_organizations_sample`, `course_types_supported`, `exam_frequency`, `first_conducted_year`, `years_active`, `exam_discontinued`, `replaced_by_exam_name`, `meta_title`, `meta_description`, `focus_keywords`, `schema_type`, `canonical_url`, `indexing_status`, `breadcrumb_category`, `official_notification_urls`, `information_source`, `last_verified_on`, `data_confidence_score`, `disclaimer_text`, `created_by`, `updated_by`, `status`, `visibility`, `featured_exam`, `has_stages`, `created_at`, `updated_at`, `registration_fee_required`, `registration_fee_structure`, `late_registration_allowed`, `late_fee_rules`, `security_deposit_required`, `partial_refund_allowed`, `security_deposit_structure`, `round_specific_fee_rules`, `refund_policy_summary`, `refund_timeline`, `refund_mode`, `forfeiture_scenarios`, `payment_modes_allowed`, `transaction_charges_applicable`, `transaction_charge_borne_by`, `payment_gateway_name`) VALUES
(12, 'ac7449fd-31dc-4412-aebc-40d2a92f76c5', 'Joint Entrance Examination MAINS', 'JEE MAINS', 'joint-entrance-examination-mains', 'media/exams/logos/1779722502_WhatsApp Image 2026-05-25 at 5.42.12 PM.jpeg', 'media/exams/covers/1779722502_ChatGPT Image May 25, 2026, 04_36_43 PM.png', 'National', '[\"Engineering\"]', 'National Testing Agency', 'Government', 'https://jeemain.nta.nic.in', '<div class=\"flex flex-col text-sm pb-25\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:4ac67ee3-432a-4156-83bf-035e5fccaceb-7\" data-testid=\"conversation-turn-16\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"7b2914e1-09e8-4221-a058-2f92c04fd424\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\r\n<p data-start=\"175\" data-end=\"518\">JEE Main 2026 is a national-level entrance exam conducted for students who wish to take admission into undergraduate courses after Class 12, mainly in engineering, architecture, and planning fields. It is widely accepted by top institutes such as NITs, IIITs, centrally funded institutions, and many state-recognized universities across India.</p>\r\n<p data-start=\"520\" data-end=\"701\">The exam is designed to assess students&rsquo; understanding and application skills, making it an important step for those aiming to build a career in technical and design-related fields.</p>\r\n<p data-start=\"703\" data-end=\"938\">JEE Main consists of two different papers based on the course a student wants to pursue. <strong data-start=\"792\" data-end=\"803\">Paper 1</strong> is meant for students interested in B.E. or B.Tech programs, while <strong data-start=\"871\" data-end=\"882\">Paper 2</strong> is for students planning to study B.Arch or B.Planning.</p>\r\n<p data-start=\"940\" data-end=\"1269\">To make the exam more student-friendly, JEE Main 2026 is conducted in <strong data-start=\"1010\" data-end=\"1047\">two sessions during the same year</strong>. This allows students to attempt the exam more than once and improve their performance. Students can choose to appear in one or both sessions, and if they take both, the <strong data-start=\"1218\" data-end=\"1268\">best score is considered for the final ranking</strong>.</p>\r\n<p data-start=\"1271\" data-end=\"1577\" data-is-last-node=\"\" data-is-only-node=\"\">The exam schedule is planned in a way that it does not clash with board exams, giving students enough flexibility and reducing stress. Overall, JEE Main provides a fair opportunity for students to demonstrate their abilities and secure admission to reputed institutions without losing a full academic year.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n<div class=\"mt-3 w-full empty:hidden\">\r\n<div class=\"text-center\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n<div class=\"pointer-events-none h-px w-px absolute bottom-0\" aria-hidden=\"true\" data-edge=\"true\">&nbsp;</div>', NULL, 'External', NULL, NULL, NULL, NULL, '[\"Physics, Mathematics + Chemistry\\/Biology\"]', NULL, NULL, '3', 1, NULL, 0, '<h4 data-section-id=\"192mm6n\" data-start=\"211\" data-end=\"231\"><span role=\"text\"><strong data-start=\"215\" data-end=\"231\">1. Age Limit</strong></span></h4>\r\n<p data-start=\"232\" data-end=\"401\">There is <strong data-start=\"241\" data-end=\"257\">no age limit</strong> to appear in JEE Main 2026.<br data-start=\"285\" data-end=\"288\">Students of any age can give the exam, but they must meet the admission rules of the college they apply to later.</p>\r\n<hr data-start=\"403\" data-end=\"406\">\r\n<h4 data-section-id=\"1l4fw7p\" data-start=\"408\" data-end=\"446\"><span role=\"text\"><strong data-start=\"412\" data-end=\"446\">2. Year of Passing / Appearing</strong></span></h4>\r\n<ul data-start=\"447\" data-end=\"651\">\r\n<li data-section-id=\"1b2ib3h\" data-start=\"447\" data-end=\"517\">Students who have passed Class 12 in <strong data-start=\"486\" data-end=\"502\">2024 or 2025</strong> are eligible</li>\r\n<li data-section-id=\"1xatd17\" data-start=\"518\" data-end=\"580\">Students <strong data-start=\"529\" data-end=\"563\">appearing for Class 12 in 2026</strong> can also apply</li>\r\n<li data-section-id=\"17zsejo\" data-start=\"581\" data-end=\"651\">Students who passed Class 12 in <strong data-start=\"615\" data-end=\"651\">2023 or earlier are not eligible</strong></li>\r\n</ul>\r\n<p data-start=\"653\" data-end=\"759\">The passing year is counted as the&nbsp;<strong data-start=\"691\" data-end=\"725\">first time you passed the exam</strong>, even if you improve marks later.</p>\r\n<hr data-start=\"761\" data-end=\"764\">\r\n<h4 data-section-id=\"3dlhrh\" data-start=\"766\" data-end=\"802\"><span role=\"text\"><strong data-start=\"770\" data-end=\"802\">3. Educational Qualification</strong></span></h4>\r\n<p data-start=\"803\" data-end=\"904\">Students must have completed or be appearing in <strong data-start=\"851\" data-end=\"879\">Class 12 (or equivalent)</strong> from a recognized board.</p>\r\n<p data-start=\"906\" data-end=\"938\">Accepted qualifications include:</p>\r\n<ul data-start=\"939\" data-end=\"1160\">\r\n<li data-section-id=\"d7ex6a\" data-start=\"939\" data-end=\"977\">CBSE, ICSE, and other State Boards</li>\r\n<li data-section-id=\"vzxobs\" data-start=\"978\" data-end=\"1018\">Pre-University or Intermediate exams</li>\r\n<li data-section-id=\"193xgid\" data-start=\"1019\" data-end=\"1059\">NIOS and other open schooling boards</li>\r\n<li data-section-id=\"rldc5q\" data-start=\"1060\" data-end=\"1114\">Diploma (3 years) approved by AICTE or State Board</li>\r\n<li data-section-id=\"14qv9na\" data-start=\"1115\" data-end=\"1160\">International boards like Cambridge or IB</li>\r\n</ul>\r\n<p data-start=\"1162\" data-end=\"1246\">If you studied from a foreign board, you may need an&nbsp;<strong data-start=\"1218\" data-end=\"1245\">equivalence certificate</strong>.</p>\r\n<hr data-start=\"1248\" data-end=\"1251\">\r\n<h4 data-section-id=\"rsu34f\" data-start=\"1253\" data-end=\"1284\"><span role=\"text\"><strong data-start=\"1257\" data-end=\"1284\">4. State of Eligibility</strong></span></h4>\r\n<ul data-start=\"1285\" data-end=\"1507\">\r\n<li data-section-id=\"1vup7ft\" data-start=\"1285\" data-end=\"1366\">This is based on the <strong data-start=\"1308\" data-end=\"1343\">state where you passed Class 12</strong>, not your home state</li>\r\n<li data-section-id=\"1xkptd4\" data-start=\"1367\" data-end=\"1414\">It is used for admission quotas in colleges</li>\r\n<li data-section-id=\"2a5uod\" data-start=\"1415\" data-end=\"1507\">If you change states for improvement exams, the <strong data-start=\"1465\" data-end=\"1505\">original passing state is considered</strong></li>\r\n</ul>\r\n<p data-start=\"1509\" data-end=\"1579\">For NIOS students, the state of the&nbsp;<strong data-start=\"1548\" data-end=\"1564\">study center</strong> is considered</p>', 'Online', 'MCQ', 90, 300, 1, '+4 for correct -1 for wrong', NULL, 180, NULL, '<p>The detailed syllabus for JEE (Main) is available on the website: https://jeemain.nta.nic.in/</p>', 'https://jeemain.nta.nic.in/document/syllabus-2026/', '[\"<p>&nbsp;Physics\",\"Chemistry\",\"&amp; Mathematics<br>&nbsp;<\\/p>\"]', 'Moderate', NULL, 0, '<p data-start=\"220\" data-end=\"378\">The admit card for JEE Main 2026 is released <strong data-start=\"265\" data-end=\"280\">online only</strong> on the official NTA website. Students must download it themselves, as it is <strong data-start=\"357\" data-end=\"377\">not sent by post</strong>.</p>\r\n<h3 data-section-id=\"19www7c\" data-start=\"380\" data-end=\"405\"><span role=\"text\"><strong data-start=\"384\" data-end=\"405\">Steps to Download</strong></span></h3>\r\n<ul data-start=\"406\" data-end=\"578\">\r\n<li data-section-id=\"1fk71wb\" data-start=\"406\" data-end=\"445\">Visit the official JEE Main website</li>\r\n<li data-section-id=\"10q8cpv\" data-start=\"446\" data-end=\"526\">Log in using your application details (like application number and password)</li>\r\n<li data-section-id=\"6tqwq3\" data-start=\"527\" data-end=\"578\">Download and take a printout of your admit card&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Make sure to keep multiple copies for safety.</li>\r\n</ul>\r\n<hr data-start=\"630\" data-end=\"633\">\r\n<h4 data-section-id=\"5z8qvd\" data-start=\"635\" data-end=\"673\">Important Instructions for Students</h4>\r\n<ul data-start=\"675\" data-end=\"969\">\r\n<li data-section-id=\"1f4aick\" data-start=\"675\" data-end=\"772\">The admit card will have details like:\r\n<ul data-start=\"718\" data-end=\"772\">\r\n<li data-section-id=\"4mq3v1\" data-start=\"718\" data-end=\"731\">Exam date</li>\r\n<li data-section-id=\"13tay8j\" data-start=\"734\" data-end=\"754\">Shift and timing</li>\r\n<li data-section-id=\"1budp82\" data-start=\"757\" data-end=\"772\">Exam centre</li>\r\n</ul>\r\n</li>\r\n<li data-section-id=\"1ybu7\" data-start=\"774\" data-end=\"857\">You must go to the <strong data-start=\"795\" data-end=\"826\">same centre, date, and time</strong> mentioned on your admit card</li>\r\n<li data-section-id=\"aacrj1\" data-start=\"858\" data-end=\"915\">Entry will <strong data-start=\"871\" data-end=\"913\">not be allowed after gate closing time</strong></li>\r\n<li data-section-id=\"1rcbxk0\" data-start=\"916\" data-end=\"969\">Do not change or damage the admit card in any way</li>\r\n</ul>\r\n<hr data-start=\"971\" data-end=\"974\">\r\n<h4 data-section-id=\"muw8et\" data-start=\"976\" data-end=\"1002\">If You Face Any Problem</h4>\r\n<ul data-start=\"1004\" data-end=\"1315\">\r\n<li data-section-id=\"ab004n\" data-start=\"1004\" data-end=\"1118\">If you are unable to download the admit card, contact the <strong data-start=\"1064\" data-end=\"1095\">NTA helpline (011-40759000)</strong> during working hours</li>\r\n<li data-section-id=\"l8wydm\" data-start=\"1119\" data-end=\"1211\">If there is any mistake in your details (photo, signature, etc.), inform NTA immediately</li>\r\n<li data-section-id=\"13sbieq\" data-start=\"1212\" data-end=\"1315\">You can still appear in the exam with the downloaded admit card while corrections are handled later</li>\r\n</ul>\r\n<hr data-start=\"1317\" data-end=\"1320\">\r\n<h4 data-section-id=\"1fr96qo\" data-start=\"1322\" data-end=\"1353\">Important Points to Remember</h4>\r\n<ul data-start=\"1355\" data-end=\"1617\">\r\n<li data-section-id=\"f4d1dm\" data-start=\"1355\" data-end=\"1464\">Admit card is issued only if:\r\n<ul data-start=\"1389\" data-end=\"1464\">\r\n<li data-section-id=\"47g393\" data-start=\"1389\" data-end=\"1421\">Application form is complete</li>\r\n<li data-section-id=\"17qudb6\" data-start=\"1424\" data-end=\"1464\">Eligibility conditions are fulfilled</li>\r\n</ul>\r\n</li>\r\n<li data-section-id=\"34kukb\" data-start=\"1466\" data-end=\"1530\">Keep your admit card safe even after the exam for future use</li>\r\n<li data-section-id=\"9myxwg\" data-start=\"1531\" data-end=\"1617\">Regularly check your <strong data-start=\"1554\" data-end=\"1574\">registered email</strong> for any updates or instructions from NTA</li>\r\n</ul>', '<h3>&nbsp;</h3>', 'Percentile', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Twice a Year', NULL, NULL, 0, NULL, 'ghjghj', 'hjhjjh', NULL, 'EducationalAssessment', 'https://jeemain.nta.nic.in/document/syllabus-2026/', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-16 04:56:36', '2026-05-25 09:51:42', 1, '{\"0\":{\"categories\":[\"General\",\"Male\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},\"2\":{\"categories\":[\"Female\"],\"amount\":\"800\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},\"3\":{\"categories\":[\"EWS\",\"OBC\"],\"amount\":\"900\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},\"4\":{\"categories\":[\"Pwd\",\"SC\",\"ST\"],\"amount\":\"500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},\"5\":{\"categories\":[\"Third Gender\"],\"amount\":\"500\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}}', 0, '[{\"condition\":\"Choice not locked\",\"penalty_type\":\"Flat\",\"penalty_amount\":\"0\",\"maximum_penalty_cap\":\"0\",\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'SBIePay / HDFC / ICICI / Paytm (varies per session)'),
(13, '1efded01-9e6e-4c59-870b-de1ed03077e5', 'National Eligibility cum Entrance Test (Undergraduate)', 'NEET UG', 'national-eligibility-cum-entrance-test-undergraduate', NULL, NULL, 'National', '[\"Medical\"]', 'National Testing Agency', 'Government', 'https://neet.nta.nic.in', '<p data-start=\"28\" data-end=\"347\">The <strong data-start=\"32\" data-end=\"104\">National Eligibility cum Entrance Test (Undergraduate), NEET UG 2026</strong>, is a nationwide entrance examination conducted by the <strong data-start=\"160\" data-end=\"193\">National Testing Agency (NTA)</strong>. It serves as a single, common eligibility test for students seeking admission into undergraduate medical and allied health science courses across India.</p>\r\n<p data-start=\"349\" data-end=\"764\">NEET UG is mandatory for admission to <strong data-start=\"387\" data-end=\"411\">MBBS and BDS courses</strong> in all medical institutions. In addition to these, it is also applicable for various courses under the Indian systems of medicine such as <strong data-start=\"550\" data-end=\"574\">BAMS, BUMS, and BSMS</strong>, as per the regulations of the National Commission for Indian System of Medicine (NCISM). It is also required for admission to <strong data-start=\"702\" data-end=\"718\">BHMS courses</strong> under the National Commission for Homeopathy.</p>\r\n<p data-start=\"766\" data-end=\"1011\">The exam is conducted in multiple languages to ensure accessibility for students from different regions of India. These include <strong data-start=\"894\" data-end=\"1010\">English, Hindi, Assamese, Bengali, Gujarati, Kannada, Malayalam, Marathi, Odia, Punjabi, Tamil, Telugu, and Urdu</strong>.</p>\r\n<p data-start=\"1013\" data-end=\"1287\">NEET UG also plays an important role for candidates aspiring to join the <strong data-start=\"1086\" data-end=\"1150\">BSc Nursing program under the Military Nursing Service (MNS)</strong> for Armed Forces Medical Service Hospitals. For this, NEET scores are used for shortlisting candidates for the four-year nursing course.</p>', NULL, 'External', NULL, NULL, NULL, NULL, '[\"Physics, Chemistry, Biology\"]', NULL, NULL, NULL, 1, NULL, 0, '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>\r\n<p data-start=\"40\" data-end=\"291\">To appear for <strong data-start=\"54\" data-end=\"70\">NEET UG 2026</strong>, candidates must fulfill the eligibility conditions prescribed by the <strong data-start=\"141\" data-end=\"178\">National Medical Commission (NMC)</strong> and <strong data-start=\"183\" data-end=\"216\">Dental Council of India (DCI)</strong>. The criteria mainly focus on age requirements and citizenship conditions.</p>\r\n<h3 data-section-id=\"1mh80ai\" data-start=\"293\" data-end=\"312\">Age Requirement</h3>\r\n<p data-start=\"313\" data-end=\"447\">Candidates must have attained the minimum required age on or before the specified date of the examination year. The key age rules are:</p>\r\n<ul data-start=\"449\" data-end=\"704\">\r\n<li data-section-id=\"oymoou\" data-start=\"449\" data-end=\"538\">The candidate must be <strong data-start=\"473\" data-end=\"498\">at least 17 years old</strong> as on or before <strong data-start=\"515\" data-end=\"537\">31st December 2026</strong>.</li>\r\n<li data-section-id=\"1jji15s\" data-start=\"539\" data-end=\"704\">This means candidates should have been born on or before:\r\n<ul data-start=\"601\" data-end=\"704\">\r\n<li data-section-id=\"1e5oile\" data-start=\"601\" data-end=\"704\"><strong data-start=\"603\" data-end=\"623\">31 December 2009</strong> (applicable for all categories including General, OBC-NCL, SC, ST, and PwBD/PwD)</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h3 data-section-id=\"ju6zwy\" data-start=\"706\" data-end=\"725\">Upper Age Limit</h3>\r\n<ul data-start=\"726\" data-end=\"891\">\r\n<li data-section-id=\"17sohia\" data-start=\"726\" data-end=\"790\">There is <strong data-start=\"737\" data-end=\"759\">no upper age limit</strong> for appearing in NEET UG 2026.</li>\r\n<li data-section-id=\"9ht9ly\" data-start=\"791\" data-end=\"891\">Candidates of any age above the minimum eligibility can apply if they meet all other requirements.</li>\r\n</ul>\r\n<h3 data-section-id=\"l90xn3\" data-start=\"893\" data-end=\"917\">Nationality Criteria</h3>\r\n<ul data-start=\"918\" data-end=\"1119\">\r\n<li data-section-id=\"8t3i22\" data-start=\"918\" data-end=\"962\"><strong data-start=\"920\" data-end=\"939\">Indian Citizens</strong> are eligible to apply.</li>\r\n<li data-section-id=\"36ocbz\" data-start=\"963\" data-end=\"1119\"><strong data-start=\"965\" data-end=\"1001\">Overseas Citizens of India (OCI)</strong> are also eligible for NEET UG, provided they meet all other admission requirements for undergraduate medical courses.</li>\r\n</ul>', 'Offline', 'MCQ', 200, 720, 1, '+4 for correct, -1 for incorrect, 0 for unattempted', NULL, 200, NULL, '<p data-start=\"35\" data-end=\"189\">The <strong data-start=\"39\" data-end=\"64\">NEET UG 2026 syllabus</strong> is officially published and made available by the competent authorities responsible for medical entrance education in India.</p>\r\n<p data-start=\"191\" data-end=\"265\">Candidates can access the detailed syllabus from the official websites of:</p>\r\n<ul data-start=\"267\" data-end=\"342\">\r\n<li data-section-id=\"1z062p9\" data-start=\"267\" data-end=\"302\"><strong data-start=\"269\" data-end=\"302\">National Testing Agency (NTA)</strong></li>\r\n<li data-section-id=\"15ddr9t\" data-start=\"303\" data-end=\"342\"><strong data-start=\"305\" data-end=\"342\">National Medical Commission (NMC)</strong></li>\r\n</ul>\r\n<p data-start=\"344\" data-end=\"519\">The syllabus is released to ensure transparency and uniformity in the examination structure and is based on the prescribed academic framework for medical entrance preparation.</p>\r\n<p data-start=\"521\" data-end=\"568\">👉 Official NMC Website: <a class=\"decorated-link\" href=\"https://www.nmc.org.in\" target=\"_new\" rel=\"noopener\" data-start=\"546\" data-end=\"568\">https://www.nmc.org.in</a></p>\r\n<p data-start=\"570\" data-end=\"748\">Candidates are advised to regularly visit the official portals of <strong data-start=\"636\" data-end=\"651\">NTA and NMC</strong> for the latest updates, revised syllabus notifications, and any changes related to NEET UG 2026.</p>', 'https://neet.nta.nic.in', '[\"<p>Physics\",\"Chemistry\",\"Biology (Botany\",\"Zoology)<\\/p>\"]', 'Moderate', NULL, 0, '<p data-start=\"225\" data-end=\"339\">The NEET UG Admit Card is issued provisionally and can be accessed online through the official examination portal.</p>\r\n<h3 data-section-id=\"yxyb7t\" data-start=\"341\" data-end=\"373\">Steps to Download Admit Card</h3>\r\n<ul data-start=\"374\" data-end=\"578\">\r\n<li data-section-id=\"16vrq51\" data-start=\"374\" data-end=\"414\">Visit the official NTA NEET website.</li>\r\n<li data-section-id=\"z1ik6o\" data-start=\"415\" data-end=\"461\">Log in using your application credentials.</li>\r\n<li data-section-id=\"1jqihqd\" data-start=\"462\" data-end=\"508\">Click on the <strong data-start=\"477\" data-end=\"505\">Admit Card download link</strong>.</li>\r\n<li data-section-id=\"14wauji\" data-start=\"509\" data-end=\"578\">Download and take a printout of the admit card for examination use.</li>\r\n</ul>\r\n<h3 data-section-id=\"1bhiq8b\" data-start=\"580\" data-end=\"606\">Important Instructions</h3>\r\n<ul data-start=\"607\" data-end=\"898\">\r\n<li data-section-id=\"10n6vy8\" data-start=\"607\" data-end=\"714\">Candidates must appear for the exam <strong data-start=\"645\" data-end=\"693\">only at the centre, date, and time mentioned</strong> on the admit card.</li>\r\n<li data-section-id=\"1gd2qvy\" data-start=\"715\" data-end=\"802\">Entry to the examination centre will <strong data-start=\"754\" data-end=\"799\">not be allowed without a valid admit card</strong>.</li>\r\n<li data-section-id=\"1y3516b\" data-start=\"803\" data-end=\"898\">The admit card is issued <strong data-start=\"830\" data-end=\"867\">subject to eligibility conditions</strong>, which will be verified later.</li>\r\n</ul>\r\n<h3 data-section-id=\"1inpl2a\" data-start=\"900\" data-end=\"930\">In Case of Download Issues</h3>\r\n<ul data-start=\"931\" data-end=\"1110\">\r\n<li data-section-id=\"o9zvb4\" data-start=\"931\" data-end=\"1110\">If unable to download the admit card, candidates should:\r\n<ul data-start=\"992\" data-end=\"1110\">\r\n<li data-section-id=\"1ywhnae\" data-start=\"992\" data-end=\"1063\">Contact the helpdesk during working hours (10:00 AM to 5:00 PM), or</li>\r\n<li data-section-id=\"yek76m\" data-start=\"1066\" data-end=\"1110\">Reach out via the official email support</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h3 data-section-id=\"161cb2e\" data-start=\"1112\" data-end=\"1136\">Discrepancy Handling</h3>\r\n<ul data-start=\"1137\" data-end=\"1387\">\r\n<li data-section-id=\"1ktrkdt\" data-start=\"1137\" data-end=\"1387\">In case of any error in details (photo, signature, or personal information):\r\n<ul data-start=\"1218\" data-end=\"1387\">\r\n<li data-section-id=\"1yqlv0d\" data-start=\"1218\" data-end=\"1254\">Immediately contact the helpdesk</li>\r\n<li data-section-id=\"191opjb\" data-start=\"1257\" data-end=\"1332\">Candidates can still appear for the exam with the downloaded admit card</li>\r\n<li data-section-id=\"ve5mjr\" data-start=\"1335\" data-end=\"1387\">Corrections will be handled by the authority later</li>\r\n</ul>\r\n</li>\r\n</ul>', '<ul>\r\n<li data-section-id=\"24ioe0\" data-start=\"525\" data-end=\"555\">Visit official NTA website</li>\r\n<li data-section-id=\"7bpd3i\" data-start=\"556\" data-end=\"580\">Click on result link</li>\r\n<li data-section-id=\"oj2rdz\" data-start=\"581\" data-end=\"625\">Enter application number &amp; date of birth</li>\r\n<li data-section-id=\"1l2w2ot\" data-start=\"626\" data-end=\"686\">Download scorecard</li>\r\n</ul>', 'Marks', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'NEET UG 2026 Exam Details, Eligibility, Pattern, Fees, Result – NTA', 'Get complete NEET UG 2026 information including eligibility, exam pattern, syllabus, application form, fees, admit card, result, and counselling details as per NTA official guidelines.', NULL, 'Exam', 'https://neet.nta.nic.in', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 1, 0, '2026-03-17 04:39:21', '2026-04-10 05:59:27', 1, '[{\"categories\":[\"General\"],\"amount\":\"1700\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"EWS\",\"OBC\"],\"amount\":\"1600\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple (varies per session, provided on official portal)'),
(14, '0b480442-868c-4c5c-8d84-12ec8183801c', 'Common University Entrance Test', 'CUET', 'common-university-entrance-test', NULL, NULL, 'National', '[\"Management\",\"Law\"]', 'National Testing Agency', 'Government', 'https://cuet.nta', '<p data-start=\"57\" data-end=\"296\">The <strong data-start=\"61\" data-end=\"103\">Common University Entrance Test (CUET)</strong> is a national-level entrance exam conducted by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">National Testing Agency</span></span> for admission to undergraduate programmes in central and other participating universities across India.</p>\r\n<p data-start=\"298\" data-end=\"584\">CUET serves as a <strong data-start=\"315\" data-end=\"344\">single-window examination</strong> for students seeking admission to multiple universities, including central, state, deemed, and private institutions. It helps streamline the admission process by allowing candidates to apply to various universities through one common test.</p>\r\n<p data-start=\"586\" data-end=\"891\">The exam is designed to provide <strong data-start=\"618\" data-end=\"670\">equal opportunities to students from all regions</strong>, especially those from rural and remote areas, by offering a standardized platform for evaluation. This ensures a fair and transparent admission process while also improving access to higher education across the country.</p>', NULL, 'External', NULL, NULL, NULL, NULL, '[\"Depends on course and university requirements (e.g., PCM, PCB, Commerce subjects, Languages, General Test)\"]', NULL, NULL, NULL, 1, NULL, 0, '<p data-start=\"70\" data-end=\"234\">To appear for the <strong data-start=\"88\" data-end=\"133\">Common University Entrance Test (CUET UG)</strong> conducted by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">National Testing Agency</span></span>, candidates must meet the following criteria:</p>\r\n<ul data-start=\"236\" data-end=\"730\">\r\n<li data-section-id=\"9y6d64\" data-start=\"236\" data-end=\"371\"><strong data-start=\"238\" data-end=\"268\">Educational Qualification:</strong> Candidates who have passed Class 12 or are <strong data-start=\"312\" data-end=\"346\">appearing for Class 12 in 2026</strong> are eligible to apply.</li>\r\n<li data-section-id=\"1dbxspq\" data-start=\"372\" data-end=\"469\"><strong data-start=\"374\" data-end=\"396\">Board Eligibility:</strong> Students from all recognized boards, including <strong data-start=\"444\" data-end=\"452\">NIOS</strong>, are eligible.</li>\r\n<li data-section-id=\"1vruuwb\" data-start=\"470\" data-end=\"537\"><strong data-start=\"472\" data-end=\"486\">Age Limit:</strong> There is <strong data-start=\"496\" data-end=\"512\">no age limit</strong> to appear for CUET UG.</li>\r\n<li data-section-id=\"14h8ntm\" data-start=\"538\" data-end=\"730\"><strong data-start=\"540\" data-end=\"568\">University Requirements:</strong> Candidates must satisfy the <strong data-start=\"597\" data-end=\"660\">specific eligibility criteria of the university/institution</strong> they are applying to (such as age or subject requirements, if any).</li>\r\n</ul>', 'Online', 'MCQ', NULL, 200, 1, '+5 for correct -1 for wrong', NULL, 60, NULL, '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\r\n<p data-start=\"31\" data-end=\"195\">The detailed syllabus for the <strong data-start=\"61\" data-end=\"111\">Common University Entrance Test (CUET UG) 2026</strong> is officially released by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">National Testing Agency</span></span> on its website.</p>\r\n<p data-start=\"197\" data-end=\"358\">Candidates can access the complete syllabus, including subject-wise topics for languages, domain subjects, and the general test, through the official link below:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">CUET UG Syllabus 2026</span></span></p>\r\n<p data-start=\"402\" data-end=\"552\">It is recommended that students carefully review the syllabus before starting their preparation to understand the exam structure and important topics.</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', 'https://cuet', '[\"<p>Language Subjects: Language to be tested through reading<br>comprehension (based on different types of passages&ndash;Factual\",\"<br>Literary\",\"and Narrative)\",\"Literary Aptitude and Vocabulary<br>Domain Subjects: As per NCERT syllabus<br>General Aptitude Test: general knowledge\",\"current affairs\",\"general<br>mental ability\",\"numerical ability\",\"quantitative reasoning (Simple<br>application of basic mathematical concepts arithmetic\\/algebra<br>geometry\\/mensuration\\/statistics)\",\"Logical and Analytical Reasoning<\\/p>\"]', 'Moderate', NULL, 0, '<p>The Admit Card would be issued provisionally to the candidates through the NTA website:<br>https://cuet.nta.nic.in subject to the fulfillment of the eligibility conditions and receipt of the<br>prescribed application fee by NTA.<br>The candidate has to download the Admit Card from the NTA website. The candidate will<br>appear in the examination at the given Centre on the date and shift/timing as indicated in<br>his/her Admit Card.<br>No candidate will be allowed to appear at the examination Centre, on the date and shift/time<br>other than that allotted to him/her in his/her Admit Card.<br>In case a candidate is unable to download his/ her Admit Card from the website, he/ she should<br>approach the NTA Help Line Number: 011-40759000 between 10.00 A.M. to 05.00 P.M.<br>The candidates are advised to read the instructions on the Admit Card carefully and strictly<br>follow them during the examination.<br>In case of any discrepancy in the particulars of the candidate or his/her photograph and<br>signature shown in the Admit Card and Confirmation Page, the candidate may immediately<br>approach the NTA Help Line between 10.00 A.M. and 5.00 P.M. In such a case, the candidate<br>would appear in the examination with the already downloaded Admit Card. However, NTA<br>will take necessary action to make corrections in the record later.<br>The date of downloading the Admit Card for the exam will be announced on the NTA website<br>https://cuet.nta.nic.in</p>', '<h4 data-start=\"238\" data-end=\"264\">Steps to Check Result</h4>\r\n<ul data-start=\"265\" data-end=\"518\">\r\n<li data-section-id=\"1nfztkt\" data-start=\"265\" data-end=\"334\">Visit the official website: <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">CUET Official Website</span></span></li>\r\n<li data-section-id=\"1m15syf\" data-start=\"335\" data-end=\"390\">Click on the <strong data-start=\"350\" data-end=\"383\">CUET UG 2026 Result/Scorecard</strong> link</li>\r\n<li data-section-id=\"1xnddl2\" data-start=\"391\" data-end=\"462\">Log in using your <strong data-start=\"411\" data-end=\"460\">application number and password/date of birth</strong></li>\r\n<li data-section-id=\"17drt6\" data-start=\"463\" data-end=\"518\">View and download your <strong data-start=\"488\" data-end=\"501\">scorecard</strong> for future use</li>\r\n</ul>\r\n<h4 data-start=\"520\" data-end=\"541\">Important Points</h4>\r\n<ul data-start=\"542\" data-end=\"871\">\r\n<li data-section-id=\"d037bk\" data-start=\"542\" data-end=\"598\">Result is prepared based on the <strong data-start=\"576\" data-end=\"596\">final answer key</strong></li>\r\n<li data-section-id=\"nnjiqu\" data-start=\"599\" data-end=\"659\"><strong data-start=\"601\" data-end=\"636\">No re-evaluation or re-checking</strong> of result is allowed</li>\r\n<li data-section-id=\"1qnnokq\" data-start=\"660\" data-end=\"726\"><strong data-start=\"662\" data-end=\"699\">No scorecard will be sent by post</strong>; download it online only</li>\r\n<li data-section-id=\"xvhhiu\" data-start=\"727\" data-end=\"812\"><strong data-start=\"729\" data-end=\"746\">No grievances</strong> regarding answer keys will be accepted after result declaration</li>\r\n<li data-section-id=\"yb83ia\" data-start=\"813\" data-end=\"871\">Marks obtained are used for preparing the final result</li>\r\n</ul>', 'Marks', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'CUET UG 2026 Exam – Dates, elig', 'CUET UG is a national-level entrance exam conducted by the National Testing Agency for admission to undergraduate programs in central and participating universities across India. Check eligibility, exam pattern, syllabus, dates, and result details.', NULL, 'educated', 'https://cuet.nta.nic.in', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-17 05:30:02', '2026-04-10 02:28:03', 1, '[{\"categories\":[\"General\"],\"amount\":\"1000\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"800\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"EWS\",\"OBC\"],\"amount\":\"900\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Not fixed (multiple gateways enabled by NTA such as SBI / HDFC / ICICI depending on session)'),
(15, '400a48fc-1857-4308-ae62-05b104f33210', 'Common Admission Test', 'CAT', 'common-admission-test', NULL, NULL, 'National', '[\"Management\"]', 'Indian Institutes of Management', 'University', 'https://iimcat.ac.in', '<p data-start=\"48\" data-end=\"382\">The <strong data-start=\"52\" data-end=\"83\">Common Admission Test (CAT)</strong> is a national-level management entrance examination conducted in India for admission into postgraduate management programmes. It is primarily used for shortlisting candidates for MBA/PGP courses offered by the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Indian Institutes of Management</span></span> and other top business schools across the country.</p>\r\n<p data-start=\"384\" data-end=\"766\">CAT is a computer-based aptitude test held once every year. It evaluates a candidate&rsquo;s abilities in areas such as quantitative aptitude, logical reasoning, data interpretation, and verbal ability. Based on CAT scores, candidates are further selected through additional stages like written ability tests, group discussions, and personal interviews conducted by respective institutes.</p>\r\n<p data-start=\"768\" data-end=\"995\">The exam is designed to assess analytical thinking, problem-solving skills, and decision-making ability required for management education. It serves as the primary gateway for admission into India&rsquo;s top management institutions.</p>', NULL, 'External', NULL, NULL, NULL, NULL, '[\"Quantitative Aptitude, Verbal Ability and Reading Comprehension\\\",\\\"Data Interpretation and Logical Reasoning\"]', NULL, NULL, NULL, 1, NULL, 0, '<p data-start=\"166\" data-end=\"479\">To appear for the Common Admission Test (CAT), candidates must meet the basic academic qualification set for management admissions in India. The exam is open to graduates from any recognised university or institution approved under Government of India norms, including deemed universities under the UGC Act, 1956.</p>\r\n<p data-start=\"481\" data-end=\"885\">A minimum academic performance is required at the undergraduate level. Candidates from General, EWS, and NC-OBC categories must secure at least 50% marks or an equivalent CGPA, while SC, ST, and PwD candidates are eligible with a minimum of 45%. The evaluation of marks follows the grading system of the respective university, and CGPA-to-percentage conversion is applied as per institutional guidelines.</p>\r\n<p data-start=\"887\" data-end=\"1224\">Students who are still completing their undergraduate degree are also allowed to apply. Such candidates are considered provisionally eligible and can take the exam in their final year. However, their admission will depend on the successful completion of their degree within the timeline specified by the respective management institutes.</p>\r\n<p data-start=\"1226\" data-end=\"1541\">Apart from traditional bachelor&rsquo;s degrees, candidates holding professional qualifications such as CA, CS, CMA (ICWA), or FIAI are also eligible, provided they meet the required percentage criteria. This ensures that applicants from diverse academic and professional backgrounds can compete for management education.</p>\r\n<p data-start=\"1543\" data-end=\"1888\">It is important to understand that meeting the eligibility criteria only allows a candidate to apply for the exam. Final shortlisting and admission decisions are made separately by the participating institutions under the guidance of the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Indian Institutes of Management</span></span>, based on overall performance in CAT and subsequent selection stages.</p>', 'Online', 'MCQ', 66, 198, 1, '+3 marks correct answer  -1 mark incorrect MCQ', NULL, 120, NULL, '<p data-start=\"38\" data-end=\"190\">The official source for all information related to the Common Admission Test (CAT) is the official website of the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Indian Institutes of Management</span></span>:</p>\r\n<p data-start=\"192\" data-end=\"217\">👉 <a class=\"decorated-link\" href=\"https://iimcat.ac.in\" target=\"_new\" rel=\"noopener\" data-start=\"195\" data-end=\"215\">https://iimcat.ac.in</a></p>', 'https://iimcat.ac.in', '[\"<p>Quantitative Aptitude\",\"Verbal Ability and Reading Comprehension\\\"\",\"\\\"Data Interpretation and Logical Reasoning<\\/p>\"]', 'Moderate', NULL, 0, '<p data-start=\"558\" data-end=\"610\">To download your admit card, follow the steps below:</p>\r\n<ul data-start=\"612\" data-end=\"905\">\r\n<li data-section-id=\"k3ihov\" data-start=\"612\" data-end=\"664\">Visit the official website: <a class=\"decorated-link\" href=\"https://iimcat.ac.in\" target=\"_new\" rel=\"noopener\" data-start=\"642\" data-end=\"662\">https://iimcat.ac.in</a></li>\r\n<li data-section-id=\"13gaj9j\" data-start=\"665\" data-end=\"704\">Open the <strong data-start=\"676\" data-end=\"702\">candidate login portal</strong></li>\r\n<li data-section-id=\"1gs6wqs\" data-start=\"705\" data-end=\"755\">Enter your <strong data-start=\"718\" data-end=\"753\">CAT application ID and password</strong></li>\r\n<li data-section-id=\"ms1twl\" data-start=\"756\" data-end=\"807\">After logging in, locate the admit card section</li>\r\n<li data-section-id=\"d39ns3\" data-start=\"808\" data-end=\"862\">Download the admit card displayed on the dashboard</li>\r\n<li data-section-id=\"6kcijl\" data-start=\"863\" data-end=\"905\">Take a clear printout for exam day use</li>\r\n</ul>', '<p data-start=\"481\" data-end=\"540\">Follow the simple process below to download your scorecard:</p>\r\n<ul data-start=\"542\" data-end=\"818\">\r\n<li data-section-id=\"k3ihov\" data-start=\"542\" data-end=\"594\">Visit the official website: <a class=\"decorated-link\" href=\"https://iimcat.ac.in\" target=\"_new\" rel=\"noopener\" data-start=\"572\" data-end=\"592\">https://iimcat.ac.in</a></li>\r\n<li data-section-id=\"1az2wtd\" data-start=\"595\" data-end=\"639\">Click on the <strong data-start=\"610\" data-end=\"629\">Candidate Login</strong> section</li>\r\n<li data-section-id=\"1ryezwk\" data-start=\"640\" data-end=\"690\">Enter your <strong data-start=\"653\" data-end=\"688\">CAT Application ID and Password</strong></li>\r\n<li data-section-id=\"137rjx7\" data-start=\"691\" data-end=\"734\">Open the <strong data-start=\"702\" data-end=\"732\">Result/Scorecard dashboard</strong></li>\r\n<li data-section-id=\"17r79gb\" data-start=\"735\" data-end=\"767\">View your CAT 2025 scorecard</li>\r\n<li data-section-id=\"n2n8um\" data-start=\"768\" data-end=\"818\">Download and save the scorecard for future use</li>\r\n</ul>', 'Percentile', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'CAT Exam 2026 – Dates, Eligibility, Pattern, Syllabus, Result', 'Common Admission Test (CAT) is a national-level MBA entrance exam conducted by the Indian Institutes of Management for admission into IIMs and top B-schools in India. Check dates, eligibility, syllabus, and results.', NULL, 'exam', 'https://iimcat.ac.in', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-19 05:06:22', '2026-04-10 03:19:52', 1, '[{\"categories\":[\"EWS\",\"General\",\"OBC\"],\"amount\":\"2600\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"PwBD\",\"SC\",\"ST\"],\"amount\":\"1300\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple gateways (e.g., BillDesk / PayU / integrated banking gateways)'),
(16, 'd8cf3396-9d79-4642-bf27-d3e0dd14a982', 'Graduate Aptitude Test in Engineering', 'GATE', 'graduate-aptitude-test-in-engineering', NULL, NULL, 'National', '[\"Engineering\"]', 'Indian Institute of Science (IISc)  Indian Institutes of Technology (IITs)', 'Government', 'https://gate2026.iitg.ac.in', NULL, NULL, 'External', NULL, NULL, NULL, NULL, '[\"Engineering Mathematics,   General Aptitude,   Core Subject (as per selected paper)\"]', NULL, NULL, NULL, 1, NULL, 0, NULL, 'Online', 'MCQ', 65, 100, 1, '1 Mark MCQ: +1 correct, -0.33 wrong  2 Mark MCQ: +2 correct, -0.66 wrong  NAT/MSQ: No negative marking', NULL, 180, NULL, NULL, 'https://gate2026.iitg.ac.in/syllabus.html', '[\"<p>Engineering Mathematics\",\"General Aptitude\",\"Computer Science Engineering\",\"Mechanical Engineering\",\"Electrical Engineering\",\"Civil Engineering\",\"Electronics and Communication Engineering\",\"Chemical Engineering\",\"Aerospace Engineering\",\"Agricultural Engineering\",\"Architecture and Planning\",\"Biomedical Engineering\",\"Biotechnology\",\"Environmental Science and Engineering\",\"Geomatics Engineering\",\"Instrumentation Engineering\",\"Mining Engineering\",\"Metallurgical Engineering\",\"Naval Architecture and Marine Engineering\",\"Petroleum Engineering\",\"Production and Industrial Engineering\",\"Textile Engineering and Fibre Science\",\"Engineering Sciences\",\"Humanities and Social Sciences\",\"Life Sciences\",\"Statistics\",\"Physics\",\"Chemistry\",\"Mathematics\",\"Data Science and Artificial Intelligence<\\/p>\"]', 'Moderate', NULL, 0, NULL, NULL, 'Marks', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'Graduate Aptitude Test in Engineering (GATE) 2026 – Exam Details, Eligibility, Syllabus, Fees', 'GATE 2026 is a national-level engineering entrance exam conducted by IITs and IISc for M.Tech admissions and PSU recruitment. Check eligibility, exam pattern, syllabus, fees, and important dates.', NULL, 'EducationalAssessment', 'https://gate2026.iitg.ac.in', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-19 23:46:28', '2026-04-09 07:20:24', 1, '[{\"categories\":[\"EWS\",\"General\",\"OBC\"],\"amount\":\"1800\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"900\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 1, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":\"500\",\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'Multiple Authorized Gateways (via official GATE Online Application Processing System - GOAPS)');
