(17, 'f5df627c-60b1-4bc8-97c3-8c5d5732353a', 'National Eligibility cum Entrance Test – Postgraduate', 'NEET PG', 'national-eligibility-cum-entrance-test-postgraduate', NULL, NULL, 'National', '[\"Medical\"]', 'National Board of Examinations in Medical Sciences', 'Government', 'https://natboard.edu.in', NULL, NULL, 'External', NULL, NULL, NULL, NULL, '[\"Pre-Clinical Subjects,   Para-Clinical Subjects,   Clinical Subjects\"]', NULL, NULL, NULL, 1, NULL, 0, NULL, 'Online', 'MCQ', 200, 800, 1, '+4 for correct answer  -1 for incorrect answer  0 for unanswered', NULL, 210, NULL, NULL, 'https://natboard.edu.in/viewnbeexam?exam=neetpg', '[\"<p>Anatomy\",\"Physiology\",\"Biochemistry\",\"Pathology\",\"Microbiology\",\"Pharmacology\",\"Forensic Medicine\",\"Social and Preventive Medicine (Community Medicine)\",\"General Medicine\",\"Dermatology Venereology and Leprosy\",\"Psychiatry\",\"General Surgery\",\"Orthopedics\",\"Anesthesiology\",\"Radiodiagnosis\",\"Obstetrics and Gynecology\",\"Pediatrics\",\"Ophthalmology\",\"Otorhinolaryngology (ENT)<\\/p>\"]', 'Moderate', NULL, 0, NULL, NULL, 'Marks', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'NEET PG 2026 – Exam Details, Eligibility, Pattern, Fees, Results', 'NEET PG 2026 is a national-level medical entrance exam conducted by NBEMS for MD/MS admissions. Check eligibility, exam pattern, syllabus, fees, results, and important dates.', NULL, 'EducationalOrganization', 'https://natboard.edu.in', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-20 00:05:24', '2026-04-09 07:19:24', 1, '[{\"categories\":[\"EWS\",\"General\",\"OBC\"],\"amount\":\"4250\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"3250\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 0, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":null,\"maximum_penalty_cap\":null,\"remarks\":null}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forfeiture_conditions\":null}]', NULL, NULL, NULL, NULL, NULL, '[\"Debit Card\",\"Credit Card\",\"Net Banking\",\"UPI\"]', 1, 'Candidate', 'SBI ePay / BillDesk (via NBEMS Portal)'),
(18, '68e1fb71-e13a-47df-bf48-ec6120334509', 'Common University Entrance Test – Postgraduate', 'CUET PG', 'common-university-entrance-test-postgraduate', NULL, NULL, 'National', '[\"Management\",\"Law\",\"School Admission\"]', 'National Testing Agency (NTA)', 'Government', 'https://exams.nta.nic.in/cuet-pg/', NULL, NULL, 'External', NULL, NULL, NULL, NULL, '[\"Relevant Undergraduate Subject (Domain Specific) ,   General Awareness ,   Language Comprehension\"]', NULL, NULL, NULL, 1, NULL, 0, NULL, 'Online', 'MCQ', 75, 300, 1, '+4 for correct answer  -1 for incorrect answer  0 for unanswered', NULL, 105, NULL, NULL, 'https://exams.nta.nic.in/cuet-pg', '[\"<p>rfeccergythufdc<\\/p>\"]', 'Moderate', NULL, 0, NULL, NULL, 'Marks', 'AIR', 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Once a Year', NULL, NULL, 0, NULL, 'CUET PG 2026 – Exam Details, Eligibility, Pattern, Fees, Results', 'CUET PG 2026 is a national-level entrance exam conducted by NTA for postgraduate admissions in central and participating universities. Check eligibility, syllabus, exam pattern, fees, and results.', NULL, 'EducationalOrganization', 'https://exams.nta.nic.in/cuet-pg/', 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, 1, 1, 'Active', 'Public', 0, 0, '2026-03-20 00:29:21', '2026-04-09 07:12:33', 1, '[{\"categories\":[\"General\"],\"amount\":\"1400\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"EWS\",\"OBC\"],\"amount\":\"1200\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null},{\"categories\":[\"SC\",\"ST\"],\"amount\":\"1100\",\"currency\":\"INR\",\"refundable\":\"No\",\"remarks\":null}]', 1, '[{\"condition\":\"Late registration\",\"penalty_type\":\"Flat\",\"penalty_amount\":\"400\",\"maximum_penalty_cap\":null,\"remarks\":\"Depends on NTA notification\"}]', 0, 0, '[{\"college_type\":\"Government\",\"quota_type\":\"All India\",\"amount\":null,\"refundable\":\"Yes\",\"refund_conditions\":null,\"forf