--
-- Dumping data for table `home_benefits`
--

INSERT INTO `home_benefits` (`id`, `title`, `icon`, `reward_amount`, `content`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(3, 'School Scholarship & Academic Support', 'images/benefits/1780230385_College Books.png', NULL, 'Students from Classes 9th to 12th can explore merit-based scholarships, academic excellence rewards, and special support programs designed to encourage bright young learners. We help students identify suitable scholarship opportunities that recognize talent, improve accessibility to quality education, and motivate academic growth from an early stage.', 0, 1, '2026-05-25 08:43:21', '2026-05-31 06:56:25'),
(4, 'Scholarships for NEET & IIT-JEE Aspirants', NULL, NULL, 'We support deserving NEET and IIT-JEE aspirants with scholarship opportunities based on academic performance, entrance exam scores, and competitive potential. From coaching support benefits to university scholarship programs, students can access financial assistance that helps reduce the burden of quality preparation and higher education expenses.', 0, 1, '2026-05-25 08:44:09', '2026-05-25 08:44:09'),
(5, 'Scholarship Guidance & Support', NULL, NULL, 'Finding the right scholarship can be confusing, but our expert counselors simplify the process for you. From eligibility checks and documentation support to application guidance and university coordination, we assist students at every step of their scholarship journey.', 0, 1, '2026-05-25 08:44:45', '2026-05-25 08:44:45'),
(6, 'Turning Hard Work into Opportunities', NULL, NULL, 'Students who perform exceptionally well in exams like JEE, NEET, CUET, CAT, NDA, and Olympiads can unlock exclusive scholarship opportunities. We help students identify institutions offering performance-based fee concessions and rewards.', 0, 1, '2026-05-25 08:49:18', '2026-05-25 08:49:18'),
(7, 'Empowering Future Women Leaders', NULL, NULL, 'Special scholarship programs are available for female students pursuing school education, undergraduate, postgraduate, and professional programs. Enrollzy supports students in identifying women-focused educational funding opportunities.', 0, 1, '2026-05-25 08:50:00', '2026-05-25 08:50:00'),
(8, 'Minority & Government Scholarship Support', NULL, NULL, 'We help students apply for central and state government scholarships, minority scholarships, and social welfare educational schemes. Our team simplifies the application and documentation process for eligible students.', 0, 1, '2026-05-25 08:50:37', '2026-05-25 08:50:37'),
(9, 'Online Degree Scholarship Programs', NULL, NULL, 'Many universities offering Online MBA, BBA, MCA, and certification programs provide scholarships and fee discounts for eligible students. Enrollzy helps students discover affordable online education options with scholarship benefits.', 0, 1, '2026-05-25 08:51:26', '2026-05-25 08:51:26');

