INSERT INTO `home_services` (`id`, `title`, `description`, `image`, `footer_text`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Discover Your Perfect Career', 'Get personalized counseling from experts to identify the right course, university, and career path based on your goals, interests, and budget.\r\n\r\nExpert Counselors\r\nPersonalized Guidance\r\nCareer Clarity', NULL, 'Get Career & Course Guidance', 0, 1, '2026-01-02 04:23:03', '2026-05-25 08:19:23'),
(2, 'Compare Universities Smartly', 'Compare universities, fees, placements, rankings, accreditations, scholarships, and student reviews — all in one place.\r\nCompare Colleges\r\nReal Insights\r\nVerified Information', NULL, 'Explore & Compare Universities', 0, 1, '2026-01-02 04:23:21', '2026-05-25 08:19:00'),
(3, 'Connect With Alumni & Experts', 'Get real insights from alumni, industry experts, and mentors before making your final admission decision.\r\n\r\nReal Experiences\r\nDirect Interaction\r\nMentorship Support', NULL, 'Talk to Alumni & Subject Experts', 0, 1, '2026-01-02 04:24:06', '2026-05-25 08:20:29'),
(4, 'Admission Assistance', 'From application forms and documentation to university communication and fee guidance — we simplify the entire admission process.\r\n\r\nDocumentation Help\r\nApplication Support\r\nHassle-Free Process', NULL, 'Complete Admission Support', 0, 1, '2026-05-25 08:21:13', '2026-05-25 08:21:13'),
(5, 'Beyond Admission', 'Our support doesn’t stop at admission. We help students with internships, career advice, skill development, and placement preparation.\r\n\r\nPlacement Guidance\r\nCareer Support\r\nLong-Term Growth', NULL, 'Career & Placement Guidance', 0, 1, '2026-05-25 08:22:33', '2026-05-25 08:22:33');

