INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(219, 66, '07985905-d41c-4ef5-9e1b-19692cba4a24', '49e8a8f2-d2e5-4b11-8054-2d811d6922b1', 221, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 05:46:38', '2026-06-16 04:35:02', '<p data-start=\"63\" data-end=\"465\">The <strong data-start=\"67\" data-end=\"107\">MCA Data Analytics admission process</strong> is structured to be simple, transparent, and fully student-friendly, ensuring that applicants can complete enrollment without confusion. Whether you are a fresh graduate, a working professional, or someone planning a shift into data-driven careers, understanding each stage helps you avoid delays, documentation errors, and missed scholarship opportunities.</p>\r\n<p data-start=\"467\" data-end=\"734\">Many students assume admission is only about filling out a form, but the complete process includes <strong data-start=\"566\" data-end=\"648\">program selection, application submission, fee payment, and final registration</strong>. Following each step carefully ensures faster approval and a smoother academic start.</p>\r\n<hr data-start=\"736\" data-end=\"739\">\r\n<h1 data-section-id=\"h8um23\" data-start=\"741\" data-end=\"768\">Step 1: Program Selection</h1>\r\n<h2 data-section-id=\"nq3tgd\" data-start=\"770\" data-end=\"818\">Choose MCA Data Analytics as Your Career Path</h2>\r\n<p data-start=\"820\" data-end=\"969\">The first step is selecting the MCA Data Analytics program based on your academic background, career goals, and interest in data-driven technologies.</p>\r\n<p data-start=\"971\" data-end=\"1026\">Before selecting the program, students should evaluate:</p>\r\n<ul data-start=\"1028\" data-end=\"1328\">\r\n<li data-section-id=\"1b5uekf\" data-start=\"1028\" data-end=\"1075\">Data Analytics curriculum and tools covered</li>\r\n<li data-section-id=\"1qoj3b7\" data-start=\"1076\" data-end=\"1126\">Career opportunities in analytics and BI roles</li>\r\n<li data-section-id=\"1hpepop\" data-start=\"1127\" data-end=\"1155\">Eligibility requirements</li>\r\n<li data-section-id=\"1fy4a4e\" data-start=\"1156\" data-end=\"1198\">Fee structure and scholarship benefits</li>\r\n<li data-section-id=\"1h9ikhm\" data-start=\"1199\" data-end=\"1241\">University recognition and credibility</li>\r\n<li data-section-id=\"1ocwh7\" data-start=\"1242\" data-end=\"1284\">Industry exposure and project learning</li>\r\n<li data-section-id=\"72480\" data-start=\"1285\" data-end=\"1328\">Learning flexibility and support system</li>\r\n</ul>\r\n<h3 data-section-id=\"6gtrn\" data-start=\"1330\" data-end=\"1351\">Practical Insight</h3>\r\n<p data-start=\"1353\" data-end=\"1503\">Choose this program if you are interested in working with data, solving business problems, generating insights, and building decision-support systems.</p>\r\n<hr data-start=\"1505\" data-end=\"1508\">\r\n<h1 data-section-id=\"6y7zmq\" data-start=\"1510\" data-end=\"1542\">Step 2: Application Completion</h1>\r\n<h2 data-section-id=\"19b0fbj\" data-start=\"1544\" data-end=\"1586\">Submit Your Application Form Accurately</h2>\r\n<p data-start=\"1588\" data-end=\"1714\">Once the program is selected, candidates must complete the online application form with correct academic and personal details.</p>\r\n<p data-start=\"1716\" data-end=\"1748\">Common details required include:</p>\r\n<ul data-start=\"1750\" data-end=\"1987\">\r\n<li data-section-id=\"rumkc6\" data-start=\"1750\" data-end=\"1787\">Full name as per official records</li>\r\n<li data-section-id=\"2mj9ql\" data-start=\"1788\" data-end=\"1825\">Active mobile number and email ID</li>\r\n<li data-section-id=\"8qcrj7\" data-start=\"1826\" data-end=\"1862\">Graduation qualification details</li>\r\n<li data-section-id=\"v2mdnn\" data-start=\"1863\" data-end=\"1889\">Academic marks or CGPA</li>\r\n<li data-section-id=\"z6r62p\" data-start=\"1890\" data-end=\"1922\">Address and identity details</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"1923\" data-end=\"1951\">Passport-size photograph</li>\r\n<li data-section-id=\"1vrt9v8\" data-start=\"1952\" data-end=\"1987\">Work experience (if applicable)</li>\r\n</ul>\r\n<h3 data-section-id=\"110ikka\" data-start=\"1989\" data-end=\"2017\">Common Mistakes to Avoid</h3>\r\n<ul data-start=\"2019\" data-end=\"2219\">\r\n<li data-section-id=\"10mdc5s\" data-start=\"2019\" data-end=\"2062\">Entering incorrect academic information</li>\r\n<li data-section-id=\"wfn249\" data-start=\"2063\" data-end=\"2105\">Uploading unclear or invalid documents</li>\r\n<li data-section-id=\"3cr5cu\" data-start=\"2106\" data-end=\"2145\">Leaving mandatory fields incomplete</li>\r\n<li data-section-id=\"1g0ia1z\" data-start=\"2146\" data-end=\"2180\">Using inactive contact details</li>\r\n<li data-section-id=\"1nx4g03\" data-start=\"2181\" data-end=\"2219\">Mismatch in name or identity proof</li>\r\n</ul>\r\n<p data-start=\"2221\" data-end=\"2275\">Even small errors can delay verification and approval.</p>\r\n<hr data-start=\"2277\" data-end=\"2280\">\r\n<h1 data-section-id=\"1hdpzj5\" data-start=\"2282\" data-end=\"2303\">Step 3: Fee Payment</h1>\r\n<h2 data-section-id=\"12a0jsc\" data-start=\"2305\" data-end=\"2335\">Confirm Your Admission Seat</h2>\r\n<p data-start=\"2337\" data-end=\"2477\">After application review, eligible candidates move to the fee payment stage. Admission is typically confirmed only after successful payment.</p>\r\n<p data-start=\"2479\" data-end=\"2517\">Available payment options may include:</p>\r\n<ul data-start=\"2519\" data-end=\"2681\">\r\n<li data-section-id=\"6e4qb7\" data-start=\"2519\" data-end=\"2547\">Full program fee payment</li>\r\n<li data-section-id=\"104c33l\" data-start=\"2548\" data-end=\"2575\">Annual installment plan</li>\r\n<li data-section-id=\"nxbx58\" data-start=\"2576\" data-end=\"2611\">Semester-wise payment structure</li>\r\n<li data-section-id=\"lq7t2u\" data-start=\"2612\" data-end=\"2640\">EMI or financing support</li>\r\n<li data-section-id=\"1gprj09\" data-start=\"2641\" data-end=\"2681\">Scholarship-adjusted payment options</li>\r\n</ul>\r\n<h3 data-section-id=\"10lnscy\" data-start=\"2683\" data-end=\"2713\">Why Timely Payment Matters</h3>\r\n<ul data-start=\"2715\" data-end=\"2867\">\r\n<li data-section-id=\"imsw8k\" data-start=\"2715\" data-end=\"2751\">Secures your seat in the program</li>\r\n<li data-section-id=\"1thiunj\" data-start=\"2752\" data-end=\"2787\">Helps lock scholarship benefits</li>\r\n<li data-section-id=\"v703tr\" data-start=\"2788\" data-end=\"2824\">Speeds up admission confirmation</li>\r\n<li data-section-id=\"1sef24u\" data-start=\"2825\" data-end=\"2867\">Avoids last-minute seat unavailability</li>\r\n</ul>\r\n<h3 data-section-id=\"lgxe1v\" data-start=\"2869\" data-end=\"2887\">Important Risk</h3>\r\n<p data-start=\"2889\" data-end=\"2986\">Delaying payment after selection may result in losing admission opportunity if seats are limited.</p>\r\n<hr data-start=\"2988\" data-end=\"2991\">\r\n<h1 data-section-id=\"1d5z8n9\" data-start=\"2993\" data-end=\"3028\">Step 4: Submission &amp; Registration</h1>\r\n<h2 data-section-id=\"hm7228\" data-start=\"3030\" data-end=\"3079\">Final Verification and Enrollment Confirmation</h2>\r\n<p data-start=\"3081\" data-end=\"3258\">The final stage includes document verification, registration approval, and student onboarding. After successful completion, students receive official confirmation of enrollment.</p>\r\n<p data-start=\"3260\" data-end=\"3290\">This stage typically includes:</p>\r\n<ul data-start=\"3292\" data-end=\"3525\">\r\n<li data-section-id=\"1k6nf5n\" data-start=\"3292\" data-end=\"3326\">Academic document verification</li>\r\n<li data-section-id=\"kxifw1\" data-start=\"3327\" data-end=\"3356\">Identity proof validation</li>\r\n<li data-section-id=\"1qa0omz\" data-start=\"3357\" data-end=\"3385\">Fee payment confirmation</li>\r\n<li data-section-id=\"n8b7e1\" data-start=\"3386\" data-end=\"3418\">Enrollment number generation</li>\r\n<li data-section-id=\"1hc2udz\" data-start=\"3419\" data-end=\"3453\">Access to student portal / LMS</li>\r\n<li data-section-id=\"ncof5j\" data-start=\"3454\" data-end=\"3493\">Orientation and academic guidelines</li>\r\n<li data-section-id=\"17v3dc4\" data-start=\"3494\" data-end=\"3525\">Course commencement details</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"3527\" data-end=\"3545\">Important Note</h3>\r\n<p data-start=\"3547\" data-end=\"3691\">Admission is considered complete only after successful verification and registration approval, not just after application submission or payment.</p>\r\n<hr data-start=\"3693\" data-end=\"3696\">\r\n<h1 data-section-id=\"130qggm\" data-start=\"3698\" data-end=\"3731\">Admission Process Summary Table</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3733\" data-end=\"4071\">\r\n<thead data-start=\"3733\" data-end=\"3769\">\r\n<tr data-start=\"3733\" data-end=\"3769\">\r\n<th class=\"\" data-start=\"3733\" data-end=\"3740\" data-col-size=\"sm\">Step</th>\r\n<th class=\"\" data-start=\"3740\" data-end=\"3758\" data-col-size=\"md\">Admission Stage</th>\r\n<th class=\"\" data-start=\"3758\" data-end=\"3769\" data-col-size=\"sm\">Purpose</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3784\" data-end=\"4071\">\r\n<tr data-start=\"3784\" data-end=\"3864\">\r\n<td data-start=\"3784\" data-end=\"3804\" data-col-size=\"sm\">Program Selection</td>\r\n<td data-col-size=\"md\" data-start=\"3804\" data-end=\"3864\">Choose MCA Data Analytics based on goals and eligibility</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"3865\" data-end=\"3939\">\r\n<td data-start=\"3865\" data-end=\"3890\" data-col-size=\"sm\">Application Completion</td>\r\n<td data-start=\"3890\" data-end=\"3939\" data-col-size=\"md\">Submit accurate academic and personal details</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"3940\" data-end=\"3996\">\r\n<td data-start=\"3940\" data-end=\"3954\" data-col-size=\"sm\">Fee Payment</td>\r\n<td data-start=\"3954\" data-end=\"3996\" data-col-size=\"md\">Confirm admission seat through payment</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"3997\" data-end=\"4071\">\r\n<td data-start=\"3997\" data-end=\"4025\" data-col-size=\"sm\">Submission &amp; Registration</td>\r\n<td data-start=\"4025\" data-end=\"4071\" data-col-size=\"md\">Complete verification and final enrollment</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"4073\" data-end=\"4076\">\r\n<h1 data-section-id=\"14s1v1v\" data-start=\"4078\" data-end=\"4098\">Documents Required</h1>\r\n<ul data-start=\"4100\" data-end=\"4338\">\r\n<li data-section-id=\"1dfca1g\" data-start=\"4100\" data-end=\"4143\">Graduation mark sheets and certificates</li>\r\n<li data-section-id=\"192hvs4\" data-start=\"4144\" data-end=\"4174\">Government-issued ID proof</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"4175\" data-end=\"4203\">Passport-size photograph</li>\r\n<li data-section-id=\"14qiub2\" data-start=\"4204\" data-end=\"4244\">Category certificate (if applicable)</li>\r\n<li data-section-id=\"bzmt3g\" data-start=\"4245\" data-end=\"4288\">Work experience documents (if required)</li>\r\n<li data-section-id=\"g172pu\" data-start=\"4289\" data-end=\"4338\">Migration or transfer certificate (if needed)</li>\r\n</ul>', 1, '<p data-start=\"76\" data-end=\"518\">To apply for the <strong data-start=\"93\" data-end=\"115\">MCA Data Analytics</strong> program, candidates must have completed a recognized undergraduate degree with a suitable academic background in computing, mathematics, statistics, programming, or analytical subjects. Since Data Analytics combines technology, business intelligence, data interpretation, predictive modeling, and decision-making tools, institutions generally prefer students with logical and quantitative fundamentals.</p>\r\n<p data-start=\"520\" data-end=\"791\">The eligibility criteria are broad and student-friendly. Both technical graduates and candidates from other academic streams may apply, provided they have studied <strong data-start=\"683\" data-end=\"748\">Mathematics, Business Mathematics, Programming, or Statistics</strong> at the <strong data-start=\"756\" data-end=\"790\">10+2 level or graduation level</strong>.</p>\r\n<p data-start=\"793\" data-end=\"1049\">This makes MCA Data Analytics an excellent option for students who want careers in <strong data-start=\"876\" data-end=\"1048\">data analysis, business intelligence, reporting, analytics consulting, AI-driven decision systems, finance analytics, marketing analytics, and enterprise strategy roles</strong>.</p>\r\n<hr data-start=\"1051\" data-end=\"1054\">\r\n<h1 data-section-id=\"15oy5s2\" data-start=\"1056\" data-end=\"1084\">Basic Eligibility Criteria</h1>\r\n<p data-start=\"1086\" data-end=\"1218\">A candidate is generally eligible for MCA Data Analytics admission if they have passed any of the following qualifying examinations:</p>\r\n<h2 data-section-id=\"gy1uve\" data-start=\"1220\" data-end=\"1280\">Directly Eligible Technical / Computer Background Degrees</h2>\r\n<ul data-start=\"1282\" data-end=\"1425\">\r\n<li data-section-id=\"1nv7qo8\" data-start=\"1282\" data-end=\"1293\"><strong data-start=\"1284\" data-end=\"1291\">BCA</strong></li>\r\n<li data-section-id=\"167rcso\" data-start=\"1294\" data-end=\"1326\"><strong data-start=\"1296\" data-end=\"1324\">B.Sc. (Computer Science)</strong></li>\r\n<li data-section-id=\"1xu7gee\" data-start=\"1327\" data-end=\"1345\"><strong data-start=\"1329\" data-end=\"1343\">B.Sc. (IT)</strong></li>\r\n<li data-section-id=\"1azmvnf\" data-start=\"1346\" data-end=\"1364\"><strong data-start=\"1348\" data-end=\"1362\">B.E. (CSE)</strong></li>\r\n<li data-section-id=\"1tg1ojo\" data-start=\"1365\" data-end=\"1386\"><strong data-start=\"1367\" data-end=\"1384\">B.Tech. (CSE)</strong></li>\r\n<li data-section-id=\"9snkpf\" data-start=\"1387\" data-end=\"1404\"><strong data-start=\"1389\" data-end=\"1402\">B.E. (IT)</strong></li>\r\n<li data-section-id=\"1kxdmrw\" data-start=\"1405\" data-end=\"1425\"><strong data-start=\"1407\" data-end=\"1423\">B.Tech. (IT)</strong></li>\r\n</ul>\r\n<p data-start=\"1427\" data-end=\"1584\">These degrees align strongly with the MCA Data Analytics curriculum because they usually include programming, systems, databases, and technical fundamentals.</p>\r\n<hr data-start=\"1586\" data-end=\"1589\">\r\n<h2 data-section-id=\"i7gacq\" data-start=\"1591\" data-end=\"1632\">Other Graduation Degrees Also Eligible</h2>\r\n<p data-start=\"1634\" data-end=\"1696\">Candidates with any graduation degree may also apply, such as:</p>\r\n<ul data-start=\"1698\" data-end=\"1775\">\r\n<li data-section-id=\"12u5hnc\" data-start=\"1698\" data-end=\"1718\"><strong data-start=\"1700\" data-end=\"1716\">B.E / B.Tech</strong></li>\r\n<li data-section-id=\"1ae8qnu\" data-start=\"1719\" data-end=\"1732\"><strong data-start=\"1721\" data-end=\"1730\">B.Sc.</strong></li>\r\n<li data-section-id=\"10juesr\" data-start=\"1733\" data-end=\"1747\"><strong data-start=\"1735\" data-end=\"1745\">B.Com.</strong></li>\r\n<li data-section-id=\"1uh53kb\" data-start=\"1748\" data-end=\"1760\"><strong data-start=\"1750\" data-end=\"1758\">B.A.</strong></li>\r\n<li data-section-id=\"1ib9f9s\" data-start=\"1761\" data-end=\"1775\"><strong data-start=\"1763\" data-end=\"1773\">B.Voc.</strong></li>\r\n</ul>\r\n<p data-start=\"1777\" data-end=\"1886\">However, they must have studied at least one of the following subjects at <strong data-start=\"1851\" data-end=\"1885\">10+2 level or graduation level</strong>:</p>\r\n<ul data-start=\"1888\" data-end=\"1959\">\r\n<li data-section-id=\"1pkuajg\" data-start=\"1888\" data-end=\"1903\">Mathematics</li>\r\n<li data-section-id=\"uhocey\" data-start=\"1904\" data-end=\"1928\">Business Mathematics</li>\r\n<li data-section-id=\"1pmqvf5\" data-start=\"1929\" data-end=\"1944\">Programming</li>\r\n<li data-section-id=\"1yq9p59\" data-start=\"1945\" data-end=\"1959\">Statistics</li>\r\n</ul>\r\n<hr data-start=\"1961\" data-end=\"1964\">\r\n<h1 data-section-id=\"1sd3qkf\" data-start=\"1966\" data-end=\"2004\">Why Subject Requirement Is Important</h1>\r\n<p data-start=\"2006\" data-end=\"2047\">Data Analytics requires understanding of:</p>\r\n<ul data-start=\"2049\" data-end=\"2223\">\r\n<li data-section-id=\"1cyz0gf\" data-start=\"2049\" data-end=\"2070\">Logical reasoning</li>\r\n<li data-section-id=\"1r2arv6\" data-start=\"2071\" data-end=\"2096\">Mathematical thinking</li>\r\n<li data-section-id=\"1axw9p5\" data-start=\"2097\" data-end=\"2127\">Statistical interpretation</li>\r\n<li data-section-id=\"px6g3m\" data-start=\"2128\" data-end=\"2152\">Programming concepts</li>\r\n<li data-section-id=\"11mjqd3\" data-start=\"2153\" data-end=\"2170\">Data handling</li>\r\n<li data-section-id=\"1gr79z7\" data-start=\"2171\" data-end=\"2199\">Business problem solving</li>\r\n<li data-section-id=\"10w4njb\" data-start=\"2200\" data-end=\"2223\">Pattern recognition</li>\r\n</ul>\r\n<p data-start=\"2225\" data-end=\"2323\">Students with prior mathematics or programming exposure generally adapt faster and perform better.</p>\r\n<hr data-start=\"2325\" data-end=\"2328\">\r\n<h1 data-section-id=\"65wtjx\" data-start=\"2330\" data-end=\"2365\">Recognized University Requirement</h1>\r\n<p data-start=\"2367\" data-end=\"2444\">The qualifying degree must be from a <strong data-start=\"2404\" data-end=\"2443\">recognized University / Institution</strong>.</p>\r\n<p data-start=\"2446\" data-end=\"2486\">Accepted institutions generally include:</p>\r\n<ul data-start=\"2488\" data-end=\"2710\">\r\n<li data-section-id=\"kiq5ue\" data-start=\"2488\" data-end=\"2519\">UGC-recognized universities</li>\r\n<li data-section-id=\"tucsj\" data-start=\"2520\" data-end=\"2552\">Government-approved colleges</li>\r\n<li data-section-id=\"4nik9f\" data-start=\"2553\" data-end=\"2601\">AICTE-approved institutions where applicable</li>\r\n<li data-section-id=\"1m4v6vg\" data-start=\"2602\" data-end=\"2637\">Accredited private institutions</li>\r\n<li data-section-id=\"wmukpo\" data-start=\"2638\" data-end=\"2710\">Recognized international institutions (subject to equivalency norms)</li>\r\n</ul>\r\n<p data-start=\"2712\" data-end=\"2790\">Degrees from unrecognized institutions may face rejection during verification.</p>\r\n<hr data-start=\"2792\" data-end=\"2795\">\r\n<h1 data-section-id=\"1pvmaxh\" data-start=\"2797\" data-end=\"2829\">Can Final-Year Students Apply?</h1>\r\n<p data-start=\"2831\" data-end=\"3009\">In many institutions, students who are <strong data-start=\"2870\" data-end=\"2915\">appearing in the final year of graduation</strong> may apply provisionally, subject to submission of final results within the required timeline.</p>\r\n<p data-start=\"3011\" data-end=\"3082\">This helps candidates secure admission without losing an academic year.</p>\r\n<hr data-start=\"3084\" data-end=\"3087\">\r\n<h1 data-section-id=\"1myqik1\" data-start=\"3089\" data-end=\"3126\">NIOS Eligibility (Where Applicable)</h1>\r\n<p data-start=\"3128\" data-end=\"3403\">Candidates who completed <strong data-start=\"3153\" data-end=\"3213\">10+2 through NIOS (National Institute of Open Schooling)</strong> are generally eligible if the qualification is recognized and they meet the required subject criteria such as Mathematics, Business Mathematics, Programming, or Statistics where applicable.</p>\r\n<p data-start=\"3405\" data-end=\"3448\">Institution-specific rules may still apply.</p>\r\n<hr data-start=\"3450\" data-end=\"3453\">\r\n<h1 data-section-id=\"3o9f9i\" data-start=\"3455\" data-end=\"3497\">Who Should Apply for MCA Data Analytics?</h1>\r\n<p data-start=\"3499\" data-end=\"3525\">This program is ideal for:</p>\r\n<ul data-start=\"3527\" data-end=\"3856\">\r\n<li data-section-id=\"q7n3ox\" data-start=\"3527\" data-end=\"3570\">BCA graduates seeking analytics careers</li>\r\n<li data-section-id=\"1sgtgng\" data-start=\"3571\" data-end=\"3624\">Students interested in data-driven business roles</li>\r\n<li data-section-id=\"1wce7w9\" data-start=\"3625\" data-end=\"3689\">Commerce graduates with mathematics background entering tech</li>\r\n<li data-section-id=\"vj4e9p\" data-start=\"3690\" data-end=\"3736\">Graduates wanting BI and reporting careers</li>\r\n<li data-section-id=\"180s0ku\" data-start=\"3737\" data-end=\"3792\">Working professionals planning analytics upskilling</li>\r\n<li data-section-id=\"1tepg8g\" data-start=\"3793\" data-end=\"3856\">Candidates interested in future-ready decision-making roles</li>\r\n</ul>', '<p data-start=\"61\" data-end=\"434\">The total <strong data-start=\"71\" data-end=\"112\">Online MCA Data Analytics Program Fee</strong> is <strong data-start=\"116\" data-end=\"132\">INR 1,55,000</strong>. With a <strong data-start=\"141\" data-end=\"171\">25% Early Bird Scholarship</strong>, eligible learners can reduce the payable amount to <strong data-start=\"224\" data-end=\"240\">INR 1,16,250</strong>. This makes the program more accessible for students and working professionals aiming to build careers in data analysis, business intelligence, reporting, and data-driven decision-making roles.</p>\r\n<p data-start=\"436\" data-end=\"676\">Flexible payment options are available, allowing learners to choose annual or semester-wise payments based on financial convenience. Easy financing options further help reduce upfront financial pressure and support smooth academic planning.</p>\r\n<hr data-start=\"678\" data-end=\"681\">\r\n<h1 data-section-id=\"j6hpqa\" data-start=\"683\" data-end=\"713\">Complete Fee Structure Table</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"715\" data-end=\"875\">\r\n<thead data-start=\"715\" data-end=\"741\">\r\n<tr data-start=\"715\" data-end=\"741\">\r\n<th class=\"\" data-start=\"715\" data-end=\"731\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"731\" data-end=\"741\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"753\" data-end=\"875\">\r\n<tr data-start=\"753\" data-end=\"792\">\r\n<td data-start=\"753\" data-end=\"776\" data-col-size=\"sm\">Original Program Fee</td>\r\n<td data-start=\"776\" data-end=\"792\" data-col-size=\"sm\">INR 1,55,000</td>\r\n</tr>\r\n<tr data-start=\"793\" data-end=\"838\">\r\n<td data-start=\"793\" data-end=\"824\" data-col-size=\"sm\">Early Bird Scholarship (25%)</td>\r\n<td data-col-size=\"sm\" data-start=\"824\" data-end=\"838\">INR 38,750</td>\r\n</tr>\r\n<tr data-start=\"839\" data-end=\"875\">\r\n<td data-start=\"839\" data-end=\"859\" data-col-size=\"sm\">Final Payable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"859\" data-end=\"875\">INR 1,16,250</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"877\" data-end=\"880\">\r\n<h1 data-section-id=\"1u2ohqe\" data-start=\"882\" data-end=\"905\">Annual Payment Option</h1>\r\n<p data-start=\"907\" data-end=\"1003\">Students who prefer yearly payments can divide the total fee across the duration of the program.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1005\" data-end=\"1125\">\r\n<thead data-start=\"1005\" data-end=\"1044\">\r\n<tr data-start=\"1005\" data-end=\"1044\">\r\n<th class=\"\" data-start=\"1005\" data-end=\"1020\" data-col-size=\"sm\">Payment Mode</th>\r\n<th class=\"\" data-start=\"1020\" data-end=\"1034\" data-col-size=\"sm\">Calculation</th>\r\n<th class=\"\" data-start=\"1034\" data-end=\"1044\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1060\" data-end=\"1125\">\r\n<tr data-start=\"1060\" data-end=\"1125\">\r\n<td data-start=\"1060\" data-end=\"1077\" data-col-size=\"sm\">Annual Payment</td>\r\n<td data-col-size=\"sm\" data-start=\"1077\" data-end=\"1102\">INR 1,16,250 &divide; 2 Years</td>\r\n<td data-col-size=\"sm\" data-start=\"1102\" data-end=\"1125\">INR 58,125 per year</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1omkccn\" data-start=\"1127\" data-end=\"1140\">Best For:</h3>\r\n<ul data-start=\"1142\" data-end=\"1335\">\r\n<li data-section-id=\"1ja0g5o\" data-start=\"1142\" data-end=\"1190\">Working professionals managing yearly income</li>\r\n<li data-section-id=\"14yahk5\" data-start=\"1191\" data-end=\"1239\">Students preferring fewer installment cycles</li>\r\n<li data-section-id=\"wci4g6\" data-start=\"1240\" data-end=\"1292\">Learners comfortable with medium payment amounts</li>\r\n<li data-section-id=\"4uewfr\" data-start=\"1293\" data-end=\"1335\">Candidates wanting simple fee planning</li>\r\n</ul>\r\n<hr data-start=\"1337\" data-end=\"1340\">\r\n<h1 data-section-id=\"jh0q5t\" data-start=\"1342\" data-end=\"1367\">Semester Payment Option</h1>\r\n<p data-start=\"1369\" data-end=\"1457\">Students who prefer smaller and structured payments can choose the semester-wise option.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1459\" data-end=\"1590\">\r\n<thead data-start=\"1459\" data-end=\"1498\">\r\n<tr data-start=\"1459\" data-end=\"1498\">\r\n<th class=\"\" data-start=\"1459\" data-end=\"1474\" data-col-size=\"sm\">Payment Mode</th>\r\n<th class=\"\" data-start=\"1474\" data-end=\"1488\" data-col-size=\"sm\">Calculation</th>\r\n<th class=\"\" data-start=\"1488\" data-end=\"1498\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1514\" data-end=\"1590\">\r\n<tr data-start=\"1514\" data-end=\"1590\">\r\n<td data-start=\"1514\" data-end=\"1533\" data-col-size=\"sm\">Semester Payment</td>\r\n<td data-start=\"1533\" data-end=\"1562\" data-col-size=\"sm\">INR 1,16,250 &divide; 4 Semesters</td>\r\n<td data-col-size=\"sm\" data-start=\"1562\" data-end=\"1590\">INR 29,063 per semester*</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1592\" data-end=\"1637\">*Rounded figure based on provided breakdown.</p>\r\n<h3 data-section-id=\"1omkccn\" data-start=\"1639\" data-end=\"1652\">Best For:</h3>\r\n<ul data-start=\"1654\" data-end=\"1846\">\r\n<li data-section-id=\"baqx39\" data-start=\"1654\" data-end=\"1694\">Students with limited upfront budget</li>\r\n<li data-section-id=\"mr3u2f\" data-start=\"1695\" data-end=\"1744\">Learners balancing studies and part-time work</li>\r\n<li data-section-id=\"l461ye\" data-start=\"1745\" data-end=\"1794\">Candidates preferring flexible payment cycles</li>\r\n<li data-section-id=\"zsrz7i\" data-start=\"1795\" data-end=\"1846\">Students planning gradual financial commitments</li>\r\n</ul>\r\n<hr data-start=\"1848\" data-end=\"1851\">\r\n<h1 data-section-id=\"1571yuk\" data-start=\"1853\" data-end=\"1887\">Easy Financing Options Available</h1>\r\n<p data-start=\"1889\" data-end=\"1988\">Easy financing options allow learners to start the program without paying the full fee immediately.</p>\r\n<p data-start=\"1990\" data-end=\"2013\">Key advantages include:</p>\r\n<ul data-start=\"2015\" data-end=\"2220\">\r\n<li data-section-id=\"1gd1xij\" data-start=\"2015\" data-end=\"2051\">Reduced upfront financial burden</li>\r\n<li data-section-id=\"7ece41\" data-start=\"2052\" data-end=\"2099\">Monthly or structured repayment flexibility</li>\r\n<li data-section-id=\"1mkqqjx\" data-start=\"2100\" data-end=\"2137\">Easier access to higher education</li>\r\n<li data-section-id=\"2hd2p1\" data-start=\"2138\" data-end=\"2175\">Support for working professionals</li>\r\n<li data-section-id=\"1oxj0au\" data-start=\"2176\" data-end=\"2220\">Better financial planning during studies</li>\r\n</ul>\r\n<p data-start=\"2222\" data-end=\"2332\">Students should carefully review EMI terms, tenure, and applicable charges before selecting financing options.</p>\r\n<hr data-start=\"2334\" data-end=\"2337\">\r\n<h1 data-section-id=\"1n1khd3\" data-start=\"2339\" data-end=\"2376\"><span style=\"font-size: 16px;\">Scholarship Advantage Students Should Not Miss</span></h1>\r\n<p data-start=\"3007\" data-end=\"3118\">The <strong data-start=\"3011\" data-end=\"3041\">25% Early Bird Scholarship</strong> significantly reduces the total payable fee and provides meaningful savings.</p>\r\n<h3 data-section-id=\"1rmz6m4\" data-start=\"3120\" data-end=\"3142\">Important Insight:</h3>\r\n<p data-start=\"3144\" data-end=\"3345\">Many students delay admission decisions and lose scholarship benefits once deadlines or limited seats are closed. Early application can directly reduce financial burden and secure admission advantages.</p>', 'Medium', '<p data-start=\"52\" data-end=\"466\">The <strong data-start=\"56\" data-end=\"87\">MCA Data Analytics syllabus</strong> is designed to build strong foundations in programming, databases, algorithms, and software systems, followed by advanced specialization in data analytics, artificial intelligence, cloud computing, full stack development, and agentic AI systems. The curriculum is structured to develop both technical expertise and analytical thinking required for modern data-driven industries.</p>\r\n<p data-start=\"468\" data-end=\"755\">Students gradually progress from core computer science fundamentals to advanced tools used in real-world analytics, machine learning, cloud platforms, and enterprise decision-making systems. The inclusion of <strong data-start=\"676\" data-end=\"720\">live industry projects and capstone work</strong> ensures strong practical exposure.</p>\r\n<hr data-start=\"757\" data-end=\"760\">\r\n<h1 data-section-id=\"161c587\" data-start=\"762\" data-end=\"815\">Semester 1: Core Programming and System Foundations</h1>\r\n<p data-start=\"817\" data-end=\"939\">The first semester focuses on building strong technical fundamentals in computing, programming, and system-level concepts.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"941\" data-end=\"957\">Core Subjects</h2>\r\n<ul data-start=\"959\" data-end=\"1110\">\r\n<li data-section-id=\"krx66d\" data-start=\"959\" data-end=\"998\">Advanced Database Management System</li>\r\n<li data-section-id=\"63nldo\" data-start=\"999\" data-end=\"1029\">Advanced Computer Networks</li>\r\n<li data-section-id=\"1wpy0ld\" data-start=\"1030\" data-end=\"1049\">Web Programming</li>\r\n<li data-section-id=\"dq3gv9\" data-start=\"1050\" data-end=\"1072\">Python Programming</li>\r\n<li data-section-id=\"n1dfbx\" data-start=\"1073\" data-end=\"1110\">Network Security and Cryptography</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"1112\" data-end=\"1137\">Key Learning Outcomes</h3>\r\n<p data-start=\"1139\" data-end=\"1173\">Students develop a strong base in:</p>\r\n<ul data-start=\"1175\" data-end=\"1394\">\r\n<li data-section-id=\"1evqo8h\" data-start=\"1175\" data-end=\"1217\">Database design and management systems</li>\r\n<li data-section-id=\"p2fjyc\" data-start=\"1218\" data-end=\"1268\">Networking principles and communication models</li>\r\n<li data-section-id=\"1px4521\" data-start=\"1269\" data-end=\"1325\">Python programming for data and software development</li>\r\n<li data-section-id=\"7bhlij\" data-start=\"1326\" data-end=\"1352\">Web application basics</li>\r\n<li data-section-id=\"1ymxolx\" data-start=\"1353\" data-end=\"1394\">Cryptography and secure system design</li>\r\n</ul>\r\n<h3 data-section-id=\"de0ac2\" data-start=\"1396\" data-end=\"1410\">Importance</h3>\r\n<p data-start=\"1412\" data-end=\"1530\">This semester builds the foundation required for data handling, analytics systems, and secure application development.</p>\r\n<hr data-start=\"1532\" data-end=\"1535\">\r\n<h1 data-section-id=\"1ksz08y\" data-start=\"1537\" data-end=\"1592\">Semester 2: Algorithms, Web Development, and Security</h1>\r\n<p data-start=\"1594\" data-end=\"1705\">This stage focuses on improving problem-solving skills and building advanced software development capabilities.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"1707\" data-end=\"1723\">Core Subjects</h2>\r\n<ul data-start=\"1725\" data-end=\"1868\">\r\n<li data-section-id=\"15hea6s\" data-start=\"1725\" data-end=\"1758\">Advanced Internet Programming</li>\r\n<li data-section-id=\"1gmgtti\" data-start=\"1759\" data-end=\"1796\">Design and Analysis of Algorithms</li>\r\n<li data-section-id=\"h4aufl\" data-start=\"1797\" data-end=\"1817\">Software Testing</li>\r\n<li data-section-id=\"1bti781\" data-start=\"1818\" data-end=\"1849\">Web Application Development</li>\r\n<li data-section-id=\"1fqz05t\" data-start=\"1850\" data-end=\"1868\">Cyber Security</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"1870\" data-end=\"1895\">Key Learning Outcomes</h3>\r\n<p data-start=\"1897\" data-end=\"1924\">Students gain expertise in:</p>\r\n<ul data-start=\"1926\" data-end=\"2115\">\r\n<li data-section-id=\"17mkt53\" data-start=\"1926\" data-end=\"1975\">Algorithm design and performance optimization</li>\r\n<li data-section-id=\"1hquxv1\" data-start=\"1976\" data-end=\"2013\">Web-based application development</li>\r\n<li data-section-id=\"7378ta\" data-start=\"2014\" data-end=\"2045\">Software testing techniques</li>\r\n<li data-section-id=\"bnudet\" data-start=\"2046\" data-end=\"2076\">Cybersecurity fundamentals</li>\r\n<li data-section-id=\"ohu5rz\" data-start=\"2077\" data-end=\"2115\">Internet-based system architecture</li>\r\n</ul>\r\n<h3 data-section-id=\"6slual\" data-start=\"2117\" data-end=\"2139\">Industry Relevance</h3>\r\n<p data-start=\"2141\" data-end=\"2228\">These skills are essential for developing scalable and secure data-driven applications.</p>\r\n<hr data-start=\"2230\" data-end=\"2233\">\r\n<h1 data-section-id=\"ozuiig\" data-start=\"2235\" data-end=\"2299\">Semester 3: Specialization Electives (Advanced Learning Phase)</h1>\r\n<p data-start=\"2301\" data-end=\"2367\">Students choose specialization tracks based on their career goals.</p>\r\n<hr data-start=\"2369\" data-end=\"2372\">\r\n<h2 data-section-id=\"n0ovgf\" data-start=\"2374\" data-end=\"2402\">Elective: Cloud Computing</h2>\r\n<ul data-start=\"2404\" data-end=\"2571\">\r\n<li data-section-id=\"e3tz8y\" data-start=\"2404\" data-end=\"2439\">Introduction to Cloud Computing</li>\r\n<li data-section-id=\"z35m9n\" data-start=\"2440\" data-end=\"2479\">Introduction to Amazon Web Services</li>\r\n<li data-section-id=\"50es40\" data-start=\"2480\" data-end=\"2524\">Introduction to Microsoft Azure Services</li>\r\n<li data-section-id=\"qfu68\" data-start=\"2525\" data-end=\"2546\">Cloud Programming</li>\r\n<li data-section-id=\"1wghzna\" data-start=\"2547\" data-end=\"2571\">Cloud Virtualization</li>\r\n</ul>\r\n<hr data-start=\"2573\" data-end=\"2576\">\r\n<h2 data-section-id=\"5ij3gw\" data-start=\"2578\" data-end=\"2613\">Elective: Full Stack Development</h2>\r\n<ul data-start=\"2615\" data-end=\"2762\">\r\n<li data-section-id=\"1lrzfvm\" data-start=\"2615\" data-end=\"2643\">HTML, CSS and JavaScript</li>\r\n<li data-section-id=\"66h9g0\" data-start=\"2644\" data-end=\"2682\">User Interface, Experience, Design</li>\r\n<li data-section-id=\"kh95vq\" data-start=\"2683\" data-end=\"2720\">DevOps - I (GIT, Jenkins, Docker)</li>\r\n<li data-section-id=\"1m5i25u\" data-start=\"2721\" data-end=\"2746\">Software Architecture</li>\r\n<li data-section-id=\"1kcertv\" data-start=\"2747\" data-end=\"2762\">Prototyping</li>\r\n</ul>\r\n<hr data-start=\"2764\" data-end=\"2767\">\r\n<h2 data-section-id=\"15vkyns\" data-start=\"2769\" data-end=\"2796\">Elective: Data Analytics</h2>\r\n<ul data-start=\"2798\" data-end=\"2929\">\r\n<li data-section-id=\"1tnj0ho\" data-start=\"2798\" data-end=\"2829\">Data Analytics Using Python</li>\r\n<li data-section-id=\"joccm3\" data-start=\"2830\" data-end=\"2856\">SQL for Data Analytics</li>\r\n<li data-section-id=\"1vn7mxa\" data-start=\"2857\" data-end=\"2874\">Web Analytics</li>\r\n<li data-section-id=\"17ahacg\" data-start=\"2875\" data-end=\"2902\">Digital Media Analytics</li>\r\n<li data-section-id=\"wjtwpj\" data-start=\"2903\" data-end=\"2929\">IoT and Data Analytics</li>\r\n</ul>\r\n<hr data-start=\"2931\" data-end=\"2934\">\r\n<h2 data-section-id=\"1mlgjbr\" data-start=\"2936\" data-end=\"2993\">Elective: Artificial Intelligence and Machine Learning</h2>\r\n<ul data-start=\"2995\" data-end=\"3186\">\r\n<li data-section-id=\"a8w6kq\" data-start=\"2995\" data-end=\"3025\">Machine Learning in Python</li>\r\n<li data-section-id=\"1d3wgsk\" data-start=\"3026\" data-end=\"3071\">Statistics and Python in Machine Learning</li>\r\n<li data-section-id=\"1w2soy4\" data-start=\"3072\" data-end=\"3116\">Business Application of Machine Learning</li>\r\n<li data-section-id=\"178w2gh\" data-start=\"3117\" data-end=\"3142\">Deep Learning and NLP</li>\r\n<li data-section-id=\"umbds8\" data-start=\"3143\" data-end=\"3186\">Web, Social Analytics and Visualization</li>\r\n</ul>\r\n<hr data-start=\"3188\" data-end=\"3191\">\r\n<h2 data-section-id=\"s8vgrp\" data-start=\"3193\" data-end=\"3216\">Elective: Agentic AI</h2>\r\n<ul data-start=\"3218\" data-end=\"3451\">\r\n<li data-section-id=\"adczt8\" data-start=\"3218\" data-end=\"3252\">Advanced NLP &amp; Language Models</li>\r\n<li data-section-id=\"131lztq\" data-start=\"3253\" data-end=\"3289\">Agentic AI &amp; Multi-Agent Systems</li>\r\n<li data-section-id=\"xqzbbb\" data-start=\"3290\" data-end=\"3329\">RAG Systems &amp; Knowledge Engineering</li>\r\n<li data-section-id=\"19r3z69\" data-start=\"3330\" data-end=\"3366\">Large Language Model Engineering</li>\r\n<li data-section-id=\"qz0x4h\" data-start=\"3367\" data-end=\"3451\">AI for FinTech including fraud detection, UPI systems, and compliance frameworks</li>\r\n</ul>\r\n<hr data-start=\"3453\" data-end=\"3456\">\r\n<h1 data-section-id=\"6c8r0y\" data-start=\"3458\" data-end=\"3510\">Semester 4: Advanced Systems and Capstone Projects</h1>\r\n<p data-start=\"3512\" data-end=\"3602\">The final semester focuses on advanced technologies and real-world project implementation.</p>\r\n<hr data-start=\"3604\" data-end=\"3607\">\r\n<h2 data-section-id=\"n0ovgf\" data-start=\"3609\" data-end=\"3637\">Elective: Cloud Computing</h2>\r\n<ul data-start=\"3639\" data-end=\"3790\">\r\n<li data-section-id=\"mweeh1\" data-start=\"3639\" data-end=\"3680\">Introduction to Google Cloud Services</li>\r\n<li data-section-id=\"1t319gq\" data-start=\"3681\" data-end=\"3719\">Introduction to IBM Cloud Services</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"3720\" data-end=\"3790\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>\r\n<hr data-start=\"3792\" data-end=\"3795\">\r\n<h2 data-section-id=\"5ij3gw\" data-start=\"3797\" data-end=\"3832\">Elective: Full Stack Development</h2>\r\n<ul data-start=\"3834\" data-end=\"4003\">\r\n<li data-section-id=\"kvr4wd\" data-start=\"3834\" data-end=\"3890\">Web Services (REST API, ReactJS, NodeJS Development)</li>\r\n<li data-section-id=\"4ujrhk\" data-start=\"3891\" data-end=\"3932\">DevOps - II (Ansible, Puppet, Nagios)</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"3933\" data-end=\"4003\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>\r\n<hr data-start=\"4005\" data-end=\"4008\">\r\n<h2 data-section-id=\"15vkyns\" data-start=\"4010\" data-end=\"4037\">Elective: Data Analytics</h2>\r\n<ul data-start=\"4039\" data-end=\"4175\">\r\n<li data-section-id=\"ptona2\" data-start=\"4039\" data-end=\"4065\">Data Analytics using R</li>\r\n<li data-section-id=\"mbnmv6\" data-start=\"4066\" data-end=\"4104\">Data Analytics for Decision Making</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"4105\" data-end=\"4175\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>\r\n<hr data-start=\"4177\" data-end=\"4180\">\r\n<h2 data-section-id=\"1mlgjbr\" data-start=\"4182\" data-end=\"4239\">Elective: Artificial Intelligence and Machine Learning</h2>\r\n<ul data-start=\"4241\" data-end=\"4366\">\r\n<li data-section-id=\"wllkrt\" data-start=\"4241\" data-end=\"4260\">Big Data Hadoop</li>\r\n<li data-section-id=\"11xowef\" data-start=\"4261\" data-end=\"4295\">AI for Enterprise Applications</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"4296\" data-end=\"4366\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>\r\n<hr data-start=\"4368\" data-end=\"4371\">\r\n<h2 data-section-id=\"s8vgrp\" data-start=\"4373\" data-end=\"4396\">Elective: Agentic AI</h2>\r\n<ul data-start=\"4398\" data-end=\"4578\">\r\n<li data-section-id=\"c6ky5t\" data-start=\"4398\" data-end=\"4442\">AI Governance, Ethics &amp; Research Methods</li>\r\n<li data-section-id=\"vsuxwh\" data-start=\"4443\" data-end=\"4507\">AI Product Management (Strategy, Road Mapping, Go-to-Market)</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"4508\" data-end=\"4578\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 155000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(220, 66, '07985905-d41c-4ef5-9e1b-19692cba4a24', '49e8a8f2-d2e5-4b11-8054-2d811d6922b1', 222, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 05:58:59', '2026-06-16 04:35:38', '<p data-start=\"62\" data-end=\"519\">The <strong data-start=\"66\" data-end=\"105\">MCA in Agentic AI admission process</strong> is designed to be simple, structured, and fully student-friendly so that applicants can complete their enrollment smoothly without confusion. Since Agentic AI is an advanced specialization focused on autonomous AI systems, large language models, and intelligent agents, the admission process ensures that only eligible candidates with the right academic background are guided through a clear step-by-step pathway.</p>\r\n<p data-start=\"521\" data-end=\"743\">Whether you are a graduate from computer science, IT, or even a non-technical background with mathematics or programming exposure, following each stage carefully is important for successful admission and timely enrollment.</p>\r\n<hr data-start=\"745\" data-end=\"748\">\r\n<h1 data-section-id=\"h8um23\" data-start=\"750\" data-end=\"777\">Step 1: Program Selection</h1>\r\n<h2 data-section-id=\"1lqa93b\" data-start=\"779\" data-end=\"826\">Choose MCA in Agentic AI as Your Career Path</h2>\r\n<p data-start=\"828\" data-end=\"1001\">The first step involves selecting the MCA in Agentic AI program based on your academic background, technical interest, and long-term career goals in artificial intelligence.</p>\r\n<p data-start=\"1003\" data-end=\"1068\">Before selecting the program, students should carefully evaluate:</p>\r\n<ul data-start=\"1070\" data-end=\"1428\">\r\n<li data-section-id=\"srrj3o\" data-start=\"1070\" data-end=\"1120\">Curriculum depth in Agentic AI and LLM systems</li>\r\n<li data-section-id=\"10374m7\" data-start=\"1121\" data-end=\"1188\">Career opportunities in AI, automation, and intelligent systems</li>\r\n<li data-section-id=\"anijfi\" data-start=\"1189\" data-end=\"1242\">Eligibility requirements and academic suitability</li>\r\n<li data-section-id=\"1g62qvx\" data-start=\"1243\" data-end=\"1291\">Program structure and specialization options</li>\r\n<li data-section-id=\"fe2zor\" data-start=\"1292\" data-end=\"1338\">Fee structure and scholarship availability</li>\r\n<li data-section-id=\"1dnojbr\" data-start=\"1339\" data-end=\"1387\">Industry exposure and project-based learning</li>\r\n<li data-section-id=\"1efzkyj\" data-start=\"1388\" data-end=\"1428\">Future scope in AI-driven industries</li>\r\n</ul>\r\n<h3 data-section-id=\"6gtrn\" data-start=\"1430\" data-end=\"1451\">Practical Insight</h3>\r\n<p data-start=\"1453\" data-end=\"1634\">This program should be chosen by students interested in building autonomous AI systems, intelligent agents, and advanced machine learning applications used in real-world industries.</p>\r\n<hr data-start=\"1636\" data-end=\"1639\">\r\n<h1 data-section-id=\"6y7zmq\" data-start=\"1641\" data-end=\"1673\">Step 2: Application Completion</h1>\r\n<h2 data-section-id=\"1265uyk\" data-start=\"1675\" data-end=\"1714\">Fill the Application Form Accurately</h2>\r\n<p data-start=\"1716\" data-end=\"1841\">After selecting the program, candidates must complete the online application form with correct academic and personal details.</p>\r\n<p data-start=\"1843\" data-end=\"1881\">Typical information required includes:</p>\r\n<ul data-start=\"1883\" data-end=\"2131\">\r\n<li data-section-id=\"14xaij8\" data-start=\"1883\" data-end=\"1922\">Full name as per official documents</li>\r\n<li data-section-id=\"2mj9ql\" data-start=\"1923\" data-end=\"1960\">Active mobile number and email ID</li>\r\n<li data-section-id=\"8qcrj7\" data-start=\"1961\" data-end=\"1997\">Graduation qualification details</li>\r\n<li data-section-id=\"avpx26\" data-start=\"1998\" data-end=\"2025\">Academic scores or CGPA</li>\r\n<li data-section-id=\"1q7hpk1\" data-start=\"2026\" data-end=\"2058\">Identity and address details</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"2059\" data-end=\"2087\">Passport-size photograph</li>\r\n<li data-section-id=\"jt0oae\" data-start=\"2088\" data-end=\"2131\">Work experience details (if applicable)</li>\r\n</ul>\r\n<h3 data-section-id=\"110ikka\" data-start=\"2133\" data-end=\"2161\">Common Mistakes to Avoid</h3>\r\n<ul data-start=\"2163\" data-end=\"2380\">\r\n<li data-section-id=\"depdnm\" data-start=\"2163\" data-end=\"2202\">Entering incorrect academic records</li>\r\n<li data-section-id=\"wfn249\" data-start=\"2203\" data-end=\"2245\">Uploading unclear or invalid documents</li>\r\n<li data-section-id=\"3cr5cu\" data-start=\"2246\" data-end=\"2285\">Leaving mandatory fields incomplete</li>\r\n<li data-section-id=\"17wbpjd\" data-start=\"2286\" data-end=\"2324\">Using inactive contact information</li>\r\n<li data-section-id=\"5pn9pm\" data-start=\"2325\" data-end=\"2380\">Mismatch between application and official documents</li>\r\n</ul>\r\n<p data-start=\"2382\" data-end=\"2446\">Even minor errors can delay verification and admission approval.</p>\r\n<hr data-start=\"2448\" data-end=\"2451\">\r\n<h1 data-section-id=\"1hdpzj5\" data-start=\"2453\" data-end=\"2474\">Step 3: Fee Payment</h1>\r\n<h2 data-section-id=\"rx0ucw\" data-start=\"2476\" data-end=\"2519\">Confirm Your Seat Through Fee Submission</h2>\r\n<p data-start=\"2521\" data-end=\"2636\">Once the application is reviewed and approved, candidates must proceed with fee payment to confirm their admission.</p>\r\n<p data-start=\"2638\" data-end=\"2676\">Available payment options may include:</p>\r\n<ul data-start=\"2678\" data-end=\"2844\">\r\n<li data-section-id=\"6e4qb7\" data-start=\"2678\" data-end=\"2706\">Full program fee payment</li>\r\n<li data-section-id=\"104c33l\" data-start=\"2707\" data-end=\"2734\">Annual installment plan</li>\r\n<li data-section-id=\"nxbx58\" data-start=\"2735\" data-end=\"2770\">Semester-wise payment structure</li>\r\n<li data-section-id=\"frpj3d\" data-start=\"2771\" data-end=\"2799\">EMI or financing options</li>\r\n<li data-section-id=\"1n3cee6\" data-start=\"2800\" data-end=\"2844\">Scholarship-based discounted fee payment</li>\r\n</ul>\r\n<h3 data-section-id=\"1fg0bqg\" data-start=\"2846\" data-end=\"2876\">Why This Step Is Important</h3>\r\n<ul data-start=\"2878\" data-end=\"3051\">\r\n<li data-section-id=\"imsw8k\" data-start=\"2878\" data-end=\"2914\">Secures your seat in the program</li>\r\n<li data-section-id=\"133daxb\" data-start=\"2915\" data-end=\"2959\">Activates admission confirmation process</li>\r\n<li data-section-id=\"1h6weql\" data-start=\"2960\" data-end=\"3006\">Locks scholarship benefits (if applicable)</li>\r\n<li data-section-id=\"584anp\" data-start=\"3007\" data-end=\"3051\">Ensures priority enrollment in the batch</li>\r\n</ul>\r\n<h3 data-section-id=\"lgxe1v\" data-start=\"3053\" data-end=\"3071\">Important Risk</h3>\r\n<p data-start=\"3073\" data-end=\"3185\">Delaying fee payment after selection may lead to loss of admission opportunity due to limited seat availability.</p>\r\n<hr data-start=\"3187\" data-end=\"3190\">\r\n<h1 data-section-id=\"1d5z8n9\" data-start=\"3192\" data-end=\"3227\">Step 4: Submission &amp; Registration</h1>\r\n<h2 data-section-id=\"oglye3\" data-start=\"3229\" data-end=\"3276\">Final Verification and Enrollment Completion</h2>\r\n<p data-start=\"3278\" data-end=\"3386\">The final stage includes document verification, registration approval, and official enrollment confirmation.</p>\r\n<p data-start=\"3388\" data-end=\"3418\">This stage generally includes:</p>\r\n<ul data-start=\"3420\" data-end=\"3664\">\r\n<li data-section-id=\"1asjco1\" data-start=\"3420\" data-end=\"3458\">Verification of academic documents</li>\r\n<li data-section-id=\"kxifw1\" data-start=\"3459\" data-end=\"3488\">Identity proof validation</li>\r\n<li data-section-id=\"njcple\" data-start=\"3489\" data-end=\"3520\">Confirmation of fee payment</li>\r\n<li data-section-id=\"1vw9fgg\" data-start=\"3521\" data-end=\"3556\">Generation of enrollment number</li>\r\n<li data-section-id=\"18oc9mt\" data-start=\"3557\" data-end=\"3592\">Access to student portal or LMS</li>\r\n<li data-section-id=\"ncof5j\" data-start=\"3593\" data-end=\"3632\">Orientation and academic guidelines</li>\r\n<li data-section-id=\"17v3dc4\" data-start=\"3633\" data-end=\"3664\">Course commencement details</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"3666\" data-end=\"3684\">Important Note</h3>\r\n<p data-start=\"3686\" data-end=\"3822\">Admission is considered fully confirmed only after successful verification and registration, not just application submission or payment.</p>\r\n<hr data-start=\"3824\" data-end=\"3827\">\r\n<h1 data-section-id=\"130qggm\" data-start=\"3829\" data-end=\"3862\">Admission Process Summary Table</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3864\" data-end=\"4208\">\r\n<thead data-start=\"3864\" data-end=\"3900\">\r\n<tr data-start=\"3864\" data-end=\"3900\">\r\n<th class=\"\" data-start=\"3864\" data-end=\"3871\" data-col-size=\"sm\">Step</th>\r\n<th class=\"\" data-start=\"3871\" data-end=\"3889\" data-col-size=\"md\">Admission Stage</th>\r\n<th class=\"\" data-start=\"3889\" data-end=\"3900\" data-col-size=\"sm\">Purpose</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3915\" data-end=\"4208\">\r\n<tr data-start=\"3915\" data-end=\"4001\">\r\n<td data-start=\"3915\" data-end=\"3935\" data-col-size=\"sm\">Program Selection</td>\r\n<td data-col-size=\"md\" data-start=\"3935\" data-end=\"4001\">Choose MCA in Agentic AI based on career goals and eligibility</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"4002\" data-end=\"4076\">\r\n<td data-start=\"4002\" data-end=\"4027\" data-col-size=\"sm\">Application Completion</td>\r\n<td data-start=\"4027\" data-end=\"4076\" data-col-size=\"md\">Submit accurate academic and personal details</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"4077\" data-end=\"4133\">\r\n<td data-start=\"4077\" data-end=\"4091\" data-col-size=\"sm\">Fee Payment</td>\r\n<td data-start=\"4091\" data-end=\"4133\" data-col-size=\"md\">Confirm admission seat through payment</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n<tr data-start=\"4134\" data-end=\"4208\">\r\n<td data-start=\"4134\" data-end=\"4162\" data-col-size=\"sm\">Submission &amp; Registration</td>\r\n<td data-col-size=\"md\" data-start=\"4162\" data-end=\"4208\">Complete verification and final enrollment</td>\r\n<td data-col-size=\"sm\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"4210\" data-end=\"4213\">\r\n<h1 data-section-id=\"1gxi2kh\" data-start=\"4215\" data-end=\"4249\">Documents Required for Admission</h1>\r\n<ul data-start=\"4251\" data-end=\"4493\">\r\n<li data-section-id=\"1dfca1g\" data-start=\"4251\" data-end=\"4294\">Graduation mark sheets and certificates</li>\r\n<li data-section-id=\"192hvs4\" data-start=\"4295\" data-end=\"4325\">Government-issued ID proof</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"4326\" data-end=\"4354\">Passport-size photograph</li>\r\n<li data-section-id=\"14qiub2\" data-start=\"4355\" data-end=\"4395\">Category certificate (if applicable)</li>\r\n<li data-section-id=\"bzmt3g\" data-start=\"4396\" data-end=\"4439\">Work experience documents (if required)</li>\r\n<li data-section-id=\"19emrj8\" data-start=\"4440\" data-end=\"4493\">Migration or transfer certificate (if applicable)</li>\r\n</ul>', 1, '<p data-start=\"72\" data-end=\"487\">The <strong data-start=\"76\" data-end=\"102\">MCA Agentic AI program</strong> is designed for students who want to build advanced careers in artificial intelligence systems, autonomous AI agents, large language models, and next-generation intelligent applications. Since Agentic AI involves deep integration of programming, mathematics, data systems, and logical reasoning, candidates must have a suitable academic background in computing or analytical subjects.</p>\r\n<p data-start=\"489\" data-end=\"843\">The eligibility structure is inclusive, allowing both technical and non-technical graduates to apply, provided they have studied <strong data-start=\"618\" data-end=\"683\">Mathematics, Business Mathematics, Programming, or Statistics</strong> at the <strong data-start=\"691\" data-end=\"725\">10+2 level or graduation level</strong>. This ensures that students have the essential logical and quantitative foundation required for advanced AI learning.</p>\r\n<hr data-start=\"845\" data-end=\"848\">\r\n<h1 data-section-id=\"15oy5s2\" data-start=\"850\" data-end=\"878\">Basic Eligibility Criteria</h1>\r\n<p data-start=\"880\" data-end=\"992\">A candidate is eligible for MCA Agentic AI admission if they have completed any of the following qualifications:</p>\r\n<h2 data-section-id=\"g228c\" data-start=\"994\" data-end=\"1032\">Directly Eligible Technical Degrees</h2>\r\n<ul data-start=\"1034\" data-end=\"1289\">\r\n<li data-section-id=\"1k4c9de\" data-start=\"1034\" data-end=\"1081\"><strong data-start=\"1036\" data-end=\"1079\">BCA (Bachelor of Computer Applications)</strong></li>\r\n<li data-section-id=\"167rcso\" data-start=\"1082\" data-end=\"1114\"><strong data-start=\"1084\" data-end=\"1112\">B.Sc. (Computer Science)</strong></li>\r\n<li data-section-id=\"awfuy9\" data-start=\"1115\" data-end=\"1153\"><strong data-start=\"1117\" data-end=\"1151\">B.Sc. (Information Technology)</strong></li>\r\n<li data-section-id=\"1djeuoy\" data-start=\"1154\" data-end=\"1203\"><strong data-start=\"1156\" data-end=\"1201\">B.E. (CSE &ndash; Computer Science Engineering)</strong></li>\r\n<li data-section-id=\"1tg1ojo\" data-start=\"1204\" data-end=\"1225\"><strong data-start=\"1206\" data-end=\"1223\">B.Tech. (CSE)</strong></li>\r\n<li data-section-id=\"1qw1yzu\" data-start=\"1226\" data-end=\"1268\"><strong data-start=\"1228\" data-end=\"1266\">B.E. (IT &ndash; Information Technology)</strong></li>\r\n<li data-section-id=\"1kxdmrw\" data-start=\"1269\" data-end=\"1289\"><strong data-start=\"1271\" data-end=\"1287\">B.Tech. (IT)</strong></li>\r\n</ul>\r\n<p data-start=\"1291\" data-end=\"1453\">These degrees are most suitable because they already include programming, algorithms, data structures, and system design fundamentals required for AI development.</p>\r\n<hr data-start=\"1455\" data-end=\"1458\">\r\n<h2 data-section-id=\"qrrj17\" data-start=\"1460\" data-end=\"1496\">Other Eligible Graduation Degrees</h2>\r\n<p data-start=\"1498\" data-end=\"1575\">Candidates from any recognized undergraduate program can also apply, such as:</p>\r\n<ul data-start=\"1577\" data-end=\"1721\">\r\n<li data-section-id=\"xh7eur\" data-start=\"1577\" data-end=\"1610\"><strong data-start=\"1579\" data-end=\"1608\">B.E / B.Tech (any stream)</strong></li>\r\n<li data-section-id=\"14kgz2f\" data-start=\"1611\" data-end=\"1641\"><strong data-start=\"1613\" data-end=\"1639\">B.Sc. (any discipline)</strong></li>\r\n<li data-section-id=\"lne3ax\" data-start=\"1642\" data-end=\"1666\"><strong data-start=\"1644\" data-end=\"1664\">B.Com (Commerce)</strong></li>\r\n<li data-section-id=\"hqq9xs\" data-start=\"1667\" data-end=\"1685\"><strong data-start=\"1669\" data-end=\"1683\">B.A (Arts)</strong></li>\r\n<li data-section-id=\"k8gr0y\" data-start=\"1686\" data-end=\"1721\"><strong data-start=\"1688\" data-end=\"1719\">B.Voc (Vocational programs)</strong></li>\r\n</ul>\r\n<p data-start=\"1723\" data-end=\"1839\">However, they must have studied at least one of the following subjects either at <strong data-start=\"1804\" data-end=\"1838\">10+2 level or graduation level</strong>:</p>\r\n<ul data-start=\"1841\" data-end=\"1912\">\r\n<li data-section-id=\"1pkuajg\" data-start=\"1841\" data-end=\"1856\">Mathematics</li>\r\n<li data-section-id=\"uhocey\" data-start=\"1857\" data-end=\"1881\">Business Mathematics</li>\r\n<li data-section-id=\"1pmqvf5\" data-start=\"1882\" data-end=\"1897\">Programming</li>\r\n<li data-section-id=\"1yq9p59\" data-start=\"1898\" data-end=\"1912\">Statistics</li>\r\n</ul>\r\n<hr data-start=\"1914\" data-end=\"1917\">\r\n<h1 data-section-id=\"1opvaxr\" data-start=\"1919\" data-end=\"1972\">Why Subject Requirement Is Important for Agentic AI</h1>\r\n<p data-start=\"1974\" data-end=\"2171\">Agentic AI is an advanced domain that involves building intelligent systems capable of autonomous decision-making, reasoning, and task execution. To succeed in this field, students must understand:</p>\r\n<ul data-start=\"2173\" data-end=\"2389\">\r\n<li data-section-id=\"tqgvtw\" data-start=\"2173\" data-end=\"2214\">Logical reasoning and problem-solving</li>\r\n<li data-section-id=\"1myivfv\" data-start=\"2215\" data-end=\"2256\">Mathematical modeling and probability</li>\r\n<li data-section-id=\"1gpcjwl\" data-start=\"2257\" data-end=\"2285\">Programming fundamentals</li>\r\n<li data-section-id=\"221mdl\" data-start=\"2286\" data-end=\"2320\">Data structures and algorithms</li>\r\n<li data-section-id=\"1p7xbpd\" data-start=\"2321\" data-end=\"2345\">Statistical analysis</li>\r\n<li data-section-id=\"1udpc37\" data-start=\"2346\" data-end=\"2389\">AI system behavior and automation logic</li>\r\n</ul>\r\n<p data-start=\"2391\" data-end=\"2472\">Without these foundations, understanding autonomous AI systems becomes difficult.</p>\r\n<hr data-start=\"2474\" data-end=\"2477\">\r\n<h1 data-section-id=\"65wtjx\" data-start=\"2479\" data-end=\"2514\">Recognized University Requirement</h1>\r\n<p data-start=\"2516\" data-end=\"2603\">The qualifying degree must be obtained from a <strong data-start=\"2562\" data-end=\"2602\">recognized University or Institution</strong>.</p>\r\n<p data-start=\"2605\" data-end=\"2645\">Accepted institutions generally include:</p>\r\n<ul data-start=\"2647\" data-end=\"2879\">\r\n<li data-section-id=\"yu27h9\" data-start=\"2647\" data-end=\"2676\">UGC-approved universities</li>\r\n<li data-section-id=\"1ye6vtz\" data-start=\"2677\" data-end=\"2737\">AICTE-recognized technical institutes (where applicable)</li>\r\n<li data-section-id=\"tucsj\" data-start=\"2738\" data-end=\"2770\">Government-approved colleges</li>\r\n<li data-section-id=\"5svyyx\" data-start=\"2771\" data-end=\"2806\">Accredited private universities</li>\r\n<li data-section-id=\"wmukpo\" data-start=\"2807\" data-end=\"2879\">Recognized international institutions (subject to equivalency norms)</li>\r\n</ul>\r\n<p data-start=\"2881\" data-end=\"2978\">Degrees from unrecognized institutions may not be considered valid during admission verification.</p>\r\n<hr data-start=\"2980\" data-end=\"2983\">\r\n<h1 data-section-id=\"1pvmaxh\" data-start=\"2985\" data-end=\"3017\">Can Final-Year Students Apply?</h1>\r\n<p data-start=\"3019\" data-end=\"3206\">In many institutions, students who are <strong data-start=\"3058\" data-end=\"3103\">appearing in the final year of graduation</strong> are allowed to apply provisionally, provided they submit final results within the prescribed timeline.</p>\r\n<p data-start=\"3208\" data-end=\"3299\">This allows students to secure admission early without waiting for final degree completion.</p>\r\n<hr data-start=\"3301\" data-end=\"3304\">\r\n<h1 data-section-id=\"1myqik1\" data-start=\"3306\" data-end=\"3343\">NIOS Eligibility (Where Applicable)</h1>\r\n<p data-start=\"3345\" data-end=\"3598\">Candidates who completed their <strong data-start=\"3376\" data-end=\"3436\">10+2 through NIOS (National Institute of Open Schooling)</strong> are generally eligible, provided the qualification is recognized and includes required subjects such as Mathematics, Programming, or Statistics where applicable.</p>\r\n<p data-start=\"3600\" data-end=\"3668\">Final eligibility confirmation may depend on institutional approval.</p>\r\n<hr data-start=\"3670\" data-end=\"3673\">\r\n<h1 data-section-id=\"13ohem3\" data-start=\"3675\" data-end=\"3713\">Who Should Apply for MCA Agentic AI?</h1>\r\n<p data-start=\"3715\" data-end=\"3860\">This program is ideal for candidates who want to build careers in next-generation AI technologies, especially autonomous and intelligent systems.</p>\r\n<p data-start=\"3862\" data-end=\"3878\">Best suited for:</p>\r\n<ul data-start=\"3880\" data-end=\"4193\">\r\n<li data-section-id=\"eiljzv\" data-start=\"3880\" data-end=\"3951\">Students interested in Artificial Intelligence and Machine Learning</li>\r\n<li data-section-id=\"3dt2pc\" data-start=\"3952\" data-end=\"3999\">Graduates aiming for AI engineering careers</li>\r\n<li data-section-id=\"1gjj0zy\" data-start=\"4000\" data-end=\"4058\">Programmers who want to shift into advanced AI systems</li>\r\n<li data-section-id=\"1t0c3ur\" data-start=\"4059\" data-end=\"4123\">Working professionals upgrading into AI and automation roles</li>\r\n<li data-section-id=\"1c0zocd\" data-start=\"4124\" data-end=\"4193\">Learners interested in Large Language Models (LLMs) and AI agents</li>\r\n</ul>', '<p data-start=\"68\" data-end=\"406\">The <strong data-start=\"72\" data-end=\"100\">Online MCA in Agentic AI</strong> program is designed for students aiming to build advanced careers in artificial intelligence, autonomous agents, large language models, and next-generation AI systems. The total program fee is <strong data-start=\"294\" data-end=\"310\">INR 1,55,000</strong>, which becomes significantly more affordable after applying the <strong data-start=\"375\" data-end=\"405\">25% Early Bird Scholarship</strong>.</p>\r\n<p data-start=\"408\" data-end=\"626\">After scholarship benefits, the effective payable fee is reduced to <strong data-start=\"476\" data-end=\"492\">INR 1,16,250</strong>, making it a structured and value-driven investment for learners entering one of the fastest-growing technology domains in the world.</p>\r\n<p data-start=\"628\" data-end=\"813\">This fee structure is designed to support both students and working professionals through flexible payment options, ensuring financial convenience without compromising learning quality.</p>\r\n<hr data-start=\"815\" data-end=\"818\">\r\n<h1 data-section-id=\"1ttj5j9\" data-start=\"820\" data-end=\"844\">Detailed Fee Structure</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"846\" data-end=\"1006\">\r\n<thead data-start=\"846\" data-end=\"872\">\r\n<tr data-start=\"846\" data-end=\"872\">\r\n<th class=\"\" data-start=\"846\" data-end=\"862\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"862\" data-end=\"872\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"884\" data-end=\"1006\">\r\n<tr data-start=\"884\" data-end=\"923\">\r\n<td data-start=\"884\" data-end=\"907\" data-col-size=\"sm\">Original Program Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"907\" data-end=\"923\">INR 1,55,000</td>\r\n</tr>\r\n<tr data-start=\"924\" data-end=\"969\">\r\n<td data-start=\"924\" data-end=\"955\" data-col-size=\"sm\">Early Bird Scholarship (25%)</td>\r\n<td data-start=\"955\" data-end=\"969\" data-col-size=\"sm\">INR 38,750</td>\r\n</tr>\r\n<tr data-start=\"970\" data-end=\"1006\">\r\n<td data-start=\"970\" data-end=\"990\" data-col-size=\"sm\">Final Payable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"990\" data-end=\"1006\">INR 1,16,250</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1008\" data-end=\"1011\">\r\n<h1 data-section-id=\"1grkqba\" data-start=\"1013\" data-end=\"1034\">Annual Payment Plan</h1>\r\n<p data-start=\"1036\" data-end=\"1184\">Students who prefer long-term financial planning can opt for annual payments. This option divides the total payable fee across the program duration.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1186\" data-end=\"1306\">\r\n<thead data-start=\"1186\" data-end=\"1225\">\r\n<tr data-start=\"1186\" data-end=\"1225\">\r\n<th class=\"\" data-start=\"1186\" data-end=\"1201\" data-col-size=\"sm\">Payment Mode</th>\r\n<th class=\"\" data-start=\"1201\" data-end=\"1215\" data-col-size=\"sm\">Calculation</th>\r\n<th class=\"\" data-start=\"1215\" data-end=\"1225\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1241\" data-end=\"1306\">\r\n<tr data-start=\"1241\" data-end=\"1306\">\r\n<td data-start=\"1241\" data-end=\"1258\" data-col-size=\"sm\">Annual Payment</td>\r\n<td data-col-size=\"sm\" data-start=\"1258\" data-end=\"1283\">INR 1,16,250 &divide; 2 Years</td>\r\n<td data-col-size=\"sm\" data-start=\"1283\" data-end=\"1306\">INR 58,125 per year</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1gwypbx\" data-start=\"1308\" data-end=\"1328\">Best Suited For:</h3>\r\n<ul data-start=\"1330\" data-end=\"1548\">\r\n<li data-section-id=\"p1pnn8\" data-start=\"1330\" data-end=\"1381\">Working professionals with steady yearly income</li>\r\n<li data-section-id=\"1bawdpo\" data-start=\"1382\" data-end=\"1426\">Students preferring fewer payment cycles</li>\r\n<li data-section-id=\"1ycj575\" data-start=\"1427\" data-end=\"1494\">Learners comfortable with larger but less frequent installments</li>\r\n<li data-section-id=\"g9ub12\" data-start=\"1495\" data-end=\"1548\">Candidates planning long-term financial budgeting</li>\r\n</ul>\r\n<hr data-start=\"1550\" data-end=\"1553\">\r\n<h1 data-section-id=\"tacoox\" data-start=\"1555\" data-end=\"1578\">Semester Payment Plan</h1>\r\n<p data-start=\"1580\" data-end=\"1695\">For learners who prefer smaller and more manageable payments, the semester-wise option offers flexibility and ease.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1697\" data-end=\"1828\">\r\n<thead data-start=\"1697\" data-end=\"1736\">\r\n<tr data-start=\"1697\" data-end=\"1736\">\r\n<th class=\"\" data-start=\"1697\" data-end=\"1712\" data-col-size=\"sm\">Payment Mode</th>\r\n<th class=\"\" data-start=\"1712\" data-end=\"1726\" data-col-size=\"sm\">Calculation</th>\r\n<th class=\"\" data-start=\"1726\" data-end=\"1736\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1752\" data-end=\"1828\">\r\n<tr data-start=\"1752\" data-end=\"1828\">\r\n<td data-start=\"1752\" data-end=\"1771\" data-col-size=\"sm\">Semester Payment</td>\r\n<td data-start=\"1771\" data-end=\"1800\" data-col-size=\"sm\">INR 1,16,250 &divide; 4 Semesters</td>\r\n<td data-col-size=\"sm\" data-start=\"1800\" data-end=\"1828\">INR 29,063 per semester*</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1830\" data-end=\"1873\">*Rounded based on structured fee division.</p>\r\n<h3 data-section-id=\"1gwypbx\" data-start=\"1875\" data-end=\"1895\">Best Suited For:</h3>\r\n<ul data-start=\"1897\" data-end=\"2092\">\r\n<li data-section-id=\"3frej5\" data-start=\"1897\" data-end=\"1942\">Students managing limited monthly budgets</li>\r\n<li data-section-id=\"129fv7h\" data-start=\"1943\" data-end=\"1995\">Learners balancing education with part-time work</li>\r\n<li data-section-id=\"17o6f2t\" data-start=\"1996\" data-end=\"2047\">Candidates preferring phased financial planning</li>\r\n<li data-section-id=\"v1t0j3\" data-start=\"2048\" data-end=\"2092\">Those seeking flexible payment structure</li>\r\n</ul>\r\n<hr data-start=\"2094\" data-end=\"2097\">\r\n<h1 data-section-id=\"fnir2t\" data-start=\"2099\" data-end=\"2123\">Easy Financing Options</h1>\r\n<p data-start=\"2125\" data-end=\"2343\">To make the <strong data-start=\"2137\" data-end=\"2158\">MCA in Agentic AI</strong> program more accessible, easy financing options may be available. These options help reduce upfront financial pressure and allow students to focus on learning advanced AI technologies.</p>\r\n<h3 data-section-id=\"1vyi0sv\" data-start=\"2345\" data-end=\"2362\">Key Benefits:</h3>\r\n<ul data-start=\"2364\" data-end=\"2580\">\r\n<li data-section-id=\"1juc81q\" data-start=\"2364\" data-end=\"2402\">Reduced immediate financial burden</li>\r\n<li data-section-id=\"zws5uu\" data-start=\"2403\" data-end=\"2435\">Flexible repayment schedules</li>\r\n<li data-section-id=\"u3l6hz\" data-start=\"2436\" data-end=\"2477\">Easier access to premium AI education</li>\r\n<li data-section-id=\"h3oblu\" data-start=\"2478\" data-end=\"2535\">Support for working professionals and fresh graduates</li>\r\n<li data-section-id=\"1oxj0au\" data-start=\"2536\" data-end=\"2580\">Better financial planning during studies</li>\r\n</ul>\r\n<p data-start=\"2582\" data-end=\"2707\">Before opting for financing, students should carefully understand repayment terms, interest rates, and applicable conditions.</p>\r\n<h1 data-section-id=\"1d34ndw\" data-start=\"2714\" data-end=\"2754\">Scholarship Advantage You Should Not Miss</h1>\r\n<p data-start=\"3391\" data-end=\"3482\">The <strong data-start=\"3395\" data-end=\"3425\">25% Early Bird Scholarship</strong> plays a crucial role in reducing overall education cost.</p>\r\n<h3 data-section-id=\"1rmz6m4\" data-start=\"3484\" data-end=\"3506\">Important Insight:</h3>\r\n<p data-start=\"3508\" data-end=\"3714\">Early applicants not only secure admission priority but also maximize financial savings. Delaying application may result in missing scholarship benefits due to limited-time availability or seat constraints.</p>', 'Medium', '<p data-start=\"51\" data-end=\"472\">The <strong data-start=\"55\" data-end=\"85\">MCA in Agentic AI syllabus</strong> is designed for learners aiming to build advanced careers in artificial intelligence systems, autonomous AI agents, large language models (LLMs), and enterprise-grade intelligent applications. This curriculum combines strong foundations in computer science with cutting-edge AI technologies that are shaping the future of automation, decision-making systems, and digital transformation.</p>\r\n<p data-start=\"474\" data-end=\"714\">Unlike traditional MCA programs, this specialization focuses heavily on <strong data-start=\"546\" data-end=\"677\">Agentic AI systems, LLM engineering, retrieval-augmented generation (RAG), AI governance, and real-world AI product development</strong>, ensuring strong industry readiness.</p>\r\n<hr data-start=\"716\" data-end=\"719\">\r\n<h1 data-section-id=\"7idefk\" data-start=\"721\" data-end=\"761\">Semester 1: Core Computing Foundations</h1>\r\n<p data-start=\"763\" data-end=\"905\">The first semester builds essential knowledge in programming, databases, networking, and system security required for advanced AI development.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"907\" data-end=\"923\">Core Subjects</h2>\r\n<ul data-start=\"925\" data-end=\"1076\">\r\n<li data-section-id=\"krx66d\" data-start=\"925\" data-end=\"964\">Advanced Database Management System</li>\r\n<li data-section-id=\"63nldo\" data-start=\"965\" data-end=\"995\">Advanced Computer Networks</li>\r\n<li data-section-id=\"1wpy0ld\" data-start=\"996\" data-end=\"1015\">Web Programming</li>\r\n<li data-section-id=\"dq3gv9\" data-start=\"1016\" data-end=\"1038\">Python Programming</li>\r\n<li data-section-id=\"n1dfbx\" data-start=\"1039\" data-end=\"1076\">Network Security and Cryptography</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"1078\" data-end=\"1103\">Key Learning Outcomes</h3>\r\n<p data-start=\"1105\" data-end=\"1144\">Students develop strong foundations in:</p>\r\n<ul data-start=\"1146\" data-end=\"1364\">\r\n<li data-section-id=\"1r05jva\" data-start=\"1146\" data-end=\"1194\">Database architecture and management systems</li>\r\n<li data-section-id=\"27434o\" data-start=\"1195\" data-end=\"1234\">Network communication and protocols</li>\r\n<li data-section-id=\"3yrk1u\" data-start=\"1235\" data-end=\"1279\">Python programming for AI and automation</li>\r\n<li data-section-id=\"1h64788\" data-start=\"1280\" data-end=\"1318\">Web application development basics</li>\r\n<li data-section-id=\"m9vjux\" data-start=\"1319\" data-end=\"1364\">Cryptography and cybersecurity principles</li>\r\n</ul>\r\n<h3 data-section-id=\"de0ac2\" data-start=\"1366\" data-end=\"1380\">Importance</h3>\r\n<p data-start=\"1382\" data-end=\"1510\">This semester prepares students for handling structured data, secure systems, and programming logic required in AI environments.</p>\r\n<hr data-start=\"1512\" data-end=\"1515\">\r\n<h1 data-section-id=\"7rpz47\" data-start=\"1517\" data-end=\"1574\">Semester 2: Algorithms, Applications, and Cybersecurity</h1>\r\n<p data-start=\"1576\" data-end=\"1700\">This stage strengthens software engineering concepts and introduces advanced application development and security practices.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"1702\" data-end=\"1718\">Core Subjects</h2>\r\n<ul data-start=\"1720\" data-end=\"1863\">\r\n<li data-section-id=\"15hea6s\" data-start=\"1720\" data-end=\"1753\">Advanced Internet Programming</li>\r\n<li data-section-id=\"1gmgtti\" data-start=\"1754\" data-end=\"1791\">Design and Analysis of Algorithms</li>\r\n<li data-section-id=\"h4aufl\" data-start=\"1792\" data-end=\"1812\">Software Testing</li>\r\n<li data-section-id=\"1bti781\" data-start=\"1813\" data-end=\"1844\">Web Application Development</li>\r\n<li data-section-id=\"1fqz05t\" data-start=\"1845\" data-end=\"1863\">Cyber Security</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"1865\" data-end=\"1890\">Key Learning Outcomes</h3>\r\n<p data-start=\"1892\" data-end=\"1919\">Students gain expertise in:</p>\r\n<ul data-start=\"1921\" data-end=\"2100\">\r\n<li data-section-id=\"16yulj3\" data-start=\"1921\" data-end=\"1958\">Algorithm design and optimization</li>\r\n<li data-section-id=\"w5lzja\" data-start=\"1959\" data-end=\"1997\">Secure web application development</li>\r\n<li data-section-id=\"1u8kal6\" data-start=\"1998\" data-end=\"2032\">Software testing methodologies</li>\r\n<li data-section-id=\"17tqb0e\" data-start=\"2033\" data-end=\"2061\">Cybersecurity frameworks</li>\r\n<li data-section-id=\"ohu5rz\" data-start=\"2062\" data-end=\"2100\">Internet-based system architecture</li>\r\n</ul>\r\n<h3 data-section-id=\"6slual\" data-start=\"2102\" data-end=\"2124\">Industry Relevance</h3>\r\n<p data-start=\"2126\" data-end=\"2221\">These skills are critical for building scalable, secure, and efficient AI-powered applications.</p>\r\n<hr data-start=\"2223\" data-end=\"2226\">\r\n<h1 data-section-id=\"1cwkxzf\" data-start=\"2228\" data-end=\"2276\">Semester 3: Advanced Agentic AI Specialization</h1>\r\n<p data-start=\"2278\" data-end=\"2376\">This semester focuses on core Agentic AI systems, language models, and enterprise AI applications.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"2378\" data-end=\"2394\">Core Subjects</h2>\r\n<ul data-start=\"2396\" data-end=\"2630\">\r\n<li data-section-id=\"4mafa7\" data-start=\"2396\" data-end=\"2429\">Advanced NLP &amp; Language Model</li>\r\n<li data-section-id=\"131lztq\" data-start=\"2430\" data-end=\"2466\">Agentic AI &amp; Multi-Agent Systems</li>\r\n<li data-section-id=\"xqzbbb\" data-start=\"2467\" data-end=\"2506\">RAG Systems &amp; Knowledge Engineering</li>\r\n<li data-section-id=\"19r3z69\" data-start=\"2507\" data-end=\"2543\">Large Language Model Engineering</li>\r\n<li data-section-id=\"1fytm5q\" data-start=\"2544\" data-end=\"2630\">AI for FinTech (fraud detection, UPI systems, India Stack agents, DPDP compliance)</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"2632\" data-end=\"2657\">Key Learning Outcomes</h3>\r\n<p data-start=\"2659\" data-end=\"2674\">Students learn:</p>\r\n<ul data-start=\"2676\" data-end=\"2929\">\r\n<li data-section-id=\"lwjit2\" data-start=\"2676\" data-end=\"2728\">Natural Language Processing (NLP) for AI systems</li>\r\n<li data-section-id=\"1a4rhzm\" data-start=\"2729\" data-end=\"2763\">Designing autonomous AI agents</li>\r\n<li data-section-id=\"14l76py\" data-start=\"2764\" data-end=\"2812\">Retrieval-Augmented Generation (RAG) systems</li>\r\n<li data-section-id=\"3odxlm\" data-start=\"2813\" data-end=\"2862\">Building and optimizing large language models</li>\r\n<li data-section-id=\"11aoqe9\" data-start=\"2863\" data-end=\"2929\">AI applications in financial technology and compliance systems</li>\r\n</ul>\r\n<h3 data-section-id=\"1espbkn\" data-start=\"2931\" data-end=\"2949\">Industry Value</h3>\r\n<p data-start=\"2951\" data-end=\"3075\">This semester prepares students for high-demand roles in AI automation, fintech intelligence, and enterprise AI development.</p>\r\n<hr data-start=\"3077\" data-end=\"3080\">\r\n<h1 data-section-id=\"fwqdi4\" data-start=\"3082\" data-end=\"3131\">Semester 4: AI Governance and Capstone Projects</h1>\r\n<p data-start=\"3133\" data-end=\"3255\">The final semester focuses on advanced AI management, governance, and real-world implementation through industry projects.</p>\r\n<h2 data-section-id=\"1va7gc1\" data-start=\"3257\" data-end=\"3273\">Core Subjects</h2>\r\n<ul data-start=\"3275\" data-end=\"3455\">\r\n<li data-section-id=\"c6ky5t\" data-start=\"3275\" data-end=\"3319\">AI Governance, Ethics &amp; Research Methods</li>\r\n<li data-section-id=\"vsuxwh\" data-start=\"3320\" data-end=\"3384\">AI Product Management (Strategy, Road Mapping, Go-to-Market)</li>\r\n<li data-section-id=\"1gih8ud\" data-start=\"3385\" data-end=\"3455\">Capstone Project (Specialization-Based with Live Industry Project)</li>\r\n</ul>\r\n<h3 data-section-id=\"18630cc\" data-start=\"3457\" data-end=\"3482\">Key Learning Outcomes</h3>\r\n<p data-start=\"3484\" data-end=\"3511\">Students develop skills in:</p>\r\n<ul data-start=\"3513\" data-end=\"3698\">\r\n<li data-section-id=\"18mjy24\" data-start=\"3513\" data-end=\"3556\">Ethical AI system design and governance</li>\r\n<li data-section-id=\"1xgf7ua\" data-start=\"3557\" data-end=\"3586\">AI research methodologies</li>\r\n<li data-section-id=\"1qwvmpa\" data-start=\"3587\" data-end=\"3622\">AI product lifecycle management</li>\r\n<li data-section-id=\"8mra4k\" data-start=\"3623\" data-end=\"3662\">Strategic planning for AI solutions</li>\r\n<li data-section-id=\"1g74f3m\" data-start=\"3663\" data-end=\"3698\">Real-world AI project execution</li>\r\n</ul>\r\n<h3 data-section-id=\"44xr2e\" data-start=\"3700\" data-end=\"3722\">Practical Exposure</h3>\r\n<p data-start=\"3724\" data-end=\"3832\">The capstone project ensures hands-on experience in building AI-driven solutions for real industry problems.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 155000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(221, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 207, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 06:34:34', '2026-06-16 05:47:48', '<p data-start=\"148\" data-end=\"612\">The admission process in modern universities is designed to be structured, transparent, and student-friendly so that applicants can complete enrollment without confusion. A clear step-by-step system ensures that every candidate follows a standardized pathway&mdash;from selecting the right program to final submission of documents. Understanding this process in detail is important because even small errors in application steps can delay admission or lead to rejection.</p>\r\n<p data-start=\"614\" data-end=\"769\">A well-organized admission system not only simplifies enrollment but also helps students make informed decisions about their academic and career direction.</p>\r\n<hr data-start=\"771\" data-end=\"774\">\r\n<h2 data-section-id=\"bx8a3r\" data-start=\"776\" data-end=\"829\">Step 1: Choose a Program and Complete Registration</h2>\r\n<p data-start=\"831\" data-end=\"1059\">The first and most important stage of the admission process is selecting the right academic program. This decision should be based on your career goals, academic background, interest area, and long-term professional aspirations.</p>\r\n<p data-start=\"1061\" data-end=\"1253\">Once the program is selected, candidates are required to complete the <strong data-start=\"1131\" data-end=\"1162\">online registration process</strong>, which typically involves creating a student account and providing basic personal details.</p>\r\n<h3 data-section-id=\"1uafnxp\" data-start=\"1255\" data-end=\"1294\">Key Points to Consider in This Step</h3>\r\n<ul data-start=\"1296\" data-end=\"1635\">\r\n<li data-section-id=\"14kvekc\" data-start=\"1296\" data-end=\"1383\">Carefully analyze program structure, syllabus, and career outcomes before selecting</li>\r\n<li data-section-id=\"dmozxz\" data-start=\"1384\" data-end=\"1468\">Ensure the chosen program aligns with your academic qualifications and interests</li>\r\n<li data-section-id=\"1881sz1\" data-start=\"1469\" data-end=\"1561\">Fill in accurate personal details during registration to avoid verification issues later</li>\r\n<li data-section-id=\"1kotpig\" data-start=\"1562\" data-end=\"1635\">Keep login credentials safe for future admission tracking and updates</li>\r\n</ul>\r\n<p data-start=\"1637\" data-end=\"1790\">This step forms the foundation of your entire admission journey, and choosing the wrong program at this stage can affect long-term academic satisfaction.</p>\r\n<hr data-start=\"1792\" data-end=\"1795\">\r\n<h2 data-section-id=\"1j5cea3\" data-start=\"1797\" data-end=\"1860\">Step 2: Provide Educational Details and Academic Information</h2>\r\n<p data-start=\"1862\" data-end=\"2074\">After registration, candidates must enter their <strong data-start=\"1910\" data-end=\"1961\">educational qualifications and academic history</strong>. This step helps the institution evaluate eligibility based on academic performance and qualification standards.</p>\r\n<p data-start=\"2076\" data-end=\"2219\">Students are required to provide details such as previous qualifications, marks obtained, board or university information, and year of passing.</p>\r\n<h3 data-section-id=\"hg9ma1\" data-start=\"2221\" data-end=\"2261\">Important Requirements in This Stage</h3>\r\n<ul data-start=\"2263\" data-end=\"2619\">\r\n<li data-section-id=\"1b2uqoq\" data-start=\"2263\" data-end=\"2334\">Enter correct details of 10th, 12th, and graduation (as applicable)</li>\r\n<li data-section-id=\"sjvle9\" data-start=\"2335\" data-end=\"2388\">Ensure accuracy in percentage or CGPA calculation</li>\r\n<li data-section-id=\"v3gz5h\" data-start=\"2389\" data-end=\"2441\">Mention recognized board/university details only</li>\r\n<li data-section-id=\"m3a97s\" data-start=\"2442\" data-end=\"2531\">NIOS and other recognized board students must clearly specify their board information</li>\r\n<li data-section-id=\"18w9ao3\" data-start=\"2532\" data-end=\"2619\">Final-year or appearing candidates should provide current academic status correctly</li>\r\n</ul>\r\n<h3 data-section-id=\"19sfpnp\" data-start=\"2621\" data-end=\"2650\">Why This Step is Critical</h3>\r\n<p data-start=\"2652\" data-end=\"2709\">Incorrect or incomplete academic information can lead to:</p>\r\n<ul data-start=\"2711\" data-end=\"2840\">\r\n<li data-section-id=\"p3tnu7\" data-start=\"2711\" data-end=\"2756\">Application rejection during verification</li>\r\n<li data-section-id=\"tmxy50\" data-start=\"2757\" data-end=\"2788\">Delay in admission approval</li>\r\n<li data-section-id=\"ebf4io\" data-start=\"2789\" data-end=\"2840\">Disqualification at document verification stage</li>\r\n</ul>\r\n<p data-start=\"2842\" data-end=\"2920\">Therefore, accuracy in educational details is essential for smooth processing.</p>\r\n<hr data-start=\"2922\" data-end=\"2925\">\r\n<h2 data-section-id=\"11av50d\" data-start=\"2927\" data-end=\"2957\">Step 3: Pay the Program Fee</h2>\r\n<p data-start=\"2959\" data-end=\"3180\">Once eligibility and academic details are submitted, candidates are required to proceed with the <strong data-start=\"3056\" data-end=\"3079\">program fee payment</strong>. This step confirms the applicant&rsquo;s intent to enroll and secures their seat in the selected program.</p>\r\n<p data-start=\"3182\" data-end=\"3287\">Fee payment is generally done through secure online payment modes, ensuring convenience and transparency.</p>\r\n<h3 data-section-id=\"pcrdif\" data-start=\"3289\" data-end=\"3319\">Key Aspects of Fee Payment</h3>\r\n<ul data-start=\"3321\" data-end=\"3611\">\r\n<li data-section-id=\"1npi08m\" data-start=\"3321\" data-end=\"3401\">Payment can usually be made via net banking, UPI, debit card, or credit card</li>\r\n<li data-section-id=\"10qnvma\" data-start=\"3402\" data-end=\"3463\">Some programs may allow installment-based payment options</li>\r\n<li data-section-id=\"10fmxvi\" data-start=\"3464\" data-end=\"3533\">Fee receipt should be saved for future reference and verification</li>\r\n<li data-section-id=\"1egonvn\" data-start=\"3534\" data-end=\"3611\">Payment confirmation is mandatory for application processing continuation</li>\r\n</ul>\r\n<h3 data-section-id=\"f2fz65\" data-start=\"3613\" data-end=\"3635\">Important Advisory</h3>\r\n<ul data-start=\"3637\" data-end=\"3822\">\r\n<li data-section-id=\"1wgztcm\" data-start=\"3637\" data-end=\"3698\">Ensure payment is completed through official portals only</li>\r\n<li data-section-id=\"cet0i7\" data-start=\"3699\" data-end=\"3762\">Do not ignore payment confirmation status after transaction</li>\r\n<li data-section-id=\"1uldhoq\" data-start=\"3763\" data-end=\"3822\">Keep digital and printed copies of the fee receipt safe</li>\r\n</ul>\r\n<p data-start=\"3824\" data-end=\"3907\">Incomplete or failed transactions can result in application delays or cancellation.</p>\r\n<hr data-start=\"3909\" data-end=\"3912\">\r\n<h2 data-section-id=\"chg883\" data-start=\"3914\" data-end=\"3964\">Step 4: Upload Documents and Submit Application</h2>\r\n<p data-start=\"3966\" data-end=\"4189\">The final stage of the admission process involves uploading all required documents and submitting the completed application form. This step is crucial because it verifies your identity, academic background, and eligibility.</p>\r\n<p data-start=\"4191\" data-end=\"4290\">Once documents are uploaded successfully, candidates can submit their application for final review.</p>\r\n<h3 data-section-id=\"1gpk3hn\" data-start=\"4292\" data-end=\"4323\">Documents Commonly Required</h3>\r\n<ul data-start=\"4325\" data-end=\"4599\">\r\n<li data-section-id=\"1f62403\" data-start=\"4325\" data-end=\"4364\">Class 10 mark sheet and certificate</li>\r\n<li data-section-id=\"8j3ev5\" data-start=\"4365\" data-end=\"4404\">Class 12 mark sheet and certificate</li>\r\n<li data-section-id=\"g3iw3b\" data-start=\"4405\" data-end=\"4453\">Graduation mark sheets (all semesters/years)</li>\r\n<li data-section-id=\"8xdz5q\" data-start=\"4454\" data-end=\"4491\">Degree certificate (if available)</li>\r\n<li data-section-id=\"1j9qxlx\" data-start=\"4492\" data-end=\"4541\">Identity proof (Aadhaar card, passport, etc.)</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"4542\" data-end=\"4570\">Passport-size photograph</li>\r\n<li data-section-id=\"az2n3s\" data-start=\"4571\" data-end=\"4599\">Signature (scanned copy)</li>\r\n</ul>\r\n<h3 data-section-id=\"16ep4ct\" data-start=\"4601\" data-end=\"4641\">Key Instructions for Document Upload</h3>\r\n<ul data-start=\"4643\" data-end=\"4850\">\r\n<li data-section-id=\"us0jl0\" data-start=\"4643\" data-end=\"4694\">Ensure documents are clear, valid, and readable</li>\r\n<li data-section-id=\"cbhr6\" data-start=\"4695\" data-end=\"4745\">Upload files in the prescribed format and size</li>\r\n<li data-section-id=\"l62jfd\" data-start=\"4746\" data-end=\"4794\">Avoid mismatched or incomplete documentation</li>\r\n<li data-section-id=\"njsr4s\" data-start=\"4795\" data-end=\"4850\">Double-check uploaded files before final submission</li>\r\n</ul>', 1, '<p data-start=\"169\" data-end=\"697\">Educational qualification plays a decisive role in higher education admission because it reflects a student&rsquo;s academic foundation, consistency, and readiness for advanced-level learning. Institutions follow structured eligibility norms to ensure that only academically prepared candidates are selected for professional and postgraduate programs. These norms are designed not only to filter applications but also to ensure that students can successfully handle rigorous coursework, assessments, and specialization-based learning.</p>\r\n<p data-start=\"699\" data-end=\"1007\">For admission into such programs, candidates must have successfully completed a recognized undergraduate degree that follows standard academic structures approved in India. The eligibility framework is designed to remain flexible for different academic backgrounds while maintaining strong quality standards.</p>\r\n<hr data-start=\"1009\" data-end=\"1012\">\r\n<h2 data-section-id=\"18ip3ss\" data-start=\"1014\" data-end=\"1088\">Accepted Bachelor&rsquo;s Degree Structure (10+2+3 / 10+2+4 / 10+3+3 Pattern)</h2>\r\n<p data-start=\"1090\" data-end=\"1237\">To be eligible, candidates must have completed a <strong data-start=\"1139\" data-end=\"1170\">full-time bachelor&rsquo;s degree</strong> in any discipline under one of the recognized academic structures:</p>\r\n<ul data-start=\"1239\" data-end=\"1370\">\r\n<li data-section-id=\"aex6cc\" data-start=\"1239\" data-end=\"1282\"><strong data-start=\"1241\" data-end=\"1282\">10+2+3-year bachelor&rsquo;s degree program</strong></li>\r\n<li data-section-id=\"mmrq9n\" data-start=\"1283\" data-end=\"1326\"><strong data-start=\"1285\" data-end=\"1326\">10+2+4-year bachelor&rsquo;s degree program</strong></li>\r\n<li data-section-id=\"wzhry5\" data-start=\"1327\" data-end=\"1370\"><strong data-start=\"1329\" data-end=\"1370\">10+3+3-year bachelor&rsquo;s degree program</strong></li>\r\n</ul>\r\n<p data-start=\"1372\" data-end=\"1647\">These formats ensure that the applicant has undergone a complete higher education journey starting from school education to undergraduate specialization. Degrees must be obtained from a <strong data-start=\"1558\" data-end=\"1598\">recognized university or institution</strong>, ensuring authenticity and academic credibility.</p>\r\n<p data-start=\"1649\" data-end=\"1946\">Candidates holding <strong data-start=\"1668\" data-end=\"1792\">equivalent qualifications recognized by the Association of Indian Universities (AIU) or other competent statutory bodies</strong> are also eligible. This is particularly important for students from diverse educational pathways, professional programs, or integrated degree structures.</p>\r\n<h3 data-section-id=\"ck9mh6\" data-start=\"1948\" data-end=\"1986\">Key Academic Validity Requirements</h3>\r\n<ul data-start=\"1988\" data-end=\"2330\">\r\n<li data-section-id=\"1dcd4fi\" data-start=\"1988\" data-end=\"2055\">Degree must be issued by a recognized university or institution</li>\r\n<li data-section-id=\"1cogvst\" data-start=\"2056\" data-end=\"2144\">Equivalent qualifications must be officially validated by AIU or competent authority</li>\r\n<li data-section-id=\"1f9u7s3\" data-start=\"2145\" data-end=\"2231\">Distance or online degrees may be accepted only if recognized by regulatory bodies</li>\r\n<li data-section-id=\"1w2w539\" data-start=\"2232\" data-end=\"2330\">Final-year students may apply only if results are declared before final admission confirmation</li>\r\n</ul>\r\n<hr data-start=\"2332\" data-end=\"2335\">\r\n<h2 data-section-id=\"135crso\" data-start=\"2337\" data-end=\"2399\">Minimum Marks Requirement (Graduation Performance Criteria)</h2>\r\n<p data-start=\"2401\" data-end=\"2717\">Academic performance is a critical parameter in the selection process because it reflects a student&rsquo;s ability to understand concepts, maintain consistency, and perform under academic pressure. Institutions set minimum percentage benchmarks to ensure students are academically capable of handling advanced coursework.</p>\r\n<h3 data-section-id=\"1bjm10a\" data-start=\"2719\" data-end=\"2746\">Required Marks Criteria</h3>\r\n<ul data-start=\"2748\" data-end=\"2881\">\r\n<li data-section-id=\"ijsf9d\" data-start=\"2748\" data-end=\"2814\"><strong data-start=\"2750\" data-end=\"2814\">Minimum 50% aggregate marks in graduation (General Category)</strong></li>\r\n<li data-section-id=\"un9x9w\" data-start=\"2815\" data-end=\"2881\"><strong data-start=\"2817\" data-end=\"2881\">Minimum 45% aggregate marks for Reserved Category candidates</strong></li>\r\n</ul>\r\n<p data-start=\"2883\" data-end=\"3048\">This relaxation for reserved categories is introduced to promote inclusivity and equal access to higher education opportunities while maintaining academic standards.</p>\r\n<hr data-start=\"3050\" data-end=\"3053\">\r\n<h2 data-section-id=\"1r1dfye\" data-start=\"3055\" data-end=\"3123\">Important Academic Evaluation Insights (What Students Often Miss)</h2>\r\n<p data-start=\"3125\" data-end=\"3354\">Many students focus only on eligibility percentage but overlook important evaluation factors that can directly impact admission outcomes. Understanding these details is essential for avoiding rejection during verification stages.</p>\r\n<h3 data-section-id=\"21z2i9\" data-start=\"3356\" data-end=\"3387\">Key Academic Considerations</h3>\r\n<ul data-start=\"3389\" data-end=\"3916\">\r\n<li data-section-id=\"1kpspzw\" data-start=\"3389\" data-end=\"3511\"><strong data-start=\"3391\" data-end=\"3425\">Aggregate calculation matters:</strong> Overall percentage across all semesters is considered, not individual subject marks</li>\r\n<li data-section-id=\"5s8kf0\" data-start=\"3512\" data-end=\"3618\"><strong data-start=\"3514\" data-end=\"3557\">Final result verification is mandatory:</strong> Provisional results may lead to conditional admission only</li>\r\n<li data-section-id=\"qj6tqy\" data-start=\"3619\" data-end=\"3722\"><strong data-start=\"3621\" data-end=\"3650\">Backlogs must be cleared:</strong> Active backlog status can disqualify candidates at verification stage</li>\r\n<li data-section-id=\"18mpoa5\" data-start=\"3723\" data-end=\"3823\"><strong data-start=\"3725\" data-end=\"3768\">Equivalent degree validation is strict:</strong> AIU recognition or regulatory approval is compulsory</li>\r\n<li data-section-id=\"6yc8g\" data-start=\"3824\" data-end=\"3916\"><strong data-start=\"3826\" data-end=\"3861\">Percentage rounding rules vary:</strong> Some institutions do not round off borderline scores</li>\r\n</ul>\r\n<p data-start=\"3918\" data-end=\"4040\">These factors often become hidden reasons for application rejection, even when candidates meet basic eligibility criteria.</p>\r\n<hr data-start=\"4042\" data-end=\"4045\">\r\n<h2 data-section-id=\"1c3tg4z\" data-start=\"4047\" data-end=\"4129\">Eligibility for Students Appearing in Final Year or Under Graduation Completion</h2>\r\n<p data-start=\"4131\" data-end=\"4371\">In many admission frameworks, students who are in the <strong data-start=\"4185\" data-end=\"4226\">final year of their bachelor&rsquo;s degree</strong> are allowed to apply provisionally. However, their final selection depends on successful completion of the degree within the required timeframe.</p>\r\n<h3 data-section-id=\"te0j55\" data-start=\"4373\" data-end=\"4411\">Conditions for Final-Year Students</h3>\r\n<ul data-start=\"4413\" data-end=\"4610\">\r\n<li data-section-id=\"1vlyu7z\" data-start=\"4413\" data-end=\"4465\">Must submit final mark sheet before the deadline</li>\r\n<li data-section-id=\"2ktxv6\" data-start=\"4466\" data-end=\"4535\">Must meet minimum percentage requirement after result declaration</li>\r\n<li data-section-id=\"1vclpz5\" data-start=\"4536\" data-end=\"4610\">Admission remains provisional until document verification is completed</li>\r\n</ul>\r\n<p data-start=\"4612\" data-end=\"4713\">This provision ensures that students do not lose academic opportunities while awaiting final results.</p>\r\n<hr data-start=\"4715\" data-end=\"4718\">\r\n<h2 data-section-id=\"1br6qzr\" data-start=\"4720\" data-end=\"4771\">NIOS and Alternative Education Board Eligibility</h2>\r\n<p data-start=\"4773\" data-end=\"4915\">Students from <strong data-start=\"4787\" data-end=\"4834\">NIOS (National Institute of Open Schooling)</strong> or other recognized open schooling systems are generally considered eligible if:</p>\r\n<ul data-start=\"4917\" data-end=\"5125\">\r\n<li data-section-id=\"1mezxns\" data-start=\"4917\" data-end=\"4986\">Their qualification is equivalent to recognized mainstream boards</li>\r\n<li data-section-id=\"1a0a2p1\" data-start=\"4987\" data-end=\"5065\">The degree obtained after higher education is from a recognized university</li>\r\n<li data-section-id=\"7gquju\" data-start=\"5066\" data-end=\"5125\">They meet the minimum percentage criteria in graduation</li>\r\n</ul>\r\n<p data-start=\"5127\" data-end=\"5236\">This ensures equal opportunity for non-traditional learners while maintaining academic credibility standards.</p>\r\n<hr data-start=\"5238\" data-end=\"5241\">\r\n<h2 data-section-id=\"b2la7z\" data-start=\"5243\" data-end=\"5315\">Why These Eligibility Criteria Matter (Academic Importance Explained)</h2>\r\n<p data-start=\"5317\" data-end=\"5533\">Eligibility requirements are not just administrative filters; they are carefully designed academic benchmarks that ensure students entering higher education are adequately prepared for advanced learning environments.</p>\r\n<h3 data-section-id=\"189bod0\" data-start=\"5535\" data-end=\"5571\">Purpose of Eligibility Standards</h3>\r\n<ul data-start=\"5573\" data-end=\"5878\">\r\n<li data-section-id=\"6lzaa8\" data-start=\"5573\" data-end=\"5634\">Ensures academic readiness for postgraduate-level studies</li>\r\n<li data-section-id=\"18krm4t\" data-start=\"5635\" data-end=\"5695\">Maintains classroom competitiveness and learning quality</li>\r\n<li data-section-id=\"1ky13wi\" data-start=\"5696\" data-end=\"5742\">Reduces academic failure and dropout risks</li>\r\n<li data-section-id=\"nqwgn4\" data-start=\"5743\" data-end=\"5808\">Standardizes admission across diverse educational backgrounds</li>\r\n<li data-section-id=\"lw4d11\" data-start=\"5809\" data-end=\"5878\">Helps institutions maintain global academic recognition standards</li>\r\n</ul>\r\n<p data-start=\"5880\" data-end=\"5995\">Students who meet these requirements are statistically more likely to perform better in advanced academic programs.</p>', '<p data-start=\"158\" data-end=\"549\">The cost of higher education is an important factor in academic decision-making, and universities design their fee structures to remain transparent, structured, and manageable for students from diverse financial backgrounds. A well-planned fee system not only covers academic delivery but also ensures access to learning resources, examinations, infrastructure, and student support services.</p>\r\n<p data-start=\"551\" data-end=\"855\">In addition to tuition fees, many institutions also provide flexible payment options and financial assistance to make education more accessible. Understanding the complete fee structure helps students and parents plan finances effectively without unexpected financial pressure during the course duration.</p>\r\n<hr data-start=\"857\" data-end=\"860\">\r\n<h2 data-section-id=\"wqawtk\" data-start=\"862\" data-end=\"914\">Total Course Fee Overview (Complete Program Cost)</h2>\r\n<p data-start=\"916\" data-end=\"1124\">The total academic cost is generally distributed across semesters to make payments more manageable and student-friendly. For a standard four-semester program, the overall fee structure is designed as follows:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1126\" data-end=\"1233\">\r\n<thead data-start=\"1126\" data-end=\"1152\">\r\n<tr data-start=\"1126\" data-end=\"1152\">\r\n<th class=\"\" data-start=\"1126\" data-end=\"1137\" data-col-size=\"sm\">Category</th>\r\n<th class=\"\" data-start=\"1137\" data-end=\"1152\" data-col-size=\"sm\">Fee Details</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1180\" data-end=\"1233\">\r\n<tr data-start=\"1180\" data-end=\"1233\">\r\n<td data-start=\"1180\" data-end=\"1213\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"1213\" data-end=\"1233\"><strong data-start=\"1215\" data-end=\"1231\">INR 1,20,000</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1235\" data-end=\"1414\">This total fee includes academic instruction, access to learning materials, institutional facilities, and examination-related academic services across the entire program duration.</p>\r\n<hr data-start=\"1416\" data-end=\"1419\">\r\n<h2 data-section-id=\"19je7fh\" data-start=\"1421\" data-end=\"1451\">Semester-wise Fee Structure</h2>\r\n<p data-start=\"1453\" data-end=\"1651\">To reduce financial burden and improve accessibility, the course fee is divided into equal semester-wise payments. This allows students to plan their expenses in a structured and predictable manner.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1653\" data-end=\"1743\">\r\n<thead data-start=\"1653\" data-end=\"1678\">\r\n<tr data-start=\"1653\" data-end=\"1678\">\r\n<th class=\"\" data-start=\"1653\" data-end=\"1664\" data-col-size=\"sm\">Semester</th>\r\n<th class=\"\" data-start=\"1664\" data-end=\"1678\" data-col-size=\"sm\">Fee Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1705\" data-end=\"1743\">\r\n<tr data-start=\"1705\" data-end=\"1743\">\r\n<td data-start=\"1705\" data-end=\"1725\" data-col-size=\"sm\">Each Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1725\" data-end=\"1743\"><strong data-start=\"1727\" data-end=\"1741\">INR 30,000</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1786v3q\" data-start=\"1745\" data-end=\"1786\">Key Highlights of Semester Fee System</h3>\r\n<ul data-start=\"1788\" data-end=\"2028\">\r\n<li data-section-id=\"2ck0v2\" data-start=\"1788\" data-end=\"1845\">Payments are distributed equally across all semesters</li>\r\n<li data-section-id=\"135tqut\" data-start=\"1846\" data-end=\"1909\">Helps students manage finances without large upfront burden</li>\r\n<li data-section-id=\"1vmfq9d\" data-start=\"1910\" data-end=\"1974\">Ensures continuity of academic access throughout the program</li>\r\n<li data-section-id=\"3gh9by\" data-start=\"1975\" data-end=\"2028\">Supports flexible financial planning for families</li>\r\n</ul>\r\n<p data-start=\"2030\" data-end=\"2134\">This structured approach ensures that students can focus more on academics rather than financial stress.</p>\r\n<hr data-start=\"2136\" data-end=\"2139\">\r\n<h2 data-section-id=\"ncv1we\" data-start=\"2141\" data-end=\"2181\">EMI (Easy Monthly Installment) Option</h2>\r\n<p data-start=\"2183\" data-end=\"2369\">To further enhance affordability, institutions often provide EMI-based payment options. This allows students to pay their fees in small monthly installments instead of a lump sum amount.</p>\r\n<h3 data-section-id=\"1ot66s6\" data-start=\"2371\" data-end=\"2391\">EMI Plan Details</h3>\r\n<ul data-start=\"2393\" data-end=\"2616\">\r\n<li data-section-id=\"mslxqq\" data-start=\"2393\" data-end=\"2435\">Starting EMI: <strong data-start=\"2409\" data-end=\"2432\">INR 5,000 per month</strong>*</li>\r\n<li data-section-id=\"1qv52ec\" data-start=\"2436\" data-end=\"2497\">Flexible repayment options available based on eligibility</li>\r\n<li data-section-id=\"1dzsut9\" data-start=\"2498\" data-end=\"2549\">Designed to reduce immediate financial pressure</li>\r\n<li data-section-id=\"16p6wgk\" data-start=\"2550\" data-end=\"2616\">Helps students manage education costs alongside other expenses</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"2618\" data-end=\"2636\">Important Note</h3>\r\n<ul data-start=\"2638\" data-end=\"2861\">\r\n<li data-section-id=\"76kzlj\" data-start=\"2638\" data-end=\"2687\"><em data-start=\"2640\" data-end=\"2685\">Terms and conditions apply for EMI approval</em></li>\r\n<li data-section-id=\"m3br0x\" data-start=\"2688\" data-end=\"2779\">EMI eligibility may depend on financial verification and partner financing institutions</li>\r\n<li data-section-id=\"182hvsa\" data-start=\"2780\" data-end=\"2861\">Processing fees or interest rates may vary depending on payment plan selected</li>\r\n</ul>\r\n<hr data-start=\"2863\" data-end=\"2866\">\r\n<h2 data-section-id=\"45l3hq\" data-start=\"2868\" data-end=\"2919\">Scholarships and Financial Support Opportunities</h2>\r\n<p data-start=\"2921\" data-end=\"3149\">Scholarship programs play a crucial role in making higher education accessible to meritorious and financially challenged students. These financial aids are designed to reward academic excellence and support deserving candidates.</p>\r\n<h3 data-section-id=\"6tzqm4\" data-start=\"3151\" data-end=\"3195\">Types of Scholarships Commonly Available</h3>\r\n<ul data-start=\"3197\" data-end=\"3609\">\r\n<li data-section-id=\"xitwes\" data-start=\"3197\" data-end=\"3284\"><strong data-start=\"3199\" data-end=\"3227\">Merit-Based Scholarships</strong> &ndash; Awarded to students with strong academic performance</li>\r\n<li data-section-id=\"uxnk2g\" data-start=\"3285\" data-end=\"3366\"><strong data-start=\"3287\" data-end=\"3315\">Need-Based Financial Aid</strong> &ndash; For students with limited financial background</li>\r\n<li data-section-id=\"uvwsxp\" data-start=\"3367\" data-end=\"3444\"><strong data-start=\"3369\" data-end=\"3399\">Category-Based Relaxations</strong> &ndash; Support for reserved category candidates</li>\r\n<li data-section-id=\"c3h3gb\" data-start=\"3445\" data-end=\"3516\"><strong data-start=\"3447\" data-end=\"3475\">Early Admission Benefits</strong> &ndash; Fee concessions for early applicants</li>\r\n<li data-section-id=\"waqne0\" data-start=\"3517\" data-end=\"3609\"><strong data-start=\"3519\" data-end=\"3553\">Performance-Based Scholarships</strong> &ndash; Renewal based on academic results during the course</li>\r\n</ul>\r\n<h3 data-section-id=\"jtxpyq\" data-start=\"3611\" data-end=\"3639\">Benefits of Scholarships</h3>\r\n<ul data-start=\"3641\" data-end=\"3875\">\r\n<li data-section-id=\"13yppje\" data-start=\"3641\" data-end=\"3675\">Reduces overall tuition burden</li>\r\n<li data-section-id=\"1la59jq\" data-start=\"3676\" data-end=\"3738\">Encourages academic excellence and performance consistency</li>\r\n<li data-section-id=\"cime6u\" data-start=\"3739\" data-end=\"3798\">Improves accessibility for economically weaker students</li>\r\n<li data-section-id=\"1vwnjy5\" data-start=\"3799\" data-end=\"3875\">Supports continuation of higher education without financial interruption</li>\r\n</ul>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 120000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(222, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 102, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 07:00:32', '2026-06-16 05:48:05', '<p data-start=\"126\" data-end=\"460\">The admission process for the MA Arts (English) program is designed to be simple, structured, and fully student-friendly, ensuring that applicants can complete their enrollment without confusion. Each step plays an important role in verifying eligibility, confirming academic details, processing fee payment, and finalizing admission.</p>\r\n<p data-start=\"462\" data-end=\"661\">A clear understanding of the admission flow helps students avoid errors, delays, and application rejection while ensuring a smooth transition into postgraduate studies in English literature and Arts.</p>\r\n<hr data-start=\"663\" data-end=\"666\">\r\n<h2 data-section-id=\"3ozalm\" data-start=\"668\" data-end=\"719\">Step 1: Choose a Program &amp; Complete Registration</h2>\r\n<p data-start=\"721\" data-end=\"937\">The first step in the admission process is selecting the MA Arts (English) program and completing the online registration. This stage establishes your application profile and officially begins your admission journey.</p>\r\n<h3 data-section-id=\"19q6ckf\" data-start=\"939\" data-end=\"980\">What Students Need to Do in This Step</h3>\r\n<ul data-start=\"982\" data-end=\"1259\">\r\n<li data-section-id=\"fy94dm\" data-start=\"982\" data-end=\"1066\">Select the MA Arts (English) program based on academic interest and career goals</li>\r\n<li data-section-id=\"1ppgu7m\" data-start=\"1067\" data-end=\"1136\">Complete the online registration form with basic personal details</li>\r\n<li data-section-id=\"a7vulm\" data-start=\"1137\" data-end=\"1188\">Create login credentials for admission tracking</li>\r\n<li data-section-id=\"1hflb3w\" data-start=\"1189\" data-end=\"1259\">Ensure accuracy in name, contact details, and identity information</li>\r\n</ul>\r\n<h3 data-section-id=\"1rmz6np\" data-start=\"1261\" data-end=\"1283\">Important Insights</h3>\r\n<p data-start=\"1285\" data-end=\"1538\">Choosing the correct program at this stage is critical because it defines your academic direction for the entire postgraduate course. Incorrect selection or inaccurate registration details can lead to delays or application rejection during verification.</p>\r\n<hr data-start=\"1540\" data-end=\"1543\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"1545\" data-end=\"1583\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"1585\" data-end=\"1799\">After registration, candidates must enter their complete academic background. This step helps the institution verify eligibility and ensure that the applicant meets the required educational qualification standards.</p>\r\n<h3 data-section-id=\"n6owhw\" data-start=\"1801\" data-end=\"1837\">Required Educational Information</h3>\r\n<ul data-start=\"1839\" data-end=\"2055\">\r\n<li data-section-id=\"1bdlbc0\" data-start=\"1839\" data-end=\"1885\">Details of Class 10 and Class 12 education</li>\r\n<li data-section-id=\"a60666\" data-start=\"1886\" data-end=\"1950\">Bachelor&rsquo;s degree information (10+2+3 pattern or equivalent)</li>\r\n<li data-section-id=\"1stubcy\" data-start=\"1951\" data-end=\"1985\">University or institution name</li>\r\n<li data-section-id=\"13b8a4\" data-start=\"1986\" data-end=\"2024\">Year of passing and marks obtained</li>\r\n<li data-section-id=\"1hwdh8a\" data-start=\"2025\" data-end=\"2055\">Percentage or CGPA details</li>\r\n</ul>\r\n<h3 data-section-id=\"1gcsdzm\" data-start=\"2057\" data-end=\"2083\">Key Points to Remember</h3>\r\n<ul data-start=\"2085\" data-end=\"2364\">\r\n<li data-section-id=\"5vihd7\" data-start=\"2085\" data-end=\"2146\">All information must match official academic certificates</li>\r\n<li data-section-id=\"k6akmy\" data-start=\"2147\" data-end=\"2209\">NIOS and other recognized boards must be clearly mentioned</li>\r\n<li data-section-id=\"ye1fdg\" data-start=\"2210\" data-end=\"2289\">Final-year students should accurately declare their current academic status</li>\r\n<li data-section-id=\"18hqzo1\" data-start=\"2290\" data-end=\"2364\">AIU-equivalent qualifications must be properly specified if applicable</li>\r\n</ul>\r\n<h3 data-section-id=\"g0deo8\" data-start=\"2366\" data-end=\"2396\">Why This Step is Important</h3>\r\n<p data-start=\"2398\" data-end=\"2453\">Incorrect or incomplete academic details can result in:</p>\r\n<ul data-start=\"2454\" data-end=\"2579\">\r\n<li data-section-id=\"tzs708\" data-start=\"2454\" data-end=\"2499\">Rejection during eligibility verification</li>\r\n<li data-section-id=\"tmxy50\" data-start=\"2500\" data-end=\"2531\">Delay in admission approval</li>\r\n<li data-section-id=\"5ex55v\" data-start=\"2532\" data-end=\"2579\">Document mismatch during final confirmation</li>\r\n</ul>\r\n<hr data-start=\"2581\" data-end=\"2584\">\r\n<h2 data-section-id=\"15pe0sk\" data-start=\"2586\" data-end=\"2612\">Step 3: Pay Program Fee</h2>\r\n<p data-start=\"2614\" data-end=\"2817\">Once educational eligibility is confirmed, candidates are required to proceed with the program fee payment. This step confirms the applicant&rsquo;s intent to secure admission in the MA Arts (English) program.</p>\r\n<h3 data-section-id=\"135hupd\" data-start=\"2819\" data-end=\"2842\">Fee Payment Process</h3>\r\n<ul data-start=\"2844\" data-end=\"3065\">\r\n<li data-section-id=\"12abrj0\" data-start=\"2844\" data-end=\"2947\">Complete payment through secure online methods such as UPI, debit card, credit card, or net banking</li>\r\n<li data-section-id=\"bv8z79\" data-start=\"2948\" data-end=\"3002\">Verify transaction status after payment completion</li>\r\n<li data-section-id=\"15wtx4s\" data-start=\"3003\" data-end=\"3065\">Download and save the payment receipt for future reference</li>\r\n</ul>\r\n<h3 data-section-id=\"1i1y6qa\" data-start=\"3067\" data-end=\"3085\">Key Highlights</h3>\r\n<ul data-start=\"3087\" data-end=\"3335\">\r\n<li data-section-id=\"f3s14a\" data-start=\"3087\" data-end=\"3136\">Payment confirms provisional admission status</li>\r\n<li data-section-id=\"1fpv40u\" data-start=\"3137\" data-end=\"3205\">Fee structure is generally divided semester-wise for convenience</li>\r\n<li data-section-id=\"120l31y\" data-start=\"3206\" data-end=\"3260\">EMI options may be available for eligible students</li>\r\n<li data-section-id=\"1wrs9ip\" data-start=\"3261\" data-end=\"3335\">Any failure in payment must be resolved before moving to the next step</li>\r\n</ul>\r\n<h3 data-section-id=\"f2fz65\" data-start=\"3337\" data-end=\"3359\">Important Advisory</h3>\r\n<p data-start=\"3361\" data-end=\"3499\">Students should always ensure they are paying through official admission portals only to avoid transaction errors or fraud-related issues.</p>\r\n<hr data-start=\"3501\" data-end=\"3504\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"3506\" data-end=\"3554\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"3556\" data-end=\"3778\">The final stage of the admission process involves uploading all required documents and submitting the completed application form. This step ensures verification of identity, academic background, and eligibility compliance.</p>\r\n<h3 data-section-id=\"8z1ntf\" data-start=\"3780\" data-end=\"3802\">Documents Required</h3>\r\n<ul data-start=\"3804\" data-end=\"4084\">\r\n<li data-section-id=\"1f62403\" data-start=\"3804\" data-end=\"3843\">Class 10 mark sheet and certificate</li>\r\n<li data-section-id=\"8j3ev5\" data-start=\"3844\" data-end=\"3883\">Class 12 mark sheet and certificate</li>\r\n<li data-section-id=\"fdwkz1\" data-start=\"3884\" data-end=\"3939\">Bachelor&rsquo;s degree mark sheets (all semesters/years)</li>\r\n<li data-section-id=\"8xdz5q\" data-start=\"3940\" data-end=\"3977\">Degree certificate (if available)</li>\r\n<li data-section-id=\"7y7fub\" data-start=\"3978\" data-end=\"4033\">Valid identity proof (Aadhaar card, passport, etc.)</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"4034\" data-end=\"4062\">Passport-size photograph</li>\r\n<li data-section-id=\"opd9y4\" data-start=\"4063\" data-end=\"4084\">Scanned signature</li>\r\n</ul>\r\n<h3 data-section-id=\"2494j1\" data-start=\"4086\" data-end=\"4116\">Document Upload Guidelines</h3>\r\n<ul data-start=\"4118\" data-end=\"4326\">\r\n<li data-section-id=\"1ls41b9\" data-start=\"4118\" data-end=\"4173\">Ensure all documents are clear, readable, and valid</li>\r\n<li data-section-id=\"8nhyrz\" data-start=\"4174\" data-end=\"4223\">Upload files in the specified format and size</li>\r\n<li data-section-id=\"1jq9l9e\" data-start=\"4224\" data-end=\"4271\">Cross-check details before final submission</li>\r\n<li data-section-id=\"k0514k\" data-start=\"4272\" data-end=\"4326\">Avoid uploading incomplete or mismatched documents</li>\r\n</ul>\r\n<h3 data-section-id=\"2iq8bt\" data-start=\"4328\" data-end=\"4356\">Final Submission Process</h3>\r\n<ul data-start=\"4358\" data-end=\"4550\">\r\n<li data-section-id=\"jm2pcu\" data-start=\"4358\" data-end=\"4419\">Review the entire application carefully before submission</li>\r\n<li data-section-id=\"zqpm4b\" data-start=\"4420\" data-end=\"4479\">Submit the application only after verifying all details</li>\r\n<li data-section-id=\"j3md9h\" data-start=\"4480\" data-end=\"4550\">Save a copy of the submitted application form for future reference</li>\r\n</ul>', 1, '<p data-start=\"138\" data-end=\"572\">The Master of Arts (MA) in English under Arts stream is a postgraduate program designed for students who want to build strong expertise in literature, language studies, critical thinking, communication, and academic writing. Admission to this program follows a structured eligibility framework to ensure that students entering the course have the necessary academic background and analytical ability required for advanced-level study.</p>\r\n<p data-start=\"574\" data-end=\"759\">This program welcomes applicants from diverse academic backgrounds, provided they meet the minimum educational qualification and recognition standards set by authorized academic bodies.</p>\r\n<hr data-start=\"761\" data-end=\"764\">\r\n<h2 data-section-id=\"3t38zh\" data-start=\"766\" data-end=\"804\">Who Can Apply for MA Arts (English)</h2>\r\n<p data-start=\"806\" data-end=\"1128\">The MA Arts (English) program is open to both domestic and international applicants who meet the required academic and eligibility conditions. The admission framework is inclusive, ensuring that students from different educational systems and regions can apply, provided their qualifications are recognized and equivalent.</p>\r\n<h3 data-section-id=\"n7srn6\" data-start=\"1130\" data-end=\"1151\">Domestic Students</h3>\r\n<p data-start=\"1153\" data-end=\"1422\">Domestic applicants include students who have completed their education within India from recognized universities or institutions. These candidates must meet the prescribed academic qualification and ensure their degree is valid under recognized higher education norms.</p>\r\n<h3 data-section-id=\"1cu564m\" data-start=\"1424\" data-end=\"1450\">International Students</h3>\r\n<p data-start=\"1452\" data-end=\"1722\">International applicants are also eligible to apply for the MA Arts (English) program, provided their academic qualifications are recognized as equivalent by competent authorities such as the Association of Indian Universities (AIU) or other approved equivalence bodies.</p>\r\n<p data-start=\"1724\" data-end=\"1764\">Key points for international applicants:</p>\r\n<ul data-start=\"1765\" data-end=\"2048\">\r\n<li data-section-id=\"36o1gg\" data-start=\"1765\" data-end=\"1841\">Must hold a valid bachelor&rsquo;s degree from a recognized foreign university</li>\r\n<li data-section-id=\"1qf2ioz\" data-start=\"1842\" data-end=\"1905\">Degree must be equivalent to Indian undergraduate standards</li>\r\n<li data-section-id=\"1papi3f\" data-start=\"1906\" data-end=\"1979\">Must provide official academic transcripts and verification documents</li>\r\n<li data-section-id=\"n2bnj4\" data-start=\"1980\" data-end=\"2048\">Equivalence certification may be required for admission approval</li>\r\n</ul>\r\n<hr data-start=\"2050\" data-end=\"2053\">\r\n<h2 data-section-id=\"1q2sa3j\" data-start=\"2055\" data-end=\"2096\">Educational Qualification Requirements</h2>\r\n<p data-start=\"2098\" data-end=\"2204\">To be eligible for admission into MA Arts (English), candidates must meet the following academic criteria:</p>\r\n<ul data-start=\"2206\" data-end=\"2563\">\r\n<li data-section-id=\"14xeym3\" data-start=\"2206\" data-end=\"2309\">Must have completed a <strong data-start=\"2230\" data-end=\"2263\">10+2+3-year bachelor&rsquo;s degree</strong> from a recognized university or institution</li>\r\n<li data-section-id=\"11m41fm\" data-start=\"2310\" data-end=\"2471\">Alternatively, candidates must hold an <strong data-start=\"2351\" data-end=\"2438\">equivalent qualification recognized by the Association of Indian Universities (AIU)</strong> or other competent authorities</li>\r\n<li data-section-id=\"ghrrr2\" data-start=\"2472\" data-end=\"2563\">Degree must be from a valid and accredited institution with proper academic recognition</li>\r\n</ul>\r\n<p data-start=\"2565\" data-end=\"2693\">This ensures that all applicants have completed a structured undergraduate education before entering postgraduate-level studies.</p>\r\n<hr data-start=\"2695\" data-end=\"2698\">\r\n<h2 data-section-id=\"1t1a4gk\" data-start=\"2700\" data-end=\"2740\">Key Academic Insights for Eligibility</h2>\r\n<p data-start=\"2742\" data-end=\"2894\">Understanding eligibility is not just about meeting minimum criteria&mdash;it is about ensuring academic readiness for advanced literary and analytical study.</p>\r\n<h3 data-section-id=\"ypjbad\" data-start=\"2896\" data-end=\"2924\">Important Considerations</h3>\r\n<ul data-start=\"2926\" data-end=\"3348\">\r\n<li data-section-id=\"11ln6h7\" data-start=\"2926\" data-end=\"3068\">The bachelor&rsquo;s degree should be completed in any discipline, but English, Arts, or Humanities background may provide an academic advantage</li>\r\n<li data-section-id=\"dk2nhc\" data-start=\"3069\" data-end=\"3137\">AIU equivalence is mandatory for foreign or non-standard degrees</li>\r\n<li data-section-id=\"1qp3tet\" data-start=\"3138\" data-end=\"3272\">Final-year students may be allowed to apply provisionally, subject to completion of graduation before final admission confirmation</li>\r\n<li data-section-id=\"109g68h\" data-start=\"3273\" data-end=\"3348\">All academic documents must be valid, verifiable, and officially issued</li>\r\n</ul>\r\n<hr data-start=\"3350\" data-end=\"3353\">\r\n<h2 data-section-id=\"kxock5\" data-start=\"3355\" data-end=\"3396\">Why This Eligibility Structure Matters</h2>\r\n<p data-start=\"3398\" data-end=\"3604\">The eligibility criteria for MA Arts (English) are designed to maintain academic quality and ensure that students are prepared for higher-level literary analysis, research work, and critical interpretation.</p>\r\n<h3 data-section-id=\"1bs1lqy\" data-start=\"3606\" data-end=\"3648\">Key Objectives of Eligibility Criteria</h3>\r\n<ul data-start=\"3650\" data-end=\"3949\">\r\n<li data-section-id=\"1ndph5c\" data-start=\"3650\" data-end=\"3707\">Ensures students have foundational academic knowledge</li>\r\n<li data-section-id=\"lzrpn\" data-start=\"3708\" data-end=\"3768\">Maintains consistency in postgraduate academic standards</li>\r\n<li data-section-id=\"1v8uby6\" data-start=\"3769\" data-end=\"3830\">Supports smooth transition into advanced literary studies</li>\r\n<li data-section-id=\"oa5l9f\" data-start=\"3831\" data-end=\"3884\">Reduces academic difficulty at postgraduate level</li>\r\n<li data-section-id=\"1t734fr\" data-start=\"3885\" data-end=\"3949\">Ensures global recognition and credibility of qualifications</li>\r\n</ul>', '<h2 data-section-id=\"gdepo1\" data-start=\"97\" data-end=\"161\">Understanding MA English Program Fees and Academic Investment</h2>\r\n<p data-start=\"163\" data-end=\"517\">The Master of Arts (MA) in English is a postgraduate program designed for students who want to build strong expertise in literature, language studies, critical theory, communication skills, and academic writing. Along with academic depth, understanding the financial structure of the program is essential for proper planning and smooth course completion.</p>\r\n<p data-start=\"519\" data-end=\"753\">The fee structure for MA English is designed to remain transparent, flexible, and student-friendly, ensuring accessibility for learners from diverse financial backgrounds while maintaining academic quality and institutional standards.</p>\r\n<hr data-start=\"755\" data-end=\"758\">\r\n<h2 data-section-id=\"d7qycf\" data-start=\"760\" data-end=\"821\">Total Course Fee Overview (MA English &ndash; Full Program Cost)</h2>\r\n<p data-start=\"823\" data-end=\"1003\">The overall program fee is structured for the complete duration of four semesters. This helps students understand the total financial commitment required for completing the degree.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1005\" data-end=\"1110\">\r\n<thead data-start=\"1005\" data-end=\"1031\">\r\n<tr data-start=\"1005\" data-end=\"1031\">\r\n<th class=\"\" data-start=\"1005\" data-end=\"1016\" data-col-size=\"sm\">Category</th>\r\n<th class=\"\" data-start=\"1016\" data-end=\"1031\" data-col-size=\"sm\">Fee Details</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1059\" data-end=\"1110\">\r\n<tr data-start=\"1059\" data-end=\"1110\">\r\n<td data-start=\"1059\" data-end=\"1092\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"1092\" data-end=\"1110\"><strong data-start=\"1094\" data-end=\"1108\">INR 75,000</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1112\" data-end=\"1311\">This total fee generally includes academic instruction, curriculum delivery, access to learning resources, internal academic support, and examination-related services throughout the program duration.</p>\r\n<hr data-start=\"1313\" data-end=\"1316\">\r\n<h2 data-section-id=\"1hnkbaw\" data-start=\"1318\" data-end=\"1363\">Semester-wise Fee Structure for MA English</h2>\r\n<p data-start=\"1365\" data-end=\"1493\">To ensure financial ease and reduce upfront burden, the MA English program fee is divided into equal semester-wise installments.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1495\" data-end=\"1585\">\r\n<thead data-start=\"1495\" data-end=\"1520\">\r\n<tr data-start=\"1495\" data-end=\"1520\">\r\n<th class=\"\" data-start=\"1495\" data-end=\"1506\" data-col-size=\"sm\">Semester</th>\r\n<th class=\"\" data-start=\"1506\" data-end=\"1520\" data-col-size=\"sm\">Fee Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1547\" data-end=\"1585\">\r\n<tr data-start=\"1547\" data-end=\"1585\">\r\n<td data-start=\"1547\" data-end=\"1567\" data-col-size=\"sm\">Each Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1567\" data-end=\"1585\"><strong data-start=\"1569\" data-end=\"1583\">INR 18,750</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"doy87c\" data-start=\"1587\" data-end=\"1635\">Key Benefits of Semester-Wise Payment System</h3>\r\n<ul data-start=\"1637\" data-end=\"1870\">\r\n<li data-section-id=\"8nh80n\" data-start=\"1637\" data-end=\"1692\">Reduces financial pressure on students and families</li>\r\n<li data-section-id=\"9ecbew\" data-start=\"1693\" data-end=\"1747\">Allows structured and predictable payment planning</li>\r\n<li data-section-id=\"1ol2lvj\" data-start=\"1748\" data-end=\"1806\">Ensures uninterrupted academic access across semesters</li>\r\n<li data-section-id=\"1e0ur68\" data-start=\"1807\" data-end=\"1870\">Helps students manage education alongside personal expenses</li>\r\n</ul>\r\n<p data-start=\"1872\" data-end=\"2016\">This system is especially beneficial for postgraduate students who may also be balancing internships, research work, or part-time opportunities.</p>\r\n<hr data-start=\"2018\" data-end=\"2021\">\r\n<h2 data-section-id=\"4sob8b\" data-start=\"2023\" data-end=\"2078\">EMI (Easy Monthly Installment) Option for MA English</h2>\r\n<p data-start=\"2080\" data-end=\"2276\">To make higher education more accessible, EMI facilities are available for eligible students. This option allows candidates to convert their semester or total fee into manageable monthly payments.</p>\r\n<h3 data-section-id=\"1ot66s6\" data-start=\"2278\" data-end=\"2298\">EMI Plan Details</h3>\r\n<ul data-start=\"2300\" data-end=\"2514\">\r\n<li data-section-id=\"14cilsi\" data-start=\"2300\" data-end=\"2342\">Starting EMI: <strong data-start=\"2316\" data-end=\"2339\">INR 3,125 per month</strong>*</li>\r\n<li data-section-id=\"1s8zit4\" data-start=\"2343\" data-end=\"2396\">Flexible repayment structure based on eligibility</li>\r\n<li data-section-id=\"1g1xlvr\" data-start=\"2397\" data-end=\"2444\">Designed to reduce upfront financial burden</li>\r\n<li data-section-id=\"1sjeya0\" data-start=\"2445\" data-end=\"2514\">Suitable for students seeking budget-friendly education financing</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"2516\" data-end=\"2534\">Important Note</h3>\r\n<ul data-start=\"2536\" data-end=\"2752\">\r\n<li data-section-id=\"76kzlj\" data-start=\"2536\" data-end=\"2585\"><em data-start=\"2538\" data-end=\"2583\">Terms and conditions apply for EMI approval</em></li>\r\n<li data-section-id=\"1vemj5q\" data-start=\"2586\" data-end=\"2671\">EMI eligibility may depend on financial assessment and partner financing approval</li>\r\n<li data-section-id=\"1vquagl\" data-start=\"2672\" data-end=\"2752\">Interest rates or processing charges may vary depending on the selected plan</li>\r\n</ul>\r\n<hr data-start=\"2754\" data-end=\"2757\">\r\n<h2 data-section-id=\"1t7bm5f\" data-start=\"2759\" data-end=\"2798\">Scholarships for MA English Students</h2>\r\n<p data-start=\"2800\" data-end=\"3063\">Scholarships play a crucial role in supporting students who demonstrate academic excellence or financial need. These financial aid options help reduce the overall cost of education and encourage talented students to pursue higher studies without financial stress.</p>\r\n<h3 data-section-id=\"1lyfrj8\" data-start=\"3065\" data-end=\"3100\">Types of Scholarships Available</h3>\r\n<ul data-start=\"3102\" data-end=\"3532\">\r\n<li data-section-id=\"ua7vxp\" data-start=\"3102\" data-end=\"3199\"><strong data-start=\"3104\" data-end=\"3132\">Merit-Based Scholarships</strong> &ndash; Awarded to students with strong academic records in graduation</li>\r\n<li data-section-id=\"s8xpeb\" data-start=\"3200\" data-end=\"3285\"><strong data-start=\"3202\" data-end=\"3237\">Need-Based Financial Assistance</strong> &ndash; Support for economically weaker backgrounds</li>\r\n<li data-section-id=\"b58tjz\" data-start=\"3286\" data-end=\"3377\"><strong data-start=\"3288\" data-end=\"3335\">Performance-Based Continuation Scholarships</strong> &ndash; Renewal based on semester performance</li>\r\n<li data-section-id=\"og1el2\" data-start=\"3378\" data-end=\"3461\"><strong data-start=\"3380\" data-end=\"3418\">Category-Based Relaxation Benefits</strong> &ndash; Support for reserved category students</li>\r\n<li data-section-id=\"111rl7a\" data-start=\"3462\" data-end=\"3532\"><strong data-start=\"3464\" data-end=\"3494\">Early Admission Incentives</strong> &ndash; Fee benefits for early applicants</li>\r\n</ul>\r\n<h3 data-section-id=\"1t64sl\" data-start=\"3534\" data-end=\"3566\">Key Benefits of Scholarships</h3>\r\n<ul data-start=\"3568\" data-end=\"3793\">\r\n<li data-section-id=\"bmgyun\" data-start=\"3568\" data-end=\"3618\">Reduces overall financial burden significantly</li>\r\n<li data-section-id=\"189butq\" data-start=\"3619\" data-end=\"3669\">Encourages academic consistency and excellence</li>\r\n<li data-section-id=\"ws0skn\" data-start=\"3670\" data-end=\"3716\">Improves accessibility to higher education</li>\r\n<li data-section-id=\"m4aust\" data-start=\"3717\" data-end=\"3793\">Supports students in continuing education without financial interruption</li>\r\n</ul>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.9, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(223, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 103, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 07:26:31', '2026-06-16 05:51:37', '<p data-start=\"123\" data-end=\"483\">The admission process for the <strong data-start=\"153\" data-end=\"177\">MA Sociology program</strong> is designed to be structured, transparent, and student-friendly, ensuring that applicants can complete each stage without confusion. Every step plays a crucial role&mdash;from selecting the right program to final submission of documents&mdash;helping institutions verify eligibility and confirm admission efficiently.</p>\r\n<p data-start=\"485\" data-end=\"665\">Understanding the complete admission flow is essential because even small errors in form filling, documentation, or fee payment can lead to delays or rejection during verification.</p>\r\n<hr data-start=\"667\" data-end=\"670\">\r\n<h2 data-section-id=\"3ozalm\" data-start=\"672\" data-end=\"723\">Step 1: Choose a Program &amp; Complete Registration</h2>\r\n<p data-start=\"725\" data-end=\"909\">The first step in the admission process is selecting the <strong data-start=\"782\" data-end=\"806\">MA Sociology program</strong> and completing the online registration. This step officially begins your academic application journey.</p>\r\n<h3 data-section-id=\"1cjvtyk\" data-start=\"911\" data-end=\"939\">What Students Need to Do</h3>\r\n<ul data-start=\"941\" data-end=\"1173\">\r\n<li data-section-id=\"19xkstu\" data-start=\"941\" data-end=\"989\">Select MA Sociology as the preferred program</li>\r\n<li data-section-id=\"1ekb3ml\" data-start=\"990\" data-end=\"1050\">Complete online registration with basic personal details</li>\r\n<li data-section-id=\"a7vulm\" data-start=\"1051\" data-end=\"1102\">Create login credentials for admission tracking</li>\r\n<li data-section-id=\"1nlppa4\" data-start=\"1103\" data-end=\"1173\">Ensure accuracy in name, contact information, and identity details</li>\r\n</ul>\r\n<h3 data-section-id=\"1e1e5k4\" data-start=\"1175\" data-end=\"1191\">Key Insights</h3>\r\n<p data-start=\"1193\" data-end=\"1470\">Choosing the right program is a critical academic decision because it determines your specialization and future career direction in sociology, research, social development, or policy-related fields. Incorrect registration details may create issues in later verification stages.</p>\r\n<hr data-start=\"1472\" data-end=\"1475\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"1477\" data-end=\"1515\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"1517\" data-end=\"1724\">After registration, candidates must enter their complete academic background. This step is used to verify eligibility and confirm whether the applicant meets the required educational qualification standards.</p>\r\n<h3 data-section-id=\"8lvply\" data-start=\"1726\" data-end=\"1759\">Required Academic Information</h3>\r\n<ul data-start=\"1761\" data-end=\"1976\">\r\n<li data-section-id=\"r6pa90\" data-start=\"1761\" data-end=\"1806\">Class 10 and Class 12 educational details</li>\r\n<li data-section-id=\"a60666\" data-start=\"1807\" data-end=\"1871\">Bachelor&rsquo;s degree information (10+2+3 pattern or equivalent)</li>\r\n<li data-section-id=\"1stubcy\" data-start=\"1872\" data-end=\"1906\">University or institution name</li>\r\n<li data-section-id=\"13b8a4\" data-start=\"1907\" data-end=\"1945\">Year of passing and marks obtained</li>\r\n<li data-section-id=\"1hwdh8a\" data-start=\"1946\" data-end=\"1976\">Percentage or CGPA details</li>\r\n</ul>\r\n<h3 data-section-id=\"1bhiq8b\" data-start=\"1978\" data-end=\"2004\">Important Instructions</h3>\r\n<ul data-start=\"2006\" data-end=\"2301\">\r\n<li data-section-id=\"169rz1h\" data-start=\"2006\" data-end=\"2063\">All academic details must match official certificates</li>\r\n<li data-section-id=\"leluy0\" data-start=\"2064\" data-end=\"2150\">Candidates from NIOS or equivalent boards must clearly mention their board details</li>\r\n<li data-section-id=\"f1ft8q\" data-start=\"2151\" data-end=\"2227\">Final-year students must correctly declare their current academic status</li>\r\n<li data-section-id=\"1c3au2q\" data-start=\"2228\" data-end=\"2301\">AIU-equivalent qualifications must be clearly specified if applicable</li>\r\n</ul>\r\n<h3 data-section-id=\"g0deo8\" data-start=\"2303\" data-end=\"2333\">Why This Step is Important</h3>\r\n<p data-start=\"2335\" data-end=\"2409\">This stage is critical because incorrect academic information can lead to:</p>\r\n<ul data-start=\"2411\" data-end=\"2548\">\r\n<li data-section-id=\"ei6sde\" data-start=\"2411\" data-end=\"2468\">Application rejection during eligibility verification</li>\r\n<li data-section-id=\"7oxh6k\" data-start=\"2469\" data-end=\"2504\">Delay in admission confirmation</li>\r\n<li data-section-id=\"1h7csk1\" data-start=\"2505\" data-end=\"2548\">Document mismatch during final scrutiny</li>\r\n</ul>\r\n<hr data-start=\"2550\" data-end=\"2553\">\r\n<h2 data-section-id=\"15pe0sk\" data-start=\"2555\" data-end=\"2581\">Step 3: Pay Program Fee</h2>\r\n<p data-start=\"2583\" data-end=\"2776\">Once eligibility and academic details are verified, candidates must proceed with the <strong data-start=\"2668\" data-end=\"2691\">program fee payment</strong>. This step confirms the applicant&rsquo;s intention to enroll in the MA Sociology program.</p>\r\n<h3 data-section-id=\"1ekgjb\" data-start=\"2778\" data-end=\"2797\">Payment Process</h3>\r\n<ul data-start=\"2799\" data-end=\"3011\">\r\n<li data-section-id=\"1o8k9xn\" data-start=\"2799\" data-end=\"2896\">Make payment through secure online modes such as UPI, debit card, credit card, or net banking</li>\r\n<li data-section-id=\"1lha11e\" data-start=\"2897\" data-end=\"2952\">Verify transaction success after payment completion</li>\r\n<li data-section-id=\"xlfwe8\" data-start=\"2953\" data-end=\"3011\">Download and save the fee receipt for future reference</li>\r\n</ul>\r\n<h3 data-section-id=\"1i1y6qa\" data-start=\"3013\" data-end=\"3031\">Key Highlights</h3>\r\n<ul data-start=\"3033\" data-end=\"3289\">\r\n<li data-section-id=\"8l74gc\" data-start=\"3033\" data-end=\"3086\">Fee payment confirms provisional admission status</li>\r\n<li data-section-id=\"1lgblg8\" data-start=\"3087\" data-end=\"3153\">Semester-wise or full program payment options may be available</li>\r\n<li data-section-id=\"nsfpkb\" data-start=\"3154\" data-end=\"3210\">EMI facilities may be provided for eligible students</li>\r\n<li data-section-id=\"gys5ka\" data-start=\"3211\" data-end=\"3289\">Admission process moves forward only after successful payment confirmation</li>\r\n</ul>\r\n<h3 data-section-id=\"f2fz65\" data-start=\"3291\" data-end=\"3313\">Important Advisory</h3>\r\n<p data-start=\"3315\" data-end=\"3444\">Students should always ensure payment is made through official portals only to avoid transaction failures or fraudulent activity.</p>\r\n<hr data-start=\"3446\" data-end=\"3449\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"3451\" data-end=\"3499\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"3501\" data-end=\"3702\">The final step involves uploading all required documents and submitting the completed application form. This stage ensures verification of identity, academic qualifications, and eligibility compliance.</p>\r\n<h3 data-section-id=\"8z1ntf\" data-start=\"3704\" data-end=\"3726\">Documents Required</h3>\r\n<ul data-start=\"3728\" data-end=\"4008\">\r\n<li data-section-id=\"1f62403\" data-start=\"3728\" data-end=\"3767\">Class 10 mark sheet and certificate</li>\r\n<li data-section-id=\"8j3ev5\" data-start=\"3768\" data-end=\"3807\">Class 12 mark sheet and certificate</li>\r\n<li data-section-id=\"fdwkz1\" data-start=\"3808\" data-end=\"3863\">Bachelor&rsquo;s degree mark sheets (all semesters/years)</li>\r\n<li data-section-id=\"8xdz5q\" data-start=\"3864\" data-end=\"3901\">Degree certificate (if available)</li>\r\n<li data-section-id=\"7y7fub\" data-start=\"3902\" data-end=\"3957\">Valid identity proof (Aadhaar card, passport, etc.)</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"3958\" data-end=\"3986\">Passport-size photograph</li>\r\n<li data-section-id=\"opd9y4\" data-start=\"3987\" data-end=\"4008\">Scanned signature</li>\r\n</ul>\r\n<h3 data-section-id=\"2494j1\" data-start=\"4010\" data-end=\"4040\">Document Upload Guidelines</h3>\r\n<ul data-start=\"4042\" data-end=\"4250\">\r\n<li data-section-id=\"1ajpwhx\" data-start=\"4042\" data-end=\"4097\">Ensure all documents are clear, valid, and readable</li>\r\n<li data-section-id=\"cbhr6\" data-start=\"4098\" data-end=\"4148\">Upload files in the prescribed format and size</li>\r\n<li data-section-id=\"1kv5120\" data-start=\"4149\" data-end=\"4206\">Double-check all uploaded documents before submission</li>\r\n<li data-section-id=\"1uzsi4t\" data-start=\"4207\" data-end=\"4250\">Avoid missing or mismatched information</li>\r\n</ul>\r\n<h3 data-section-id=\"2iq8bt\" data-start=\"4252\" data-end=\"4280\">Final Submission Process</h3>\r\n<ul data-start=\"4282\" data-end=\"4467\">\r\n<li data-section-id=\"jm2pcu\" data-start=\"4282\" data-end=\"4343\">Review the entire application carefully before submission</li>\r\n<li data-section-id=\"3uvr3r\" data-start=\"4344\" data-end=\"4396\">Submit the form only after verifying all details</li>\r\n<li data-section-id=\"j3md9h\" data-start=\"4397\" data-end=\"4467\">Save a copy of the submitted application form for future reference</li>\r\n</ul>\r\n<hr data-start=\"4469\" data-end=\"4472\">\r\n<h2 data-section-id=\"3rrbgb\" data-start=\"4474\" data-end=\"4508\">Complete Admission Flow Summary</h2>\r\n<p data-start=\"4510\" data-end=\"4582\">The MA Sociology admission process follows a simple four-step structure:</p>\r\n<ul data-start=\"4584\" data-end=\"4707\">\r\n<li data-section-id=\"1ldp32m\" data-start=\"4584\" data-end=\"4613\">Choose program &amp; register</li>\r\n<li data-section-id=\"i95iqm\" data-start=\"4614\" data-end=\"4645\">Provide educational details</li>\r\n<li data-section-id=\"4wifn6\" data-start=\"4646\" data-end=\"4665\">Pay program fee</li>\r\n<li data-section-id=\"1xk7h33\" data-start=\"4666\" data-end=\"4707\">Upload documents &amp; submit application</li>\r\n</ul>', 1, '<p data-start=\"146\" data-end=\"521\">The Master of Arts (MA) in Sociology is a postgraduate program designed for students who want to develop a deep understanding of society, social structures, human behavior, inequality, culture, and institutions. To ensure academic readiness for such an advanced program, universities follow clearly defined eligibility criteria based on recognized educational qualifications.</p>\r\n<p data-start=\"523\" data-end=\"735\">The eligibility framework ensures that students entering the program have the necessary academic foundation to handle theoretical concepts, research methodologies, and analytical studies in sociology effectively.</p>\r\n<hr data-start=\"737\" data-end=\"740\">\r\n<h2 data-section-id=\"4i2a24\" data-start=\"742\" data-end=\"800\">Educational Qualification Requirements for MA Sociology</h2>\r\n<p data-start=\"802\" data-end=\"906\">To be eligible for admission into MA Sociology, candidates must fulfill the following academic criteria:</p>\r\n<ul data-start=\"908\" data-end=\"1178\">\r\n<li data-section-id=\"14xeym3\" data-start=\"908\" data-end=\"1011\">Must have completed a <strong data-start=\"932\" data-end=\"965\">10+2+3-year bachelor&rsquo;s degree</strong> from a recognized university or institution</li>\r\n<li data-section-id=\"148tdec\" data-start=\"1012\" data-end=\"1178\">Alternatively, candidates must hold an <strong data-start=\"1053\" data-end=\"1140\">equivalent qualification recognized by the Association of Indian Universities (AIU)</strong> or other competent statutory bodies</li>\r\n</ul>\r\n<p data-start=\"1180\" data-end=\"1348\">This ensures that all applicants have completed a structured undergraduate education that provides the necessary academic base for postgraduate-level sociology studies.</p>\r\n<hr data-start=\"1350\" data-end=\"1353\">\r\n<h2 data-section-id=\"6qtw7j\" data-start=\"1355\" data-end=\"1391\">Key Academic Eligibility Insights</h2>\r\n<p data-start=\"1393\" data-end=\"1551\">Understanding eligibility is not only about meeting the minimum qualification but also about ensuring academic readiness for advanced social science learning.</p>\r\n<h3 data-section-id=\"13e4bkc\" data-start=\"1553\" data-end=\"1579\">Important Requirements</h3>\r\n<ul data-start=\"1581\" data-end=\"2048\">\r\n<li data-section-id=\"17t4zof\" data-start=\"1581\" data-end=\"1744\">Bachelor&rsquo;s degree can be in any discipline, but backgrounds in Arts, Humanities, Social Sciences, or related fields may provide better conceptual understanding</li>\r\n<li data-section-id=\"g8ajfg\" data-start=\"1745\" data-end=\"1835\">The degree must be obtained from a recognized and accredited university or institution</li>\r\n<li data-section-id=\"1plqwho\" data-start=\"1836\" data-end=\"1911\">AIU recognition is mandatory for foreign or non-standard qualifications</li>\r\n<li data-section-id=\"j5gugi\" data-start=\"1912\" data-end=\"2048\">Final-year undergraduate students may apply provisionally, subject to completion of their degree before final admission confirmation</li>\r\n</ul>\r\n<hr data-start=\"2050\" data-end=\"2053\">\r\n<h2 data-section-id=\"1s6r4qx\" data-start=\"2055\" data-end=\"2096\">Importance of Recognized Qualification</h2>\r\n<p data-start=\"2098\" data-end=\"2357\">Recognition of academic qualification plays a critical role in ensuring the credibility and validity of a student&rsquo;s educational background. Admission authorities strictly verify whether the degree is issued by a valid institution or approved equivalence body.</p>\r\n<h3 data-section-id=\"qi2psf\" data-start=\"2359\" data-end=\"2386\">Why Recognition Matters</h3>\r\n<ul data-start=\"2388\" data-end=\"2608\">\r\n<li data-section-id=\"1ym14rk\" data-start=\"2388\" data-end=\"2440\">Ensures academic credibility and standardization</li>\r\n<li data-section-id=\"1du00jb\" data-start=\"2441\" data-end=\"2498\">Maintains consistency in postgraduate learning levels</li>\r\n<li data-section-id=\"c4pp7k\" data-start=\"2499\" data-end=\"2563\">Prevents admission of unrecognized or invalid qualifications</li>\r\n<li data-section-id=\"1hpss36\" data-start=\"2564\" data-end=\"2608\">Supports global acceptance of the degree</li>\r\n</ul>\r\n<hr data-start=\"2610\" data-end=\"2613\">\r\n<h2 data-section-id=\"1tc8ekn\" data-start=\"3136\" data-end=\"3174\">Eligibility for Final-Year Students</h2>\r\n<p data-start=\"3176\" data-end=\"3323\">Students who are currently in the final year of their bachelor&rsquo;s degree may also be eligible to apply, provided they meet the following conditions:</p>\r\n<ul data-start=\"3325\" data-end=\"3530\">\r\n<li data-section-id=\"1v7fwtz\" data-start=\"3325\" data-end=\"3395\">Must complete their graduation before final admission confirmation</li>\r\n<li data-section-id=\"150rhde\" data-start=\"3396\" data-end=\"3459\">Must submit final mark sheets within the specified deadline</li>\r\n<li data-section-id=\"lobls6\" data-start=\"3460\" data-end=\"3530\">Must fulfill all academic requirements at the time of verification</li>\r\n</ul>\r\n<p data-start=\"3532\" data-end=\"3642\">This provision ensures that students do not lose academic opportunities while waiting for their final results.</p>\r\n<hr data-start=\"3644\" data-end=\"3647\">\r\n<h2 data-section-id=\"1tpbasy\" data-start=\"3649\" data-end=\"3712\">Why This Eligibility Structure is Important for MA Sociology</h2>\r\n<p data-start=\"3714\" data-end=\"3893\">The eligibility criteria for MA Sociology are designed to ensure that students entering the program are academically prepared for advanced theoretical and research-based learning.</p>\r\n<h3 data-section-id=\"1f8rd8t\" data-start=\"3895\" data-end=\"3913\">Key Objectives</h3>\r\n<ul data-start=\"3915\" data-end=\"4248\">\r\n<li data-section-id=\"ctty44\" data-start=\"3915\" data-end=\"3978\">Ensures strong academic foundation for sociological studies</li>\r\n<li data-section-id=\"c3mwnu\" data-start=\"3979\" data-end=\"4045\">Maintains uniform learning standards in postgraduate education</li>\r\n<li data-section-id=\"1w1oo4y\" data-start=\"4046\" data-end=\"4117\">Supports smooth transition from undergraduate to postgraduate level</li>\r\n<li data-section-id=\"1ego42w\" data-start=\"4118\" data-end=\"4177\">Enhances analytical and research capability of students</li>\r\n<li data-section-id=\"jyfou1\" data-start=\"4178\" data-end=\"4248\">Ensures credibility of degree at national and international levels</li>\r\n</ul>', '<p data-start=\"165\" data-end=\"517\">The Master of Arts (MA) in Sociology is a postgraduate program that helps students understand society, social behavior, institutions, culture, inequality, and human interaction in a structured and analytical way. Along with academic learning, understanding the <strong data-start=\"426\" data-end=\"466\">fee structure and financial planning</strong> is equally important for smooth course completion.</p>\r\n<p data-start=\"519\" data-end=\"729\">A well-designed fee system ensures that students can manage their education costs without financial stress while focusing on academic growth, research skills, and career development in sociology-related fields.</p>\r\n<hr data-start=\"731\" data-end=\"734\">\r\n<h2 data-section-id=\"7mwuab\" data-start=\"736\" data-end=\"803\">Total Course Fee Overview (MA Sociology &ndash; Complete Program Cost)</h2>\r\n<p data-start=\"805\" data-end=\"970\">The MA Sociology program fee is structured for the entire duration of <strong data-start=\"875\" data-end=\"893\">four semesters</strong>, making it easier for students to plan their academic investment in advance.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"972\" data-end=\"1077\">\r\n<thead data-start=\"972\" data-end=\"998\">\r\n<tr data-start=\"972\" data-end=\"998\">\r\n<th class=\"\" data-start=\"972\" data-end=\"983\" data-col-size=\"sm\">Category</th>\r\n<th class=\"\" data-start=\"983\" data-end=\"998\" data-col-size=\"sm\">Fee Details</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1026\" data-end=\"1077\">\r\n<tr data-start=\"1026\" data-end=\"1077\">\r\n<td data-start=\"1026\" data-end=\"1059\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"1059\" data-end=\"1077\"><strong data-start=\"1061\" data-end=\"1075\">INR 75,000</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1079\" data-end=\"1259\">This total fee generally includes academic instruction, access to study materials, examination-related services, and institutional academic support throughout the program duration.</p>\r\n<hr data-start=\"1261\" data-end=\"1264\">\r\n<h2 data-section-id=\"1hnr2vi\" data-start=\"1266\" data-end=\"1313\">Semester-Wise Fee Structure for MA Sociology</h2>\r\n<p data-start=\"1315\" data-end=\"1432\">To ensure affordability and reduce financial burden, the course fee is divided into equal semester-wise installments.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1434\" data-end=\"1524\">\r\n<thead data-start=\"1434\" data-end=\"1459\">\r\n<tr data-start=\"1434\" data-end=\"1459\">\r\n<th class=\"\" data-start=\"1434\" data-end=\"1445\" data-col-size=\"sm\">Semester</th>\r\n<th class=\"\" data-start=\"1445\" data-end=\"1459\" data-col-size=\"sm\">Fee Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1486\" data-end=\"1524\">\r\n<tr data-start=\"1486\" data-end=\"1524\">\r\n<td data-start=\"1486\" data-end=\"1506\" data-col-size=\"sm\">Each Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1506\" data-end=\"1524\"><strong data-start=\"1508\" data-end=\"1522\">INR 18,750</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"dey4xd\" data-start=\"1526\" data-end=\"1573\">Key Advantages of Semester-Based Fee System</h3>\r\n<ul data-start=\"1575\" data-end=\"1810\">\r\n<li data-section-id=\"1hgdcbj\" data-start=\"1575\" data-end=\"1624\">Reduces one-time financial burden on students</li>\r\n<li data-section-id=\"1955ors\" data-start=\"1625\" data-end=\"1675\">Allows better financial planning and budgeting</li>\r\n<li data-section-id=\"q5yb7y\" data-start=\"1676\" data-end=\"1735\">Ensures continuous academic access without interruption</li>\r\n<li data-section-id=\"1m7mccz\" data-start=\"1736\" data-end=\"1810\">Provides flexibility for students from different financial backgrounds</li>\r\n</ul>\r\n<p data-start=\"1812\" data-end=\"1957\">This structure is particularly helpful for postgraduate students who may also be preparing for competitive exams, internships, or part-time work.</p>\r\n<hr data-start=\"1959\" data-end=\"1962\">\r\n<h2 data-section-id=\"1qq5fm5\" data-start=\"1964\" data-end=\"2021\">EMI (Easy Monthly Installment) Option for MA Sociology</h2>\r\n<p data-start=\"2023\" data-end=\"2212\">To make higher education more accessible, EMI-based payment options are available for eligible students. This allows students to convert their academic fee into manageable monthly payments.</p>\r\n<h3 data-section-id=\"1ot66s6\" data-start=\"2214\" data-end=\"2234\">EMI Plan Details</h3>\r\n<ul data-start=\"2236\" data-end=\"2454\">\r\n<li data-section-id=\"14cilsi\" data-start=\"2236\" data-end=\"2278\">Starting EMI: <strong data-start=\"2252\" data-end=\"2275\">INR 3,125 per month</strong>*</li>\r\n<li data-section-id=\"12ikpiq\" data-start=\"2279\" data-end=\"2334\">Flexible repayment options depending on eligibility</li>\r\n<li data-section-id=\"1d8x60\" data-start=\"2335\" data-end=\"2384\">Designed to reduce upfront financial pressure</li>\r\n<li data-section-id=\"1sjeya0\" data-start=\"2385\" data-end=\"2454\">Suitable for students seeking budget-friendly education financing</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"2456\" data-end=\"2474\">Important Note</h3>\r\n<ul data-start=\"2476\" data-end=\"2698\">\r\n<li data-section-id=\"76kzlj\" data-start=\"2476\" data-end=\"2525\"><em data-start=\"2478\" data-end=\"2523\">Terms and conditions apply for EMI approval</em></li>\r\n<li data-section-id=\"jc0rhb\" data-start=\"2526\" data-end=\"2615\">EMI eligibility may depend on financial verification and partner lending institutions</li>\r\n<li data-section-id=\"1lfoddy\" data-start=\"2616\" data-end=\"2698\">Interest rates and processing charges may vary based on payment plan selection</li>\r\n</ul>\r\n<hr data-start=\"2700\" data-end=\"2703\">\r\n<h2 data-section-id=\"6y0q7p\" data-start=\"2705\" data-end=\"2746\">Scholarships for MA Sociology Students</h2>\r\n<p data-start=\"2748\" data-end=\"2978\">Scholarships play a major role in supporting students who show academic excellence or financial need. These financial assistance options help reduce the overall cost of education and improve accessibility for deserving candidates.</p>\r\n<h3 data-section-id=\"1lyfrj8\" data-start=\"2980\" data-end=\"3015\">Types of Scholarships Available</h3>\r\n<ul data-start=\"3017\" data-end=\"3427\">\r\n<li data-section-id=\"1w8ymaz\" data-start=\"3017\" data-end=\"3111\"><strong data-start=\"3019\" data-end=\"3047\">Merit-Based Scholarships</strong> &ndash; For students with strong academic performance in graduation</li>\r\n<li data-section-id=\"1x15hw9\" data-start=\"3112\" data-end=\"3190\"><strong data-start=\"3114\" data-end=\"3142\">Need-Based Financial Aid</strong> &ndash; Support for economically weaker backgrounds</li>\r\n<li data-section-id=\"q1a3e2\" data-start=\"3191\" data-end=\"3279\"><strong data-start=\"3193\" data-end=\"3227\">Performance-Based Scholarships</strong> &ndash; Continued support based on semester performance</li>\r\n<li data-section-id=\"1uzyw49\" data-start=\"3280\" data-end=\"3355\"><strong data-start=\"3282\" data-end=\"3311\">Category-Based Relaxation</strong> &ndash; Benefits for reserved category students</li>\r\n<li data-section-id=\"c3h3gb\" data-start=\"3356\" data-end=\"3427\"><strong data-start=\"3358\" data-end=\"3386\">Early Admission Benefits</strong> &ndash; Fee concessions for early applicants</li>\r\n</ul>\r\n<h3 data-section-id=\"jtxpyq\" data-start=\"3429\" data-end=\"3457\">Benefits of Scholarships</h3>\r\n<ul data-start=\"3459\" data-end=\"3670\">\r\n<li data-section-id=\"1a3zmaa\" data-start=\"3459\" data-end=\"3507\">Reduces overall tuition burden significantly</li>\r\n<li data-section-id=\"189butq\" data-start=\"3508\" data-end=\"3558\">Encourages academic consistency and excellence</li>\r\n<li data-section-id=\"2y5mw2\" data-start=\"3559\" data-end=\"3622\">Improves accessibility for financially constrained students</li>\r\n<li data-section-id=\"1g8svx5\" data-start=\"3623\" data-end=\"3670\">Supports uninterrupted academic progression</li>\r\n</ul>', 'Medium', '<p data-start=\"142\" data-end=\"547\">The Online MA Sociology program is designed to provide a deep and structured understanding of society, human behavior, social institutions, cultural systems, and development patterns through a combination of theoretical and research-based learning. The curriculum is carefully curated to help students develop analytical thinking, research skills, and a strong understanding of contemporary social issues.</p>\r\n<p data-start=\"549\" data-end=\"913\">This postgraduate program focuses on both classical and modern sociological perspectives, ensuring that learners gain academic depth along with practical insights into real-world social systems. The subject structure is aligned with current academic standards, making it suitable for careers in research, education, civil services, NGOs, and policy-related fields.</p>\r\n<hr data-start=\"915\" data-end=\"918\">\r\n<h2 data-section-id=\"1lin39\" data-start=\"920\" data-end=\"967\">Core Subjects in Online MA Sociology Program</h2>\r\n<p data-start=\"969\" data-end=\"1255\">The MA Sociology curriculum includes a range of core subjects that build a strong foundation in sociological theories, research methodologies, and applied sociology. Each subject is designed to enhance critical thinking and develop a deeper understanding of society and its functioning.</p>\r\n<h3 data-section-id=\"1ofz8xq\" data-start=\"1257\" data-end=\"1295\">Contemporary Sociological Theories</h3>\r\n<p data-start=\"1297\" data-end=\"1455\">This subject focuses on modern sociological perspectives and theoretical frameworks that explain social structures and human behavior in contemporary society.</p>\r\n<ul data-start=\"1457\" data-end=\"1714\">\r\n<li data-section-id=\"1le1s0c\" data-start=\"1457\" data-end=\"1510\">Covers key modern sociologists and their theories</li>\r\n<li data-section-id=\"10efdbv\" data-start=\"1511\" data-end=\"1583\">Explores functionalism, conflict theory, and symbolic interactionism</li>\r\n<li data-section-id=\"1qgxa4z\" data-start=\"1584\" data-end=\"1645\">Helps students understand social change and modernization</li>\r\n<li data-section-id=\"1izn49l\" data-start=\"1646\" data-end=\"1714\">Builds theoretical foundation for advanced sociological analysis</li>\r\n</ul>\r\n<h3 data-section-id=\"1xoabab\" data-start=\"1716\" data-end=\"1753\">Culture, Personality, and Society</h3>\r\n<p data-start=\"1755\" data-end=\"1874\">This paper explores the relationship between individual personality development and cultural influences within society.</p>\r\n<ul data-start=\"1876\" data-end=\"2088\">\r\n<li data-section-id=\"106y5kr\" data-start=\"1876\" data-end=\"1922\">Examines how culture shapes human behavior</li>\r\n<li data-section-id=\"4irsaw\" data-start=\"1923\" data-end=\"1974\">Studies socialization and personality formation</li>\r\n<li data-section-id=\"1jjzkib\" data-start=\"1975\" data-end=\"2030\">Analyzes interaction between individual and society</li>\r\n<li data-section-id=\"1x6oua8\" data-start=\"2031\" data-end=\"2088\">Provides insight into cultural diversity and identity</li>\r\n</ul>\r\n<h3 data-section-id=\"27j8dt\" data-start=\"2090\" data-end=\"2127\">Research Methodology in Sociology</h3>\r\n<p data-start=\"2129\" data-end=\"2253\">This is a fundamental subject that equips students with tools and techniques required for social research and data analysis.</p>\r\n<ul data-start=\"2255\" data-end=\"2505\">\r\n<li data-section-id=\"1mr92x6\" data-start=\"2255\" data-end=\"2315\">Introduces qualitative and quantitative research methods</li>\r\n<li data-section-id=\"1i3loay\" data-start=\"2316\" data-end=\"2395\">Covers data collection techniques like surveys, interviews, and observation</li>\r\n<li data-section-id=\"1bq8fcv\" data-start=\"2396\" data-end=\"2453\">Focuses on research design and hypothesis formulation</li>\r\n<li data-section-id=\"3zit9i\" data-start=\"2454\" data-end=\"2505\">Develops analytical and academic writing skills</li>\r\n</ul>\r\n<h3 data-section-id=\"9seus6\" data-start=\"2507\" data-end=\"2532\">Sociology of Religion</h3>\r\n<p data-start=\"2534\" data-end=\"2627\">This subject examines the role of religion in shaping social norms, values, and institutions.</p>\r\n<ul data-start=\"2629\" data-end=\"2837\">\r\n<li data-section-id=\"1nw0u4n\" data-start=\"2629\" data-end=\"2682\">Studies relationship between religion and society</li>\r\n<li data-section-id=\"1osv44w\" data-start=\"2683\" data-end=\"2740\">Analyzes religious beliefs, rituals, and institutions</li>\r\n<li data-section-id=\"1a3xe4v\" data-start=\"2741\" data-end=\"2788\">Explores secularism and religious diversity</li>\r\n<li data-section-id=\"5e56la\" data-start=\"2789\" data-end=\"2837\">Understands religion as a social institution</li>\r\n</ul>\r\n<h3 data-section-id=\"18e9emw\" data-start=\"2839\" data-end=\"2867\">Sociology of Development</h3>\r\n<p data-start=\"2869\" data-end=\"2979\">This paper focuses on development theories, economic growth, and social transformation in different societies.</p>\r\n<ul data-start=\"2981\" data-end=\"3195\">\r\n<li data-section-id=\"1r3l0tr\" data-start=\"2981\" data-end=\"3036\">Covers concepts of development and underdevelopment</li>\r\n<li data-section-id=\"b1zppt\" data-start=\"3037\" data-end=\"3085\">Examines globalization and its social impact</li>\r\n<li data-section-id=\"1xlca8g\" data-start=\"3086\" data-end=\"3134\">Studies rural and urban development patterns</li>\r\n<li data-section-id=\"sb3mdk\" data-start=\"3135\" data-end=\"3195\">Analyzes policies affecting social and economic progress</li>\r\n</ul>\r\n<h3 data-section-id=\"110grzr\" data-start=\"3197\" data-end=\"3220\">Sociology of Health</h3>\r\n<p data-start=\"3222\" data-end=\"3319\">This subject deals with the social aspects of health, illness, and healthcare systems in society.</p>\r\n<ul data-start=\"3321\" data-end=\"3525\">\r\n<li data-section-id=\"kutxb9\" data-start=\"3321\" data-end=\"3373\">Explores relationship between society and health</li>\r\n<li data-section-id=\"164rwgh\" data-start=\"3374\" data-end=\"3429\">Studies healthcare systems and accessibility issues</li>\r\n<li data-section-id=\"hoe2k1\" data-start=\"3430\" data-end=\"3472\">Analyzes social determinants of health</li>\r\n<li data-section-id=\"1f6hvcj\" data-start=\"3473\" data-end=\"3525\">Focuses on public health policies and challenges</li>\r\n</ul>\r\n<h3 data-section-id=\"qdig2p\" data-start=\"3527\" data-end=\"3556\">Social Movements in India</h3>\r\n<p data-start=\"3558\" data-end=\"3657\">This paper focuses on historical and contemporary social movements that have shaped Indian society.</p>\r\n<ul data-start=\"3659\" data-end=\"3876\">\r\n<li data-section-id=\"iqtyzj\" data-start=\"3659\" data-end=\"3716\">Studies major social and political movements in India</li>\r\n<li data-section-id=\"rcm8yf\" data-start=\"3717\" data-end=\"3767\">Examines issues of caste, gender, and equality</li>\r\n<li data-section-id=\"ixouqw\" data-start=\"3768\" data-end=\"3815\">Analyzes role of movements in social change</li>\r\n<li data-section-id=\"1ewr95k\" data-start=\"3816\" data-end=\"3876\">Develops understanding of collective action and activism</li>\r\n</ul>\r\n<hr data-start=\"3878\" data-end=\"3881\">\r\n<h2 data-section-id=\"1mdpmvr\" data-start=\"3883\" data-end=\"3927\">Academic Value of MA Sociology Curriculum</h2>\r\n<p data-start=\"3929\" data-end=\"4234\">The Online MA Sociology syllabus is designed not only to provide theoretical knowledge but also to develop practical understanding of social realities. It bridges the gap between academic learning and real-world application, making students capable of critical analysis and research-based decision-making.</p>\r\n<h3 data-section-id=\"18630cc\" data-start=\"4236\" data-end=\"4261\">Key Learning Outcomes</h3>\r\n<ul data-start=\"4263\" data-end=\"4557\">\r\n<li data-section-id=\"w6pdw3\" data-start=\"4263\" data-end=\"4327\">Strong understanding of sociological theories and frameworks</li>\r\n<li data-section-id=\"h2eh9t\" data-start=\"4328\" data-end=\"4378\">Ability to conduct independent social research</li>\r\n<li data-section-id=\"h9i2v5\" data-start=\"4379\" data-end=\"4435\">Analytical thinking about social issues and policies</li>\r\n<li data-section-id=\"mjtlyg\" data-start=\"4436\" data-end=\"4500\">Awareness of cultural, religious, and developmental dynamics</li>\r\n<li data-section-id=\"dkhd1g\" data-start=\"4501\" data-end=\"4557\">Preparation for research, teaching, and policy roles</li>\r\n</ul>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(224, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 104, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 07:34:31', '2026-06-16 05:48:52', NULL, 1, '<p data-start=\"171\" data-end=\"625\">The <strong data-start=\"175\" data-end=\"202\">MA in Political Science</strong> is a postgraduate program designed for students who want to develop a strong understanding of political systems, governance, public administration, international relations, political theory, and policy analysis. Since it is an advanced academic program, universities follow a clearly defined eligibility structure to ensure that students entering the course have the required academic foundation and analytical capability.</p>\r\n<p data-start=\"627\" data-end=\"815\">The eligibility criteria are designed to maintain academic quality, ensure conceptual readiness, and support students in successfully handling postgraduate-level political science studies.</p>\r\n<hr data-start=\"817\" data-end=\"820\">\r\n<h2 data-section-id=\"dul1nr\" data-start=\"822\" data-end=\"863\">Who Can Apply for MA Political Science</h2>\r\n<p data-start=\"865\" data-end=\"1210\">The MA Political Science program is open to both domestic and international applicants, provided they meet the required academic qualifications and institutional recognition standards. The admission framework is inclusive, allowing students from diverse educational backgrounds to apply, as long as their previous degree is valid and recognized.</p>\r\n<h3 data-section-id=\"aucx2f\" data-start=\"1212\" data-end=\"1235\">Domestic Applicants</h3>\r\n<p data-start=\"1237\" data-end=\"1523\">Domestic students include candidates who have completed their education within India from recognized universities or institutions. These applicants must meet the prescribed graduation requirements and ensure that their degree is officially valid under recognized higher education norms.</p>\r\n<h3 data-section-id=\"17eon9v\" data-start=\"1525\" data-end=\"1553\">International Applicants</h3>\r\n<p data-start=\"1555\" data-end=\"1705\">International students are also eligible to apply for MA Political Science, provided their academic qualifications are equivalent to Indian standards.</p>\r\n<p data-start=\"1707\" data-end=\"1761\">Key requirements for international applicants include:</p>\r\n<ul data-start=\"1763\" data-end=\"2114\">\r\n<li data-section-id=\"36o1gg\" data-start=\"1763\" data-end=\"1839\">Must hold a valid bachelor&rsquo;s degree from a recognized foreign university</li>\r\n<li data-section-id=\"103jvc9\" data-start=\"1840\" data-end=\"1913\">Degree must be equivalent to Indian undergraduate education standards</li>\r\n<li data-section-id=\"1ymle61\" data-start=\"1914\" data-end=\"2029\">Qualification must be recognized by the Association of Indian Universities (AIU) or other competent authorities</li>\r\n<li data-section-id=\"msij3v\" data-start=\"2030\" data-end=\"2114\">Academic transcripts and supporting documents must be submitted for verification</li>\r\n</ul>\r\n<p data-start=\"2116\" data-end=\"2277\">This ensures that students from different countries can pursue higher education in India while maintaining academic consistency and global recognition standards.</p>\r\n<hr data-start=\"2279\" data-end=\"2282\">\r\n<h2 data-section-id=\"1q2sa3j\" data-start=\"2284\" data-end=\"2325\">Educational Qualification Requirements</h2>\r\n<p data-start=\"2327\" data-end=\"2439\">To be eligible for admission into MA Political Science, candidates must meet the following academic requirement:</p>\r\n<ul data-start=\"2441\" data-end=\"2711\">\r\n<li data-section-id=\"14xeym3\" data-start=\"2441\" data-end=\"2544\">Must have completed a <strong data-start=\"2465\" data-end=\"2498\">10+2+3-year bachelor&rsquo;s degree</strong> from a recognized university or institution</li>\r\n<li data-section-id=\"148tdec\" data-start=\"2545\" data-end=\"2711\">Alternatively, candidates must hold an <strong data-start=\"2586\" data-end=\"2673\">equivalent qualification recognized by the Association of Indian Universities (AIU)</strong> or other competent statutory bodies</li>\r\n</ul>\r\n<p data-start=\"2713\" data-end=\"2888\">This ensures that all applicants have completed a structured undergraduate program that provides a strong academic foundation for postgraduate-level political science studies.</p>\r\n<hr data-start=\"2890\" data-end=\"2893\">\r\n<h2 data-section-id=\"6qtw7j\" data-start=\"2895\" data-end=\"2931\">Key Academic Eligibility Insights</h2>\r\n<p data-start=\"2933\" data-end=\"3157\">Eligibility for MA Political Science is not just about completing a degree&mdash;it is about ensuring that students have the analytical and academic readiness required for advanced study in political theory and governance systems.</p>\r\n<h3 data-section-id=\"9hvfnk\" data-start=\"3159\" data-end=\"3196\">Important Academic Considerations</h3>\r\n<ul data-start=\"3198\" data-end=\"3648\">\r\n<li data-section-id=\"1612zff\" data-start=\"3198\" data-end=\"3344\">Bachelor&rsquo;s degree can be from any discipline, but Arts, Social Sciences, or Humanities backgrounds may provide better conceptual understanding</li>\r\n<li data-section-id=\"1plqwho\" data-start=\"3345\" data-end=\"3420\">AIU recognition is mandatory for foreign or non-standard qualifications</li>\r\n<li data-section-id=\"kok4zc\" data-start=\"3421\" data-end=\"3556\">Final-year students may be eligible to apply provisionally, subject to completion of graduation before final admission confirmation</li>\r\n<li data-section-id=\"537ni1\" data-start=\"3557\" data-end=\"3648\">All academic documents must be valid, verifiable, and issued by recognized institutions</li>\r\n</ul>\r\n<hr data-start=\"3650\" data-end=\"3653\">\r\n<h2 data-section-id=\"hwjh22\" data-start=\"3655\" data-end=\"3727\">Importance of Recognized Qualification in Political Science Admission</h2>\r\n<p data-start=\"3729\" data-end=\"3979\">Recognition of academic qualifications ensures that students entering the program have a standardized level of education. This is essential for maintaining academic quality in discussions related to governance, political systems, and policy analysis.</p>\r\n<h3 data-section-id=\"qi2psf\" data-start=\"3981\" data-end=\"4008\">Why Recognition Matters</h3>\r\n<ul data-start=\"4010\" data-end=\"4271\">\r\n<li data-section-id=\"fq403k\" data-start=\"4010\" data-end=\"4069\">Ensures credibility and validity of academic background</li>\r\n<li data-section-id=\"c3mwnu\" data-start=\"4070\" data-end=\"4136\">Maintains uniform learning standards in postgraduate education</li>\r\n<li data-section-id=\"c4pp7k\" data-start=\"4137\" data-end=\"4201\">Prevents admission of unrecognized or invalid qualifications</li>\r\n<li data-section-id=\"2qycnn\" data-start=\"4202\" data-end=\"4271\">Supports global acceptance of the degree for future opportunities</li>\r\n</ul>\r\n<hr data-start=\"4273\" data-end=\"4276\">\r\n<h2 data-section-id=\"1tc8ekn\" data-start=\"4806\" data-end=\"4844\">Eligibility for Final-Year Students</h2>\r\n<p data-start=\"4846\" data-end=\"4987\">Students who are currently in the final year of their bachelor&rsquo;s degree may also be eligible to apply, provided they meet certain conditions.</p>\r\n<h3 data-section-id=\"1od1ws1\" data-start=\"4989\" data-end=\"5007\">Key Conditions</h3>\r\n<ul data-start=\"5009\" data-end=\"5212\">\r\n<li data-section-id=\"a9ou8l\" data-start=\"5009\" data-end=\"5073\">Must complete graduation before final admission confirmation</li>\r\n<li data-section-id=\"hcwk9v\" data-start=\"5074\" data-end=\"5137\">Must submit final mark sheets within the specified timeline</li>\r\n<li data-section-id=\"1vde4n1\" data-start=\"5138\" data-end=\"5212\">Must fulfill minimum eligibility requirements after result declaration</li>\r\n</ul>\r\n<p data-start=\"5214\" data-end=\"5325\">This provision ensures that students do not miss admission opportunities while waiting for their final results.</p>', '<p data-start=\"180\" data-end=\"570\">The <strong data-start=\"184\" data-end=\"228\">Master of Arts (MA) in Political Science</strong> is a postgraduate program designed for students who want to understand governance, political systems, public administration, international relations, public policy, and political theory in depth. Along with academic preparation, understanding the <strong data-start=\"476\" data-end=\"516\">fee structure and financial planning</strong> is essential for making informed admission decisions.</p>\r\n<p data-start=\"572\" data-end=\"848\">A well-structured fee system ensures transparency, affordability, and flexibility so that students from different financial backgrounds can pursue higher education without stress while focusing on academic excellence and career development in political science-related fields.</p>\r\n<hr data-start=\"850\" data-end=\"853\">\r\n<h2 data-section-id=\"1q2zscw\" data-start=\"855\" data-end=\"926\">Total Course Fee Overview (MA Political Science &ndash; Full Program Cost)</h2>\r\n<p data-start=\"928\" data-end=\"1107\">The MA Political Science program fee is structured for the complete duration of <strong data-start=\"1008\" data-end=\"1026\">four semesters</strong>, allowing students to clearly understand the total academic investment required.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1109\" data-end=\"1214\">\r\n<thead data-start=\"1109\" data-end=\"1135\">\r\n<tr data-start=\"1109\" data-end=\"1135\">\r\n<th class=\"\" data-start=\"1109\" data-end=\"1120\" data-col-size=\"sm\">Category</th>\r\n<th class=\"\" data-start=\"1120\" data-end=\"1135\" data-col-size=\"sm\">Fee Details</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1163\" data-end=\"1214\">\r\n<tr data-start=\"1163\" data-end=\"1214\">\r\n<td data-start=\"1163\" data-end=\"1196\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"1196\" data-end=\"1214\"><strong data-start=\"1198\" data-end=\"1212\">INR 75,000</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1216\" data-end=\"1401\">This total fee generally covers academic instruction, curriculum delivery, access to learning resources, examination services, and institutional academic support throughout the program.</p>\r\n<hr data-start=\"1403\" data-end=\"1406\">\r\n<h2 data-section-id=\"1pbz3qv\" data-start=\"1408\" data-end=\"1463\">Semester-Wise Fee Structure for MA Political Science</h2>\r\n<p data-start=\"1465\" data-end=\"1640\">To ensure affordability and financial ease, the course fee is divided into equal semester-wise installments. This helps students manage their academic expenses systematically.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1642\" data-end=\"1732\">\r\n<thead data-start=\"1642\" data-end=\"1667\">\r\n<tr data-start=\"1642\" data-end=\"1667\">\r\n<th class=\"\" data-start=\"1642\" data-end=\"1653\" data-col-size=\"sm\">Semester</th>\r\n<th class=\"\" data-start=\"1653\" data-end=\"1667\" data-col-size=\"sm\">Fee Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1694\" data-end=\"1732\">\r\n<tr data-start=\"1694\" data-end=\"1732\">\r\n<td data-start=\"1694\" data-end=\"1714\" data-col-size=\"sm\">Each Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1714\" data-end=\"1732\"><strong data-start=\"1716\" data-end=\"1730\">INR 18,750</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1mqa0zx\" data-start=\"1734\" data-end=\"1779\">Key Benefits of Semester-Based Fee System</h3>\r\n<ul data-start=\"1781\" data-end=\"2048\">\r\n<li data-section-id=\"yeq6sk\" data-start=\"1781\" data-end=\"1843\">Reduces one-time financial burden on students and families</li>\r\n<li data-section-id=\"urt5h7\" data-start=\"1844\" data-end=\"1900\">Allows structured and predictable financial planning</li>\r\n<li data-section-id=\"185rcbv\" data-start=\"1901\" data-end=\"1964\">Ensures uninterrupted access to academic learning resources</li>\r\n<li data-section-id=\"ztbr8a\" data-start=\"1965\" data-end=\"2048\">Helps students balance education with personal or professional responsibilities</li>\r\n</ul>\r\n<p data-start=\"2050\" data-end=\"2229\">This structure is particularly beneficial for students preparing for competitive exams such as UPSC, state PSCs, or other government services alongside their postgraduate studies.</p>\r\n<hr data-start=\"2231\" data-end=\"2234\">\r\n<h2 data-section-id=\"1n869pw\" data-start=\"2236\" data-end=\"2301\">EMI (Easy Monthly Installment) Option for MA Political Science</h2>\r\n<p data-start=\"2303\" data-end=\"2493\">To make higher education more accessible, EMI-based payment options are available for eligible students. This allows students to convert their academic fees into affordable monthly payments.</p>\r\n<h3 data-section-id=\"1ot66s6\" data-start=\"2495\" data-end=\"2515\">EMI Plan Details</h3>\r\n<ul data-start=\"2517\" data-end=\"2731\">\r\n<li data-section-id=\"14cilsi\" data-start=\"2517\" data-end=\"2559\">Starting EMI: <strong data-start=\"2533\" data-end=\"2556\">INR 3,125 per month</strong>*</li>\r\n<li data-section-id=\"15detlp\" data-start=\"2560\" data-end=\"2611\">Flexible repayment options based on eligibility</li>\r\n<li data-section-id=\"1d8x60\" data-start=\"2612\" data-end=\"2661\">Designed to reduce upfront financial pressure</li>\r\n<li data-section-id=\"1sjeya0\" data-start=\"2662\" data-end=\"2731\">Suitable for students seeking budget-friendly education financing</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"2733\" data-end=\"2751\">Important Note</h3>\r\n<ul data-start=\"2753\" data-end=\"2974\">\r\n<li data-section-id=\"76kzlj\" data-start=\"2753\" data-end=\"2802\"><em data-start=\"2755\" data-end=\"2800\">Terms and conditions apply for EMI approval</em></li>\r\n<li data-section-id=\"1npdp6m\" data-start=\"2803\" data-end=\"2888\">EMI eligibility may depend on financial verification and lending partner policies</li>\r\n<li data-section-id=\"8qo0n4\" data-start=\"2889\" data-end=\"2974\">Interest rates and processing charges may vary depending on selected payment plan</li>\r\n</ul>\r\n<hr data-start=\"2976\" data-end=\"2979\">\r\n<h2 data-section-id=\"1p5b6b0\" data-start=\"2981\" data-end=\"3030\">Scholarships for MA Political Science Students</h2>\r\n<p data-start=\"3032\" data-end=\"3297\">Scholarships are an important financial support system that helps students reduce their educational expenses while encouraging academic excellence. These benefits ensure that deserving students are not denied access to higher education due to financial constraints.</p>\r\n<h3 data-section-id=\"1lyfrj8\" data-start=\"3299\" data-end=\"3334\">Types of Scholarships Available</h3>\r\n<ul data-start=\"3336\" data-end=\"3758\">\r\n<li data-section-id=\"1w8ymaz\" data-start=\"3336\" data-end=\"3430\"><strong data-start=\"3338\" data-end=\"3366\">Merit-Based Scholarships</strong> &ndash; For students with strong academic performance in graduation</li>\r\n<li data-section-id=\"y0nzao\" data-start=\"3431\" data-end=\"3522\"><strong data-start=\"3433\" data-end=\"3468\">Need-Based Financial Assistance</strong> &ndash; For students from economically weaker backgrounds</li>\r\n<li data-section-id=\"1fjxb9k\" data-start=\"3523\" data-end=\"3607\"><strong data-start=\"3525\" data-end=\"3559\">Performance-Based Scholarships</strong> &ndash; Continued support based on semester results</li>\r\n<li data-section-id=\"1ch4yat\" data-start=\"3608\" data-end=\"3685\"><strong data-start=\"3610\" data-end=\"3648\">Category-Based Relaxation Benefits</strong> &ndash; For reserved category candidates</li>\r\n<li data-section-id=\"1ldgpvh\" data-start=\"3686\" data-end=\"3758\"><strong data-start=\"3688\" data-end=\"3720\">Early Admission Scholarships</strong> &ndash; Fee benefits for early applicants</li>\r\n</ul>\r\n<h3 data-section-id=\"1t64sl\" data-start=\"3760\" data-end=\"3792\">Key Benefits of Scholarships</h3>\r\n<ul data-start=\"3794\" data-end=\"3993\">\r\n<li data-section-id=\"3r1dzx\" data-start=\"3794\" data-end=\"3845\">Reduces overall course fee burden significantly</li>\r\n<li data-section-id=\"daultx\" data-start=\"3846\" data-end=\"3892\">Encourages consistent academic performance</li>\r\n<li data-section-id=\"ws0skn\" data-start=\"3893\" data-end=\"3939\">Improves accessibility to higher education</li>\r\n<li data-section-id=\"7klcev\" data-start=\"3940\" data-end=\"3993\">Supports students throughout the academic journey</li>\r\n</ul>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL),
(225, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 75, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-04-30 23:56:46', '2026-06-16 05:49:16', '<p data-start=\"22\" data-end=\"273\">The admission process is designed to be simple, fully structured, and student-friendly so that applicants can complete their registration smoothly without confusion. Each step is clearly defined to ensure transparency and quick application submission.</p>\r\n<hr data-start=\"275\" data-end=\"278\">\r\n<h2 data-section-id=\"g9ni70\" data-start=\"280\" data-end=\"309\">Step 1: Choose a Programme</h2>\r\n<p data-start=\"311\" data-end=\"579\">The first step is to carefully select the desired academic programme based on your career goals, academic background, and future aspirations. Applicants should review the course structure, eligibility requirements, and learning outcomes before finalizing their choice.</p>\r\n<p data-start=\"581\" data-end=\"736\">Selecting the right programme at this stage is important because it determines your specialization, skill development path, and long-term career direction.</p>\r\n<hr data-start=\"738\" data-end=\"741\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"743\" data-end=\"781\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"783\" data-end=\"992\">After selecting the programme, candidates are required to fill in their complete educational information. This includes academic qualifications, previous degree details, and other relevant educational history.</p>\r\n<p data-start=\"994\" data-end=\"1169\">Applicants must ensure that all details entered are accurate and match official academic records, as incorrect information may lead to delays or rejection during verification.</p>\r\n<hr data-start=\"1171\" data-end=\"1174\">\r\n<h2 data-section-id=\"7jn770\" data-start=\"1176\" data-end=\"1204\">Step 3: Pay Programme Fee</h2>\r\n<p data-start=\"1206\" data-end=\"1425\">Once the educational details are submitted, candidates need to proceed with the fee payment process. The programme fee can be paid through available online payment methods, ensuring a secure and hassle-free transaction.</p>\r\n<p data-start=\"1427\" data-end=\"1605\">Students may also explore flexible payment options such as installment plans or EMI facilities (if applicable), which help in managing the financial commitment more conveniently.</p>\r\n<p data-start=\"1607\" data-end=\"1704\">Timely payment is essential to confirm the application and move forward in the admission process.</p>\r\n<hr data-start=\"1706\" data-end=\"1709\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"1711\" data-end=\"1759\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"1761\" data-end=\"1985\">In the final stage, applicants are required to upload all necessary supporting documents. These typically include academic certificates, identity proof, and other required records as specified during the application process.</p>\r\n<p data-start=\"1987\" data-end=\"2210\">After uploading the documents, candidates must carefully review all entered information and then submit the application form. Once submitted, the application is processed for verification and further admission confirmation.</p>\r\n<hr data-start=\"2212\" data-end=\"2215\">\r\n<h2 data-section-id=\"b6zxer\" data-start=\"2217\" data-end=\"2259\">Key Highlights of the Admission Process</h2>\r\n<ul data-start=\"2261\" data-end=\"2465\">\r\n<li data-section-id=\"9cb5z4\" data-start=\"2261\" data-end=\"2305\">Simple and fully online application flow</li>\r\n<li data-section-id=\"yvu30h\" data-start=\"2306\" data-end=\"2346\">Step-by-step guided admission system</li>\r\n<li data-section-id=\"1sfkv83\" data-start=\"2347\" data-end=\"2377\">Secure fee payment options</li>\r\n<li data-section-id=\"1k6fcr6\" data-start=\"2378\" data-end=\"2420\">Document verification after submission</li>\r\n<li data-section-id=\"1e34sdp\" data-start=\"2421\" data-end=\"2465\">Transparent and student-friendly process</li>\r\n</ul>', 1, '<h2 data-section-id=\"1a1xifn\" data-start=\"0\" data-end=\"34\">Who Can Apply for the Programme</h2>\r\n<p data-start=\"36\" data-end=\"372\">The eligibility framework is designed to be inclusive while ensuring that students have the foundational academic background required to successfully pursue advanced studies. It accommodates both technically trained candidates and students from diverse academic streams, provided they complete necessary bridge support in core subjects.</p>\r\n<hr data-start=\"374\" data-end=\"377\">\r\n<h2 data-section-id=\"pghhov\" data-start=\"379\" data-end=\"401\">Eligible Applicants</h2>\r\n<p data-start=\"403\" data-end=\"561\">The programme is open to both domestic and international students, ensuring a diverse learning environment with global academic exposure and peer interaction.</p>\r\n<h3 data-section-id=\"tt18ux\" data-start=\"563\" data-end=\"585\">Student Categories</h3>\r\n<ul data-start=\"586\" data-end=\"634\">\r\n<li data-section-id=\"55zn8c\" data-start=\"586\" data-end=\"607\">Domestic Students</li>\r\n<li data-section-id=\"1ovgt2g\" data-start=\"608\" data-end=\"634\">International Students</li>\r\n</ul>\r\n<hr data-start=\"636\" data-end=\"639\">\r\n<h2 data-section-id=\"1qu9ips\" data-start=\"641\" data-end=\"678\">Educational Qualification Criteria</h2>\r\n<p data-start=\"680\" data-end=\"769\">Candidates must meet one of the following academic pathways to be eligible for admission.</p>\r\n<h3 data-section-id=\"oadyhw\" data-start=\"771\" data-end=\"825\">Primary Eligibility Route (IT/Computer Background)</h3>\r\n<p data-start=\"827\" data-end=\"976\">Candidates should have completed a <strong data-start=\"862\" data-end=\"895\">10+2+3-year bachelor&rsquo;s degree</strong> in any of the following disciplines from a recognized university or institution:</p>\r\n<ul data-start=\"978\" data-end=\"1051\">\r\n<li data-section-id=\"1kb4bqe\" data-start=\"978\" data-end=\"1003\">Computer Applications</li>\r\n<li data-section-id=\"8av9i3\" data-start=\"1004\" data-end=\"1024\">Computer Science</li>\r\n<li data-section-id=\"in4br6\" data-start=\"1025\" data-end=\"1051\">Information Technology</li>\r\n</ul>\r\n<p data-start=\"1053\" data-end=\"1196\">Equivalent qualifications recognized by the <strong data-start=\"1097\" data-end=\"1141\">Association of Indian Universities (AIU)</strong> or other competent statutory bodies are also accepted.</p>\r\n<p data-start=\"1198\" data-end=\"1343\">This pathway is designed for students who already possess a strong foundational understanding of computing concepts, programming, and IT systems.</p>\r\n<hr data-start=\"1345\" data-end=\"1348\">\r\n<h3 data-section-id=\"qp4vh3\" data-start=\"1350\" data-end=\"1412\">Alternative Eligibility Route (Non-IT Background Students)</h3>\r\n<p data-start=\"1414\" data-end=\"1612\">Candidates from diverse academic backgrounds are also eligible, ensuring wider accessibility to the programme. Students who have completed a <strong data-start=\"1555\" data-end=\"1588\">10+2+3-year bachelor&rsquo;s degree</strong> in disciplines such as:</p>\r\n<ul data-start=\"1614\" data-end=\"1747\">\r\n<li data-section-id=\"y83j8c\" data-start=\"1614\" data-end=\"1625\">Science</li>\r\n<li data-section-id=\"5uoz40\" data-start=\"1626\" data-end=\"1653\">Business Administration</li>\r\n<li data-section-id=\"17aknr1\" data-start=\"1654\" data-end=\"1677\">Business Management</li>\r\n<li data-section-id=\"v4h0lx\" data-start=\"1678\" data-end=\"1690\">Commerce</li>\r\n<li data-section-id=\"1lc25rb\" data-start=\"1691\" data-end=\"1712\">Arts &amp; Humanities</li>\r\n<li data-section-id=\"zlti1n\" data-start=\"1713\" data-end=\"1747\">Or any other recognized stream</li>\r\n</ul>\r\n<p data-start=\"1749\" data-end=\"1782\">can also apply for MCA admission.</p>\r\n<p data-start=\"1784\" data-end=\"1901\">However, such candidates are required to strengthen their foundational knowledge through structured academic support.</p>\r\n<h3 data-section-id=\"8rq0rk\" data-start=\"1903\" data-end=\"1931\">Mandatory Bridge Courses</h3>\r\n<p data-start=\"1933\" data-end=\"2026\">Students from non-computer backgrounds must complete the following compulsory bridge modules:</p>\r\n<ul data-start=\"2028\" data-end=\"2185\">\r\n<li data-section-id=\"1eiyd3l\" data-start=\"2028\" data-end=\"2098\"><strong data-start=\"2030\" data-end=\"2063\">Fundamentals of Computer &amp; IT</strong> (along with Semester 1 subjects)</li>\r\n<li data-section-id=\"1ukzua8\" data-start=\"2099\" data-end=\"2185\"><strong data-start=\"2101\" data-end=\"2130\">Mathematics Bridge Course</strong> (if Mathematics was not studied in 10+2 or graduation)</li>\r\n</ul>\r\n<p data-start=\"2187\" data-end=\"2366\">These bridge courses ensure that all students reach a common academic baseline, helping them handle programming, algorithms, and technical subjects effectively in later semesters.</p>\r\n<hr data-start=\"2368\" data-end=\"2371\">\r\n<h2 data-section-id=\"1y2qck1\" data-start=\"2373\" data-end=\"2416\">Minimum Academic Performance Requirement</h2>\r\n<p data-start=\"2418\" data-end=\"2535\">To ensure academic readiness and consistent performance standards, candidates must meet the following grade criteria:</p>\r\n<ul data-start=\"2537\" data-end=\"2685\">\r\n<li data-section-id=\"jnjcf5\" data-start=\"2537\" data-end=\"2616\">Minimum <strong data-start=\"2547\" data-end=\"2584\">50% aggregate marks in graduation</strong> for general category students</li>\r\n<li data-section-id=\"1xcq7uc\" data-start=\"2617\" data-end=\"2685\">Minimum <strong data-start=\"2627\" data-end=\"2650\">45% aggregate marks</strong> for reserved category candidates</li>\r\n</ul>\r\n<hr data-start=\"2687\" data-end=\"2690\">\r\n<h2 data-section-id=\"19ntkbp\" data-start=\"2692\" data-end=\"2730\">Key Academic Insight for Applicants</h2>\r\n<p data-start=\"2732\" data-end=\"3051\">This eligibility structure is designed not just to filter applicants, but to support long-term academic success. Students from non-technical backgrounds often face initial difficulty in programming-intensive subjects, which is why bridge courses play a crucial role in strengthening fundamentals early in the programme.</p>\r\n<p data-start=\"3053\" data-end=\"3367\">Choosing this programme without evaluating your comfort with logical reasoning, mathematics, and basic computer concepts may lead to initial academic pressure. However, with consistent effort and completion of bridge modules, students from any stream can successfully adapt and perform well in advanced IT studies.</p>', '<p data-start=\"42\" data-end=\"423\">The programme fee structure is designed to offer a balanced and affordable academic pathway for both Indian and international students while maintaining flexibility through semester-wise payments and EMI options. The structure ensures that students can plan their education investment systematically without financial burden, making higher education more accessible and manageable.</p>\r\n<hr data-start=\"425\" data-end=\"428\">\r\n<h2 data-section-id=\"gvgz7s\" data-start=\"430\" data-end=\"490\">Programme Fee Structure (Indian &amp; International Students)</h2>\r\n<p data-start=\"492\" data-end=\"740\">The total academic cost is structured across four semesters, with clarity on semester-wise payment and optional EMI support for added convenience. Both Indian and international students are considered under a transparent and standardized fee model.</p>\r\n<h3 data-section-id=\"1aszbcy\" data-start=\"742\" data-end=\"757\">Fee Details</h3>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"759\" data-end=\"1094\">\r\n<thead data-start=\"759\" data-end=\"805\">\r\n<tr data-start=\"759\" data-end=\"805\">\r\n<th class=\"\" data-start=\"759\" data-end=\"775\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"775\" data-end=\"790\" data-col-size=\"sm\">Amount (INR)</th>\r\n<th class=\"\" data-start=\"790\" data-end=\"805\" data-col-size=\"md\">Description</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"853\" data-end=\"1094\">\r\n<tr data-start=\"853\" data-end=\"946\">\r\n<td data-start=\"853\" data-end=\"886\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"886\" data-end=\"897\">1,10,000</td>\r\n<td data-col-size=\"md\" data-start=\"897\" data-end=\"946\">Complete programme cost for the full duration</td>\r\n</tr>\r\n<tr data-start=\"947\" data-end=\"1020\">\r\n<td data-start=\"947\" data-end=\"966\" data-col-size=\"sm\">Fee Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"966\" data-end=\"975\">27,500</td>\r\n<td data-col-size=\"md\" data-start=\"975\" data-end=\"1020\">Payable at the beginning of each semester</td>\r\n</tr>\r\n<tr data-start=\"1021\" data-end=\"1094\">\r\n<td data-start=\"1021\" data-end=\"1041\" data-col-size=\"sm\">EMI Starting From</td>\r\n<td data-col-size=\"sm\" data-start=\"1041\" data-end=\"1056\">4,583/month*</td>\r\n<td data-col-size=\"md\" data-start=\"1056\" data-end=\"1094\">Flexible monthly instalment option</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1096\" data-end=\"1179\">*Terms and conditions apply as per institutional financing and partner guidelines.</p>\r\n<hr data-start=\"1181\" data-end=\"1184\">\r\n<h2 data-section-id=\"1qep2i7\" data-start=\"1186\" data-end=\"1236\">EMI Payment Option (Flexible Financial Support)</h2>\r\n<p data-start=\"1238\" data-end=\"1471\">To support students who prefer monthly payments over lump-sum semester fees, EMI options are available. This allows learners to manage their education expenses more efficiently while continuing their studies without financial stress.</p>\r\n<p data-start=\"1473\" data-end=\"1514\">The EMI plan is structured in a way that:</p>\r\n<ul data-start=\"1516\" data-end=\"1758\">\r\n<li data-section-id=\"1qaxh8z\" data-start=\"1516\" data-end=\"1579\">Reduces upfront financial pressure on students and families</li>\r\n<li data-section-id=\"1lsb3ns\" data-start=\"1580\" data-end=\"1632\">Enables monthly budgeting for education expenses</li>\r\n<li data-section-id=\"1dki4ro\" data-start=\"1633\" data-end=\"1703\">Offers flexibility for working professionals and distance learners</li>\r\n<li data-section-id=\"1duud7p\" data-start=\"1704\" data-end=\"1758\">Makes higher education more financially accessible</li>\r\n</ul>\r\n<p data-start=\"1760\" data-end=\"1886\">The starting EMI is approximately INR 4,583 per month, subject to eligibility, tenure, and applicable financial partner terms.</p>\r\n<hr data-start=\"1888\" data-end=\"1891\">\r\n<h2 data-section-id=\"1iuqual\" data-start=\"1893\" data-end=\"1921\">Scholarships for Students</h2>\r\n<p data-start=\"1923\" data-end=\"2190\">Scholarship opportunities are provided to encourage merit, support financial need, and promote academic excellence among deserving candidates. These scholarships are designed to reduce the overall financial burden and motivate students to perform better academically.</p>\r\n<p data-start=\"2192\" data-end=\"2242\">Typically, scholarship considerations may include:</p>\r\n<ul data-start=\"2244\" data-end=\"2466\">\r\n<li data-section-id=\"1qfed15\" data-start=\"2244\" data-end=\"2301\">Academic merit and previous qualification performance</li>\r\n<li data-section-id=\"ijyfna\" data-start=\"2302\" data-end=\"2341\">Financial background of the student</li>\r\n<li data-section-id=\"nfnjc8\" data-start=\"2342\" data-end=\"2412\">Category-based or institutional support schemes (where applicable)</li>\r\n<li data-section-id=\"1tabe9o\" data-start=\"2413\" data-end=\"2466\">Special provisions for high-performing candidates</li>\r\n</ul>\r\n<p data-start=\"2468\" data-end=\"2610\">Students are encouraged to apply early, as scholarship availability is often limited and awarded on a first-qualified, first-considered basis.</p>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 110000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(226, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 77, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 00:08:01', '2026-06-16 05:49:36', '<p data-start=\"40\" data-end=\"313\">The admission process for the M.Com programme is designed to be simple, structured, and completely student-friendly. It ensures that applicants can complete their registration in a smooth step-by-step manner without confusion, while maintaining transparency at every stage.</p>\r\n<hr data-start=\"315\" data-end=\"318\">\r\n<h2 data-section-id=\"g9ni70\" data-start=\"320\" data-end=\"349\">Step 1: Choose a Programme</h2>\r\n<p data-start=\"351\" data-end=\"512\">The first step is to select the M.Com programme based on your academic interest and long-term career goals in commerce, finance, accounting, or business studies.</p>\r\n<p data-start=\"514\" data-end=\"801\">At this stage, applicants should carefully review the programme structure and ensure it aligns with their academic background and professional aspirations. Choosing the right programme is important because it forms the foundation of your postgraduate specialization and career direction.</p>\r\n<hr data-start=\"803\" data-end=\"806\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"808\" data-end=\"846\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"848\" data-end=\"1062\">After selecting the programme, candidates must fill in their complete educational details in the application form. This includes academic qualifications, graduation details, and other relevant academic information.</p>\r\n<p data-start=\"1064\" data-end=\"1265\">It is important that all information provided is accurate and matches official academic records, as any mismatch during verification may delay the admission process or require additional clarification.</p>\r\n<p data-start=\"1267\" data-end=\"1391\">This step ensures that the eligibility of the candidate is properly assessed before moving forward in the admission process.</p>\r\n<hr data-start=\"1393\" data-end=\"1396\">\r\n<h2 data-section-id=\"7jn770\" data-start=\"1398\" data-end=\"1426\">Step 3: Pay Programme Fee</h2>\r\n<p data-start=\"1428\" data-end=\"1538\">Once the educational details are submitted, candidates are required to proceed with the programme fee payment.</p>\r\n<p data-start=\"1540\" data-end=\"1788\">The fee can be paid through secure online payment methods, ensuring a smooth and hassle-free transaction experience. Students may also check for available installment or EMI options (if applicable), which help reduce the immediate financial burden.</p>\r\n<p data-start=\"1790\" data-end=\"1902\">Completing this step confirms the candidate&rsquo;s intent to enroll and moves the application forward for processing.</p>\r\n<hr data-start=\"1904\" data-end=\"1907\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"1909\" data-end=\"1957\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"1959\" data-end=\"2178\">In the final step, candidates must upload all required documents as part of the application process. These typically include academic certificates, identity proof, and other supporting records required for verification.</p>\r\n<p data-start=\"2180\" data-end=\"2355\">After uploading the documents, applicants should carefully review all entered details to ensure accuracy. Once verified, the application can be submitted for final processing.</p>\r\n<p data-start=\"2357\" data-end=\"2498\">After submission, the application moves into the verification stage, where eligibility and documents are reviewed for admission confirmation.</p>\r\n<hr data-start=\"2500\" data-end=\"2503\">\r\n<h2 data-section-id=\"b6zxer\" data-start=\"2505\" data-end=\"2547\">Key Highlights of the Admission Process</h2>\r\n<ul data-start=\"2549\" data-end=\"2769\">\r\n<li data-section-id=\"cdnmw4\" data-start=\"2549\" data-end=\"2599\">Fully structured step-by-step admission system</li>\r\n<li data-section-id=\"1m0u77h\" data-start=\"2600\" data-end=\"2646\">Simple and easy online application process</li>\r\n<li data-section-id=\"1sfkv83\" data-start=\"2647\" data-end=\"2677\">Secure fee payment options</li>\r\n<li data-section-id=\"k1xmrx\" data-start=\"2678\" data-end=\"2720\">Document verification for transparency</li>\r\n<li data-section-id=\"1i95kaa\" data-start=\"2721\" data-end=\"2769\">Student-friendly and time-efficient workflow</li>\r\n</ul>', 1, '<p data-start=\"38\" data-end=\"352\">The M.Com programme is designed for students who want to build strong expertise in commerce, finance, accounting, and business management. The eligibility criteria are structured to include learners from India as well as international backgrounds, ensuring a diverse academic environment with wide career exposure.</p>\r\n<hr data-start=\"354\" data-end=\"357\">\r\n<h2 data-section-id=\"pghhov\" data-start=\"359\" data-end=\"381\">Eligible Applicants</h2>\r\n<p data-start=\"383\" data-end=\"436\">The programme is open to both categories of students:</p>\r\n<ul data-start=\"438\" data-end=\"486\">\r\n<li data-section-id=\"55zn8c\" data-start=\"438\" data-end=\"459\">Domestic Students</li>\r\n<li data-section-id=\"1ovgt2g\" data-start=\"460\" data-end=\"486\">International Students</li>\r\n</ul>\r\n<p data-start=\"488\" data-end=\"631\">This inclusive approach allows candidates from different educational systems to apply, provided they meet the required academic qualifications.</p>\r\n<hr data-start=\"633\" data-end=\"636\">\r\n<h2 data-section-id=\"1qu9ips\" data-start=\"638\" data-end=\"675\">Educational Qualification Criteria</h2>\r\n<p data-start=\"677\" data-end=\"856\">To be eligible for admission into the M.Com programme, candidates must have successfully completed a <strong data-start=\"778\" data-end=\"811\">10+2+3-year bachelor&rsquo;s degree</strong> from a recognized university or institution.</p>\r\n<p data-start=\"858\" data-end=\"1032\">The degree can be in any relevant discipline, provided it is recognized as equivalent by the <strong data-start=\"951\" data-end=\"995\">Association of Indian Universities (AIU)</strong> or other competent statutory bodies.</p>\r\n<h3 data-section-id=\"wsoph0\" data-start=\"1034\" data-end=\"1068\">Accepted Qualification Pathway</h3>\r\n<p data-start=\"1070\" data-end=\"1091\">Candidates must have:</p>\r\n<ul data-start=\"1093\" data-end=\"1286\">\r\n<li data-section-id=\"1x84jl\" data-start=\"1093\" data-end=\"1158\">Completed a <strong data-start=\"1107\" data-end=\"1156\">3-year bachelor&rsquo;s degree after 10+2 education</strong></li>\r\n<li data-section-id=\"17nm5ca\" data-start=\"1159\" data-end=\"1219\">Degree obtained from a recognized university/institution</li>\r\n<li data-section-id=\"1kagww7\" data-start=\"1220\" data-end=\"1286\">Equivalent qualification approved by AIU or relevant authority</li>\r\n</ul>\r\n<p data-start=\"1288\" data-end=\"1420\">This ensures that students entering the programme have a solid foundation in undergraduate-level commerce or related academic areas.</p>\r\n<hr data-start=\"1422\" data-end=\"1425\">\r\n<h2 data-section-id=\"1gi5y95\" data-start=\"1427\" data-end=\"1466\">Key Admission Insight for Applicants</h2>\r\n<p data-start=\"1468\" data-end=\"1793\">The M.Com programme is academically rigorous and focuses on advanced concepts in accounting, economics, taxation, and financial management. While students from commerce backgrounds may find it more aligned with their previous studies, candidates from other streams can also adapt successfully with consistent academic effort.</p>\r\n<p data-start=\"1795\" data-end=\"2003\">It is important for applicants to evaluate their interest in analytical thinking, financial systems, and business concepts before applying, as the programme demands conceptual clarity and continuous learning.</p>\r\n<hr data-start=\"2005\" data-end=\"2008\">\r\n<h2 data-section-id=\"y2bjhp\" data-start=\"2010\" data-end=\"2035\">Summary of Eligibility</h2>\r\n<ul data-start=\"2037\" data-end=\"2249\">\r\n<li data-section-id=\"1ecojvm\" data-start=\"2037\" data-end=\"2084\">Open to domestic and international students</li>\r\n<li data-section-id=\"sjlq2e\" data-start=\"2085\" data-end=\"2127\">Requires 10+2+3-year bachelor&rsquo;s degree</li>\r\n<li data-section-id=\"1f2qh0s\" data-start=\"2128\" data-end=\"2187\">Degree must be from a recognized university/institution</li>\r\n<li data-section-id=\"1uzpo94\" data-start=\"2188\" data-end=\"2249\">Equivalent qualifications accepted as per AIU recognition</li>\r\n</ul>', '<p data-start=\"60\" data-end=\"431\">The M.Com programme is structured to offer a cost-effective and flexible academic pathway for both Indian and international students. The fee system is designed in a semester-wise format, allowing students to manage their education expenses in a planned and transparent manner. In addition, EMI options further reduce financial pressure by enabling easy monthly payments.</p>\r\n<hr data-start=\"433\" data-end=\"436\">\r\n<h2 data-section-id=\"gvgz7s\" data-start=\"438\" data-end=\"498\">Programme Fee Structure (Indian &amp; International Students)</h2>\r\n<p data-start=\"500\" data-end=\"747\">The total programme fee is distributed across four semesters, ensuring affordability and financial clarity throughout the course duration. Both Indian and international students follow the same structured fee pattern with flexible payment support.</p>\r\n<h3 data-section-id=\"1aszbcy\" data-start=\"749\" data-end=\"764\">Fee Details</h3>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"766\" data-end=\"1099\">\r\n<thead data-start=\"766\" data-end=\"812\">\r\n<tr data-start=\"766\" data-end=\"812\">\r\n<th class=\"\" data-start=\"766\" data-end=\"782\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"782\" data-end=\"797\" data-col-size=\"sm\">Amount (INR)</th>\r\n<th class=\"\" data-start=\"797\" data-end=\"812\" data-col-size=\"md\">Description</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"860\" data-end=\"1099\">\r\n<tr data-start=\"860\" data-end=\"951\">\r\n<td data-start=\"860\" data-end=\"893\" data-col-size=\"sm\">Total Course Fee (4 Semesters)</td>\r\n<td data-start=\"893\" data-end=\"902\" data-col-size=\"sm\">75,000</td>\r\n<td data-col-size=\"md\" data-start=\"902\" data-end=\"951\">Complete programme cost for the full duration</td>\r\n</tr>\r\n<tr data-start=\"952\" data-end=\"1025\">\r\n<td data-start=\"952\" data-end=\"971\" data-col-size=\"sm\">Fee Per Semester</td>\r\n<td data-start=\"971\" data-end=\"980\" data-col-size=\"sm\">18,750</td>\r\n<td data-start=\"980\" data-end=\"1025\" data-col-size=\"md\">Payable at the beginning of each semester</td>\r\n</tr>\r\n<tr data-start=\"1026\" data-end=\"1099\">\r\n<td data-start=\"1026\" data-end=\"1046\" data-col-size=\"sm\">EMI Starting From</td>\r\n<td data-start=\"1046\" data-end=\"1061\" data-col-size=\"sm\">3,125/month*</td>\r\n<td data-start=\"1061\" data-end=\"1099\" data-col-size=\"md\">Flexible monthly instalment option</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1101\" data-end=\"1190\">*Terms and conditions apply as per applicable financial policies and partner guidelines.</p>\r\n<hr data-start=\"1192\" data-end=\"1195\">\r\n<h2 data-section-id=\"1md6vcz\" data-start=\"1197\" data-end=\"1245\">EMI Payment Option (Flexible Monthly Support)</h2>\r\n<p data-start=\"1247\" data-end=\"1527\">To make higher education more accessible, an EMI facility is available for students who prefer monthly payments instead of semester-wise lump sum payments. This option is especially beneficial for students who want better financial planning without compromising on academic goals.</p>\r\n<h3 data-section-id=\"10v02qm\" data-start=\"1529\" data-end=\"1559\">Key Benefits of EMI Option</h3>\r\n<ul data-start=\"1561\" data-end=\"1806\">\r\n<li data-section-id=\"1jtqh0n\" data-start=\"1561\" data-end=\"1609\">Reduces upfront financial burden on students</li>\r\n<li data-section-id=\"fre0zi\" data-start=\"1610\" data-end=\"1666\">Allows easy monthly budgeting for education expenses</li>\r\n<li data-section-id=\"18fdkt6\" data-start=\"1667\" data-end=\"1745\">Provides flexibility for working professionals and self-financing students</li>\r\n<li data-section-id=\"115ajg\" data-start=\"1746\" data-end=\"1806\">Makes postgraduate education more financially manageable</li>\r\n</ul>\r\n<p data-start=\"1808\" data-end=\"1938\">The starting EMI is approximately INR 3,125 per month, subject to eligibility, repayment duration, and applicable financial terms.</p>\r\n<hr data-start=\"1940\" data-end=\"1943\">\r\n<h2 data-section-id=\"1an5e0v\" data-start=\"1945\" data-end=\"1979\">Scholarships for M.Com Students</h2>\r\n<p data-start=\"1981\" data-end=\"2224\">Scholarships are offered to support meritorious and deserving students, helping reduce the overall cost of education. These financial aids are designed to encourage academic excellence and support students from different financial backgrounds.</p>\r\n<h3 data-section-id=\"6p2zs4\" data-start=\"2226\" data-end=\"2263\">Scholarship Consideration Factors</h3>\r\n<ul data-start=\"2265\" data-end=\"2481\">\r\n<li data-section-id=\"16btz2c\" data-start=\"2265\" data-end=\"2325\">Academic performance in previous qualifying examinations</li>\r\n<li data-section-id=\"11o83yf\" data-start=\"2326\" data-end=\"2361\">Financial need of the applicant</li>\r\n<li data-section-id=\"y6wg43\" data-start=\"2362\" data-end=\"2412\">Merit-based institutional scholarship criteria</li>\r\n<li data-section-id=\"1lcramz\" data-start=\"2413\" data-end=\"2481\">Special category or eligibility-based support (where applicable)</li>\r\n</ul>\r\n<p data-start=\"2483\" data-end=\"2591\">Students are advised to apply early, as scholarships are generally limited and awarded on a selective basis.</p>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL),
(227, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 68, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 00:20:25', '2026-06-16 05:49:57', '<p data-start=\"379\" data-end=\"726\">The BBA admission process is designed to be simple, structured, and easy for students from different academic backgrounds. It ensures a smooth application experience with clear steps for selection, verification, payment, and final submission. The entire process is online-based, making it convenient for both domestic and international applicants.</p>\r\n<hr data-start=\"728\" data-end=\"731\">\r\n<h2 data-section-id=\"g9ni70\" data-start=\"733\" data-end=\"762\">Step 1: Choose a Programme</h2>\r\n<p data-start=\"764\" data-end=\"941\">The first step is selecting the BBA programme according to your academic interest and long-term career goals in business, management, entrepreneurship, and corporate leadership.</p>\r\n<p data-start=\"943\" data-end=\"1198\">At this stage, students should carefully understand the course structure and future opportunities. Choosing the right programme is important because it directly influences your specialization, skill development, and career direction in the business field.</p>\r\n<p data-start=\"1200\" data-end=\"1353\">A well-informed decision at this stage helps avoid confusion later and ensures alignment with your professional goals in management and business studies.</p>\r\n<hr data-start=\"1355\" data-end=\"1358\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"1360\" data-end=\"1398\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"1400\" data-end=\"1523\">After selecting the programme, candidates are required to enter their complete educational details in the application form.</p>\r\n<p data-start=\"1525\" data-end=\"1539\">This includes:</p>\r\n<ul data-start=\"1540\" data-end=\"1685\">\r\n<li data-section-id=\"123d4u8\" data-start=\"1540\" data-end=\"1569\">Class 10 academic details</li>\r\n<li data-section-id=\"10lc8oy\" data-start=\"1570\" data-end=\"1599\">Class 12 academic details</li>\r\n<li data-section-id=\"19g3okc\" data-start=\"1600\" data-end=\"1629\">Board or institution name</li>\r\n<li data-section-id=\"ac66pr\" data-start=\"1630\" data-end=\"1649\">Year of passing</li>\r\n<li data-section-id=\"1au3ggr\" data-start=\"1650\" data-end=\"1685\">Diploma details (if applicable)</li>\r\n</ul>\r\n<p data-start=\"1687\" data-end=\"1857\">All information must be accurate and match official academic documents. Any mismatch in details may lead to delays in verification or issues during the admission process.</p>\r\n<p data-start=\"1859\" data-end=\"1960\">This step ensures that eligibility is properly assessed before moving to the next stage of admission.</p>\r\n<hr data-start=\"1962\" data-end=\"1965\">\r\n<h2 data-section-id=\"7jn770\" data-start=\"1967\" data-end=\"1995\">Step 3: Pay Programme Fee</h2>\r\n<p data-start=\"1997\" data-end=\"2095\">Once the educational details are submitted, candidates need to complete the programme fee payment.</p>\r\n<p data-start=\"2097\" data-end=\"2333\">The payment can be made through secure online modes, ensuring a smooth and safe transaction process. Students may also choose installment or EMI options (if available), which help in managing educational expenses in a more flexible way.</p>\r\n<p data-start=\"2335\" data-end=\"2449\">Completing the fee payment confirms the application and allows it to move forward for verification and processing.</p>\r\n<p data-start=\"2451\" data-end=\"2529\">Paying the fee on time is important to avoid delays in admission confirmation.</p>\r\n<hr data-start=\"2531\" data-end=\"2534\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"2536\" data-end=\"2584\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"2586\" data-end=\"2817\">In the final step, candidates must upload all required documents for verification purposes. These generally include academic certificates, identity proof, and other supporting documents as specified in the application requirements.</p>\r\n<p data-start=\"2819\" data-end=\"3003\">After uploading documents, applicants should carefully review all details entered in the form. Even minor errors in personal or academic information can delay the verification process.</p>\r\n<p data-start=\"3005\" data-end=\"3228\">Once everything is checked and confirmed, the application can be submitted for final processing. After submission, the application enters the review stage where eligibility and documents are verified for admission approval.</p>\r\n<hr data-start=\"3230\" data-end=\"3233\">\r\n<h2 data-section-id=\"b6zxer\" data-start=\"3235\" data-end=\"3277\">Key Highlights of the Admission Process</h2>\r\n<ul data-start=\"3279\" data-end=\"3557\">\r\n<li data-section-id=\"1hiqd7f\" data-start=\"3279\" data-end=\"3328\">Simple and structured 4-step admission system</li>\r\n<li data-section-id=\"1fuo65a\" data-start=\"3329\" data-end=\"3380\">Fully online and convenient application process</li>\r\n<li data-section-id=\"1894x2h\" data-start=\"3381\" data-end=\"3419\">Secure digital fee payment options</li>\r\n<li data-section-id=\"1decbs7\" data-start=\"3420\" data-end=\"3458\">Document-based verification system</li>\r\n<li data-section-id=\"1qxlvk7\" data-start=\"3459\" data-end=\"3511\">Suitable for domestic and international students</li>\r\n<li data-section-id=\"1tumnwd\" data-start=\"3512\" data-end=\"3557\">Transparent and smooth admission workflow</li>\r\n</ul>', 1, '<p data-start=\"444\" data-end=\"837\">The BBA (Bachelor of Business Administration) programme is designed for students who want to build a strong foundation in business management, entrepreneurship, marketing, finance, and leadership skills. The eligibility criteria are structured to ensure accessibility for students from different academic backgrounds while maintaining a basic academic standard required for management studies.</p>\r\n<hr data-start=\"839\" data-end=\"842\">\r\n<h2 data-section-id=\"pghhov\" data-start=\"844\" data-end=\"866\">Eligible Applicants</h2>\r\n<p data-start=\"868\" data-end=\"1028\">The programme is open to a wide range of students from both national and international academic backgrounds, ensuring global exposure and diversity in learning.</p>\r\n<h3 data-section-id=\"18gg9gc\" data-start=\"1030\" data-end=\"1061\">Student Categories Eligible</h3>\r\n<ul data-start=\"1062\" data-end=\"1110\">\r\n<li data-section-id=\"55zn8c\" data-start=\"1062\" data-end=\"1083\">Domestic Students</li>\r\n<li data-section-id=\"1ovgt2g\" data-start=\"1084\" data-end=\"1110\">International Students</li>\r\n</ul>\r\n<p data-start=\"1112\" data-end=\"1261\">This inclusive structure allows students from various education systems to apply, provided they meet the minimum academic qualification requirements.</p>\r\n<hr data-start=\"1263\" data-end=\"1266\">\r\n<h2 data-section-id=\"1qu9ips\" data-start=\"1268\" data-end=\"1305\">Educational Qualification Criteria</h2>\r\n<p data-start=\"1307\" data-end=\"1466\">To be eligible for admission into the BBA programme, candidates must have completed one of the following qualifications from a recognized board or institution:</p>\r\n<h3 data-section-id=\"clqstm\" data-start=\"1468\" data-end=\"1500\">Minimum Academic Requirement</h3>\r\n<ul data-start=\"1502\" data-end=\"1782\">\r\n<li data-section-id=\"4mnk3n\" data-start=\"1502\" data-end=\"1592\"><strong data-start=\"1504\" data-end=\"1541\">10+2 (Senior Secondary Education)</strong> from a recognized national or state board<br data-start=\"1583\" data-end=\"1586\"><strong data-start=\"1586\" data-end=\"1592\">OR</strong></li>\r\n<li data-section-id=\"b65keg\" data-start=\"1593\" data-end=\"1686\"><strong data-start=\"1595\" data-end=\"1611\">10+3 Diploma</strong> from a recognized national or state technical/institutional board<br data-start=\"1677\" data-end=\"1680\"><strong data-start=\"1680\" data-end=\"1686\">OR</strong></li>\r\n<li data-section-id=\"wtg25m\" data-start=\"1687\" data-end=\"1782\">Any <strong data-start=\"1693\" data-end=\"1780\">equivalent qualification recognized by the Association of Indian Universities (AIU)</strong></li>\r\n</ul>\r\n<p data-start=\"1784\" data-end=\"1928\">Candidates from <strong data-start=\"1800\" data-end=\"1852\">any academic stream (Arts, Commerce, or Science)</strong> are eligible to apply, making the programme highly flexible and accessible.</p>\r\n<hr data-start=\"1930\" data-end=\"1933\">\r\n<h2 data-section-id=\"1pxxm7s\" data-start=\"1935\" data-end=\"1979\">Understanding Eligibility in Simple Terms</h2>\r\n<p data-start=\"1981\" data-end=\"2225\">The BBA programme is designed in a way that students do not need a specific stream background in school. Whether a student comes from commerce, science, or humanities, they can apply as long as they have completed 10+2 or an equivalent diploma.</p>\r\n<p data-start=\"2227\" data-end=\"2422\">This flexibility ensures that students interested in business, management, startups, or corporate careers can start their journey early after school without restriction on subject specialization.</p>\r\n<hr data-start=\"2424\" data-end=\"2427\">\r\n<h2 data-section-id=\"k4c33v\" data-start=\"2429\" data-end=\"2478\">Key Admission Insight (Important for Students)</h2>\r\n<p data-start=\"2480\" data-end=\"2666\">Many students assume that only commerce background candidates are suitable for BBA, but this is not true. The programme is structured to build management fundamentals from the ground up.</p>\r\n<p data-start=\"2668\" data-end=\"2702\">However, students should evaluate:</p>\r\n<ul data-start=\"2703\" data-end=\"2885\">\r\n<li data-section-id=\"1e1t060\" data-start=\"2703\" data-end=\"2754\">Their interest in business and leadership roles</li>\r\n<li data-section-id=\"xuaaaw\" data-start=\"2755\" data-end=\"2824\">Comfort with communication, logical reasoning, and basic numeracy</li>\r\n<li data-section-id=\"gh1ov1\" data-start=\"2825\" data-end=\"2885\">Long-term career goals in management or entrepreneurship</li>\r\n</ul>\r\n<p data-start=\"2887\" data-end=\"3035\">Choosing BBA without interest in business studies may lead to lack of engagement later, as the programme is career-oriented and practical in nature.</p>\r\n<hr data-start=\"3037\" data-end=\"3040\">\r\n<h2 data-section-id=\"1xesv8m\" data-start=\"3042\" data-end=\"3099\">Career-Oriented Perspective (Why Eligibility is Broad)</h2>\r\n<p data-start=\"3101\" data-end=\"3304\">The broad eligibility structure is intentional because modern business education focuses on skill development rather than only academic background. This allows students from different streams to develop:</p>\r\n<ul data-start=\"3306\" data-end=\"3442\">\r\n<li data-section-id=\"19p8x7g\" data-start=\"3306\" data-end=\"3334\">Business thinking skills</li>\r\n<li data-section-id=\"6jzt50\" data-start=\"3335\" data-end=\"3379\">Leadership and decision-making abilities</li>\r\n<li data-section-id=\"1iqtf5v\" data-start=\"3380\" data-end=\"3407\">Entrepreneurial mindset</li>\r\n<li data-section-id=\"ipxjk9\" data-start=\"3408\" data-end=\"3442\">Corporate communication skills</li>\r\n</ul>', '<p data-start=\"58\" data-end=\"395\">The BBA programme is structured to offer an affordable and well-planned academic investment for both Indian and international students. The fee system is designed in a semester-wise format, making it easier for students to manage their education expenses while focusing on skill development in business, management, and entrepreneurship.</p>\r\n<hr data-start=\"397\" data-end=\"400\">\r\n<h2 data-section-id=\"gvgz7s\" data-start=\"402\" data-end=\"462\">Programme Fee Structure (Indian &amp; International Students)</h2>\r\n<p data-start=\"464\" data-end=\"713\">The total programme fee is distributed across six semesters, ensuring financial flexibility and clarity throughout the course duration. Both Indian and international students follow a transparent fee structure with options for easy payment planning.</p>\r\n<h3 data-section-id=\"1aszbcy\" data-start=\"715\" data-end=\"730\">Fee Details</h3>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"732\" data-end=\"1064\">\r\n<thead data-start=\"732\" data-end=\"778\">\r\n<tr data-start=\"732\" data-end=\"778\">\r\n<th class=\"\" data-start=\"732\" data-end=\"748\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"748\" data-end=\"763\" data-col-size=\"sm\">Amount (INR)</th>\r\n<th class=\"\" data-start=\"763\" data-end=\"778\" data-col-size=\"md\">Description</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"826\" data-end=\"1064\">\r\n<tr data-start=\"826\" data-end=\"917\">\r\n<td data-start=\"826\" data-end=\"859\" data-col-size=\"sm\">Total Course Fee (6 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"859\" data-end=\"868\">90,000</td>\r\n<td data-col-size=\"md\" data-start=\"868\" data-end=\"917\">Complete programme cost for the full duration</td>\r\n</tr>\r\n<tr data-start=\"918\" data-end=\"991\">\r\n<td data-start=\"918\" data-end=\"937\" data-col-size=\"sm\">Fee Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"937\" data-end=\"946\">15,000</td>\r\n<td data-col-size=\"md\" data-start=\"946\" data-end=\"991\">Payable at the beginning of each semester</td>\r\n</tr>\r\n<tr data-start=\"992\" data-end=\"1064\">\r\n<td data-start=\"992\" data-end=\"1012\" data-col-size=\"sm\">EMI Starting From</td>\r\n<td data-start=\"1012\" data-end=\"1026\" data-col-size=\"sm\">2,500/month</td>\r\n<td data-start=\"1026\" data-end=\"1064\" data-col-size=\"md\">Flexible monthly instalment option</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1066\" data-end=\"1069\">\r\n<h2 data-section-id=\"1gxk53s\" data-start=\"1071\" data-end=\"1118\">EMI Payment Option (Affordable Monthly Plan)</h2>\r\n<p data-start=\"1120\" data-end=\"1332\">To support students in managing their education expenses more comfortably, an EMI option is available. This allows learners to pay their fees in small monthly instalments instead of larger semester-wise payments.</p>\r\n<h3 data-section-id=\"10v02qm\" data-start=\"1334\" data-end=\"1364\">Key Benefits of EMI Option</h3>\r\n<ul data-start=\"1366\" data-end=\"1596\">\r\n<li data-section-id=\"158uuvw\" data-start=\"1366\" data-end=\"1427\">Reduces upfront financial burden on students and families</li>\r\n<li data-section-id=\"1pi9oqt\" data-start=\"1428\" data-end=\"1471\">Enables easy monthly financial planning</li>\r\n<li data-section-id=\"1umdada\" data-start=\"1472\" data-end=\"1533\">Suitable for working students and self-financing learners</li>\r\n<li data-section-id=\"tmg4c1\" data-start=\"1534\" data-end=\"1596\">Makes management education more accessible and stress-free</li>\r\n</ul>\r\n<p data-start=\"1598\" data-end=\"1728\">The EMI starts from approximately INR 2,500 per month, subject to applicable terms, eligibility, and financial partner conditions.</p>\r\n<hr data-start=\"1730\" data-end=\"1733\">\r\n<h2 data-section-id=\"esm49o\" data-start=\"1735\" data-end=\"1767\">Scholarships for BBA Students</h2>\r\n<p data-start=\"1769\" data-end=\"2007\">Scholarships are offered to encourage academic excellence and support deserving students from different financial backgrounds. These financial aid options help reduce the overall cost of education and promote equal learning opportunities.</p>\r\n<h3 data-section-id=\"1uw1a3t\" data-start=\"2009\" data-end=\"2047\">Scholarship Consideration Criteria</h3>\r\n<ul data-start=\"2049\" data-end=\"2253\">\r\n<li data-section-id=\"16btz2c\" data-start=\"2049\" data-end=\"2109\">Academic performance in previous qualifying examinations</li>\r\n<li data-section-id=\"ijyfna\" data-start=\"2110\" data-end=\"2149\">Financial background of the student</li>\r\n<li data-section-id=\"13ntg7a\" data-start=\"2150\" data-end=\"2199\">Merit-based institutional scholarship schemes</li>\r\n<li data-section-id=\"4fflfv\" data-start=\"2200\" data-end=\"2253\">Special category-based support (where applicable)</li>\r\n</ul>\r\n<p data-start=\"2255\" data-end=\"2367\">Students are encouraged to apply early, as scholarship availability is limited and awarded on a selective basis.</p>\r\n<hr data-start=\"2369\" data-end=\"2372\">\r\n<h2 data-section-id=\"8yrnuz\" data-start=\"2374\" data-end=\"2408\">Key Highlights of Fee Structure</h2>\r\n<p data-start=\"2410\" data-end=\"2553\">The BBA fee structure is designed to ensure transparency, affordability, and flexibility for students at every stage of their academic journey.</p>\r\n<ul data-start=\"2555\" data-end=\"2782\">\r\n<li data-section-id=\"inkvvw\" data-start=\"2555\" data-end=\"2594\">Clear six-semester fee distribution</li>\r\n<li data-section-id=\"f6u1hr\" data-start=\"2595\" data-end=\"2630\">Affordable total programme cost</li>\r\n<li data-section-id=\"g68g5l\" data-start=\"2631\" data-end=\"2679\">Low starting EMI option for monthly payments</li>\r\n<li data-section-id=\"mdb995\" data-start=\"2680\" data-end=\"2731\">Scholarship opportunities for eligible students</li>\r\n<li data-section-id=\"16zivlm\" data-start=\"2732\" data-end=\"2782\">Simple and student-friendly financial planning</li>\r\n</ul>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 90000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(228, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 44, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 00:27:16', '2026-06-16 05:50:20', '<h2 data-section-id=\"zihdbe\" data-start=\"318\" data-end=\"344\">B.Com Admission Process</h2>\r\n<p data-start=\"346\" data-end=\"670\">The B.Com admission process is designed to be simple, structured, and convenient for students who want to begin their journey in commerce, accounting, finance, taxation, and business studies. The complete application flow is organized in clear stages so applicants can submit their admission form smoothly without confusion.</p>\r\n<p data-start=\"672\" data-end=\"819\">Whether you are a domestic or international student, following each step carefully helps in faster verification and quicker admission confirmation.</p>\r\n<hr data-start=\"821\" data-end=\"824\">\r\n<h2 data-section-id=\"g9ni70\" data-start=\"826\" data-end=\"855\">Step 1: Choose a Programme</h2>\r\n<p data-start=\"857\" data-end=\"1131\">The first step is selecting the B.Com programme based on your academic interests and future career plans. Students interested in banking, accounting, finance, taxation, corporate jobs, entrepreneurship, or higher studies often choose B.Com as a strong undergraduate pathway.</p>\r\n<p data-start=\"1133\" data-end=\"1173\">Before applying, students should review:</p>\r\n<ul data-start=\"1175\" data-end=\"1331\">\r\n<li data-section-id=\"4r7etc\" data-start=\"1175\" data-end=\"1195\">Course structure</li>\r\n<li data-section-id=\"v6fwjj\" data-start=\"1196\" data-end=\"1215\">Learning format</li>\r\n<li data-section-id=\"1w3z4mh\" data-start=\"1216\" data-end=\"1257\">Career opportunities after graduation</li>\r\n<li data-section-id=\"fpwwlf\" data-start=\"1258\" data-end=\"1282\">Total programme fees</li>\r\n<li data-section-id=\"10294dl\" data-start=\"1283\" data-end=\"1331\">Future scope such as MBA, M.Com, CA, CMA, CS</li>\r\n</ul>\r\n<p data-start=\"1333\" data-end=\"1445\">Choosing the right programme early helps avoid wrong academic decisions and improves long-term career alignment.</p>\r\n<hr data-start=\"1447\" data-end=\"1450\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"1452\" data-end=\"1490\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"1492\" data-end=\"1595\">After selecting the programme, candidates must enter their educational details in the application form.</p>\r\n<p data-start=\"1597\" data-end=\"1621\">This generally includes:</p>\r\n<ul data-start=\"1623\" data-end=\"1769\">\r\n<li data-section-id=\"tbi9z9\" data-start=\"1623\" data-end=\"1643\">Class 10 details</li>\r\n<li data-section-id=\"1bd864n\" data-start=\"1644\" data-end=\"1664\">Class 12 details</li>\r\n<li data-section-id=\"19g3okc\" data-start=\"1665\" data-end=\"1694\">Board or institution name</li>\r\n<li data-section-id=\"ac66pr\" data-start=\"1695\" data-end=\"1714\">Year of passing</li>\r\n<li data-section-id=\"148a1kg\" data-start=\"1715\" data-end=\"1733\">Marks obtained</li>\r\n<li data-section-id=\"1au3ggr\" data-start=\"1734\" data-end=\"1769\">Diploma details (if applicable)</li>\r\n</ul>\r\n<p data-start=\"1771\" data-end=\"1908\">All details should exactly match official documents. Incorrect marks, wrong spelling, or incomplete data may delay the admission process.</p>\r\n<p data-start=\"1910\" data-end=\"2014\">This stage is important because institutions verify eligibility based on submitted academic information.</p>\r\n<hr data-start=\"2016\" data-end=\"2019\">\r\n<h2 data-section-id=\"7jn770\" data-start=\"2021\" data-end=\"2049\">Step 3: Pay Programme Fee</h2>\r\n<p data-start=\"2051\" data-end=\"2170\">Once educational details are completed, applicants need to pay the programme fee through the available payment options.</p>\r\n<p data-start=\"2172\" data-end=\"2341\">Payment may usually be completed through secure online methods. Depending on the institution, EMI or installment options may also be available for easier fee management.</p>\r\n<h3 data-section-id=\"1t6kxfg\" data-start=\"2343\" data-end=\"2368\">Why This Step Matters</h3>\r\n<ul data-start=\"2370\" data-end=\"2540\">\r\n<li data-section-id=\"1f8p7w\" data-start=\"2370\" data-end=\"2407\">Confirms serious intent to enroll</li>\r\n<li data-section-id=\"1tswr1m\" data-start=\"2408\" data-end=\"2443\">Reserves application processing</li>\r\n<li data-section-id=\"1goi2hm\" data-start=\"2444\" data-end=\"2480\">Moves form to verification stage</li>\r\n<li data-section-id=\"8fpjhf\" data-start=\"2481\" data-end=\"2540\">Reduces chances of delayed admission due to unpaid fees</li>\r\n</ul>\r\n<p data-start=\"2542\" data-end=\"2629\">Students should always keep payment receipts or transaction proof for future reference.</p>\r\n<hr data-start=\"2631\" data-end=\"2634\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"2636\" data-end=\"2684\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"2686\" data-end=\"2793\">In the final stage, candidates need to upload required documents and submit the completed application form.</p>\r\n<p data-start=\"2795\" data-end=\"2835\">Commonly required documents may include:</p>\r\n<ul data-start=\"2837\" data-end=\"3003\">\r\n<li data-section-id=\"1ulae2l\" data-start=\"2837\" data-end=\"2859\">Class 10 marksheet</li>\r\n<li data-section-id=\"1eaztxb\" data-start=\"2860\" data-end=\"2882\">Class 12 marksheet</li>\r\n<li data-section-id=\"11bawgc\" data-start=\"2883\" data-end=\"2922\">Diploma certificate (if applicable)</li>\r\n<li data-section-id=\"1l6qwl6\" data-start=\"2923\" data-end=\"2941\">Identity proof</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"2942\" data-end=\"2970\">Passport-size photograph</li>\r\n<li data-section-id=\"1f0lxta\" data-start=\"2971\" data-end=\"3003\">Signature copy (if required)</li>\r\n</ul>\r\n<p data-start=\"3005\" data-end=\"3142\">Before final submission, students should carefully review all entered details. Even minor mistakes can create delays during verification.</p>\r\n<p data-start=\"3144\" data-end=\"3247\">Once submitted, the application enters the review process for eligibility check and admission approval.</p>\r\n<hr data-start=\"3249\" data-end=\"3252\">\r\n<h2 data-section-id=\"1uv9fke\" data-start=\"3254\" data-end=\"3302\">Key Highlights of the B.Com Admission Process</h2>\r\n<ul data-start=\"3304\" data-end=\"3564\">\r\n<li data-section-id=\"16u88gt\" data-start=\"3304\" data-end=\"3345\">Easy 4-step online application system</li>\r\n<li data-section-id=\"h5e8af\" data-start=\"3346\" data-end=\"3390\">Student-friendly and time-saving process</li>\r\n<li data-section-id=\"oob51r\" data-start=\"3391\" data-end=\"3421\">Secure fee payment methods</li>\r\n<li data-section-id=\"k1xmrx\" data-start=\"3422\" data-end=\"3464\">Document verification for transparency</li>\r\n<li data-section-id=\"1b6qolu\" data-start=\"3465\" data-end=\"3519\">Suitable for domestic and international applicants</li>\r\n<li data-section-id=\"dfhigh\" data-start=\"3520\" data-end=\"3564\">Smooth and organized enrollment workflow</li>\r\n</ul>', 1, '<h2 data-section-id=\"1ymqzhj\" data-start=\"326\" data-end=\"362\">Who Can Apply for B.Com Programme</h2>\r\n<p data-start=\"364\" data-end=\"716\">The B.Com (Bachelor of Commerce) programme is designed for students who want to build strong academic and practical knowledge in commerce, accounting, taxation, banking, finance, and business operations. It is one of the most preferred undergraduate degrees for students planning careers in corporate, financial, government, or entrepreneurial sectors.</p>\r\n<p data-start=\"718\" data-end=\"898\">The eligibility criteria are structured to keep the programme accessible to students from multiple academic backgrounds while ensuring a suitable foundation for commerce education.</p>\r\n<hr data-start=\"900\" data-end=\"903\">\r\n<h2 data-section-id=\"pghhov\" data-start=\"905\" data-end=\"927\">Eligible Applicants</h2>\r\n<p data-start=\"929\" data-end=\"1040\">The programme is open to students from India and abroad, creating a diverse and inclusive learning environment.</p>\r\n<h3 data-section-id=\"18gg9gc\" data-start=\"1042\" data-end=\"1073\">Student Categories Eligible</h3>\r\n<ul data-start=\"1075\" data-end=\"1123\">\r\n<li data-section-id=\"55zn8c\" data-start=\"1075\" data-end=\"1096\">Domestic Students</li>\r\n<li data-section-id=\"1ovgt2g\" data-start=\"1097\" data-end=\"1123\">International Students</li>\r\n</ul>\r\n<p data-start=\"1125\" data-end=\"1267\">This broad eligibility structure allows students from different educational systems to apply, subject to fulfillment of academic requirements.</p>\r\n<hr data-start=\"1269\" data-end=\"1272\">\r\n<h2 data-section-id=\"1qu9ips\" data-start=\"1274\" data-end=\"1311\">Educational Qualification Criteria</h2>\r\n<p data-start=\"1313\" data-end=\"1425\">To apply for B.Com admission, candidates must have completed any one of the following recognized qualifications:</p>\r\n<h3 data-section-id=\"clqstm\" data-start=\"1427\" data-end=\"1459\">Minimum Academic Requirement</h3>\r\n<ul data-start=\"1461\" data-end=\"1632\">\r\n<li data-section-id=\"khfp87\" data-start=\"1461\" data-end=\"1565\"><strong data-start=\"1463\" data-end=\"1500\">10+2 (Senior Secondary Education)</strong> from a recognized national or state board institution<br data-start=\"1554\" data-end=\"1557\"><strong data-start=\"1557\" data-end=\"1563\">OR</strong></li>\r\n<li data-section-id=\"vydfjt\" data-start=\"1566\" data-end=\"1632\"><strong data-start=\"1568\" data-end=\"1584\">10+3 Diploma</strong> from a recognized national or state institute</li>\r\n</ul>\r\n<p data-start=\"1634\" data-end=\"1798\">Candidates from different streams such as Commerce, Science, or Arts can generally pursue B.Com, making it a flexible and widely accessible undergraduate programme.</p>\r\n<hr data-start=\"1800\" data-end=\"1803\">\r\n<h2 data-section-id=\"pcvb4\" data-start=\"1805\" data-end=\"1847\">Is Commerce Stream Mandatory for B.Com?</h2>\r\n<p data-start=\"1849\" data-end=\"2031\">No, in many cases Commerce background is beneficial but not always mandatory. Students from Science or Arts streams may also pursue B.Com if they meet the qualification requirements.</p>\r\n<p data-start=\"2033\" data-end=\"2157\">However, students with prior exposure to accounting, economics, or business studies may initially find some subjects easier.</p>\r\n<hr data-start=\"2159\" data-end=\"2162\">\r\n<h2 data-section-id=\"jp2o4\" data-start=\"2164\" data-end=\"2204\">Why B.Com is Open to Multiple Streams</h2>\r\n<p data-start=\"2206\" data-end=\"2325\">The B.Com curriculum usually begins with foundational concepts and gradually progresses into specialized areas such as:</p>\r\n<ul data-start=\"2327\" data-end=\"2454\">\r\n<li data-section-id=\"eovt40\" data-start=\"2327\" data-end=\"2351\">Financial Accounting</li>\r\n<li data-section-id=\"15obis4\" data-start=\"2352\" data-end=\"2368\">Business Law</li>\r\n<li data-section-id=\"19cyfx0\" data-start=\"2369\" data-end=\"2382\">Economics</li>\r\n<li data-section-id=\"1h04yyg\" data-start=\"2383\" data-end=\"2395\">Taxation</li>\r\n<li data-section-id=\"chlzle\" data-start=\"2396\" data-end=\"2419\">Banking &amp; Insurance</li>\r\n<li data-section-id=\"6iw3z9\" data-start=\"2420\" data-end=\"2432\">Auditing</li>\r\n<li data-section-id=\"1tz8fnn\" data-start=\"2433\" data-end=\"2454\">Corporate Finance</li>\r\n</ul>\r\n<p data-start=\"2456\" data-end=\"2555\">This allows students from different streams to adapt and learn successfully with consistent effort.</p>\r\n<hr data-start=\"2557\" data-end=\"2560\">\r\n<h2 data-section-id=\"17m4gbx\" data-start=\"2562\" data-end=\"2605\">Important Admission Insight for Students</h2>\r\n<p data-start=\"2607\" data-end=\"2747\">Many students choose B.Com only because it is popular after Class 12. A better approach is to match the programme with your long-term goals.</p>\r\n<p data-start=\"2749\" data-end=\"2801\">B.Com is highly suitable for students interested in:</p>\r\n<ul data-start=\"2803\" data-end=\"2979\">\r\n<li data-section-id=\"100mlnf\" data-start=\"2803\" data-end=\"2837\">Accounting and finance careers</li>\r\n<li data-section-id=\"1f5x2o6\" data-start=\"2838\" data-end=\"2861\">Banking sector jobs</li>\r\n<li data-section-id=\"rj60yd\" data-start=\"2862\" data-end=\"2901\">CA, CMA, CS, MBA, or M.Com pathways</li>\r\n<li data-section-id=\"zzbgpm\" data-start=\"2902\" data-end=\"2931\">Business management roles</li>\r\n<li data-section-id=\"kextur\" data-start=\"2932\" data-end=\"2979\">Entrepreneurship and family business growth</li>\r\n</ul>\r\n<p data-start=\"2981\" data-end=\"3085\">Students who prefer highly technical or engineering-focused careers may need a different academic route.</p>', '<h2 data-section-id=\"1blynd0\" data-start=\"336\" data-end=\"373\">B.Com Fee Structure &amp; Scholarships</h2>\r\n<p data-start=\"375\" data-end=\"708\">The B.Com programme is designed to provide affordable and career-focused education for students who want to build strong knowledge in commerce, accounting, taxation, finance, and business operations. The fee structure is planned in a transparent semester-wise format so students can manage their academic investment more effectively.</p>\r\n<p data-start=\"710\" data-end=\"881\">With flexible payment options and scholarship support, the programme becomes more accessible for both Indian and international students seeking quality commerce education.</p>\r\n<hr data-start=\"883\" data-end=\"886\">\r\n<h2 data-section-id=\"gvgz7s\" data-start=\"888\" data-end=\"948\">Programme Fee Structure (Indian &amp; International Students)</h2>\r\n<p data-start=\"950\" data-end=\"1091\">The total course fee is divided across six semesters, making it easier for students to plan their payments throughout the programme duration.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" style=\"width: 100.03%;\" data-start=\"1093\" data-end=\"1416\">\r\n<thead data-start=\"1093\" data-end=\"1139\">\r\n<tr data-start=\"1093\" data-end=\"1139\">\r\n<th class=\"\" style=\"width: 33.7508%;\" data-start=\"1093\" data-end=\"1109\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" style=\"width: 25.2587%;\" data-start=\"1109\" data-end=\"1124\" data-col-size=\"sm\">Amount (INR)</th>\r\n<th class=\"\" style=\"width: 40.9365%;\" data-start=\"1124\" data-end=\"1139\" data-col-size=\"md\">Description</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1185\" data-end=\"1416\">\r\n<tr data-start=\"1185\" data-end=\"1271\">\r\n<td style=\"width: 33.7508%;\" data-start=\"1185\" data-end=\"1218\" data-col-size=\"sm\">Total Course Fee (6 Semesters)</td>\r\n<td style=\"width: 25.2587%;\" data-col-size=\"sm\" data-start=\"1218\" data-end=\"1227\">75,000</td>\r\n<td style=\"width: 40.9365%;\" data-col-size=\"md\" data-start=\"1227\" data-end=\"1271\">Full programme fee for complete duration</td>\r\n</tr>\r\n<tr data-start=\"1272\" data-end=\"1345\">\r\n<td style=\"width: 33.7508%;\" data-start=\"1272\" data-end=\"1291\" data-col-size=\"sm\">Fee Per Semester</td>\r\n<td style=\"width: 25.2587%;\" data-col-size=\"sm\" data-start=\"1291\" data-end=\"1300\">12,500</td>\r\n<td style=\"width: 40.9365%;\" data-col-size=\"md\" data-start=\"1300\" data-end=\"1345\">Payable at the beginning of each semester</td>\r\n</tr>\r\n<tr data-start=\"1346\" data-end=\"1416\">\r\n<td style=\"width: 33.7508%;\" data-start=\"1346\" data-end=\"1366\" data-col-size=\"sm\">EMI Starting From</td>\r\n<td style=\"width: 25.2587%;\" data-col-size=\"sm\" data-start=\"1366\" data-end=\"1381\">2,083/month*</td>\r\n<td style=\"width: 40.9365%;\" data-col-size=\"md\" data-start=\"1381\" data-end=\"1416\">Flexible monthly payment option</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1418\" data-end=\"1447\">*Terms and conditions apply.</p>\r\n<hr data-start=\"1449\" data-end=\"1452\">\r\n<h2 data-section-id=\"1ka4sxy\" data-start=\"1454\" data-end=\"1494\">Understanding the B.Com Fee Structure</h2>\r\n<p data-start=\"1496\" data-end=\"1704\">The semester-wise fee model helps students avoid a heavy one-time payment burden. Instead of paying the full amount together, students can manage costs in smaller scheduled payments during each academic term.</p>\r\n<p data-start=\"1706\" data-end=\"1816\">This approach benefits students who prefer better financial planning while continuing uninterrupted education.</p>\r\n<hr data-start=\"1818\" data-end=\"1821\">\r\n<h2 data-section-id=\"o4zen1\" data-start=\"1823\" data-end=\"1844\">EMI Payment Option</h2>\r\n<p data-start=\"1846\" data-end=\"2053\">To make higher education more financially manageable, EMI facilities may be available for eligible students. This allows payment of course fees in monthly installments rather than semester lump-sum payments.</p>\r\n<h3 data-section-id=\"fxs65l\" data-start=\"2055\" data-end=\"2081\">Benefits of EMI Option</h3>\r\n<ul data-start=\"2083\" data-end=\"2290\">\r\n<li data-section-id=\"t2f7fa\" data-start=\"2083\" data-end=\"2121\">Lower immediate financial pressure</li>\r\n<li data-section-id=\"1yl84yt\" data-start=\"2122\" data-end=\"2156\">Better monthly budget planning</li>\r\n<li data-section-id=\"h4pgnz\" data-start=\"2157\" data-end=\"2195\">Easier fee management for families</li>\r\n<li data-section-id=\"1f3q9j6\" data-start=\"2196\" data-end=\"2238\">Convenient option for working students</li>\r\n<li data-section-id=\"1cp0oxu\" data-start=\"2239\" data-end=\"2290\">Continued academic focus without payment stress</li>\r\n</ul>\r\n<p data-start=\"2292\" data-end=\"2383\">The EMI starts from INR 2,083 per month, depending on applicable terms and repayment plans.</p>\r\n<hr data-start=\"2385\" data-end=\"2388\">\r\n<h2 data-section-id=\"rjp7kg\" data-start=\"2390\" data-end=\"2424\">Scholarships for B.Com Students</h2>\r\n<p data-start=\"2426\" data-end=\"2626\">Scholarships can significantly reduce the total academic cost for deserving students. These are generally offered to encourage academic merit and support students from different financial backgrounds.</p>\r\n<h3 data-section-id=\"6p2zs4\" data-start=\"2628\" data-end=\"2665\">Scholarship Consideration Factors</h3>\r\n<ul data-start=\"2667\" data-end=\"2933\">\r\n<li data-section-id=\"7vutdt\" data-start=\"2667\" data-end=\"2724\">Strong academic performance in previous qualification</li>\r\n<li data-section-id=\"p1ci19\" data-start=\"2725\" data-end=\"2761\">Merit-based eligibility criteria</li>\r\n<li data-section-id=\"1yfexl7\" data-start=\"2762\" data-end=\"2803\">Need-based financial support criteria</li>\r\n<li data-section-id=\"42zdw5\" data-start=\"2804\" data-end=\"2872\">Category-based or special scholarship schemes (where applicable)</li>\r\n<li data-section-id=\"weoo8j\" data-start=\"2873\" data-end=\"2933\">Early application advantage in limited scholarship seats</li>\r\n</ul>\r\n<p data-start=\"2935\" data-end=\"3012\">Students should apply early because scholarship opportunities may be limited.</p>\r\n<p>&nbsp;</p>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL),
(229, 67, '9805c1bc-8d63-4310-a03e-92f17c4736fa', 'fab98dd2-2ced-4705-829f-a40524825f73', 52, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 00:32:59', '2026-06-16 05:50:38', '<h2 data-section-id=\"1yisvlw\" data-start=\"312\" data-end=\"335\">BA Admission Process</h2>\r\n<p data-start=\"337\" data-end=\"707\">The BA admission process is designed to be simple, student-friendly, and convenient for applicants who want to begin their undergraduate journey in humanities, social sciences, communication, literature, psychology, economics, political science, and related fields. The application flow is structured in clear stages so students can complete admission without confusion.</p>\r\n<p data-start=\"709\" data-end=\"864\">Whether you are a domestic or international applicant, following each step carefully can help ensure faster verification and smooth admission confirmation.</p>\r\n<hr data-start=\"866\" data-end=\"869\">\r\n<h2 data-section-id=\"g9ni70\" data-start=\"871\" data-end=\"900\">Step 1: Choose a Programme</h2>\r\n<p data-start=\"902\" data-end=\"1181\">The first step is selecting the BA programme based on your academic interests, preferred subjects, and long-term career goals. BA is often chosen by students interested in government exams, teaching, media, administration, psychology, research, public policy, and higher studies.</p>\r\n<p data-start=\"1183\" data-end=\"1223\">Before applying, students should review:</p>\r\n<ul data-start=\"1225\" data-end=\"1416\">\r\n<li data-section-id=\"4r7etc\" data-start=\"1225\" data-end=\"1245\">Course structure</li>\r\n<li data-section-id=\"pjvpzq\" data-start=\"1246\" data-end=\"1283\">Subject or specialization options</li>\r\n<li data-section-id=\"v6fwjj\" data-start=\"1284\" data-end=\"1303\">Learning format</li>\r\n<li data-section-id=\"1w3z4mh\" data-start=\"1304\" data-end=\"1345\">Career opportunities after graduation</li>\r\n<li data-section-id=\"ywynlc\" data-start=\"1346\" data-end=\"1369\">Total programme fee</li>\r\n<li data-section-id=\"nf91s2\" data-start=\"1370\" data-end=\"1416\">Future pathways such as MA, MBA, LLB, B.Ed</li>\r\n</ul>\r\n<p data-start=\"1418\" data-end=\"1537\">Choosing the right programme early helps students make a smarter academic decision and align studies with future goals.</p>\r\n<hr data-start=\"1539\" data-end=\"1542\">\r\n<h2 data-section-id=\"zsdpc9\" data-start=\"1544\" data-end=\"1582\">Step 2: Provide Educational Details</h2>\r\n<p data-start=\"1584\" data-end=\"1689\">After selecting the programme, candidates must fill in their educational details in the application form.</p>\r\n<p data-start=\"1691\" data-end=\"1715\">This generally includes:</p>\r\n<ul data-start=\"1717\" data-end=\"1863\">\r\n<li data-section-id=\"tbi9z9\" data-start=\"1717\" data-end=\"1737\">Class 10 details</li>\r\n<li data-section-id=\"1bd864n\" data-start=\"1738\" data-end=\"1758\">Class 12 details</li>\r\n<li data-section-id=\"19g3okc\" data-start=\"1759\" data-end=\"1788\">Board or institution name</li>\r\n<li data-section-id=\"ac66pr\" data-start=\"1789\" data-end=\"1808\">Year of passing</li>\r\n<li data-section-id=\"148a1kg\" data-start=\"1809\" data-end=\"1827\">Marks obtained</li>\r\n<li data-section-id=\"1au3ggr\" data-start=\"1828\" data-end=\"1863\">Diploma details (if applicable)</li>\r\n</ul>\r\n<p data-start=\"1865\" data-end=\"2015\">All details should match official records. Errors in marks, spelling, or incomplete information may delay document verification or admission approval.</p>\r\n<p data-start=\"2017\" data-end=\"2114\">This stage is important because institutions assess eligibility based on submitted academic data.</p>\r\n<hr data-start=\"2116\" data-end=\"2119\">\r\n<h2 data-section-id=\"7jn770\" data-start=\"2121\" data-end=\"2149\">Step 3: Pay Programme Fee</h2>\r\n<p data-start=\"2151\" data-end=\"2268\">Once educational details are completed, candidates need to pay the programme fee using the available payment options.</p>\r\n<p data-start=\"2270\" data-end=\"2437\">Payment is generally completed through secure online methods. Depending on the institution, EMI or installment options may also be available for easier fee management.</p>\r\n<h3 data-section-id=\"1t6kxfg\" data-start=\"2439\" data-end=\"2464\">Why This Step Matters</h3>\r\n<ul data-start=\"2466\" data-end=\"2632\">\r\n<li data-section-id=\"1qtscft\" data-start=\"2466\" data-end=\"2500\">Confirms your intent to enroll</li>\r\n<li data-section-id=\"1pj9vs\" data-start=\"2501\" data-end=\"2544\">Moves the application to the next stage</li>\r\n<li data-section-id=\"zyccmu\" data-start=\"2545\" data-end=\"2579\">Helps secure timely processing</li>\r\n<li data-section-id=\"15icpok\" data-start=\"2580\" data-end=\"2632\">Reduces delays caused by incomplete applications</li>\r\n</ul>\r\n<p data-start=\"2634\" data-end=\"2719\">Students should always keep payment confirmation or transaction receipts for records.</p>\r\n<hr data-start=\"2721\" data-end=\"2724\">\r\n<h2 data-section-id=\"ix7rwu\" data-start=\"2726\" data-end=\"2774\">Step 4: Upload Documents &amp; Submit Application</h2>\r\n<p data-start=\"2776\" data-end=\"2883\">In the final stage, candidates need to upload required documents and submit the completed application form.</p>\r\n<p data-start=\"2885\" data-end=\"2925\">Commonly required documents may include:</p>\r\n<ul data-start=\"2927\" data-end=\"3093\">\r\n<li data-section-id=\"1ulae2l\" data-start=\"2927\" data-end=\"2949\">Class 10 marksheet</li>\r\n<li data-section-id=\"1eaztxb\" data-start=\"2950\" data-end=\"2972\">Class 12 marksheet</li>\r\n<li data-section-id=\"11bawgc\" data-start=\"2973\" data-end=\"3012\">Diploma certificate (if applicable)</li>\r\n<li data-section-id=\"1l6qwl6\" data-start=\"3013\" data-end=\"3031\">Identity proof</li>\r\n<li data-section-id=\"11yc9fs\" data-start=\"3032\" data-end=\"3060\">Passport-size photograph</li>\r\n<li data-section-id=\"1f0lxta\" data-start=\"3061\" data-end=\"3093\">Signature copy (if required)</li>\r\n</ul>\r\n<p data-start=\"3095\" data-end=\"3205\">Before final submission, students should carefully review all details. Even small mistakes can delay approval.</p>\r\n<p data-start=\"3207\" data-end=\"3349\">Once submitted, the application enters the verification process where eligibility and documents are reviewed for final admission confirmation.</p>', 1, '<p data-start=\"352\" data-end=\"763\">The BA (Bachelor of Arts) programme is designed for students who want to build knowledge in humanities, social sciences, language studies, psychology, political science, sociology, history, economics, and communication-related fields. It is one of the most flexible undergraduate degree options for students planning careers in government sectors, education, media, administration, research, and higher studies.</p>\r\n<p data-start=\"765\" data-end=\"952\">The eligibility criteria are structured to make the programme accessible to students from different academic backgrounds while maintaining a recognized educational standard for admission.</p>\r\n<hr data-start=\"954\" data-end=\"957\">\r\n<h2 data-section-id=\"pghhov\" data-start=\"959\" data-end=\"981\">Eligible Applicants</h2>\r\n<p data-start=\"983\" data-end=\"1111\">The programme welcomes students from India and international backgrounds, creating a diverse and inclusive academic environment.</p>\r\n<h3 data-section-id=\"18gg9gc\" data-start=\"1113\" data-end=\"1144\">Student Categories Eligible</h3>\r\n<ul data-start=\"1146\" data-end=\"1194\">\r\n<li data-section-id=\"55zn8c\" data-start=\"1146\" data-end=\"1167\">Domestic Students</li>\r\n<li data-section-id=\"1ovgt2g\" data-start=\"1168\" data-end=\"1194\">International Students</li>\r\n</ul>\r\n<p data-start=\"1196\" data-end=\"1309\">Students from different educational systems can apply, subject to meeting the minimum qualification requirements.</p>\r\n<hr data-start=\"1311\" data-end=\"1314\">\r\n<h2 data-section-id=\"1qu9ips\" data-start=\"1316\" data-end=\"1353\">Educational Qualification Criteria</h2>\r\n<p data-start=\"1355\" data-end=\"1464\">To apply for BA admission, candidates must have completed any one of the following recognized qualifications:</p>\r\n<h3 data-section-id=\"clqstm\" data-start=\"1466\" data-end=\"1498\">Minimum Academic Requirement</h3>\r\n<ul data-start=\"1500\" data-end=\"1671\">\r\n<li data-section-id=\"khfp87\" data-start=\"1500\" data-end=\"1604\"><strong data-start=\"1502\" data-end=\"1539\">10+2 (Senior Secondary Education)</strong> from a recognized national or state board institution<br data-start=\"1593\" data-end=\"1596\"><strong data-start=\"1596\" data-end=\"1602\">OR</strong></li>\r\n<li data-section-id=\"vydfjt\" data-start=\"1605\" data-end=\"1671\"><strong data-start=\"1607\" data-end=\"1623\">10+3 Diploma</strong> from a recognized national or state institute</li>\r\n</ul>\r\n<p data-start=\"1673\" data-end=\"1826\">Candidates from Arts, Commerce, or Science streams are generally eligible to apply, making BA one of the most accessible undergraduate degree programmes.</p>\r\n<hr data-start=\"1828\" data-end=\"1831\">\r\n<h2 data-section-id=\"j2rkjr\" data-start=\"1833\" data-end=\"1868\">Is Arts Stream Mandatory for BA?</h2>\r\n<p data-start=\"1870\" data-end=\"2036\">No, Arts background is not always compulsory. Students from Commerce or Science streams can also apply for BA if they meet the educational qualification requirements.</p>\r\n<p data-start=\"2038\" data-end=\"2184\">Many students from non-Arts streams choose BA for careers in administration, civil services, media, psychology, public policy, and higher studies.</p>\r\n<hr data-start=\"2186\" data-end=\"2189\">\r\n<h2 data-section-id=\"xv2iqy\" data-start=\"2191\" data-end=\"2228\">Why BA is Open to Multiple Streams</h2>\r\n<p data-start=\"2230\" data-end=\"2420\">The BA curriculum usually starts with foundational concepts and gradually develops subject-specific knowledge. This allows students from different academic backgrounds to adapt successfully.</p>\r\n<p data-start=\"2422\" data-end=\"2457\">Popular learning areas may include:</p>\r\n<ul data-start=\"2459\" data-end=\"2604\">\r\n<li data-section-id=\"1odor5h\" data-start=\"2459\" data-end=\"2480\">Political Science</li>\r\n<li data-section-id=\"48fvv0\" data-start=\"2481\" data-end=\"2494\">Sociology</li>\r\n<li data-section-id=\"19cyfx0\" data-start=\"2495\" data-end=\"2508\">Economics</li>\r\n<li data-section-id=\"uv5ai\" data-start=\"2509\" data-end=\"2520\">History</li>\r\n<li data-section-id=\"5hg1ei\" data-start=\"2521\" data-end=\"2532\">English</li>\r\n<li data-section-id=\"1mvey2z\" data-start=\"2533\" data-end=\"2547\">Psychology</li>\r\n<li data-section-id=\"2ujt53\" data-start=\"2548\" data-end=\"2573\">Public Administration</li>\r\n<li data-section-id=\"1g6ov7c\" data-start=\"2574\" data-end=\"2604\">Journalism &amp; Communication</li>\r\n</ul>\r\n<p data-start=\"2606\" data-end=\"2701\">This broad structure makes BA valuable for both career growth and competitive exam preparation.</p>\r\n<hr data-start=\"2703\" data-end=\"2706\">\r\n<h2 data-section-id=\"17m4gbx\" data-start=\"2708\" data-end=\"2751\">Important Admission Insight for Students</h2>\r\n<p data-start=\"2753\" data-end=\"2889\">Many students choose BA only because it seems easy or common after Class 12. A smarter approach is choosing BA based on long-term goals.</p>\r\n<p data-start=\"2891\" data-end=\"2940\">BA is highly suitable for students interested in:</p>\r\n<ul data-start=\"2942\" data-end=\"3164\">\r\n<li data-section-id=\"1yzxml0\" data-start=\"2942\" data-end=\"2988\">UPSC, SSC, Banking, State Government Exams</li>\r\n<li data-section-id=\"16lfv37\" data-start=\"2989\" data-end=\"3023\">Teaching and education careers</li>\r\n<li data-section-id=\"u73kyo\" data-start=\"3024\" data-end=\"3057\">Media and communication roles</li>\r\n<li data-section-id=\"1szftbf\" data-start=\"3058\" data-end=\"3089\">Research and policy careers</li>\r\n<li data-section-id=\"oiqips\" data-start=\"3090\" data-end=\"3121\">Law, MBA, MA, B.Ed pathways</li>\r\n<li data-section-id=\"1cyg8rl\" data-start=\"3122\" data-end=\"3164\">Social impact and administrative roles</li>\r\n</ul>\r\n<p data-start=\"3166\" data-end=\"3255\">Students who prefer technical or engineering careers may need a different academic route.</p>', '<h2 data-section-id=\"1v5o4q2\" data-start=\"330\" data-end=\"364\">BA Fee Structure &amp; Scholarships</h2>\r\n<p data-start=\"366\" data-end=\"724\">The BA (Bachelor of Arts) programme is designed for students who want to build strong academic knowledge in humanities, social sciences, communication, public administration, psychology, literature, and other career-oriented disciplines. The fee structure is planned to make higher education affordable and accessible for students from different backgrounds.</p>\r\n<p data-start=\"726\" data-end=\"911\">With transparent semester-wise payments, EMI flexibility, and scholarship opportunities, the BA programme offers a balanced combination of quality education and cost-effective learning.</p>\r\n<hr data-start=\"913\" data-end=\"916\">\r\n<h2 data-section-id=\"gvgz7s\" data-start=\"918\" data-end=\"978\">Programme Fee Structure (Indian &amp; International Students)</h2>\r\n<p data-start=\"980\" data-end=\"1118\">The total course fee is divided across six semesters, helping students manage their academic expenses in a structured and predictable way.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1120\" data-end=\"1442\">\r\n<thead data-start=\"1120\" data-end=\"1166\">\r\n<tr data-start=\"1120\" data-end=\"1166\">\r\n<th class=\"\" data-start=\"1120\" data-end=\"1136\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"1136\" data-end=\"1151\" data-col-size=\"sm\">Amount (INR)</th>\r\n<th class=\"\" data-start=\"1151\" data-end=\"1166\" data-col-size=\"md\">Description</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1212\" data-end=\"1442\">\r\n<tr data-start=\"1212\" data-end=\"1298\">\r\n<td data-start=\"1212\" data-end=\"1245\" data-col-size=\"sm\">Total Course Fee (6 Semesters)</td>\r\n<td data-col-size=\"sm\" data-start=\"1245\" data-end=\"1254\">75,000</td>\r\n<td data-col-size=\"md\" data-start=\"1254\" data-end=\"1298\">Full programme fee for complete duration</td>\r\n</tr>\r\n<tr data-start=\"1299\" data-end=\"1372\">\r\n<td data-start=\"1299\" data-end=\"1318\" data-col-size=\"sm\">Fee Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"1318\" data-end=\"1327\">12,500</td>\r\n<td data-col-size=\"md\" data-start=\"1327\" data-end=\"1372\">Payable at the beginning of each semester</td>\r\n</tr>\r\n<tr data-start=\"1373\" data-end=\"1442\">\r\n<td data-start=\"1373\" data-end=\"1393\" data-col-size=\"sm\">EMI Starting From</td>\r\n<td data-col-size=\"sm\" data-start=\"1393\" data-end=\"1407\">2,083/month</td>\r\n<td data-col-size=\"md\" data-start=\"1407\" data-end=\"1442\">Flexible monthly payment option</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1444\" data-end=\"1447\">\r\n<h2 data-section-id=\"1j33ki0\" data-start=\"1449\" data-end=\"1486\">Understanding the BA Fee Structure</h2>\r\n<p data-start=\"1488\" data-end=\"1735\">The semester-wise payment model allows students to distribute their education cost over the full course duration instead of paying a large amount at once. This creates better financial planning and makes degree completion easier for many families.</p>\r\n<p data-start=\"1737\" data-end=\"1879\">It is especially useful for students who want affordable graduation options while preparing for competitive exams, careers, or higher studies.</p>\r\n<hr data-start=\"1881\" data-end=\"1884\">\r\n<h2 data-section-id=\"o4zen1\" data-start=\"1886\" data-end=\"1907\">EMI Payment Option</h2>\r\n<p data-start=\"1909\" data-end=\"2058\">To make fee payments easier, EMI options may be available for eligible students. This enables monthly payments instead of semester lump-sum payments.</p>\r\n<h3 data-section-id=\"fxs65l\" data-start=\"2060\" data-end=\"2086\">Benefits of EMI Option</h3>\r\n<ul data-start=\"2088\" data-end=\"2315\">\r\n<li data-section-id=\"t2f7fa\" data-start=\"2088\" data-end=\"2126\">Lower immediate financial pressure</li>\r\n<li data-section-id=\"lvcttt\" data-start=\"2127\" data-end=\"2155\">Easier monthly budgeting</li>\r\n<li data-section-id=\"17haj20\" data-start=\"2156\" data-end=\"2206\">Better affordability for students and families</li>\r\n<li data-section-id=\"13aqeys\" data-start=\"2207\" data-end=\"2256\">Helps continue studies without payment stress</li>\r\n<li data-section-id=\"n7sia\" data-start=\"2257\" data-end=\"2315\">Useful for working learners and self-financed students</li>\r\n</ul>\r\n<p data-start=\"2317\" data-end=\"2395\">The EMI starts from INR 2,083 per month depending on applicable payment terms.</p>\r\n<hr data-start=\"2397\" data-end=\"2400\">\r\n<h2 data-section-id=\"1da3npa\" data-start=\"2402\" data-end=\"2433\">Scholarships for BA Students</h2>\r\n<p data-start=\"2435\" data-end=\"2621\">Scholarships can help deserving students reduce the total cost of education. These opportunities are usually designed to support merit, need-based cases, and eligible student categories.</p>\r\n<h3 data-section-id=\"6p2zs4\" data-start=\"2623\" data-end=\"2660\">Scholarship Consideration Factors</h3>\r\n<ul data-start=\"2662\" data-end=\"2885\">\r\n<li data-section-id=\"5i5gmq\" data-start=\"2662\" data-end=\"2712\">Academic performance in previous qualification</li>\r\n<li data-section-id=\"ye8ug0\" data-start=\"2713\" data-end=\"2747\">Merit-based selection criteria</li>\r\n<li data-section-id=\"198916a\" data-start=\"2748\" data-end=\"2781\">Financial need of the student</li>\r\n<li data-section-id=\"2ou3xo\" data-start=\"2782\" data-end=\"2835\">Category-based support schemes (where applicable)</li>\r\n<li data-section-id=\"e2zy3p\" data-start=\"2836\" data-end=\"2885\">Early application advantage for limited seats</li>\r\n</ul>\r\n<p data-start=\"2887\" data-end=\"2963\">Students should apply early because scholarship availability may be limited.</p>', 'Medium', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(230, 69, 'd67d3d73-4a79-4175-89f0-c61979138bac', '956f52ba-dcf0-4224-9a30-f9f785980fe3', 207, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 02:21:09', '2026-06-16 06:03:18', '<p data-start=\"363\" data-end=\"701\">Taking admission into a university program is now easier through a fully online process. Students can complete registration, submit the application form, upload documents, pay fees, and receive final enrollment confirmation without visiting the campus. Understanding each step carefully helps avoid mistakes, delays, and rejection issues.</p>\r\n<p data-start=\"703\" data-end=\"883\">This detailed guide explains the complete admission process, important documents required, expert strategies, common mistakes, and FAQs so you can complete your admission smoothly.</p>\r\n<hr data-start=\"885\" data-end=\"888\">\r\n<h2 data-section-id=\"n6olxg\" data-start=\"890\" data-end=\"919\">Admission Process Overview</h2>\r\n<p data-start=\"921\" data-end=\"977\">The admission process usually includes four main stages:</p>\r\n<ol data-start=\"979\" data-end=\"1122\">\r\n<li data-section-id=\"nl6le3\" data-start=\"979\" data-end=\"996\">Registration</li>\r\n<li data-section-id=\"b57nsi\" data-start=\"997\" data-end=\"1036\">Online Application Form Submission</li>\r\n<li data-section-id=\"101zuxd\" data-start=\"1037\" data-end=\"1077\">Document Verification by University</li>\r\n<li data-section-id=\"1n3o77u\" data-start=\"1078\" data-end=\"1122\">Student Registration and LMS Activation</li>\r\n</ol>\r\n<p data-start=\"1124\" data-end=\"1181\">Each step is important and should be completed carefully.</p>\r\n<hr data-start=\"1183\" data-end=\"1186\">\r\n<h2 data-section-id=\"1nf6nd9\" data-start=\"1188\" data-end=\"1211\">Step 1: Registration</h2>\r\n<p data-start=\"1213\" data-end=\"1354\">The first step is to create your account on the official admission portal. During registration, students need to enter basic details such as:</p>\r\n<ul data-start=\"1356\" data-end=\"1438\">\r\n<li data-section-id=\"u7na1o\" data-start=\"1356\" data-end=\"1369\">Full Name</li>\r\n<li data-section-id=\"1dep5uz\" data-start=\"1370\" data-end=\"1387\">Mobile Number</li>\r\n<li data-section-id=\"36fvl5\" data-start=\"1388\" data-end=\"1400\">Email ID</li>\r\n<li data-section-id=\"4ligt3\" data-start=\"1401\" data-end=\"1417\">State / City</li>\r\n<li data-section-id=\"ngbb80\" data-start=\"1418\" data-end=\"1438\">Preferred Course</li>\r\n</ul>\r\n<p data-start=\"1440\" data-end=\"1512\">After entering the details, pay the initial registration fee to proceed.</p>\r\n<h3 data-section-id=\"rdfplr\" data-start=\"1514\" data-end=\"1529\">Expert Tip:</h3>\r\n<p data-start=\"1530\" data-end=\"1670\">Use an active mobile number and email ID because all admission alerts, fee receipts, login credentials, and approval updates are sent there.</p>\r\n<h3 data-section-id=\"1r2916b\" data-start=\"1672\" data-end=\"1700\">Common Mistake to Avoid:</h3>\r\n<p data-start=\"1701\" data-end=\"1778\">Using incorrect phone numbers or inactive email IDs may cause missed updates.</p>\r\n<hr data-start=\"1780\" data-end=\"1783\">\r\n<h2 data-section-id=\"1s32fp8\" data-start=\"1785\" data-end=\"1819\">Step 2: Online Application Form</h2>\r\n<p data-start=\"1821\" data-end=\"1920\">After registration, log in and complete the online application form. This section usually asks for:</p>\r\n<ul data-start=\"1922\" data-end=\"2091\">\r\n<li data-section-id=\"1a7orss\" data-start=\"1922\" data-end=\"1946\">Personal information</li>\r\n<li data-section-id=\"19byrdb\" data-start=\"1947\" data-end=\"1974\">Academic qualifications</li>\r\n<li data-section-id=\"15di1ss\" data-start=\"1975\" data-end=\"1994\">Address details</li>\r\n<li data-section-id=\"yylsws\" data-start=\"1995\" data-end=\"2016\">Program selection</li>\r\n<li data-section-id=\"1it83p5\" data-start=\"2017\" data-end=\"2053\">Category details (if applicable)</li>\r\n<li data-section-id=\"24qq0u\" data-start=\"2054\" data-end=\"2091\">Work experience (for some programs)</li>\r\n</ul>\r\n<p data-start=\"2093\" data-end=\"2171\">Once the form is completed, pay the program fee and upload required documents.</p>\r\n<h3 data-section-id=\"vk3dum\" data-start=\"2173\" data-end=\"2202\">Common Documents Required</h3>\r\n<ul data-start=\"2204\" data-end=\"2392\">\r\n<li data-section-id=\"cr8wnx\" data-start=\"2204\" data-end=\"2226\">Class 10 Marksheet</li>\r\n<li data-section-id=\"17vfufz\" data-start=\"2227\" data-end=\"2249\">Class 12 Marksheet</li>\r\n<li data-section-id=\"1d3jjwv\" data-start=\"2250\" data-end=\"2291\">Graduation documents (for PG courses)</li>\r\n<li data-section-id=\"1pbph22\" data-start=\"2292\" data-end=\"2310\">Identity Proof</li>\r\n<li data-section-id=\"1lteajs\" data-start=\"2311\" data-end=\"2339\">Passport-size Photograph</li>\r\n<li data-section-id=\"1yra9zg\" data-start=\"2340\" data-end=\"2353\">Signature</li>\r\n<li data-section-id=\"8duxhq\" data-start=\"2354\" data-end=\"2392\">Category Certificate (if applicable)</li>\r\n</ul>\r\n<h3 data-section-id=\"1r40k1a\" data-start=\"2394\" data-end=\"2417\">Admission Strategy:</h3>\r\n<p data-start=\"2418\" data-end=\"2540\">Keep scanned documents ready in PDF/JPG format before starting the form. This saves time and avoids session expiry issues.</p>\r\n<hr data-start=\"2542\" data-end=\"2545\">\r\n<h2 data-section-id=\"12ygutz\" data-start=\"2547\" data-end=\"2593\">Step 3: Document Verification by University</h2>\r\n<p data-start=\"2595\" data-end=\"2726\">After submission, the university verifies all entered details and uploaded documents. During this stage, the admission team checks:</p>\r\n<ul data-start=\"2728\" data-end=\"2851\">\r\n<li data-section-id=\"1vvng9i\" data-start=\"2728\" data-end=\"2752\">Eligibility criteria</li>\r\n<li data-section-id=\"y9v8m0\" data-start=\"2753\" data-end=\"2780\">Marksheets authenticity</li>\r\n<li data-section-id=\"mtjolo\" data-start=\"2781\" data-end=\"2809\">Correct personal details</li>\r\n<li data-section-id=\"ql0fuo\" data-start=\"2810\" data-end=\"2832\">Fee payment status</li>\r\n<li data-section-id=\"1v7qo9r\" data-start=\"2833\" data-end=\"2851\">Document clarity</li>\r\n</ul>\r\n<p data-start=\"2853\" data-end=\"2946\">If any issue is found, correction requests may be sent through email or portal notifications.</p>\r\n<h3 data-section-id=\"1xc2m1y\" data-start=\"2948\" data-end=\"2969\">Important Advice:</h3>\r\n<p data-start=\"2970\" data-end=\"3022\">Check your email daily after application submission.</p>\r\n<h3 data-section-id=\"1bl8n98\" data-start=\"3024\" data-end=\"3052\">Hidden Reason for Delay:</h3>\r\n<p data-start=\"3053\" data-end=\"3137\">Blurred documents, mismatched names, or incomplete mark sheets often delay approval.</p>\r\n<hr data-start=\"3139\" data-end=\"3142\">\r\n<h2 data-section-id=\"1peq11o\" data-start=\"3144\" data-end=\"3194\">Step 4: Student Registration and LMS Activation</h2>\r\n<p data-start=\"3196\" data-end=\"3288\">Once verification is successful, final admission approval is granted. Students then receive:</p>\r\n<ul data-start=\"3290\" data-end=\"3394\">\r\n<li data-section-id=\"el5erz\" data-start=\"3290\" data-end=\"3311\">Enrollment Number</li>\r\n<li data-section-id=\"f73c3w\" data-start=\"3312\" data-end=\"3326\">Student ID</li>\r\n<li data-section-id=\"1onixcx\" data-start=\"3327\" data-end=\"3352\">LMS Login Credentials</li>\r\n<li data-section-id=\"qb3s5a\" data-start=\"3353\" data-end=\"3370\">Welcome Email</li>\r\n<li data-section-id=\"13zrgz\" data-start=\"3371\" data-end=\"3394\">Course Access Details</li>\r\n</ul>\r\n<p data-start=\"3396\" data-end=\"3450\">The LMS (Learning Management System) allows access to:</p>\r\n<ul data-start=\"3452\" data-end=\"3551\">\r\n<li data-section-id=\"8imkcm\" data-start=\"3452\" data-end=\"3468\">Live classes</li>\r\n<li data-section-id=\"1d3fguj\" data-start=\"3469\" data-end=\"3490\">Recorded lectures</li>\r\n<li data-section-id=\"13wjzos\" data-start=\"3491\" data-end=\"3509\">Study material</li>\r\n<li data-section-id=\"1f7qwlk\" data-start=\"3510\" data-end=\"3525\">Assignments</li>\r\n<li data-section-id=\"82dhm\" data-start=\"3526\" data-end=\"3535\">Exams</li>\r\n<li data-section-id=\"5lejyy\" data-start=\"3536\" data-end=\"3551\">Announcements</li>\r\n</ul>\r\n<hr data-start=\"3553\" data-end=\"3556\">\r\n<h2 data-section-id=\"66k2di\" data-start=\"3558\" data-end=\"3600\">Why Completing Admission Early is Smart</h2>\r\n<p data-start=\"3602\" data-end=\"3654\">Students who apply early often get benefits such as:</p>\r\n<ul data-start=\"3656\" data-end=\"3813\">\r\n<li data-section-id=\"bb1h4j\" data-start=\"3656\" data-end=\"3683\">Faster approval process</li>\r\n<li data-section-id=\"1qim1fu\" data-start=\"3684\" data-end=\"3712\">Better seat availability</li>\r\n<li data-section-id=\"srwl7u\" data-start=\"3713\" data-end=\"3757\">Scholarship opportunities (if available)</li>\r\n<li data-section-id=\"im1sd2\" data-start=\"3758\" data-end=\"3787\">More time for corrections</li>\r\n<li data-section-id=\"1cd1pf0\" data-start=\"3788\" data-end=\"3813\">Early access to classes</li>\r\n</ul>', 1, '<p data-start=\"359\" data-end=\"642\">Pursuing an MBA is one of the most popular choices for students and working professionals who want career growth, management skills, higher salary potential, and leadership opportunities. Before applying, it is important to understand the latest MBA eligibility criteria carefully.</p>\r\n<p data-start=\"644\" data-end=\"944\">Many students assume only commerce or business graduates can apply, but in reality, MBA programs usually accept candidates from multiple academic backgrounds. This makes MBA a flexible option for engineers, arts graduates, science students, commerce graduates, and professional qualification holders.</p>\r\n<p data-start=\"946\" data-end=\"1088\">This guide explains the complete MBA eligibility, accepted qualifications, who should apply, hidden mistakes to avoid, and admission strategy.</p>\r\n<hr data-start=\"1090\" data-end=\"1093\">\r\n<h2 data-section-id=\"rk8gie\" data-start=\"1095\" data-end=\"1131\">MBA Eligibility Criteria Overview</h2>\r\n<p data-start=\"1133\" data-end=\"1238\">Candidates are eligible for MBA admission if they have completed any one of the following qualifications:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1240\" data-end=\"1489\">\r\n<thead data-start=\"1240\" data-end=\"1287\">\r\n<tr data-start=\"1240\" data-end=\"1287\">\r\n<th class=\"\" data-start=\"1240\" data-end=\"1265\" data-col-size=\"sm\">Accepted Qualification</th>\r\n<th class=\"\" data-start=\"1265\" data-end=\"1287\" data-col-size=\"sm\">Eligibility Status</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1298\" data-end=\"1489\">\r\n<tr data-start=\"1298\" data-end=\"1348\">\r\n<td data-start=\"1298\" data-end=\"1336\" data-col-size=\"sm\">Bachelor&rsquo;s Degree in any discipline</td>\r\n<td data-col-size=\"sm\" data-start=\"1336\" data-end=\"1348\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1349\" data-end=\"1396\">\r\n<td data-start=\"1349\" data-end=\"1384\" data-col-size=\"sm\">Company Secretary (CS) from ICSI</td>\r\n<td data-col-size=\"sm\" data-start=\"1384\" data-end=\"1396\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1397\" data-end=\"1438\">\r\n<td data-start=\"1397\" data-end=\"1426\" data-col-size=\"sm\">Chartered Accountancy (CA)</td>\r\n<td data-col-size=\"sm\" data-start=\"1426\" data-end=\"1438\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1439\" data-end=\"1489\">\r\n<td data-start=\"1439\" data-end=\"1477\" data-col-size=\"sm\">Cost &amp; Management Accountancy (CMA)</td>\r\n<td data-col-size=\"sm\" data-start=\"1477\" data-end=\"1489\">Eligible</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1491\" data-end=\"1494\">\r\n<h2 data-section-id=\"4ekgak\" data-start=\"1496\" data-end=\"1537\">Primary Eligibility: Bachelor&rsquo;s Degree</h2>\r\n<p data-start=\"1539\" data-end=\"1679\">Applicants who have completed a <strong data-start=\"1571\" data-end=\"1610\">bachelor&rsquo;s degree in any discipline</strong> or equivalent qualification are eligible to apply for MBA admission.</p>\r\n<p data-start=\"1681\" data-end=\"1746\">This means students from the following streams can usually apply:</p>\r\n<ul data-start=\"1748\" data-end=\"1849\">\r\n<li data-section-id=\"16ynlwp\" data-start=\"1748\" data-end=\"1755\">BBA</li>\r\n<li data-section-id=\"1kuwkdh\" data-start=\"1756\" data-end=\"1765\">B.Com</li>\r\n<li data-section-id=\"1j42u0b\" data-start=\"1766\" data-end=\"1772\">BA</li>\r\n<li data-section-id=\"1ub0l3o\" data-start=\"1773\" data-end=\"1781\">B.Sc</li>\r\n<li data-section-id=\"1hnd5hy\" data-start=\"1782\" data-end=\"1797\">B.Tech / BE</li>\r\n<li data-section-id=\"16yrbgo\" data-start=\"1798\" data-end=\"1805\">BCA</li>\r\n<li data-section-id=\"16ym967\" data-start=\"1806\" data-end=\"1813\">BHM</li>\r\n<li data-section-id=\"1p8ot6m\" data-start=\"1814\" data-end=\"1849\">Other recognized graduate degrees</li>\r\n</ul>\r\n<h3 data-section-id=\"1r1zf6i\" data-start=\"1851\" data-end=\"1868\">Key Advantage</h3>\r\n<p data-start=\"1870\" data-end=\"1960\">MBA accepts students from diverse backgrounds, allowing career transition into management.</p>\r\n<hr data-start=\"1962\" data-end=\"1965\">\r\n<h2 data-section-id=\"y2042o\" data-start=\"1967\" data-end=\"2018\">Professional Qualification Holders Also Eligible</h2>\r\n<p data-start=\"2020\" data-end=\"2113\">Apart from graduation, candidates with recognized professional qualifications can also apply.</p>\r\n<h3 data-section-id=\"5jfpak\" data-start=\"2115\" data-end=\"2141\">Company Secretary (CS)</h3>\r\n<p data-start=\"2143\" data-end=\"2275\">Candidates who have completed <strong data-start=\"2173\" data-end=\"2199\">Company Secretary (CS)</strong> from the <strong data-start=\"2209\" data-end=\"2261\">Institute of Company Secretaries of India (ICSI)</strong> are eligible.</p>\r\n<h3 data-section-id=\"1h990r\" data-start=\"2277\" data-end=\"2307\">Chartered Accountancy (CA)</h3>\r\n<p data-start=\"2309\" data-end=\"2416\">Candidates who have completed <strong data-start=\"2339\" data-end=\"2345\">CA</strong> from the <strong data-start=\"2355\" data-end=\"2402\">Institute of Chartered Accountants of India</strong> are eligible.</p>\r\n<h3 data-section-id=\"10wraxu\" data-start=\"2418\" data-end=\"2457\">Cost &amp; Management Accountancy (CMA)</h3>\r\n<p data-start=\"2459\" data-end=\"2567\">Candidates who have completed <strong data-start=\"2489\" data-end=\"2496\">CMA</strong> from the <strong data-start=\"2506\" data-end=\"2548\">Institute of Cost Accountants of India</strong> are also eligible.</p>\r\n<hr data-start=\"2569\" data-end=\"2572\">\r\n<h2 data-section-id=\"1bfmnnm\" data-start=\"2574\" data-end=\"2602\">Who Should Apply for MBA?</h2>\r\n<p data-start=\"2604\" data-end=\"2624\">MBA is suitable for:</p>\r\n<ul data-start=\"2626\" data-end=\"2889\">\r\n<li data-section-id=\"1rqau5a\" data-start=\"2626\" data-end=\"2672\">Fresh graduates seeking management careers</li>\r\n<li data-section-id=\"icu3nh\" data-start=\"2673\" data-end=\"2717\">Working professionals wanting promotions</li>\r\n<li data-section-id=\"4kcsfe\" data-start=\"2718\" data-end=\"2760\">Entrepreneurs building business skills</li>\r\n<li data-section-id=\"1dgzjh0\" data-start=\"2761\" data-end=\"2803\">Engineers moving into leadership roles</li>\r\n<li data-section-id=\"uyd1zb\" data-start=\"2804\" data-end=\"2851\">Commerce students targeting finance careers</li>\r\n<li data-section-id=\"1uxbwel\" data-start=\"2852\" data-end=\"2889\">Professionals seeking salary growth</li>\r\n</ul>\r\n<hr data-start=\"2891\" data-end=\"2894\">\r\n<h2 data-section-id=\"h11mz5\" data-start=\"2896\" data-end=\"2940\">MBA Admission Strategy for Better Success</h2>\r\n<h3 data-section-id=\"h1wimp\" data-start=\"2942\" data-end=\"2957\">Apply Early</h3>\r\n<p data-start=\"2959\" data-end=\"3040\">Seats, scholarships, and early admission benefits may reduce closer to deadlines.</p>\r\n<h3 data-section-id=\"1av94kq\" data-start=\"3042\" data-end=\"3066\">Keep Documents Ready</h3>\r\n<p data-start=\"3068\" data-end=\"3093\">Prepare these in advance:</p>\r\n<ul data-start=\"3095\" data-end=\"3225\">\r\n<li data-section-id=\"15u4qah\" data-start=\"3095\" data-end=\"3120\">Graduation marksheets</li>\r\n<li data-section-id=\"123dnd5\" data-start=\"3121\" data-end=\"3143\">Degree certificate</li>\r\n<li data-section-id=\"1rsbash\" data-start=\"3144\" data-end=\"3156\">ID proof</li>\r\n<li data-section-id=\"1djs98o\" data-start=\"3157\" data-end=\"3171\">Photograph</li>\r\n<li data-section-id=\"3mti2j\" data-start=\"3172\" data-end=\"3225\">Professional certificates (CA/CS/CMA if applicable)</li>\r\n</ul>\r\n<h3 data-section-id=\"1gzztx4\" data-start=\"3227\" data-end=\"3260\">Choose Specialization Smartly</h3>\r\n<p data-start=\"3262\" data-end=\"3327\">Select MBA specialization based on career goals, not trends only.</p>\r\n<p data-start=\"3329\" data-end=\"3338\">Examples:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3340\" data-end=\"3569\">\r\n<thead data-start=\"3340\" data-end=\"3376\">\r\n<tr data-start=\"3340\" data-end=\"3376\">\r\n<th class=\"\" data-start=\"3340\" data-end=\"3347\" data-col-size=\"sm\">Goal</th>\r\n<th class=\"\" data-start=\"3347\" data-end=\"3376\" data-col-size=\"sm\">Better MBA Specialization</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3387\" data-end=\"3569\">\r\n<tr data-start=\"3387\" data-end=\"3430\">\r\n<td data-start=\"3387\" data-end=\"3410\" data-col-size=\"sm\">Corporate Leadership</td>\r\n<td data-col-size=\"sm\" data-start=\"3410\" data-end=\"3430\">HR / General MBA</td>\r\n</tr>\r\n<tr data-start=\"3431\" data-end=\"3459\">\r\n<td data-start=\"3431\" data-end=\"3448\" data-col-size=\"sm\">Finance Career</td>\r\n<td data-start=\"3448\" data-end=\"3459\" data-col-size=\"sm\">Finance</td>\r\n</tr>\r\n<tr data-start=\"3460\" data-end=\"3490\">\r\n<td data-start=\"3460\" data-end=\"3477\" data-col-size=\"sm\">Marketing Jobs</td>\r\n<td data-col-size=\"sm\" data-start=\"3477\" data-end=\"3490\">Marketing</td>\r\n</tr>\r\n<tr data-start=\"3491\" data-end=\"3531\">\r\n<td data-start=\"3491\" data-end=\"3509\" data-col-size=\"sm\">Data/Tech Roles</td>\r\n<td data-col-size=\"sm\" data-start=\"3509\" data-end=\"3531\">Business Analytics</td>\r\n</tr>\r\n<tr data-start=\"3532\" data-end=\"3569\">\r\n<td data-start=\"3532\" data-end=\"3549\" data-col-size=\"sm\">Startup Growth</td>\r\n<td data-start=\"3549\" data-end=\"3569\" data-col-size=\"sm\">Entrepreneurship</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', '<p data-start=\"379\" data-end=\"621\">Understanding the fee structure before taking admission is one of the most important steps for students and parents. A clear fee breakdown helps in budgeting, comparing universities, planning EMI payments, and avoiding hidden charges later.</p>\r\n<p data-start=\"623\" data-end=\"797\">This guide explains the latest applicable fee, semester charges, payment options, student grant benefits, registration fee, examination charges, and smart payment strategies.</p>\r\n<hr data-start=\"799\" data-end=\"802\">\r\n<h2 data-section-id=\"1q0y9lx\" data-start=\"804\" data-end=\"825\">Quick Fee Overview</h2>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"827\" data-end=\"1144\">\r\n<thead data-start=\"827\" data-end=\"853\">\r\n<tr data-start=\"827\" data-end=\"853\">\r\n<th class=\"\" data-start=\"827\" data-end=\"843\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"843\" data-end=\"853\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"865\" data-end=\"1144\">\r\n<tr data-start=\"865\" data-end=\"889\">\r\n<td data-start=\"865\" data-end=\"878\" data-col-size=\"sm\">Actual Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"878\" data-end=\"889\">₹50,000</td>\r\n</tr>\r\n<tr data-start=\"890\" data-end=\"931\">\r\n<td data-start=\"890\" data-end=\"907\" data-col-size=\"sm\">Applicable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"907\" data-end=\"931\">₹40,400 per semester</td>\r\n</tr>\r\n<tr data-start=\"932\" data-end=\"963\">\r\n<td data-start=\"932\" data-end=\"956\" data-col-size=\"sm\">Student Grant Benefit</td>\r\n<td data-col-size=\"sm\" data-start=\"956\" data-end=\"963\">20%</td>\r\n</tr>\r\n<tr data-start=\"964\" data-end=\"1010\">\r\n<td data-start=\"964\" data-end=\"983\" data-col-size=\"sm\">Registration Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"983\" data-end=\"1010\">₹1,000 (Non-refundable)</td>\r\n</tr>\r\n<tr data-start=\"1011\" data-end=\"1061\">\r\n<td data-start=\"1011\" data-end=\"1038\" data-col-size=\"sm\">Examination Fee Included</td>\r\n<td data-col-size=\"sm\" data-start=\"1038\" data-end=\"1061\">₹2,000 per semester</td>\r\n</tr>\r\n<tr data-start=\"1062\" data-end=\"1096\">\r\n<td data-start=\"1062\" data-end=\"1078\" data-col-size=\"sm\">Payment Modes</td>\r\n<td data-col-size=\"sm\" data-start=\"1078\" data-end=\"1096\">One-Time / EMI</td>\r\n</tr>\r\n<tr data-start=\"1097\" data-end=\"1144\">\r\n<td data-start=\"1097\" data-end=\"1118\" data-col-size=\"sm\">Payment Preference</td>\r\n<td data-col-size=\"sm\" data-start=\"1118\" data-end=\"1144\">No-Cost EMI / Standard</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1146\" data-end=\"1149\">\r\n<h2 data-section-id=\"1kj9mkj\" data-start=\"1151\" data-end=\"1186\">Current Discounted Fee Structure</h2>\r\n<p data-start=\"1188\" data-end=\"1274\">Students currently receive a <strong data-start=\"1217\" data-end=\"1238\">20% Student Grant</strong>, reducing the regular semester fee.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1276\" data-end=\"1419\">\r\n<thead data-start=\"1276\" data-end=\"1300\">\r\n<tr data-start=\"1276\" data-end=\"1300\">\r\n<th class=\"\" data-start=\"1276\" data-end=\"1290\" data-col-size=\"sm\">Particulars</th>\r\n<th class=\"\" data-start=\"1290\" data-end=\"1300\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1312\" data-end=\"1419\">\r\n<tr data-start=\"1312\" data-end=\"1347\">\r\n<td data-start=\"1312\" data-end=\"1336\" data-col-size=\"sm\">Original Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1336\" data-end=\"1347\">₹50,000</td>\r\n</tr>\r\n<tr data-start=\"1348\" data-end=\"1385\">\r\n<td data-start=\"1348\" data-end=\"1374\" data-col-size=\"sm\">Discounted Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1374\" data-end=\"1385\">₹40,400</td>\r\n</tr>\r\n<tr data-start=\"1386\" data-end=\"1419\">\r\n<td data-start=\"1386\" data-end=\"1409\" data-col-size=\"sm\">Savings Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"1409\" data-end=\"1419\">₹9,600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1421\" data-end=\"1497\"><strong data-start=\"1421\" data-end=\"1440\">Offer Validity:</strong> Till <strong data-start=\"1446\" data-end=\"1462\">9th May 2026</strong> (subject to terms and conditions).</p>\r\n<hr data-start=\"1499\" data-end=\"1502\">\r\n<h2 data-section-id=\"w56wte\" data-start=\"1504\" data-end=\"1534\">Amount Payable Per Semester</h2>\r\n<p data-start=\"1536\" data-end=\"1557\">Students need to pay:</p>\r\n<h2 data-section-id=\"1wry475\" data-start=\"1559\" data-end=\"1580\">₹40,400 / Semester</h2>\r\n<p data-start=\"1582\" data-end=\"1640\">This amount is the applicable fee after the current grant.</p>\r\n<hr data-start=\"1642\" data-end=\"1645\">\r\n<h2 data-section-id=\"1hotckd\" data-start=\"1647\" data-end=\"1679\">Included and Excluded Charges</h2>\r\n<h3 data-section-id=\"475otu\" data-start=\"1681\" data-end=\"1711\">Included in Applicable Fee</h3>\r\n<ul data-start=\"1713\" data-end=\"1802\">\r\n<li data-section-id=\"1wi1p1u\" data-start=\"1713\" data-end=\"1755\">Examination Fee of ₹2,000 per semester</li>\r\n<li data-section-id=\"h25n39\" data-start=\"1756\" data-end=\"1802\">Tuition and academic charges (as applicable)</li>\r\n</ul>\r\n<h3 data-section-id=\"62bp9p\" data-start=\"1804\" data-end=\"1824\">Excluded Charges</h3>\r\n<ul data-start=\"1826\" data-end=\"1914\">\r\n<li data-section-id=\"aqcom4\" data-start=\"1826\" data-end=\"1864\">Initial registration fee of ₹1,000</li>\r\n<li data-section-id=\"8e7fh9\" data-start=\"1865\" data-end=\"1914\">Other optional charges, if any applicable later</li>\r\n</ul>\r\n<hr data-start=\"1916\" data-end=\"1919\">\r\n<h2 data-section-id=\"1ciqit1\" data-start=\"1921\" data-end=\"1955\">Eligible Countries for This Fee</h2>\r\n<p data-start=\"1957\" data-end=\"2009\">The mentioned fee is applicable for applicants from:</p>\r\n<ul data-start=\"2011\" data-end=\"2084\">\r\n<li data-section-id=\"tgrdfn\" data-start=\"2011\" data-end=\"2020\">India</li>\r\n<li data-section-id=\"qjtdvt\" data-start=\"2021\" data-end=\"2034\">Sri Lanka</li>\r\n<li data-section-id=\"yxs3bg\" data-start=\"2035\" data-end=\"2045\">Bhutan</li>\r\n<li data-section-id=\"ef0w72\" data-start=\"2046\" data-end=\"2055\">Nepal</li>\r\n<li data-section-id=\"xi9ghh\" data-start=\"2056\" data-end=\"2070\">Bangladesh</li>\r\n<li data-section-id=\"1woqgfi\" data-start=\"2071\" data-end=\"2084\">Afghanistan</li>\r\n</ul>\r\n<hr data-start=\"2086\" data-end=\"2089\">\r\n<h2 data-section-id=\"148ijp2\" data-start=\"2091\" data-end=\"2119\">Payment Options Available</h2>\r\n<p data-start=\"2121\" data-end=\"2182\">Students can choose payment methods according to convenience.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2184\" data-end=\"2401\">\r\n<thead data-start=\"2184\" data-end=\"2217\">\r\n<tr data-start=\"2184\" data-end=\"2217\">\r\n<th class=\"\" data-start=\"2184\" data-end=\"2205\" data-col-size=\"sm\">Payment Preference</th>\r\n<th class=\"\" data-start=\"2205\" data-end=\"2217\" data-col-size=\"sm\">Best For</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2228\" data-end=\"2401\">\r\n<tr data-start=\"2228\" data-end=\"2281\">\r\n<td data-start=\"2228\" data-end=\"2242\" data-col-size=\"sm\">No-Cost EMI</td>\r\n<td data-start=\"2242\" data-end=\"2281\" data-col-size=\"sm\">Students wanting low monthly burden</td>\r\n</tr>\r\n<tr data-start=\"2282\" data-end=\"2328\">\r\n<td data-start=\"2282\" data-end=\"2301\" data-col-size=\"sm\">Standard Payment</td>\r\n<td data-start=\"2301\" data-end=\"2328\" data-col-size=\"sm\">Direct regular payments</td>\r\n</tr>\r\n<tr data-start=\"2329\" data-end=\"2372\">\r\n<td data-start=\"2329\" data-end=\"2348\" data-col-size=\"sm\">One-Time Payment</td>\r\n<td data-start=\"2348\" data-end=\"2372\" data-col-size=\"sm\">Faster fee clearance</td>\r\n</tr>\r\n<tr data-start=\"2373\" data-end=\"2401\">\r\n<td data-start=\"2373\" data-end=\"2379\" data-col-size=\"sm\">EMI</td>\r\n<td data-start=\"2379\" data-end=\"2401\" data-col-size=\"sm\">Flexible budgeting</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', NULL, '<p data-start=\"359\" data-end=\"687\">The MBA syllabus is designed to build strong business knowledge, leadership ability, decision-making skills, and industry-ready management expertise. A well-structured MBA program covers core management subjects in the first year and specialization-based electives, strategy, projects, and advanced learning in the final year.</p>\r\n<p data-start=\"689\" data-end=\"863\">This semester-wise MBA syllabus gives students clarity about what they will study, how the curriculum develops practical skills, and how each semester supports career growth.</p>\r\n<hr data-start=\"865\" data-end=\"868\">\r\n<h2 data-section-id=\"1skm340\" data-start=\"870\" data-end=\"902\">MBA Course Structure Overview</h2>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"904\" data-end=\"1108\">\r\n<thead data-start=\"904\" data-end=\"925\">\r\n<tr data-start=\"904\" data-end=\"925\">\r\n<th class=\"\" data-start=\"904\" data-end=\"911\" data-col-size=\"sm\">Year</th>\r\n<th class=\"\" data-start=\"911\" data-end=\"925\" data-col-size=\"md\">Focus Area</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"936\" data-end=\"1108\">\r\n<tr data-start=\"936\" data-end=\"981\">\r\n<td data-start=\"936\" data-end=\"949\" data-col-size=\"sm\">First Year</td>\r\n<td data-col-size=\"md\" data-start=\"949\" data-end=\"981\">Core management fundamentals</td>\r\n</tr>\r\n<tr data-start=\"982\" data-end=\"1049\">\r\n<td data-start=\"982\" data-end=\"996\" data-col-size=\"sm\">Second Year</td>\r\n<td data-col-size=\"md\" data-start=\"996\" data-end=\"1049\">Specialization, strategy, electives, project work</td>\r\n</tr>\r\n<tr data-start=\"1050\" data-end=\"1108\">\r\n<td data-start=\"1050\" data-end=\"1067\" data-col-size=\"sm\">Final Semester</td>\r\n<td data-col-size=\"md\" data-start=\"1067\" data-end=\"1108\">Advanced electives + capstone project</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1110\" data-end=\"1113\">\r\n<h1 data-section-id=\"qd45fl\" data-start=\"1115\" data-end=\"1143\">MBA Semester Wise Syllabus</h1>\r\n<h2 data-section-id=\"1m6zdaj\" data-start=\"1145\" data-end=\"1182\">Semester 1: Management Foundations</h2>\r\n<p data-start=\"1184\" data-end=\"1309\">The first semester builds a strong base in finance, economics, marketing, business environment, and organizational behaviour.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1311\" data-end=\"1595\">\r\n<thead data-start=\"1311\" data-end=\"1342\">\r\n<tr data-start=\"1311\" data-end=\"1342\">\r\n<th class=\"\" data-start=\"1311\" data-end=\"1326\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"1326\" data-end=\"1342\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1353\" data-end=\"1595\">\r\n<tr data-start=\"1353\" data-end=\"1411\">\r\n<td data-start=\"1353\" data-end=\"1363\" data-col-size=\"sm\">EACC506</td>\r\n<td data-start=\"1363\" data-end=\"1411\" data-col-size=\"md\">Financial Reporting, Statements and Analysis</td>\r\n</tr>\r\n<tr data-start=\"1412\" data-end=\"1446\">\r\n<td data-start=\"1412\" data-end=\"1422\" data-col-size=\"sm\">EECO515</td>\r\n<td data-start=\"1422\" data-end=\"1446\" data-col-size=\"md\">Managerial Economics</td>\r\n</tr>\r\n<tr data-start=\"1447\" data-end=\"1495\">\r\n<td data-start=\"1447\" data-end=\"1457\" data-col-size=\"sm\">EMGN578</td>\r\n<td data-start=\"1457\" data-end=\"1495\" data-col-size=\"md\">International Business Environment</td>\r\n</tr>\r\n<tr data-start=\"1496\" data-end=\"1530\">\r\n<td data-start=\"1496\" data-end=\"1506\" data-col-size=\"sm\">EMKT503</td>\r\n<td data-start=\"1506\" data-end=\"1530\" data-col-size=\"md\">Marketing Management</td>\r\n</tr>\r\n<tr data-start=\"1531\" data-end=\"1595\">\r\n<td data-start=\"1531\" data-end=\"1541\" data-col-size=\"sm\">EMGN581</td>\r\n<td data-start=\"1541\" data-end=\"1595\" data-col-size=\"md\">Organizational Behaviour &amp; Human Resource Dynamics</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1vujmey\" data-start=\"1597\" data-end=\"1634\">What Students Learn in Semester 1</h3>\r\n<ul data-start=\"1636\" data-end=\"1860\">\r\n<li data-section-id=\"192xamd\" data-start=\"1636\" data-end=\"1668\">Reading financial statements</li>\r\n<li data-section-id=\"1kbck98\" data-start=\"1669\" data-end=\"1712\">Understanding market demand and pricing</li>\r\n<li data-section-id=\"1xnmqfm\" data-start=\"1713\" data-end=\"1766\">Basics of international trade and global business</li>\r\n<li data-section-id=\"417m08\" data-start=\"1767\" data-end=\"1813\">Marketing strategies and consumer behavior</li>\r\n<li data-section-id=\"jchmfw\" data-start=\"1814\" data-end=\"1860\">Employee motivation and workplace management</li>\r\n</ul>\r\n<h3 data-section-id=\"1ehqn4f\" data-start=\"1862\" data-end=\"1878\">Career Value</h3>\r\n<p data-start=\"1880\" data-end=\"1960\">This semester develops the business foundation needed for every management role.</p>\r\n<hr data-start=\"1962\" data-end=\"1965\">\r\n<h2 data-section-id=\"1e7l77z\" data-start=\"1967\" data-end=\"2015\">Semester 2: Functional Management &amp; Analytics</h2>\r\n<p data-start=\"2017\" data-end=\"2125\">The second semester focuses on finance, operations, analytics, legal knowledge, communication, and research.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2127\" data-end=\"2395\">\r\n<thead data-start=\"2127\" data-end=\"2158\">\r\n<tr data-start=\"2127\" data-end=\"2158\">\r\n<th class=\"\" data-start=\"2127\" data-end=\"2142\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2142\" data-end=\"2158\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2169\" data-end=\"2395\">\r\n<tr data-start=\"2169\" data-end=\"2200\">\r\n<td data-start=\"2169\" data-end=\"2179\" data-col-size=\"sm\">EFIN542</td>\r\n<td data-start=\"2179\" data-end=\"2200\" data-col-size=\"sm\">Corporate Finance</td>\r\n</tr>\r\n<tr data-start=\"2201\" data-end=\"2247\">\r\n<td data-start=\"2201\" data-end=\"2211\" data-col-size=\"sm\">EOPR639</td>\r\n<td data-col-size=\"sm\" data-start=\"2211\" data-end=\"2247\">Operations Management &amp; Research</td>\r\n</tr>\r\n<tr data-start=\"2248\" data-end=\"2280\">\r\n<td data-start=\"2248\" data-end=\"2258\" data-col-size=\"sm\">EMGN801</td>\r\n<td data-col-size=\"sm\" data-start=\"2258\" data-end=\"2280\">Business Analytics</td>\r\n</tr>\r\n<tr data-start=\"2281\" data-end=\"2315\">\r\n<td data-start=\"2281\" data-end=\"2291\" data-col-size=\"sm\">EMGN832</td>\r\n<td data-col-size=\"sm\" data-start=\"2291\" data-end=\"2315\">Research Methodology</td>\r\n</tr>\r\n<tr data-start=\"2316\" data-end=\"2355\">\r\n<td data-start=\"2316\" data-end=\"2326\" data-col-size=\"sm\">EBSL605</td>\r\n<td data-start=\"2326\" data-end=\"2355\" data-col-size=\"sm\">Legal Aspects of Business</td>\r\n</tr>\r\n<tr data-start=\"2356\" data-end=\"2395\">\r\n<td data-start=\"2356\" data-end=\"2366\" data-col-size=\"sm\">EPEL537</td>\r\n<td data-start=\"2366\" data-end=\"2395\" data-col-size=\"sm\">Communication for Leaders</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1vujmex\" data-start=\"2397\" data-end=\"2434\">What Students Learn in Semester 2</h3>\r\n<ul data-start=\"2436\" data-end=\"2675\">\r\n<li data-section-id=\"1ytcs33\" data-start=\"2436\" data-end=\"2483\">Budgeting and corporate financial decisions</li>\r\n<li data-section-id=\"9mr0ss\" data-start=\"2484\" data-end=\"2526\">Supply chain and operations efficiency</li>\r\n<li data-section-id=\"87d47a\" data-start=\"2527\" data-end=\"2567\">Data-driven business decision making</li>\r\n<li data-section-id=\"1n43fgj\" data-start=\"2568\" data-end=\"2608\">Research design and business surveys</li>\r\n<li data-section-id=\"1gf4gtt\" data-start=\"2609\" data-end=\"2641\">Business laws and compliance</li>\r\n<li data-section-id=\"nybw43\" data-start=\"2642\" data-end=\"2675\">Leadership communication skills</li>\r\n</ul>\r\n<h3 data-section-id=\"7zaalc\" data-start=\"2677\" data-end=\"2706\">Why This Semester Matters</h3>\r\n<p data-start=\"2708\" data-end=\"2781\">Recruiters highly value analytics + communication + finance combinations.</p>\r\n<hr data-start=\"2783\" data-end=\"2786\">\r\n<h2 data-section-id=\"158e5u8\" data-start=\"2788\" data-end=\"2828\">Semester 3: Specialization &amp; Strategy</h2>\r\n<p data-start=\"2830\" data-end=\"2926\">This semester shifts focus toward electives, entrepreneurship, strategy, and practical exposure.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2928\" data-end=\"3249\">\r\n<thead data-start=\"2928\" data-end=\"2959\">\r\n<tr data-start=\"2928\" data-end=\"2959\">\r\n<th class=\"\" data-start=\"2928\" data-end=\"2943\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2943\" data-end=\"2959\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2970\" data-end=\"3249\">\r\n<tr data-start=\"2970\" data-end=\"3012\">\r\n<td data-start=\"2970\" data-end=\"2978\" data-col-size=\"sm\">DSE-I</td>\r\n<td data-col-size=\"md\" data-start=\"2978\" data-end=\"3012\">Discipline Specific Elective I</td>\r\n</tr>\r\n<tr data-start=\"3013\" data-end=\"3057\">\r\n<td data-start=\"3013\" data-end=\"3022\" data-col-size=\"sm\">DSE-II</td>\r\n<td data-col-size=\"md\" data-start=\"3022\" data-end=\"3057\">Discipline Specific Elective II</td>\r\n</tr>\r\n<tr data-start=\"3058\" data-end=\"3104\">\r\n<td data-start=\"3058\" data-end=\"3068\" data-col-size=\"sm\">DSE-III</td>\r\n<td data-col-size=\"md\" data-start=\"3068\" data-end=\"3104\">Discipline Specific Elective III</td>\r\n</tr>\r\n<tr data-start=\"3105\" data-end=\"3154\">\r\n<td data-start=\"3105\" data-end=\"3115\" data-col-size=\"sm\">EMGN571</td>\r\n<td data-start=\"3115\" data-end=\"3154\" data-col-size=\"md\">Corporate Strategy Entrepreneurship</td>\r\n</tr>\r\n<tr data-start=\"3155\" data-end=\"3184\">\r\n<td data-start=\"3155\" data-end=\"3162\" data-col-size=\"sm\">GE-I</td>\r\n<td data-col-size=\"md\" data-start=\"3162\" data-end=\"3184\">Generic Elective I</td>\r\n</tr>\r\n<tr data-start=\"3185\" data-end=\"3249\">\r\n<td data-start=\"3185\" data-end=\"3195\" data-col-size=\"sm\">EMGN583</td>\r\n<td data-col-size=\"md\" data-start=\"3195\" data-end=\"3249\">Seminar on Summer Training / Course from GE Basket</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1vujmew\" data-start=\"3251\" data-end=\"3288\">What Students Learn in Semester 3</h3>\r\n<ul data-start=\"3290\" data-end=\"3474\">\r\n<li data-section-id=\"1rn7uie\" data-start=\"3290\" data-end=\"3326\">Advanced specialization subjects</li>\r\n<li data-section-id=\"1uu6l5f\" data-start=\"3327\" data-end=\"3371\">Competitive strategy and growth planning</li>\r\n<li data-section-id=\"ls7ajp\" data-start=\"3372\" data-end=\"3400\">Entrepreneurship mindset</li>\r\n<li data-section-id=\"pli1f2\" data-start=\"3401\" data-end=\"3436\">Internship learning application</li>\r\n<li data-section-id=\"8lpo49\" data-start=\"3437\" data-end=\"3474\">Cross-domain business understanding</li>\r\n</ul>\r\n<h3 data-section-id=\"lgtwr4\" data-start=\"3476\" data-end=\"3494\">Important Note</h3>\r\n<p data-start=\"3496\" data-end=\"3566\">Elective choices in this semester can strongly shape career direction.</p>\r\n<hr data-start=\"3568\" data-end=\"3571\">\r\n<h2 data-section-id=\"6qmfb2\" data-start=\"3573\" data-end=\"3617\">Semester 4: Advanced Electives &amp; Capstone</h2>\r\n<p data-start=\"3619\" data-end=\"3702\">The final semester focuses on advanced specialization subjects and a final project.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3704\" data-end=\"3941\">\r\n<thead data-start=\"3704\" data-end=\"3735\">\r\n<tr data-start=\"3704\" data-end=\"3735\">\r\n<th class=\"\" data-start=\"3704\" data-end=\"3719\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3719\" data-end=\"3735\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3746\" data-end=\"3941\">\r\n<tr data-start=\"3746\" data-end=\"3790\">\r\n<td data-start=\"3746\" data-end=\"3755\" data-col-size=\"sm\">DSE-IV</td>\r\n<td data-col-size=\"sm\" data-start=\"3755\" data-end=\"3790\">Discipline Specific Elective IV</td>\r\n</tr>\r\n<tr data-start=\"3791\" data-end=\"3833\">\r\n<td data-start=\"3791\" data-end=\"3799\" data-col-size=\"sm\">DSE-V</td>\r\n<td data-col-size=\"sm\" data-start=\"3799\" data-end=\"3833\">Discipline Specific Elective V</td>\r\n</tr>\r\n<tr data-start=\"3834\" data-end=\"3878\">\r\n<td data-start=\"3834\" data-end=\"3843\" data-col-size=\"sm\">DSE-VI</td>\r\n<td data-col-size=\"sm\" data-start=\"3843\" data-end=\"3878\">Discipline Specific Elective VI</td>\r\n</tr>\r\n<tr data-start=\"3879\" data-end=\"3910\">\r\n<td data-start=\"3879\" data-end=\"3887\" data-col-size=\"sm\">GE-II</td>\r\n<td data-col-size=\"sm\" data-start=\"3887\" data-end=\"3910\">Generic Elective II</td>\r\n</tr>\r\n<tr data-start=\"3911\" data-end=\"3941\">\r\n<td data-start=\"3911\" data-end=\"3921\" data-col-size=\"sm\">EMGN696</td>\r\n<td data-start=\"3921\" data-end=\"3941\" data-col-size=\"sm\">Capstone Project</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1vujmf3\" data-start=\"3943\" data-end=\"3980\">What Students Learn in Semester 4</h3>\r\n<ul data-start=\"3982\" data-end=\"4134\">\r\n<li data-section-id=\"1fp9pev\" data-start=\"3982\" data-end=\"4011\">Advanced domain expertise</li>\r\n<li data-section-id=\"1a0vti7\" data-start=\"4012\" data-end=\"4040\">Industry problem solving</li>\r\n<li data-section-id=\"gbq9a\" data-start=\"4041\" data-end=\"4063\">Project management</li>\r\n<li data-section-id=\"zmakkh\" data-start=\"4064\" data-end=\"4099\">Real-world business application</li>\r\n<li data-section-id=\"4j5n2m\" data-start=\"4100\" data-end=\"4134\">Research and presentation skills</li>\r\n</ul>\r\n<h3 data-section-id=\"285a8o\" data-start=\"4136\" data-end=\"4173\">Why Capstone Project is Important</h3>\r\n<p data-start=\"4175\" data-end=\"4276\">It helps students apply MBA knowledge to real business challenges and strengthens placement profiles.</p>\r\n<hr data-start=\"4278\" data-end=\"4281\">\r\n<h1 data-section-id=\"sc4hxs\" data-start=\"4283\" data-end=\"4321\">Popular MBA Specialization Electives</h1>\r\n<p data-start=\"4323\" data-end=\"4380\">Depending on university offerings, electives may include:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"4382\" data-end=\"4716\">\r\n<thead data-start=\"4382\" data-end=\"4415\">\r\n<tr data-start=\"4382\" data-end=\"4415\">\r\n<th class=\"\" data-start=\"4382\" data-end=\"4399\" data-col-size=\"sm\">Specialization</th>\r\n<th class=\"\" data-start=\"4399\" data-end=\"4415\" data-col-size=\"sm\">Career Scope</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"4426\" data-end=\"4716\">\r\n<tr data-start=\"4426\" data-end=\"4474\">\r\n<td data-start=\"4426\" data-end=\"4436\" data-col-size=\"sm\">Finance</td>\r\n<td data-start=\"4436\" data-end=\"4474\" data-col-size=\"sm\">Banking, investment, analyst roles</td>\r\n</tr>\r\n<tr data-start=\"4475\" data-end=\"4522\">\r\n<td data-start=\"4475\" data-end=\"4487\" data-col-size=\"sm\">Marketing</td>\r\n<td data-start=\"4487\" data-end=\"4522\" data-col-size=\"sm\">Brand, digital marketing, sales</td>\r\n</tr>\r\n<tr data-start=\"4523\" data-end=\"4568\">\r\n<td data-start=\"4523\" data-end=\"4528\" data-col-size=\"sm\">HR</td>\r\n<td data-start=\"4528\" data-end=\"4568\" data-col-size=\"sm\">Recruitment, HRBP, talent management</td>\r\n</tr>\r\n<tr data-start=\"4569\" data-end=\"4609\">\r\n<td data-start=\"4569\" data-end=\"4582\" data-col-size=\"sm\">Operations</td>\r\n<td data-col-size=\"sm\" data-start=\"4582\" data-end=\"4609\">Supply chain, logistics</td>\r\n</tr>\r\n<tr data-start=\"4610\" data-end=\"4661\">\r\n<td data-start=\"4610\" data-end=\"4631\" data-col-size=\"sm\">Business Analytics</td>\r\n<td data-col-size=\"sm\" data-start=\"4631\" data-end=\"4661\">Data, consulting, strategy</td>\r\n</tr>\r\n<tr data-start=\"4662\" data-end=\"4716\">\r\n<td data-start=\"4662\" data-end=\"4687\" data-col-size=\"sm\">International Business</td>\r\n<td data-col-size=\"sm\" data-start=\"4687\" data-end=\"4716\">Export, global operations</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', NULL, '<p data-start=\"401\" data-end=\"655\">Placement support is one of the most important factors students consider before choosing an online degree program. A recognized university with strong career services can significantly improve employability, confidence, and access to job opportunities.</p>\r\n<p data-start=\"657\" data-end=\"993\"><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Lovely Professional University</span></span> Online offers placement support services designed to strengthen students&rsquo; industry readiness, improve professional skills, and connect learners with suitable career opportunities. The objective is not only academic learning, but also helping students become job-ready in today&rsquo;s competitive market.</p>\r\n<p data-start=\"995\" data-end=\"1145\">This guide explains LPU Online placement support, career services, placement drives, student benefits, ROI value, and strategies to maximize outcomes.</p>\r\n<hr data-start=\"1147\" data-end=\"1150\">\r\n<h1 data-section-id=\"15xyz8p\" data-start=\"1152\" data-end=\"1191\">What is LPU Online Placement Support?</h1>\r\n<p data-start=\"1193\" data-end=\"1406\">LPU Online placement support focuses on helping students prepare for employment through structured career assistance. These services are designed to align students&rsquo; capabilities with current industry requirements.</p>\r\n<p data-start=\"1408\" data-end=\"1478\">The support system generally aims to help students in three key areas:</p>\r\n<ul data-start=\"1480\" data-end=\"1549\">\r\n<li data-section-id=\"1raiwkh\" data-start=\"1480\" data-end=\"1501\">Skill enhancement</li>\r\n<li data-section-id=\"15xbx1d\" data-start=\"1502\" data-end=\"1522\">Career awareness</li>\r\n<li data-section-id=\"h7b6p3\" data-start=\"1523\" data-end=\"1549\">Employment opportunities</li>\r\n</ul>\r\n<p data-start=\"1551\" data-end=\"1655\">This means students are encouraged to build additional professional skills beyond their degree syllabus.</p>\r\n<hr data-start=\"1657\" data-end=\"1660\">\r\n<h1 data-section-id=\"1g2rnnj\" data-start=\"1662\" data-end=\"1705\">Key LPU Online Placement Support Services</h1>\r\n<h2 data-section-id=\"18k74lo\" data-start=\"1707\" data-end=\"1729\">1. Placement Drives</h2>\r\n<p data-start=\"1731\" data-end=\"1850\">LPU Online conducts placement drives where students get opportunities to interact with recruiters and hiring companies.</p>\r\n<h3 data-section-id=\"1iaul7c\" data-start=\"1852\" data-end=\"1865\">Benefits:</h3>\r\n<ul data-start=\"1867\" data-end=\"1995\">\r\n<li data-section-id=\"1erip0d\" data-start=\"1867\" data-end=\"1895\">Direct job opportunities</li>\r\n<li data-section-id=\"wx8y0i\" data-start=\"1896\" data-end=\"1918\">Interview exposure</li>\r\n<li data-section-id=\"1aakc4x\" data-start=\"1919\" data-end=\"1949\">Real recruiter interaction</li>\r\n<li data-section-id=\"xufam5\" data-start=\"1950\" data-end=\"1975\">Faster hiring chances</li>\r\n<li data-section-id=\"13vh2o6\" data-start=\"1976\" data-end=\"1995\">Better networking</li>\r\n</ul>\r\n<hr data-start=\"1997\" data-end=\"2000\">\r\n<h2 data-section-id=\"zmp5s0\" data-start=\"2002\" data-end=\"2035\">2. Career Guidance &amp; Awareness</h2>\r\n<p data-start=\"2037\" data-end=\"2141\">Many students complete degrees without clear career direction. Career support helps learners understand:</p>\r\n<ul data-start=\"2143\" data-end=\"2262\">\r\n<li data-section-id=\"sscy54\" data-start=\"2143\" data-end=\"2172\">Current job market trends</li>\r\n<li data-section-id=\"gp4qbn\" data-start=\"2173\" data-end=\"2196\">High-demand sectors</li>\r\n<li data-section-id=\"r3g8ko\" data-start=\"2197\" data-end=\"2219\">Resume positioning</li>\r\n<li data-section-id=\"15vwjfp\" data-start=\"2220\" data-end=\"2240\">Role suitability</li>\r\n<li data-section-id=\"kgv2nn\" data-start=\"2241\" data-end=\"2262\">Salary growth paths</li>\r\n</ul>\r\n<hr data-start=\"2264\" data-end=\"2267\">\r\n<h2 data-section-id=\"19q1se5\" data-start=\"2269\" data-end=\"2301\">3. Skill Development Programs</h2>\r\n<p data-start=\"2303\" data-end=\"2419\">Modern recruiters hire for skills, not only degrees. Students are motivated to gain additional capabilities such as:</p>\r\n<ul data-start=\"2421\" data-end=\"2565\">\r\n<li data-section-id=\"1mfo8p6\" data-start=\"2421\" data-end=\"2445\">Communication skills</li>\r\n<li data-section-id=\"100ww9o\" data-start=\"2446\" data-end=\"2469\">Presentation skills</li>\r\n<li data-section-id=\"1ayu3bh\" data-start=\"2470\" data-end=\"2497\">Excel / analytics tools</li>\r\n<li data-section-id=\"1nzdt2d\" data-start=\"2498\" data-end=\"2522\">Interview confidence</li>\r\n<li data-section-id=\"1ei5gii\" data-start=\"2523\" data-end=\"2547\">Leadership qualities</li>\r\n<li data-section-id=\"11mjt2d\" data-start=\"2548\" data-end=\"2565\">Problem solving</li>\r\n</ul>\r\n<hr data-start=\"2567\" data-end=\"2570\">\r\n<h2 data-section-id=\"1anskog\" data-start=\"2572\" data-end=\"2608\">4. Resume &amp; Interview Preparation</h2>\r\n<p data-start=\"2610\" data-end=\"2717\">Placement success often depends on professional presentation. Students may benefit from support related to:</p>\r\n<ul data-start=\"2719\" data-end=\"2837\">\r\n<li data-section-id=\"1hew0fb\" data-start=\"2719\" data-end=\"2738\">Resume building</li>\r\n<li data-section-id=\"hg8gpk\" data-start=\"2739\" data-end=\"2758\">Mock interviews</li>\r\n<li data-section-id=\"d9c9is\" data-start=\"2759\" data-end=\"2784\">HR interview handling</li>\r\n<li data-section-id=\"1f1k17y\" data-start=\"2785\" data-end=\"2817\">Group discussion preparation</li>\r\n<li data-section-id=\"i9rhcb\" data-start=\"2818\" data-end=\"2837\">Personal branding</li>\r\n</ul>\r\n<hr data-start=\"2839\" data-end=\"2842\">\r\n<h1 data-section-id=\"1i7871o\" data-start=\"2844\" data-end=\"2895\">Why Placement Support Matters in Online Education</h1>\r\n<p data-start=\"2897\" data-end=\"3088\">Many students worry whether online learners receive career opportunities. Strong placement support can reduce this concern by helping students compete effectively with traditional candidates.</p>\r\n<h3 data-section-id=\"z2ymsf\" data-start=\"3090\" data-end=\"3111\">Major Advantages:</h3>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3113\" data-end=\"3385\">\r\n<thead data-start=\"3113\" data-end=\"3141\">\r\n<tr data-start=\"3113\" data-end=\"3141\">\r\n<th class=\"\" data-start=\"3113\" data-end=\"3123\" data-col-size=\"sm\">Benefit</th>\r\n<th class=\"\" data-start=\"3123\" data-end=\"3141\" data-col-size=\"sm\">Why It Matters</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3152\" data-end=\"3385\">\r\n<tr data-start=\"3152\" data-end=\"3194\">\r\n<td data-start=\"3152\" data-end=\"3165\" data-col-size=\"sm\">Job Access</td>\r\n<td data-col-size=\"sm\" data-start=\"3165\" data-end=\"3194\">More hiring opportunities</td>\r\n</tr>\r\n<tr data-start=\"3195\" data-end=\"3244\">\r\n<td data-start=\"3195\" data-end=\"3213\" data-col-size=\"sm\">Skill Readiness</td>\r\n<td data-col-size=\"sm\" data-start=\"3213\" data-end=\"3244\">Better recruiter confidence</td>\r\n</tr>\r\n<tr data-start=\"3245\" data-end=\"3288\">\r\n<td data-start=\"3245\" data-end=\"3264\" data-col-size=\"sm\">Career Direction</td>\r\n<td data-col-size=\"sm\" data-start=\"3264\" data-end=\"3288\">Clear role targeting</td>\r\n</tr>\r\n<tr data-start=\"3289\" data-end=\"3325\">\r\n<td data-start=\"3289\" data-end=\"3302\" data-col-size=\"sm\">Networking</td>\r\n<td data-col-size=\"sm\" data-start=\"3302\" data-end=\"3325\">Company interaction</td>\r\n</tr>\r\n<tr data-start=\"3326\" data-end=\"3385\">\r\n<td data-start=\"3326\" data-end=\"3352\" data-col-size=\"sm\">Salary Growth Potential</td>\r\n<td data-col-size=\"sm\" data-start=\"3352\" data-end=\"3385\">Better starting opportunities</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"3387\" data-end=\"3390\">\r\n<h1 data-section-id=\"27sqig\" data-start=\"3392\" data-end=\"3420\">LPU Online ROI Perspective</h1>\r\n<p data-start=\"3422\" data-end=\"3523\">When evaluating an online degree, students should consider Return on Investment (ROI), not just fees.</p>\r\n<p data-start=\"3525\" data-end=\"3545\">Good ROI comes from:</p>\r\n<ul data-start=\"3547\" data-end=\"3697\">\r\n<li data-section-id=\"sg2xn\" data-start=\"3547\" data-end=\"3574\">Affordable program fees</li>\r\n<li data-section-id=\"2katx8\" data-start=\"3575\" data-end=\"3612\">Recognized university brand value</li>\r\n<li data-section-id=\"4ebpce\" data-start=\"3613\" data-end=\"3634\">Placement support</li>\r\n<li data-section-id=\"1exvq2l\" data-start=\"3635\" data-end=\"3671\">Career advancement opportunities</li>\r\n<li data-section-id=\"12vxdtw\" data-start=\"3672\" data-end=\"3697\">Long-term salary growth</li>\r\n</ul>\r\n<p data-start=\"3699\" data-end=\"3802\">If placement support converts into real opportunities, the overall course value improves significantly.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 200000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(231, 69, 'd67d3d73-4a79-4175-89f0-c61979138bac', '956f52ba-dcf0-4224-9a30-f9f785980fe3', 75, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 02:37:06', '2026-06-16 06:04:18', '<p data-start=\"352\" data-end=\"605\">Taking admission into an MCA program is now simple, fast, and student-friendly through the online admission process. Students can complete registration, submit documents, pay fees, and receive final enrollment confirmation without visiting the campus.</p>\r\n<p data-start=\"607\" data-end=\"801\">For students planning careers in software development, data analytics, cloud computing, cybersecurity, and IT management, understanding the MCA admission process helps avoid delays and mistakes.</p>\r\n<p data-start=\"803\" data-end=\"936\">This guide explains each step of MCA admission, required documents, expert strategies, hidden mistakes, and tips for faster approval.</p>\r\n<hr data-start=\"938\" data-end=\"941\">\r\n<h1 data-section-id=\"1lxrh7s\" data-start=\"943\" data-end=\"975\">MCA Admission Process Overview</h1>\r\n<p data-start=\"977\" data-end=\"1037\">The MCA admission process usually includes four main stages:</p>\r\n<ol data-start=\"1039\" data-end=\"1169\">\r\n<li data-section-id=\"nl6le3\" data-start=\"1039\" data-end=\"1056\">Registration</li>\r\n<li data-section-id=\"ylnmm2\" data-start=\"1057\" data-end=\"1085\">Online Application Form</li>\r\n<li data-section-id=\"101zuxd\" data-start=\"1086\" data-end=\"1126\">Document Verification by University</li>\r\n<li data-section-id=\"19bjzt6\" data-start=\"1127\" data-end=\"1169\">Student Registration and LMS Activation</li>\r\n</ol>\r\n<p data-start=\"1171\" data-end=\"1233\">Each stage should be completed carefully for smooth admission.</p>\r\n<hr data-start=\"1235\" data-end=\"1238\">\r\n<h1 data-section-id=\"52akem\" data-start=\"1240\" data-end=\"1262\">Step 1: Registration</h1>\r\n<p data-start=\"1264\" data-end=\"1395\">The first step is creating an account on the official admission portal. Students need to sign up by entering basic details such as:</p>\r\n<ul data-start=\"1397\" data-end=\"1484\">\r\n<li data-section-id=\"u7na1o\" data-start=\"1397\" data-end=\"1410\">Full Name</li>\r\n<li data-section-id=\"1dep5uz\" data-start=\"1411\" data-end=\"1428\">Mobile Number</li>\r\n<li data-section-id=\"36fvl5\" data-start=\"1429\" data-end=\"1441\">Email ID</li>\r\n<li data-section-id=\"4ligt3\" data-start=\"1442\" data-end=\"1458\">State / City</li>\r\n<li data-section-id=\"1lslmjb\" data-start=\"1459\" data-end=\"1484\">Preferred Program (MCA)</li>\r\n</ul>\r\n<p data-start=\"1486\" data-end=\"1579\">After successful sign-up, pay the initial registration fee to continue the admission process.</p>\r\n<h3 data-section-id=\"1my1m11\" data-start=\"1581\" data-end=\"1595\">Expert Tip</h3>\r\n<p data-start=\"1597\" data-end=\"1712\">Use an active mobile number and email ID because all important updates, receipts, and login details are sent there.</p>\r\n<h3 data-section-id=\"10clvjd\" data-start=\"1714\" data-end=\"1741\">Common Mistake to Avoid</h3>\r\n<p data-start=\"1743\" data-end=\"1815\">Entering incorrect contact details can delay communication and approval.</p>\r\n<hr data-start=\"1817\" data-end=\"1820\">\r\n<h1 data-section-id=\"1vjt9r3\" data-start=\"1822\" data-end=\"1855\">Step 2: Online Application Form</h1>\r\n<p data-start=\"1857\" data-end=\"1963\">After registration, log in and complete the online MCA application form. Students usually need to provide:</p>\r\n<ul data-start=\"1965\" data-end=\"2116\">\r\n<li data-section-id=\"1fxsuaa\" data-start=\"1965\" data-end=\"1985\">Personal details</li>\r\n<li data-section-id=\"itkbd9\" data-start=\"1986\" data-end=\"2016\">Educational qualifications</li>\r\n<li data-section-id=\"19381gy\" data-start=\"2017\" data-end=\"2040\">Address information</li>\r\n<li data-section-id=\"i1lfbp\" data-start=\"2041\" data-end=\"2061\">Course selection</li>\r\n<li data-section-id=\"yxjbvg\" data-start=\"2062\" data-end=\"2082\">Identity details</li>\r\n<li data-section-id=\"1e5lq9g\" data-start=\"2083\" data-end=\"2116\">Work experience (if applicable)</li>\r\n</ul>\r\n<p data-start=\"2118\" data-end=\"2196\">Once the form is completed, pay the program fee and upload required documents.</p>\r\n<hr data-start=\"2198\" data-end=\"2201\">\r\n<h1 data-section-id=\"ylmyd2\" data-start=\"2203\" data-end=\"2250\">Documents Commonly Required for MCA Admission</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2252\" data-end=\"2602\">\r\n<thead data-start=\"2252\" data-end=\"2274\">\r\n<tr data-start=\"2252\" data-end=\"2274\">\r\n<th class=\"\" data-start=\"2252\" data-end=\"2263\" data-col-size=\"sm\">Document</th>\r\n<th class=\"\" data-start=\"2263\" data-end=\"2274\" data-col-size=\"sm\">Purpose</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2285\" data-end=\"2602\">\r\n<tr data-start=\"2285\" data-end=\"2336\">\r\n<td data-start=\"2285\" data-end=\"2306\" data-col-size=\"sm\">Class 10 Marksheet</td>\r\n<td data-col-size=\"sm\" data-start=\"2306\" data-end=\"2336\">Identity / academic record</td>\r\n</tr>\r\n<tr data-start=\"2337\" data-end=\"2382\">\r\n<td data-start=\"2337\" data-end=\"2358\" data-col-size=\"sm\">Class 12 Marksheet</td>\r\n<td data-col-size=\"sm\" data-start=\"2358\" data-end=\"2382\">Qualification record</td>\r\n</tr>\r\n<tr data-start=\"2383\" data-end=\"2439\">\r\n<td data-start=\"2383\" data-end=\"2407\" data-col-size=\"sm\">Graduation Marksheets</td>\r\n<td data-col-size=\"sm\" data-start=\"2407\" data-end=\"2439\">MCA eligibility verification</td>\r\n</tr>\r\n<tr data-start=\"2440\" data-end=\"2490\">\r\n<td data-start=\"2440\" data-end=\"2461\" data-col-size=\"sm\">Degree Certificate</td>\r\n<td data-col-size=\"sm\" data-start=\"2461\" data-end=\"2490\">Final qualification proof</td>\r\n</tr>\r\n<tr data-start=\"2491\" data-end=\"2527\">\r\n<td data-start=\"2491\" data-end=\"2502\" data-col-size=\"sm\">ID Proof</td>\r\n<td data-col-size=\"sm\" data-start=\"2502\" data-end=\"2527\">Identity confirmation</td>\r\n</tr>\r\n<tr data-start=\"2528\" data-end=\"2569\">\r\n<td data-start=\"2528\" data-end=\"2550\" data-col-size=\"sm\">Passport Size Photo</td>\r\n<td data-col-size=\"sm\" data-start=\"2550\" data-end=\"2569\">Student profile</td>\r\n</tr>\r\n<tr data-start=\"2570\" data-end=\"2602\">\r\n<td data-start=\"2570\" data-end=\"2582\" data-col-size=\"sm\">Signature</td>\r\n<td data-col-size=\"sm\" data-start=\"2582\" data-end=\"2602\">Official records</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"jt31xg\" data-start=\"2604\" data-end=\"2622\">Smart Strategy</h3>\r\n<p data-start=\"2624\" data-end=\"2698\">Keep scanned copies ready in PDF or image format before starting the form.</p>\r\n<hr data-start=\"2700\" data-end=\"2703\">\r\n<h1 data-section-id=\"ln8rck\" data-start=\"2705\" data-end=\"2750\">Step 3: Document Verification by University</h1>\r\n<p data-start=\"2752\" data-end=\"2842\">After submission, the university verifies your application details and uploaded documents.</p>\r\n<h3 data-section-id=\"131lww1\" data-start=\"2844\" data-end=\"2878\">Verification Usually Includes:</h3>\r\n<ul data-start=\"2880\" data-end=\"3002\">\r\n<li data-section-id=\"v9ifvn\" data-start=\"2880\" data-end=\"2901\">Eligibility check</li>\r\n<li data-section-id=\"pl172g\" data-start=\"2902\" data-end=\"2922\">Marksheet review</li>\r\n<li data-section-id=\"27zx9a\" data-start=\"2923\" data-end=\"2948\">Name and DOB matching</li>\r\n<li data-section-id=\"1qa0omz\" data-start=\"2949\" data-end=\"2977\">Fee payment confirmation</li>\r\n<li data-section-id=\"1nwe261\" data-start=\"2978\" data-end=\"3002\">Document clarity check</li>\r\n</ul>\r\n<p data-start=\"3004\" data-end=\"3094\">If corrections are needed, updates may be requested through email or portal notifications.</p>\r\n<h3 data-section-id=\"1bl8nat\" data-start=\"3096\" data-end=\"3124\">Hidden Reason for Delays</h3>\r\n<p data-start=\"3126\" data-end=\"3152\">Most delays happen due to:</p>\r\n<ul data-start=\"3154\" data-end=\"3245\">\r\n<li data-section-id=\"1ax6vdu\" data-start=\"3154\" data-end=\"3173\">Blurred uploads</li>\r\n<li data-section-id=\"1yndzvz\" data-start=\"3174\" data-end=\"3199\">Incomplete marksheets</li>\r\n<li data-section-id=\"2rvepl\" data-start=\"3200\" data-end=\"3220\">Mismatched names</li>\r\n<li data-section-id=\"1p35kxi\" data-start=\"3221\" data-end=\"3245\">Wrong course selection</li>\r\n</ul>\r\n<hr data-start=\"3247\" data-end=\"3250\">\r\n<h1 data-section-id=\"1fuepgv\" data-start=\"3252\" data-end=\"3301\">Step 4: Student Registration and LMS Activation</h1>\r\n<p data-start=\"3303\" data-end=\"3415\">Once documents are approved, final enrollment is processed. Students then receive LMS credentials through email.</p>\r\n<h3 data-section-id=\"1k7bjc6\" data-start=\"3417\" data-end=\"3446\">Students Usually Receive:</h3>\r\n<ul data-start=\"3448\" data-end=\"3541\">\r\n<li data-section-id=\"el5erz\" data-start=\"3448\" data-end=\"3469\">Enrollment Number</li>\r\n<li data-section-id=\"f73c3w\" data-start=\"3470\" data-end=\"3484\">Student ID</li>\r\n<li data-section-id=\"17cwsxh\" data-start=\"3485\" data-end=\"3512\">LMS Username &amp; Password</li>\r\n<li data-section-id=\"1w9uwii\" data-start=\"3513\" data-end=\"3541\">Course access instructions</li>\r\n</ul>\r\n<h3 data-section-id=\"uttsmo\" data-start=\"3543\" data-end=\"3559\">LMS Benefits</h3>\r\n<p data-start=\"3561\" data-end=\"3614\">The Learning Management System helps students access:</p>\r\n<ul data-start=\"3616\" data-end=\"3717\">\r\n<li data-section-id=\"8imkcm\" data-start=\"3616\" data-end=\"3632\">Live classes</li>\r\n<li data-section-id=\"1d3fguj\" data-start=\"3633\" data-end=\"3654\">Recorded lectures</li>\r\n<li data-section-id=\"12a9mov\" data-start=\"3655\" data-end=\"3674\">Study materials</li>\r\n<li data-section-id=\"1f7qwlk\" data-start=\"3675\" data-end=\"3690\">Assignments</li>\r\n<li data-section-id=\"cq9jk1\" data-start=\"3691\" data-end=\"3702\">Notices</li>\r\n<li data-section-id=\"1ick1y3\" data-start=\"3703\" data-end=\"3717\">Exam updates</li>\r\n</ul>', 1, '<p data-start=\"367\" data-end=\"732\">MCA (Master of Computer Applications) is one of the most preferred postgraduate programs for students aiming for careers in software development, IT, cloud computing, data analytics, cybersecurity, and digital technologies. Before applying, students should clearly understand the latest MCA eligibility criteria, mathematics requirements, and bridge course rules.</p>\r\n<p data-start=\"734\" data-end=\"1019\">Many students assume only BCA or B.Tech graduates can apply, but MCA admission is often open to students from multiple academic backgrounds such as commerce, arts, science, and vocational streams. This creates strong career transition opportunities for non-technical graduates as well.</p>\r\n<p data-start=\"1021\" data-end=\"1185\">This guide explains complete MCA eligibility, accepted qualifications, mathematics rules, bridge courses, who should apply, common mistakes, and admission strategy.</p>\r\n<hr data-start=\"1187\" data-end=\"1190\">\r\n<h1 data-section-id=\"16py42c\" data-start=\"1192\" data-end=\"1227\">MCA Eligibility Criteria Overview</h1>\r\n<p data-start=\"1229\" data-end=\"1284\">Candidates are eligible for MCA admission if they have:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1286\" data-end=\"1562\">\r\n<thead data-start=\"1286\" data-end=\"1322\">\r\n<tr data-start=\"1286\" data-end=\"1322\">\r\n<th class=\"\" data-start=\"1286\" data-end=\"1300\" data-col-size=\"md\">Requirement</th>\r\n<th class=\"\" data-start=\"1300\" data-end=\"1322\" data-col-size=\"sm\">Eligibility Status</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1333\" data-end=\"1562\">\r\n<tr data-start=\"1333\" data-end=\"1390\">\r\n<td data-start=\"1333\" data-end=\"1378\" data-col-size=\"md\">Bachelor&rsquo;s degree in recognized discipline</td>\r\n<td data-col-size=\"sm\" data-start=\"1378\" data-end=\"1390\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1391\" data-end=\"1451\">\r\n<td data-start=\"1391\" data-end=\"1439\" data-col-size=\"md\">Mathematics at 10+2 level or Graduation level</td>\r\n<td data-col-size=\"sm\" data-start=\"1439\" data-end=\"1451\">Required</td>\r\n</tr>\r\n<tr data-start=\"1452\" data-end=\"1505\">\r\n<td data-start=\"1452\" data-end=\"1478\" data-col-size=\"md\">Non-computer background</td>\r\n<td data-col-size=\"sm\" data-start=\"1478\" data-end=\"1505\">Bridge course may apply</td>\r\n</tr>\r\n<tr data-start=\"1506\" data-end=\"1562\">\r\n<td data-start=\"1506\" data-end=\"1535\" data-col-size=\"md\">Non-mathematics background</td>\r\n<td data-col-size=\"sm\" data-start=\"1535\" data-end=\"1562\">Bridge course may apply</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1564\" data-end=\"1567\">\r\n<h1 data-section-id=\"ppxcs1\" data-start=\"1569\" data-end=\"1602\">Accepted Qualifications for MCA</h1>\r\n<p data-start=\"1604\" data-end=\"1713\">Candidates with a bachelor&rsquo;s degree in any of the following or equivalent qualifications can generally apply:</p>\r\n<ul data-start=\"1715\" data-end=\"1818\">\r\n<li data-section-id=\"1uaihxr\" data-start=\"1715\" data-end=\"1723\">B.E.</li>\r\n<li data-section-id=\"y69ov2\" data-start=\"1724\" data-end=\"1734\">B.Tech</li>\r\n<li data-section-id=\"1ub0l3o\" data-start=\"1735\" data-end=\"1743\">B.Sc</li>\r\n<li data-section-id=\"1kuwkdh\" data-start=\"1744\" data-end=\"1753\">B.Com</li>\r\n<li data-section-id=\"1uale4r\" data-start=\"1754\" data-end=\"1762\">B.A.</li>\r\n<li data-section-id=\"1l4c7b2\" data-start=\"1763\" data-end=\"1772\">B.Voc</li>\r\n<li data-section-id=\"16yrbgo\" data-start=\"1773\" data-end=\"1780\">BCA</li>\r\n<li data-section-id=\"1bacwl9\" data-start=\"1781\" data-end=\"1818\">Other recognized bachelor&rsquo;s degrees</li>\r\n</ul>\r\n<h3 data-section-id=\"123vz07\" data-start=\"1820\" data-end=\"1835\">Key Insight</h3>\r\n<p data-start=\"1837\" data-end=\"1948\">This broad eligibility makes MCA a strong option for students who want to enter the IT sector after graduation.</p>\r\n<hr data-start=\"1950\" data-end=\"1953\">\r\n<h1 data-section-id=\"y2b515\" data-start=\"1955\" data-end=\"1988\">Mathematics Requirement for MCA</h1>\r\n<p data-start=\"1990\" data-end=\"2043\">Applicants should have studied Mathematics at either:</p>\r\n<ul data-start=\"2045\" data-end=\"2086\">\r\n<li data-section-id=\"axr4nr\" data-start=\"2045\" data-end=\"2067\">10+2 level, <strong data-start=\"2059\" data-end=\"2065\">or</strong></li>\r\n<li data-section-id=\"1u6fubq\" data-start=\"2068\" data-end=\"2086\">Graduation level</li>\r\n</ul>\r\n<p data-start=\"2088\" data-end=\"2138\">Accepted mathematics-related subjects may include:</p>\r\n<ul data-start=\"2140\" data-end=\"2226\">\r\n<li data-section-id=\"1pkuajg\" data-start=\"2140\" data-end=\"2155\">Mathematics</li>\r\n<li data-section-id=\"1yq9p59\" data-start=\"2156\" data-end=\"2170\">Statistics</li>\r\n<li data-section-id=\"11rpgz2\" data-start=\"2171\" data-end=\"2203\">Quantitative Techniques (QT)</li>\r\n<li data-section-id=\"13y29ne\" data-start=\"2204\" data-end=\"2226\">Business Mathematics</li>\r\n</ul>\r\n<h3 data-section-id=\"1ohko87\" data-start=\"2228\" data-end=\"2259\">Why Mathematics is Required</h3>\r\n<p data-start=\"2261\" data-end=\"2433\">MCA includes programming logic, algorithms, databases, analytics, and computational thinking. Basic mathematical understanding helps students perform better in these areas.</p>\r\n<hr data-start=\"2435\" data-end=\"2438\">\r\n<h1 data-section-id=\"1gchoom\" data-start=\"2440\" data-end=\"2512\">Bridge Courses for Non-Mathematics or Non-Computer Background Students</h1>\r\n<p data-start=\"2514\" data-end=\"2629\">Students without mathematics or computer background may still be considered eligible, but bridge courses can apply.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2631\" data-end=\"2873\">\r\n<thead data-start=\"2631\" data-end=\"2681\">\r\n<tr data-start=\"2631\" data-end=\"2681\">\r\n<th class=\"\" data-start=\"2631\" data-end=\"2652\" data-col-size=\"md\">Student Background</th>\r\n<th class=\"\" data-start=\"2652\" data-end=\"2681\" data-col-size=\"sm\">Bridge Course Requirement</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2692\" data-end=\"2873\">\r\n<tr data-start=\"2692\" data-end=\"2744\">\r\n<td data-start=\"2692\" data-end=\"2720\" data-col-size=\"md\">No Mathematics background</td>\r\n<td data-col-size=\"sm\" data-start=\"2720\" data-end=\"2744\">1 Mathematics course</td>\r\n</tr>\r\n<tr data-start=\"2745\" data-end=\"2791\">\r\n<td data-start=\"2745\" data-end=\"2770\" data-col-size=\"md\">No Computer background</td>\r\n<td data-col-size=\"sm\" data-start=\"2770\" data-end=\"2791\">1 Computer course</td>\r\n</tr>\r\n<tr data-start=\"2792\" data-end=\"2873\">\r\n<td data-start=\"2792\" data-end=\"2836\" data-col-size=\"md\">No Mathematics and No Computer background</td>\r\n<td data-col-size=\"sm\" data-start=\"2836\" data-end=\"2873\">1 Mathematics + 1 Computer course</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1tynepg\" data-start=\"2875\" data-end=\"2903\">What Are Bridge Courses?</h3>\r\n<p data-start=\"2905\" data-end=\"3034\">Bridge courses are foundation modules designed to help students catch up with required basics before advanced MCA subjects begin.</p>\r\n<hr data-start=\"3036\" data-end=\"3039\">\r\n<h1 data-section-id=\"10wgf7e\" data-start=\"3041\" data-end=\"3079\">Good News for Non-Technical Students</h1>\r\n<p data-start=\"3081\" data-end=\"3229\">Many students from B.Com, BA, or non-IT backgrounds hesitate to apply for MCA. However, bridge courses can help them transition into the tech field.</p>\r\n<h3 data-section-id=\"t2q8fr\" data-start=\"3231\" data-end=\"3258\">Best Suitable Students:</h3>\r\n<ul data-start=\"3260\" data-end=\"3439\">\r\n<li data-section-id=\"522dun\" data-start=\"3260\" data-end=\"3307\">Commerce graduates interested in IT careers</li>\r\n<li data-section-id=\"6iq3s8\" data-start=\"3308\" data-end=\"3351\">Arts graduates wanting software careers</li>\r\n<li data-section-id=\"1buon6o\" data-start=\"3352\" data-end=\"3395\">Science students shifting to tech roles</li>\r\n<li data-section-id=\"1e3wojn\" data-start=\"3396\" data-end=\"3439\">Working professionals wanting IT upgrades</li>\r\n</ul>\r\n<hr data-start=\"3441\" data-end=\"3444\">\r\n<h1 data-section-id=\"11tq0wj\" data-start=\"3446\" data-end=\"3489\">MCA Admission Strategy for Better Success</h1>\r\n<h2 data-section-id=\"d8449p\" data-start=\"3491\" data-end=\"3532\">1. Apply Even If You Are Non-Technical</h2>\r\n<p data-start=\"3534\" data-end=\"3597\">If bridge courses are available, MCA can still be a smart path.</p>\r\n<h2 data-section-id=\"af1076\" data-start=\"3599\" data-end=\"3629\">2. Start Basic Skills Early</h2>\r\n<p data-start=\"3631\" data-end=\"3664\">Before admission, begin learning:</p>\r\n<ul data-start=\"3666\" data-end=\"3753\">\r\n<li data-section-id=\"1oixtsr\" data-start=\"3666\" data-end=\"3691\">Computer fundamentals</li>\r\n<li data-section-id=\"iun1jq\" data-start=\"3692\" data-end=\"3708\">Excel basics</li>\r\n<li data-section-id=\"1tee75c\" data-start=\"3709\" data-end=\"3727\">Logic building</li>\r\n<li data-section-id=\"d8dadp\" data-start=\"3728\" data-end=\"3753\">Intro Python / C / Java</li>\r\n</ul>\r\n<h2 data-section-id=\"1x4pywm\" data-start=\"3755\" data-end=\"3784\">3. Improve Math Confidence</h2>\r\n<p data-start=\"3786\" data-end=\"3846\">Revise percentages, algebra, logic, and data interpretation.</p>\r\n<h2 data-section-id=\"lupyvn\" data-start=\"3848\" data-end=\"3874\">4. Keep Documents Ready</h2>\r\n<ul data-start=\"3876\" data-end=\"3964\">\r\n<li data-section-id=\"15u4qah\" data-start=\"3876\" data-end=\"3901\">Graduation marksheets</li>\r\n<li data-section-id=\"1x24cga\" data-start=\"3902\" data-end=\"3920\">10+2 marksheet</li>\r\n<li data-section-id=\"123dnd5\" data-start=\"3921\" data-end=\"3943\">Degree certificate</li>\r\n<li data-section-id=\"1rsbash\" data-start=\"3944\" data-end=\"3956\">ID proof</li>\r\n<li data-section-id=\"1753lus\" data-start=\"3957\" data-end=\"3964\">Photo</li>\r\n</ul>', '<p data-start=\"360\" data-end=\"620\">Choosing the right MCA program requires understanding not only the syllabus and placements, but also the complete fee structure. A transparent fee breakdown helps students plan finances, compare universities, evaluate ROI, and choose the best payment option.</p>\r\n<p data-start=\"622\" data-end=\"779\">This guide explains the latest MCA semester fee, discounted payable amount, student grant benefit, EMI options, hidden costs, and smart admission strategies.</p>\r\n<hr data-start=\"781\" data-end=\"784\">\r\n<h1 data-section-id=\"5iwr0s\" data-start=\"786\" data-end=\"804\">MCA Fee Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"806\" data-end=\"1123\">\r\n<thead data-start=\"806\" data-end=\"832\">\r\n<tr data-start=\"806\" data-end=\"832\">\r\n<th class=\"\" data-start=\"806\" data-end=\"822\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"822\" data-end=\"832\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"844\" data-end=\"1123\">\r\n<tr data-start=\"844\" data-end=\"868\">\r\n<td data-start=\"844\" data-end=\"857\" data-col-size=\"sm\">Actual Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"857\" data-end=\"868\">₹40,000</td>\r\n</tr>\r\n<tr data-start=\"869\" data-end=\"910\">\r\n<td data-start=\"869\" data-end=\"886\" data-col-size=\"sm\">Applicable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"886\" data-end=\"910\">₹32,400 per semester</td>\r\n</tr>\r\n<tr data-start=\"911\" data-end=\"934\">\r\n<td data-start=\"911\" data-end=\"927\" data-col-size=\"sm\">Student Grant</td>\r\n<td data-col-size=\"sm\" data-start=\"927\" data-end=\"934\">20%</td>\r\n</tr>\r\n<tr data-start=\"935\" data-end=\"985\">\r\n<td data-start=\"935\" data-end=\"962\" data-col-size=\"sm\">Examination Fee Included</td>\r\n<td data-col-size=\"sm\" data-start=\"962\" data-end=\"985\">₹2,000 per semester</td>\r\n</tr>\r\n<tr data-start=\"986\" data-end=\"1032\">\r\n<td data-start=\"986\" data-end=\"1005\" data-col-size=\"sm\">Registration Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1005\" data-end=\"1032\">₹1,000 (Non-refundable)</td>\r\n</tr>\r\n<tr data-start=\"1033\" data-end=\"1075\">\r\n<td data-start=\"1033\" data-end=\"1049\" data-col-size=\"sm\">Payment Modes</td>\r\n<td data-col-size=\"sm\" data-start=\"1049\" data-end=\"1075\">One-Time Payment / EMI</td>\r\n</tr>\r\n<tr data-start=\"1076\" data-end=\"1123\">\r\n<td data-start=\"1076\" data-end=\"1097\" data-col-size=\"sm\">Payment Preference</td>\r\n<td data-col-size=\"sm\" data-start=\"1097\" data-end=\"1123\">No-Cost EMI / Standard</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1125\" data-end=\"1128\">\r\n<h1 data-section-id=\"oxgrfz\" data-start=\"1130\" data-end=\"1168\">Current MCA Discounted Fee Structure</h1>\r\n<p data-start=\"1170\" data-end=\"1266\">Students can currently benefit from a <strong data-start=\"1208\" data-end=\"1229\">20% Student Grant</strong>, reducing the standard semester fee.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1268\" data-end=\"1411\">\r\n<thead data-start=\"1268\" data-end=\"1292\">\r\n<tr data-start=\"1268\" data-end=\"1292\">\r\n<th class=\"\" data-start=\"1268\" data-end=\"1282\" data-col-size=\"sm\">Particulars</th>\r\n<th class=\"\" data-start=\"1282\" data-end=\"1292\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1304\" data-end=\"1411\">\r\n<tr data-start=\"1304\" data-end=\"1339\">\r\n<td data-start=\"1304\" data-end=\"1328\" data-col-size=\"sm\">Original Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1328\" data-end=\"1339\">₹40,000</td>\r\n</tr>\r\n<tr data-start=\"1340\" data-end=\"1377\">\r\n<td data-start=\"1340\" data-end=\"1366\" data-col-size=\"sm\">Discounted Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1366\" data-end=\"1377\">₹32,400</td>\r\n</tr>\r\n<tr data-start=\"1378\" data-end=\"1411\">\r\n<td data-start=\"1378\" data-end=\"1401\" data-col-size=\"sm\">Savings Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"1401\" data-end=\"1411\">₹7,600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1413\" data-end=\"1489\"><strong data-start=\"1413\" data-end=\"1432\">Offer Validity:</strong> Till <strong data-start=\"1438\" data-end=\"1454\">9th May 2026</strong> (subject to terms and conditions).</p>\r\n<hr data-start=\"1491\" data-end=\"1494\">\r\n<h1 data-section-id=\"1da9b7l\" data-start=\"1496\" data-end=\"1525\">Amount Payable Per Semester</h1>\r\n<h2 data-section-id=\"qu4flw\" data-start=\"1527\" data-end=\"1548\">₹32,400 / Semester</h2>\r\n<p data-start=\"1550\" data-end=\"1615\">This is the current applicable semester fee after grant benefits.</p>\r\n<hr data-start=\"1617\" data-end=\"1620\">\r\n<h1 data-section-id=\"18kzs72\" data-start=\"1622\" data-end=\"1653\">Included and Excluded Charges</h1>\r\n<h2 data-section-id=\"c40zw2\" data-start=\"1655\" data-end=\"1682\">Included in Semester Fee</h2>\r\n<ul data-start=\"1684\" data-end=\"1769\">\r\n<li data-section-id=\"dhanzm\" data-start=\"1684\" data-end=\"1726\">Examination fee of ₹2,000 per semester</li>\r\n<li data-section-id=\"10nr766\" data-start=\"1727\" data-end=\"1769\">Academic tuition charges (as applicable)</li>\r\n</ul>\r\n<h2 data-section-id=\"ocwtce\" data-start=\"1771\" data-end=\"1790\">Excluded Charges</h2>\r\n<ul data-start=\"1792\" data-end=\"1897\">\r\n<li data-section-id=\"12c5wuz\" data-start=\"1792\" data-end=\"1847\">Initial registration fee of ₹1,000 (non-refundable)</li>\r\n<li data-section-id=\"1iq867u\" data-start=\"1848\" data-end=\"1897\">Optional additional charges if applicable later</li>\r\n</ul>\r\n<hr data-start=\"1899\" data-end=\"1902\">\r\n<h1 data-section-id=\"1p7u5zq\" data-start=\"1904\" data-end=\"1937\">Eligible Countries for This Fee</h1>\r\n<p data-start=\"1939\" data-end=\"1987\">The above fee is applicable for applicants from:</p>\r\n<ul data-start=\"1989\" data-end=\"2062\">\r\n<li data-section-id=\"tgrdfn\" data-start=\"1989\" data-end=\"1998\">India</li>\r\n<li data-section-id=\"qjtdvt\" data-start=\"1999\" data-end=\"2012\">Sri Lanka</li>\r\n<li data-section-id=\"yxs3bg\" data-start=\"2013\" data-end=\"2023\">Bhutan</li>\r\n<li data-section-id=\"ef0w72\" data-start=\"2024\" data-end=\"2033\">Nepal</li>\r\n<li data-section-id=\"xi9ghh\" data-start=\"2034\" data-end=\"2048\">Bangladesh</li>\r\n<li data-section-id=\"1woqgfi\" data-start=\"2049\" data-end=\"2062\">Afghanistan</li>\r\n</ul>\r\n<hr data-start=\"2064\" data-end=\"2067\">\r\n<h1 data-section-id=\"x5a8d1\" data-start=\"2069\" data-end=\"2096\">Payment Options Available</h1>\r\n<p data-start=\"2098\" data-end=\"2166\">Students can select payment methods based on budget and convenience.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2168\" data-end=\"2392\">\r\n<thead data-start=\"2168\" data-end=\"2201\">\r\n<tr data-start=\"2168\" data-end=\"2201\">\r\n<th class=\"\" data-start=\"2168\" data-end=\"2185\" data-col-size=\"sm\">Payment Option</th>\r\n<th class=\"\" data-start=\"2185\" data-end=\"2201\" data-col-size=\"md\">Suitable For</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2212\" data-end=\"2392\">\r\n<tr data-start=\"2212\" data-end=\"2271\">\r\n<td data-start=\"2212\" data-end=\"2226\" data-col-size=\"sm\">No-Cost EMI</td>\r\n<td data-col-size=\"md\" data-start=\"2226\" data-end=\"2271\">Students preferring monthly affordability</td>\r\n</tr>\r\n<tr data-start=\"2272\" data-end=\"2307\">\r\n<td data-start=\"2272\" data-end=\"2283\" data-col-size=\"sm\">Standard</td>\r\n<td data-col-size=\"md\" data-start=\"2283\" data-end=\"2307\">Regular payment mode</td>\r\n</tr>\r\n<tr data-start=\"2308\" data-end=\"2352\">\r\n<td data-start=\"2308\" data-end=\"2327\" data-col-size=\"sm\">One-Time Payment</td>\r\n<td data-col-size=\"md\" data-start=\"2327\" data-end=\"2352\">Faster fee completion</td>\r\n</tr>\r\n<tr data-start=\"2353\" data-end=\"2392\">\r\n<td data-start=\"2353\" data-end=\"2359\" data-col-size=\"sm\">EMI</td>\r\n<td data-col-size=\"md\" data-start=\"2359\" data-end=\"2392\">Flexible installment planning</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"2394\" data-end=\"2397\">\r\n<h1 data-section-id=\"10awgtk\" data-start=\"2399\" data-end=\"2438\">Is No-Cost EMI Good for MCA Students?</h1>\r\n<p data-start=\"2440\" data-end=\"2543\">For many students, No-Cost EMI can make higher education easier without a heavy upfront payment burden.</p>\r\n<h2 data-section-id=\"jgrr8b\" data-start=\"2545\" data-end=\"2557\">Benefits:</h2>\r\n<ul data-start=\"2559\" data-end=\"2718\">\r\n<li data-section-id=\"1fczb0b\" data-start=\"2559\" data-end=\"2593\">Lower monthly expense pressure</li>\r\n<li data-section-id=\"1fu6w5c\" data-start=\"2594\" data-end=\"2625\">Better cash flow management</li>\r\n<li data-section-id=\"cay0o4\" data-start=\"2626\" data-end=\"2658\">Continue studies immediately</li>\r\n<li data-section-id=\"1avvrfh\" data-start=\"2659\" data-end=\"2718\">Save funds for laptop, software, internet, certifications</li>\r\n</ul>\r\n<h2 data-section-id=\"86h6gk\" data-start=\"2720\" data-end=\"2751\">Important Checks Before EMI:</h2>\r\n<ul data-start=\"2753\" data-end=\"2847\">\r\n<li data-section-id=\"51gpzo\" data-start=\"2753\" data-end=\"2767\">EMI tenure</li>\r\n<li data-section-id=\"i49auq\" data-start=\"2768\" data-end=\"2799\">Processing charges (if any)</li>\r\n<li data-section-id=\"1j3art6\" data-start=\"2800\" data-end=\"2828\">Missed payment penalties</li>\r\n<li data-section-id=\"wvka1w\" data-start=\"2829\" data-end=\"2847\">Auto debit terms</li>\r\n</ul>', 'Medium', '<p data-start=\"361\" data-end=\"772\">The MCA (Master of Computer Applications) syllabus is designed for students who want advanced knowledge in software development, programming, databases, cloud computing, networking, analytics, and emerging technologies. It is one of the most career-focused postgraduate programs for students aiming for jobs in IT, software engineering, data science, cloud computing, cybersecurity, and technology management.</p>\r\n<p data-start=\"774\" data-end=\"966\">This detailed semester-wise MCA syllabus helps students understand what they will study, which technical skills they will develop, and how the curriculum supports placements and salary growth.</p>\r\n<hr data-start=\"968\" data-end=\"971\">\r\n<h1 data-section-id=\"nhb9he\" data-start=\"973\" data-end=\"1004\">MCA Course Structure Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1006\" data-end=\"1237\">\r\n<thead data-start=\"1006\" data-end=\"1027\">\r\n<tr data-start=\"1006\" data-end=\"1027\">\r\n<th class=\"\" data-start=\"1006\" data-end=\"1013\" data-col-size=\"sm\">Year</th>\r\n<th class=\"\" data-start=\"1013\" data-end=\"1027\" data-col-size=\"md\">Focus Area</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1038\" data-end=\"1237\">\r\n<tr data-start=\"1038\" data-end=\"1107\">\r\n<td data-start=\"1038\" data-end=\"1051\" data-col-size=\"sm\">First Year</td>\r\n<td data-col-size=\"md\" data-start=\"1051\" data-end=\"1107\">Core programming, databases, networking, web &amp; cloud</td>\r\n</tr>\r\n<tr data-start=\"1108\" data-end=\"1182\">\r\n<td data-start=\"1108\" data-end=\"1122\" data-col-size=\"sm\">Second Year</td>\r\n<td data-col-size=\"md\" data-start=\"1122\" data-end=\"1182\">Advanced technologies, electives, training, project work</td>\r\n</tr>\r\n<tr data-start=\"1183\" data-end=\"1237\">\r\n<td data-start=\"1183\" data-end=\"1200\" data-col-size=\"sm\">Final Semester</td>\r\n<td data-col-size=\"md\" data-start=\"1200\" data-end=\"1237\">Industry project + specialization</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1239\" data-end=\"1242\">\r\n<h1 data-section-id=\"1mmqkzk\" data-start=\"1244\" data-end=\"1272\">MCA Semester Wise Syllabus</h1>\r\n<h2 data-section-id=\"3jvrxo\" data-start=\"1274\" data-end=\"1329\">Semester 1: Programming Foundations &amp; Core Computing</h2>\r\n<p data-start=\"1331\" data-end=\"1466\">The first semester builds strong fundamentals in software development, databases, operating systems, networking, and programming logic.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1468\" data-end=\"1876\">\r\n<thead data-start=\"1468\" data-end=\"1499\">\r\n<tr data-start=\"1468\" data-end=\"1499\">\r\n<th class=\"\" data-start=\"1468\" data-end=\"1483\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"1483\" data-end=\"1499\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1510\" data-end=\"1876\">\r\n<tr data-start=\"1510\" data-end=\"1554\">\r\n<td data-start=\"1510\" data-end=\"1520\" data-col-size=\"sm\">ECAP437</td>\r\n<td data-start=\"1520\" data-end=\"1554\" data-col-size=\"md\">Software Engineering Practices</td>\r\n</tr>\r\n<tr data-start=\"1555\" data-end=\"1606\">\r\n<td data-start=\"1555\" data-end=\"1565\" data-col-size=\"sm\">ECAP444</td>\r\n<td data-col-size=\"md\" data-start=\"1565\" data-end=\"1606\">Object Oriented Programming using C++</td>\r\n</tr>\r\n<tr data-start=\"1607\" data-end=\"1653\">\r\n<td data-start=\"1607\" data-end=\"1617\" data-col-size=\"sm\">ECAP446</td>\r\n<td data-col-size=\"md\" data-start=\"1617\" data-end=\"1653\">Data Warehousing and Data Mining</td>\r\n</tr>\r\n<tr data-start=\"1654\" data-end=\"1693\">\r\n<td data-start=\"1654\" data-end=\"1664\" data-col-size=\"sm\">ECAP448</td>\r\n<td data-col-size=\"md\" data-start=\"1664\" data-end=\"1693\">Linux and Shell Scripting</td>\r\n</tr>\r\n<tr data-start=\"1694\" data-end=\"1741\">\r\n<td data-start=\"1694\" data-end=\"1704\" data-col-size=\"sm\">ECAP453</td>\r\n<td data-col-size=\"md\" data-start=\"1704\" data-end=\"1741\">Data Communication and Networking</td>\r\n</tr>\r\n<tr data-start=\"1742\" data-end=\"1780\">\r\n<td data-start=\"1742\" data-end=\"1750\" data-col-size=\"sm\">SEC-I</td>\r\n<td data-start=\"1750\" data-end=\"1780\" data-col-size=\"md\">Skill Enhancement Course I</td>\r\n</tr>\r\n<tr data-start=\"1781\" data-end=\"1838\">\r\n<td data-start=\"1781\" data-end=\"1791\" data-col-size=\"sm\">ECAP012</td>\r\n<td data-start=\"1791\" data-end=\"1838\" data-col-size=\"md\">Fundamentals of Computer and C Programming*</td>\r\n</tr>\r\n<tr data-start=\"1839\" data-end=\"1876\">\r\n<td data-start=\"1839\" data-end=\"1849\" data-col-size=\"sm\">EMTH006</td>\r\n<td data-start=\"1849\" data-end=\"1876\" data-col-size=\"md\">Elementary Mathematics*</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"aqq1xr\" data-start=\"1878\" data-end=\"1914\">Bridge Courses (When Applicable)</h3>\r\n<p data-start=\"1916\" data-end=\"2023\">The following bridge courses are generally for students without Computer Science or Mathematics background:</p>\r\n<ul data-start=\"2025\" data-end=\"2096\">\r\n<li data-section-id=\"koo6tf\" data-start=\"2025\" data-end=\"2071\">Fundamentals of Computer and C Programming</li>\r\n<li data-section-id=\"1qla7vs\" data-start=\"2072\" data-end=\"2096\">Elementary Mathematics</li>\r\n</ul>\r\n<h3 data-section-id=\"1yb3s8s\" data-start=\"2098\" data-end=\"2132\">Skills Developed in Semester 1</h3>\r\n<ul data-start=\"2134\" data-end=\"2261\">\r\n<li data-section-id=\"d24kin\" data-start=\"2134\" data-end=\"2155\">Programming logic</li>\r\n<li data-section-id=\"1doqeo8\" data-start=\"2156\" data-end=\"2176\">C++ OOP concepts</li>\r\n<li data-section-id=\"1sfycit\" data-start=\"2177\" data-end=\"2206\">Linux command line skills</li>\r\n<li data-section-id=\"gnuh6n\" data-start=\"2207\" data-end=\"2228\">Networking basics</li>\r\n<li data-section-id=\"96ak7d\" data-start=\"2229\" data-end=\"2261\">Data storage and mining basics</li>\r\n</ul>\r\n<hr data-start=\"2263\" data-end=\"2266\">\r\n<h2 data-section-id=\"1xmv4uo\" data-start=\"2268\" data-end=\"2327\">Semester 2: Advanced Development &amp; Emerging Technologies</h2>\r\n<p data-start=\"2329\" data-end=\"2438\">This semester focuses on Java, data structures, big data, cloud computing, mathematics, and web technologies.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2440\" data-end=\"2754\">\r\n<thead data-start=\"2440\" data-end=\"2471\">\r\n<tr data-start=\"2440\" data-end=\"2471\">\r\n<th class=\"\" data-start=\"2440\" data-end=\"2455\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2455\" data-end=\"2471\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2482\" data-end=\"2754\">\r\n<tr data-start=\"2482\" data-end=\"2515\">\r\n<td data-start=\"2482\" data-end=\"2492\" data-col-size=\"sm\">ECAP615</td>\r\n<td data-start=\"2492\" data-end=\"2515\" data-col-size=\"md\">Programming in Java</td>\r\n</tr>\r\n<tr data-start=\"2516\" data-end=\"2554\">\r\n<td data-start=\"2516\" data-end=\"2526\" data-col-size=\"sm\">ECAP770</td>\r\n<td data-start=\"2526\" data-end=\"2554\" data-col-size=\"md\">Advanced Data Structures</td>\r\n</tr>\r\n<tr data-start=\"2555\" data-end=\"2593\">\r\n<td data-start=\"2555\" data-end=\"2565\" data-col-size=\"sm\">ECAP456</td>\r\n<td data-start=\"2565\" data-end=\"2593\" data-col-size=\"md\">Introduction to Big Data</td>\r\n</tr>\r\n<tr data-start=\"2594\" data-end=\"2623\">\r\n<td data-start=\"2594\" data-end=\"2604\" data-col-size=\"sm\">ECAP470</td>\r\n<td data-start=\"2604\" data-end=\"2623\" data-col-size=\"md\">Cloud Computing</td>\r\n</tr>\r\n<tr data-start=\"2624\" data-end=\"2682\">\r\n<td data-start=\"2624\" data-end=\"2634\" data-col-size=\"sm\">EMTH403</td>\r\n<td data-start=\"2634\" data-end=\"2682\" data-col-size=\"md\">Mathematical Foundation for Computer Science</td>\r\n</tr>\r\n<tr data-start=\"2683\" data-end=\"2713\">\r\n<td data-start=\"2683\" data-end=\"2693\" data-col-size=\"sm\">ECAP472</td>\r\n<td data-start=\"2693\" data-end=\"2713\" data-col-size=\"md\">Web Technologies</td>\r\n</tr>\r\n<tr data-start=\"2714\" data-end=\"2754\">\r\n<td data-start=\"2714\" data-end=\"2723\" data-col-size=\"sm\">SEC-II</td>\r\n<td data-start=\"2723\" data-end=\"2754\" data-col-size=\"md\">Skill Enhancement Course II</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"lcqk80\" data-start=\"2756\" data-end=\"2787\">Why Semester 2 is Important</h3>\r\n<p data-start=\"2789\" data-end=\"2857\">Recruiters highly value Java + Data Structures + Cloud + Web skills.</p>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"2859\" data-end=\"2879\">Skills Developed</h3>\r\n<ul data-start=\"2881\" data-end=\"3014\">\r\n<li data-section-id=\"qkcrif\" data-start=\"2881\" data-end=\"2901\">Java development</li>\r\n<li data-section-id=\"14sb5oj\" data-start=\"2902\" data-end=\"2935\">Algorithms &amp; efficient coding</li>\r\n<li data-section-id=\"1hsqtmo\" data-start=\"2936\" data-end=\"2961\">Big data fundamentals</li>\r\n<li data-section-id=\"bvwyjg\" data-start=\"2962\" data-end=\"2988\">Cloud platforms basics</li>\r\n<li data-section-id=\"wvf4bf\" data-start=\"2989\" data-end=\"3014\">Full-stack web concepts</li>\r\n</ul>\r\n<hr data-start=\"3016\" data-end=\"3019\">\r\n<h2 data-section-id=\"1hxg46f\" data-start=\"3021\" data-end=\"3073\">Semester 3: Python, Electives &amp; Industry Exposure</h2>\r\n<p data-start=\"3075\" data-end=\"3173\">This semester introduces Python, specialization choices, generic electives, and training exposure.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3175\" data-end=\"3505\">\r\n<thead data-start=\"3175\" data-end=\"3206\">\r\n<tr data-start=\"3175\" data-end=\"3206\">\r\n<th class=\"\" data-start=\"3175\" data-end=\"3190\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3190\" data-end=\"3206\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3217\" data-end=\"3505\">\r\n<tr data-start=\"3217\" data-end=\"3252\">\r\n<td data-start=\"3217\" data-end=\"3227\" data-col-size=\"sm\">ECAP776</td>\r\n<td data-start=\"3227\" data-end=\"3252\" data-col-size=\"md\">Programming in Python</td>\r\n</tr>\r\n<tr data-start=\"3253\" data-end=\"3295\">\r\n<td data-start=\"3253\" data-end=\"3263\" data-col-size=\"sm\">SEC-III</td>\r\n<td data-start=\"3263\" data-end=\"3295\" data-col-size=\"md\">Skill Enhancement Course III</td>\r\n</tr>\r\n<tr data-start=\"3296\" data-end=\"3338\">\r\n<td data-start=\"3296\" data-end=\"3304\" data-col-size=\"sm\">DSE-I</td>\r\n<td data-start=\"3304\" data-end=\"3338\" data-col-size=\"md\">Discipline Specific Elective I</td>\r\n</tr>\r\n<tr data-start=\"3339\" data-end=\"3383\">\r\n<td data-start=\"3339\" data-end=\"3348\" data-col-size=\"sm\">DSE-II</td>\r\n<td data-start=\"3348\" data-end=\"3383\" data-col-size=\"md\">Discipline Specific Elective II</td>\r\n</tr>\r\n<tr data-start=\"3384\" data-end=\"3413\">\r\n<td data-start=\"3384\" data-end=\"3391\" data-col-size=\"sm\">GE-I</td>\r\n<td data-start=\"3391\" data-end=\"3413\" data-col-size=\"md\">Generic Elective I</td>\r\n</tr>\r\n<tr data-start=\"3414\" data-end=\"3445\">\r\n<td data-start=\"3414\" data-end=\"3422\" data-col-size=\"sm\">GE-II</td>\r\n<td data-start=\"3422\" data-end=\"3445\" data-col-size=\"md\">Generic Elective II</td>\r\n</tr>\r\n<tr data-start=\"3446\" data-end=\"3505\">\r\n<td data-start=\"3446\" data-end=\"3456\" data-col-size=\"sm\">ECAP735</td>\r\n<td data-start=\"3456\" data-end=\"3505\" data-col-size=\"md\">Seminar on Summer Training / GE Basket Course</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"7zaalc\" data-start=\"3507\" data-end=\"3536\">Why This Semester Matters</h3>\r\n<p data-start=\"3538\" data-end=\"3613\">This is where students begin tailoring their career path through electives.</p>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"3615\" data-end=\"3635\">Skills Developed</h3>\r\n<ul data-start=\"3637\" data-end=\"3754\">\r\n<li data-section-id=\"1t12n5x\" data-start=\"3637\" data-end=\"3659\">Python programming</li>\r\n<li data-section-id=\"11ssbxs\" data-start=\"3660\" data-end=\"3684\">Internship readiness</li>\r\n<li data-section-id=\"jl2qz3\" data-start=\"3685\" data-end=\"3716\">Specialized domain learning</li>\r\n<li data-section-id=\"xqzxi2\" data-start=\"3717\" data-end=\"3754\">Communication &amp; presentation skills</li>\r\n</ul>\r\n<hr data-start=\"3756\" data-end=\"3759\">\r\n<h2 data-section-id=\"u3054k\" data-start=\"3761\" data-end=\"3811\">Semester 4: Project Work &amp; Final Specialization</h2>\r\n<p data-start=\"3813\" data-end=\"3912\">The final semester focuses on advanced electives, employability skills, and project implementation.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3914\" data-end=\"4181\">\r\n<thead data-start=\"3914\" data-end=\"3945\">\r\n<tr data-start=\"3914\" data-end=\"3945\">\r\n<th class=\"\" data-start=\"3914\" data-end=\"3929\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3929\" data-end=\"3945\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3956\" data-end=\"4181\">\r\n<tr data-start=\"3956\" data-end=\"3996\">\r\n<td data-start=\"3956\" data-end=\"3965\" data-col-size=\"sm\">SEC-IV</td>\r\n<td data-start=\"3965\" data-end=\"3996\" data-col-size=\"sm\">Skill Enhancement Course IV</td>\r\n</tr>\r\n<tr data-start=\"3997\" data-end=\"4043\">\r\n<td data-start=\"3997\" data-end=\"4007\" data-col-size=\"sm\">DSE-III</td>\r\n<td data-start=\"4007\" data-end=\"4043\" data-col-size=\"sm\">Discipline Specific Elective III</td>\r\n</tr>\r\n<tr data-start=\"4044\" data-end=\"4088\">\r\n<td data-start=\"4044\" data-end=\"4053\" data-col-size=\"sm\">DSE-IV</td>\r\n<td data-start=\"4053\" data-end=\"4088\" data-col-size=\"sm\">Discipline Specific Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4089\" data-end=\"4122\">\r\n<td data-start=\"4089\" data-end=\"4098\" data-col-size=\"sm\">GE-III</td>\r\n<td data-start=\"4098\" data-end=\"4122\" data-col-size=\"sm\">Generic Elective III</td>\r\n</tr>\r\n<tr data-start=\"4123\" data-end=\"4154\">\r\n<td data-start=\"4123\" data-end=\"4131\" data-col-size=\"sm\">GE-IV</td>\r\n<td data-start=\"4131\" data-end=\"4154\" data-col-size=\"sm\">Generic Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4155\" data-end=\"4181\">\r\n<td data-start=\"4155\" data-end=\"4165\" data-col-size=\"sm\">ECAP788</td>\r\n<td data-start=\"4165\" data-end=\"4181\" data-col-size=\"sm\">Project Work</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"a82sdk\" data-start=\"4183\" data-end=\"4216\">Why Project Work is Important</h3>\r\n<p data-start=\"4218\" data-end=\"4311\">The final project can become one of the strongest parts of your resume and placement profile.</p>\r\n<h3 data-section-id=\"szhg14\" data-start=\"4313\" data-end=\"4333\">Project Examples</h3>\r\n<ul data-start=\"4335\" data-end=\"4491\">\r\n<li data-section-id=\"8gi2oh\" data-start=\"4335\" data-end=\"4366\">Web application development</li>\r\n<li data-section-id=\"1u07p36\" data-start=\"4367\" data-end=\"4388\">AI chatbot system</li>\r\n<li data-section-id=\"1hoz8j9\" data-start=\"4389\" data-end=\"4417\">Cloud deployment project</li>\r\n<li data-section-id=\"lc45nu\" data-start=\"4418\" data-end=\"4446\">Data analytics dashboard</li>\r\n<li data-section-id=\"kg4ipu\" data-start=\"4447\" data-end=\"4470\">E-commerce platform</li>\r\n<li data-section-id=\"5uw21\" data-start=\"4471\" data-end=\"4491\">Cybersecurity tool</li>\r\n</ul>\r\n<hr data-start=\"4493\" data-end=\"4496\">\r\n<h1 data-section-id=\"19885l5\" data-start=\"4498\" data-end=\"4526\">Popular MCA Elective Areas</h1>\r\n<p data-start=\"4528\" data-end=\"4585\">Depending on university offerings, electives may include:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"4587\" data-end=\"4862\">\r\n<thead data-start=\"4587\" data-end=\"4620\">\r\n<tr data-start=\"4587\" data-end=\"4620\">\r\n<th class=\"\" data-start=\"4587\" data-end=\"4604\" data-col-size=\"sm\">Specialization</th>\r\n<th class=\"\" data-start=\"4604\" data-end=\"4620\" data-col-size=\"sm\">Career Scope</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"4631\" data-end=\"4862\">\r\n<tr data-start=\"4631\" data-end=\"4667\">\r\n<td data-start=\"4631\" data-end=\"4646\" data-col-size=\"sm\">Data Science</td>\r\n<td data-start=\"4646\" data-end=\"4667\" data-col-size=\"sm\">Analyst, ML roles</td>\r\n</tr>\r\n<tr data-start=\"4668\" data-end=\"4704\">\r\n<td data-start=\"4668\" data-end=\"4686\" data-col-size=\"sm\">Cloud Computing</td>\r\n<td data-start=\"4686\" data-end=\"4704\" data-col-size=\"sm\">AWS/Azure jobs</td>\r\n</tr>\r\n<tr data-start=\"4705\" data-end=\"4741\">\r\n<td data-start=\"4705\" data-end=\"4721\" data-col-size=\"sm\">Cybersecurity</td>\r\n<td data-start=\"4721\" data-end=\"4741\" data-col-size=\"sm\">Security analyst</td>\r\n</tr>\r\n<tr data-start=\"4742\" data-end=\"4784\">\r\n<td data-start=\"4742\" data-end=\"4767\" data-col-size=\"sm\">Full Stack Development</td>\r\n<td data-start=\"4767\" data-end=\"4784\" data-col-size=\"sm\">Web developer</td>\r\n</tr>\r\n<tr data-start=\"4785\" data-end=\"4824\">\r\n<td data-start=\"4785\" data-end=\"4809\" data-col-size=\"sm\">AI &amp; Machine Learning</td>\r\n<td data-start=\"4809\" data-end=\"4824\" data-col-size=\"sm\">AI engineer</td>\r\n</tr>\r\n<tr data-start=\"4825\" data-end=\"4862\">\r\n<td data-start=\"4825\" data-end=\"4838\" data-col-size=\"sm\">Networking</td>\r\n<td data-start=\"4838\" data-end=\"4862\" data-col-size=\"sm\">Infrastructure roles</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', NULL, '<p data-start=\"383\" data-end=\"711\">For MCA students, placement support is one of the most important factors while selecting an online postgraduate program. Since MCA is a career-oriented degree focused on software, IT, cloud, analytics, and technical roles, students often look for universities that provide not only academics but also strong career assistance.</p>\r\n<p data-start=\"713\" data-end=\"1062\"><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Lovely Professional University</span></span> Online offers placement support services designed to improve students&rsquo; employability, align their skills with industry demand, and help them access suitable job opportunities. The focus goes beyond classroom learning by encouraging students to build additional career-ready skills that recruiters actively seek.</p>\r\n<p data-start=\"1064\" data-end=\"1224\">This guide explains MCA placement support, LPU Online career services, IT job opportunities, ROI value, hiring strategy, and how students can maximize outcomes.</p>\r\n<hr data-start=\"1226\" data-end=\"1229\">\r\n<h1 data-section-id=\"7e8h4w\" data-start=\"1231\" data-end=\"1279\">Why Placement Support Matters for MCA Students</h1>\r\n<p data-start=\"1281\" data-end=\"1518\">MCA graduates usually compete for roles in software development, data analytics, cloud support, cybersecurity, and web technologies. Academic knowledge alone is often not enough. Recruiters usually prefer candidates who also demonstrate:</p>\r\n<ul data-start=\"1520\" data-end=\"1660\">\r\n<li data-section-id=\"hi2z8i\" data-start=\"1520\" data-end=\"1538\">Coding ability</li>\r\n<li data-section-id=\"1mfo8p6\" data-start=\"1539\" data-end=\"1563\">Communication skills</li>\r\n<li data-section-id=\"s3q404\" data-start=\"1564\" data-end=\"1591\">Problem-solving mindset</li>\r\n<li data-section-id=\"5g0fc3\" data-start=\"1592\" data-end=\"1614\">Project experience</li>\r\n<li data-section-id=\"1nzdt2d\" data-start=\"1615\" data-end=\"1639\">Interview confidence</li>\r\n<li data-section-id=\"15y4qxl\" data-start=\"1640\" data-end=\"1660\">Industry awareness</li>\r\n</ul>\r\n<p data-start=\"1662\" data-end=\"1741\">Strong placement support helps bridge the gap between education and employment.</p>\r\n<hr data-start=\"1743\" data-end=\"1746\">\r\n<h1 data-section-id=\"1o91jlz\" data-start=\"1748\" data-end=\"1791\">LPU Online MCA Placement Support Services</h1>\r\n<h2 data-section-id=\"18k74lo\" data-start=\"1793\" data-end=\"1815\">1. Placement Drives</h2>\r\n<p data-start=\"1817\" data-end=\"2006\">Placement drives help students connect with hiring companies and recruiters. These drives can create valuable job opportunities for MCA students seeking entry-level or growth-focused roles.</p>\r\n<h3 data-section-id=\"1iaul7c\" data-start=\"2008\" data-end=\"2021\">Benefits:</h3>\r\n<ul data-start=\"2023\" data-end=\"2177\">\r\n<li data-section-id=\"1ay2xnq\" data-start=\"2023\" data-end=\"2055\">Direct recruiter interaction</li>\r\n<li data-section-id=\"1bd1f2x\" data-start=\"2056\" data-end=\"2087\">Job interview opportunities</li>\r\n<li data-section-id=\"1t6ljvc\" data-start=\"2088\" data-end=\"2114\">Better hiring exposure</li>\r\n<li data-section-id=\"391fa9\" data-start=\"2115\" data-end=\"2150\">Real-time industry expectations</li>\r\n<li data-section-id=\"1w9y0p5\" data-start=\"2151\" data-end=\"2177\">Networking opportunities</li>\r\n</ul>\r\n<hr data-start=\"2179\" data-end=\"2182\">\r\n<h2 data-section-id=\"1fm5jpo\" data-start=\"2184\" data-end=\"2215\">2. Career Readiness Programs</h2>\r\n<p data-start=\"2217\" data-end=\"2319\">Students may receive support aimed at making them professionally ready for technical hiring processes.</p>\r\n<h3 data-section-id=\"wc98l0\" data-start=\"2321\" data-end=\"2337\">Focus Areas:</h3>\r\n<ul data-start=\"2339\" data-end=\"2464\">\r\n<li data-section-id=\"1ewtugo\" data-start=\"2339\" data-end=\"2358\">Resume creation</li>\r\n<li data-section-id=\"pr6i54\" data-start=\"2359\" data-end=\"2384\">Interview preparation</li>\r\n<li data-section-id=\"1tzjmu7\" data-start=\"2385\" data-end=\"2409\">Technical confidence</li>\r\n<li data-section-id=\"125j4sf\" data-start=\"2410\" data-end=\"2436\">Professional etiquette</li>\r\n<li data-section-id=\"hsibv6\" data-start=\"2437\" data-end=\"2464\">Career direction planning</li>\r\n</ul>\r\n<hr data-start=\"2466\" data-end=\"2469\">\r\n<h2 data-section-id=\"eyxhxz\" data-start=\"2471\" data-end=\"2501\">3. Add-On Skill Development</h2>\r\n<p data-start=\"2503\" data-end=\"2601\">Modern IT hiring is skill-driven. Students are motivated to gain extra skills beyond the syllabus.</p>\r\n<h3 data-section-id=\"1bks4ft\" data-start=\"2603\" data-end=\"2647\">Valuable Add-On Skills for MCA Students:</h3>\r\n<ul data-start=\"2649\" data-end=\"2779\">\r\n<li data-section-id=\"1lju5j0\" data-start=\"2649\" data-end=\"2659\">Python</li>\r\n<li data-section-id=\"1qhyh3o\" data-start=\"2660\" data-end=\"2668\">Java</li>\r\n<li data-section-id=\"177lgg6\" data-start=\"2669\" data-end=\"2676\">SQL</li>\r\n<li data-section-id=\"1dr3u2a\" data-start=\"2677\" data-end=\"2692\">Cloud tools</li>\r\n<li data-section-id=\"15rsfwm\" data-start=\"2693\" data-end=\"2714\">Excel / Analytics</li>\r\n<li data-section-id=\"fnkx3s\" data-start=\"2715\" data-end=\"2731\">Git / GitHub</li>\r\n<li data-section-id=\"1mfo8p6\" data-start=\"2732\" data-end=\"2756\">Communication skills</li>\r\n<li data-section-id=\"1vfe7od\" data-start=\"2757\" data-end=\"2779\">Aptitude preparation</li>\r\n</ul>\r\n<hr data-start=\"2781\" data-end=\"2784\">\r\n<h2 data-section-id=\"101x11c\" data-start=\"2786\" data-end=\"2825\">4. Awareness of Career Opportunities</h2>\r\n<p data-start=\"2827\" data-end=\"2920\">Many students know coding but not career pathways. Career support can create awareness about:</p>\r\n<ul data-start=\"2922\" data-end=\"3074\">\r\n<li data-section-id=\"lcbvbq\" data-start=\"2922\" data-end=\"2950\">Software developer roles</li>\r\n<li data-section-id=\"bv562j\" data-start=\"2951\" data-end=\"2981\">Data analyst opportunities</li>\r\n<li data-section-id=\"wpsiov\" data-start=\"2982\" data-end=\"3006\">Web development jobs</li>\r\n<li data-section-id=\"4l1cy0\" data-start=\"3007\" data-end=\"3024\">Cloud careers</li>\r\n<li data-section-id=\"kutwvd\" data-start=\"3025\" data-end=\"3045\">QA testing roles</li>\r\n<li data-section-id=\"1jc1sjp\" data-start=\"3046\" data-end=\"3074\">Technical support pathways</li>\r\n</ul>', NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 160000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(232, 69, 'd67d3d73-4a79-4175-89f0-c61979138bac', '956f52ba-dcf0-4224-9a30-f9f785980fe3', 68, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 03:02:00', '2026-06-16 06:05:45', '<p data-start=\"352\" data-end=\"599\">Getting admission into a BBA program is now easier through a fully online process. Students can complete registration, submit the application form, upload documents, pay fees, and receive final admission confirmation without visiting the campus.</p>\r\n<p data-start=\"601\" data-end=\"881\">BBA is one of the most popular undergraduate management programs for students who want careers in business, marketing, finance, HR, entrepreneurship, and corporate leadership. Understanding the admission process early helps students avoid delays, mistakes, and last-minute stress.</p>\r\n<p data-start=\"883\" data-end=\"1035\">This guide explains each stage of the BBA admission process, required documents, expert tips, common mistakes, and smart strategies for faster approval.</p>\r\n<hr data-start=\"1037\" data-end=\"1040\">\r\n<h1 data-section-id=\"1iwwqva\" data-start=\"1042\" data-end=\"1074\">BBA Admission Process Overview</h1>\r\n<p data-start=\"1076\" data-end=\"1137\">The BBA admission process usually includes four major stages:</p>\r\n<ol data-start=\"1139\" data-end=\"1269\">\r\n<li data-section-id=\"nl6le3\" data-start=\"1139\" data-end=\"1156\">Registration</li>\r\n<li data-section-id=\"ylnmm2\" data-start=\"1157\" data-end=\"1185\">Online Application Form</li>\r\n<li data-section-id=\"101zuxd\" data-start=\"1186\" data-end=\"1226\">Document Verification by University</li>\r\n<li data-section-id=\"19bjzt6\" data-start=\"1227\" data-end=\"1269\">Student Registration and LMS Activation</li>\r\n</ol>\r\n<p data-start=\"1271\" data-end=\"1341\">Completing each stage carefully ensures a smooth admission experience.</p>\r\n<hr data-start=\"1343\" data-end=\"1346\">\r\n<h1 data-section-id=\"52akem\" data-start=\"1348\" data-end=\"1370\">Step 1: Registration</h1>\r\n<p data-start=\"1372\" data-end=\"1446\">The first step is to create your account on the official admission portal.</p>\r\n<p data-start=\"1448\" data-end=\"1481\">Students generally need to enter:</p>\r\n<ul data-start=\"1483\" data-end=\"1570\">\r\n<li data-section-id=\"u7na1o\" data-start=\"1483\" data-end=\"1496\">Full Name</li>\r\n<li data-section-id=\"1dep5uz\" data-start=\"1497\" data-end=\"1514\">Mobile Number</li>\r\n<li data-section-id=\"36fvl5\" data-start=\"1515\" data-end=\"1527\">Email ID</li>\r\n<li data-section-id=\"4ligt3\" data-start=\"1528\" data-end=\"1544\">State / City</li>\r\n<li data-section-id=\"1lshnnd\" data-start=\"1545\" data-end=\"1570\">Preferred Program (BBA)</li>\r\n</ul>\r\n<p data-start=\"1572\" data-end=\"1639\">After sign-up, pay the initial registration fee to proceed further.</p>\r\n<h3 data-section-id=\"1my1m11\" data-start=\"1641\" data-end=\"1655\">Expert Tip</h3>\r\n<p data-start=\"1657\" data-end=\"1766\">Use an active mobile number and email ID because all updates, receipts, and login credentials are sent there.</p>\r\n<h3 data-section-id=\"10clvjd\" data-start=\"1768\" data-end=\"1795\">Common Mistake to Avoid</h3>\r\n<p data-start=\"1797\" data-end=\"1878\">Incorrect email IDs or inactive phone numbers may cause missed admission updates.</p>\r\n<hr data-start=\"1880\" data-end=\"1883\">\r\n<h1 data-section-id=\"1vjt9r3\" data-start=\"1885\" data-end=\"1918\">Step 2: Online Application Form</h1>\r\n<p data-start=\"1920\" data-end=\"1992\">After registration, log in and complete the online BBA application form.</p>\r\n<p data-start=\"1994\" data-end=\"2020\">Students may need to fill:</p>\r\n<ul data-start=\"2022\" data-end=\"2138\">\r\n<li data-section-id=\"1fxsuaa\" data-start=\"2022\" data-end=\"2042\">Personal details</li>\r\n<li data-section-id=\"itkbd9\" data-start=\"2043\" data-end=\"2073\">Educational qualifications</li>\r\n<li data-section-id=\"15di1ss\" data-start=\"2074\" data-end=\"2093\">Address details</li>\r\n<li data-section-id=\"yylsws\" data-start=\"2094\" data-end=\"2115\">Program selection</li>\r\n<li data-section-id=\"1bjeo8i\" data-start=\"2116\" data-end=\"2138\">Identity information</li>\r\n</ul>\r\n<p data-start=\"2140\" data-end=\"2217\">After completing the form, pay the program fee and upload required documents.</p>\r\n<hr data-start=\"2219\" data-end=\"2222\">\r\n<h1 data-section-id=\"14kthqw\" data-start=\"2224\" data-end=\"2271\">Documents Commonly Required for BBA Admission</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2273\" data-end=\"2532\">\r\n<thead data-start=\"2273\" data-end=\"2295\">\r\n<tr data-start=\"2273\" data-end=\"2295\">\r\n<th class=\"\" data-start=\"2273\" data-end=\"2284\" data-col-size=\"sm\">Document</th>\r\n<th class=\"\" data-start=\"2284\" data-end=\"2295\" data-col-size=\"sm\">Purpose</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2306\" data-end=\"2532\">\r\n<tr data-start=\"2306\" data-end=\"2352\">\r\n<td data-start=\"2306\" data-end=\"2327\" data-col-size=\"sm\">Class 10 Marksheet</td>\r\n<td data-col-size=\"sm\" data-start=\"2327\" data-end=\"2352\">Basic academic record</td>\r\n</tr>\r\n<tr data-start=\"2353\" data-end=\"2420\">\r\n<td data-start=\"2353\" data-end=\"2392\" data-col-size=\"sm\">Class 12 Marksheet / Appearing Proof</td>\r\n<td data-col-size=\"sm\" data-start=\"2392\" data-end=\"2420\">Eligibility verification</td>\r\n</tr>\r\n<tr data-start=\"2421\" data-end=\"2457\">\r\n<td data-start=\"2421\" data-end=\"2432\" data-col-size=\"sm\">ID Proof</td>\r\n<td data-col-size=\"sm\" data-start=\"2432\" data-end=\"2457\">Identity confirmation</td>\r\n</tr>\r\n<tr data-start=\"2458\" data-end=\"2499\">\r\n<td data-start=\"2458\" data-end=\"2480\" data-col-size=\"sm\">Passport Size Photo</td>\r\n<td data-col-size=\"sm\" data-start=\"2480\" data-end=\"2499\">Student profile</td>\r\n</tr>\r\n<tr data-start=\"2500\" data-end=\"2532\">\r\n<td data-start=\"2500\" data-end=\"2512\" data-col-size=\"sm\">Signature</td>\r\n<td data-start=\"2512\" data-end=\"2532\" data-col-size=\"sm\">Official records</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"jt31xg\" data-start=\"2534\" data-end=\"2552\">Smart Strategy</h3>\r\n<p data-start=\"2554\" data-end=\"2629\">Keep clear scanned copies ready in PDF/JPG format before starting the form.</p>\r\n<hr data-start=\"2631\" data-end=\"2634\">\r\n<h1 data-section-id=\"ln8rck\" data-start=\"2636\" data-end=\"2681\">Step 3: Document Verification by University</h1>\r\n<p data-start=\"2683\" data-end=\"2791\">Once the application is submitted, the university verifies all submitted information and uploaded documents.</p>\r\n<h3 data-section-id=\"131lww1\" data-start=\"2793\" data-end=\"2827\">Verification Usually Includes:</h3>\r\n<ul data-start=\"2829\" data-end=\"2961\">\r\n<li data-section-id=\"adbeij\" data-start=\"2829\" data-end=\"2855\">10+2 eligibility check</li>\r\n<li data-section-id=\"1dlv2x\" data-start=\"2856\" data-end=\"2880\">Marksheet validation</li>\r\n<li data-section-id=\"27zx9a\" data-start=\"2881\" data-end=\"2906\">Name and DOB matching</li>\r\n<li data-section-id=\"1qa0omz\" data-start=\"2907\" data-end=\"2935\">Fee payment confirmation</li>\r\n<li data-section-id=\"10eo6wg\" data-start=\"2936\" data-end=\"2961\">Document quality review</li>\r\n</ul>\r\n<p data-start=\"2963\" data-end=\"3041\">If corrections are needed, students may receive email or portal notifications.</p>\r\n<h3 data-section-id=\"1mcxn79\" data-start=\"3043\" data-end=\"3071\">Hidden Reasons for Delay</h3>\r\n<p data-start=\"3073\" data-end=\"3113\">Most admission delays happen because of:</p>\r\n<ul data-start=\"3115\" data-end=\"3237\">\r\n<li data-section-id=\"2v78q6\" data-start=\"3115\" data-end=\"3136\">Blurred documents</li>\r\n<li data-section-id=\"1yndzvz\" data-start=\"3137\" data-end=\"3162\">Incomplete marksheets</li>\r\n<li data-section-id=\"qew425\" data-start=\"3163\" data-end=\"3189\">Wrong spelling in name</li>\r\n<li data-section-id=\"14kzt0i\" data-start=\"3190\" data-end=\"3219\">Incorrect details in form</li>\r\n<li data-section-id=\"7jdazg\" data-start=\"3220\" data-end=\"3237\">Missing uploads</li>\r\n</ul>\r\n<hr data-start=\"3239\" data-end=\"3242\">\r\n<h1 data-section-id=\"1fuepgv\" data-start=\"3244\" data-end=\"3293\">Step 4: Student Registration and LMS Activation</h1>\r\n<p data-start=\"3295\" data-end=\"3404\">After successful verification, final admission is processed. Students then receive LMS credentials via email.</p>\r\n<h3 data-section-id=\"1k7bjc6\" data-start=\"3406\" data-end=\"3435\">Students Usually Receive:</h3>\r\n<ul data-start=\"3437\" data-end=\"3525\">\r\n<li data-section-id=\"el5erz\" data-start=\"3437\" data-end=\"3458\">Enrollment Number</li>\r\n<li data-section-id=\"f73c3w\" data-start=\"3459\" data-end=\"3473\">Student ID</li>\r\n<li data-section-id=\"17cwsxh\" data-start=\"3474\" data-end=\"3501\">LMS Username &amp; Password</li>\r\n<li data-section-id=\"1c7cimr\" data-start=\"3502\" data-end=\"3525\">Course access details</li>\r\n</ul>\r\n<h3 data-section-id=\"uttsmo\" data-start=\"3527\" data-end=\"3543\">LMS Benefits</h3>\r\n<p data-start=\"3545\" data-end=\"3598\">The Learning Management System helps students access:</p>\r\n<ul data-start=\"3600\" data-end=\"3707\">\r\n<li data-section-id=\"8imkcm\" data-start=\"3600\" data-end=\"3616\">Live classes</li>\r\n<li data-section-id=\"1d3fguj\" data-start=\"3617\" data-end=\"3638\">Recorded lectures</li>\r\n<li data-section-id=\"12a9mov\" data-start=\"3639\" data-end=\"3658\">Study materials</li>\r\n<li data-section-id=\"1f7qwlk\" data-start=\"3659\" data-end=\"3674\">Assignments</li>\r\n<li data-section-id=\"1iupgyi\" data-start=\"3675\" data-end=\"3692\">Announcements</li>\r\n<li data-section-id=\"1ick1y3\" data-start=\"3693\" data-end=\"3707\">Exam updates</li>\r\n</ul>', 1, '<p data-start=\"373\" data-end=\"745\">BBA (Bachelor of Business Administration) is one of the most popular undergraduate management programs for students who want early career exposure in business, marketing, finance, entrepreneurship, management, and corporate leadership. Before applying, students should clearly understand the latest BBA eligibility criteria, accepted qualifications, and admission rules.</p>\r\n<p data-start=\"747\" data-end=\"940\">The biggest advantage of BBA is that students from <strong data-start=\"798\" data-end=\"821\">any academic stream</strong> can usually apply. This makes it a flexible and career-oriented option for commerce, science, and arts students alike.</p>\r\n<p data-start=\"942\" data-end=\"1079\">This detailed guide explains complete BBA eligibility, who can apply, future career value, common mistakes, and smart admission strategy.</p>\r\n<hr data-start=\"1081\" data-end=\"1084\">\r\n<h1 data-section-id=\"ii7pve\" data-start=\"1086\" data-end=\"1121\">BBA Eligibility Criteria Overview</h1>\r\n<p data-start=\"1123\" data-end=\"1212\">Candidates are generally eligible for BBA admission if they meet the following condition:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1214\" data-end=\"1483\">\r\n<thead data-start=\"1214\" data-end=\"1250\">\r\n<tr data-start=\"1214\" data-end=\"1250\">\r\n<th class=\"\" data-start=\"1214\" data-end=\"1228\" data-col-size=\"md\">Requirement</th>\r\n<th class=\"\" data-start=\"1228\" data-end=\"1250\" data-col-size=\"sm\">Eligibility Status</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1261\" data-end=\"1483\">\r\n<tr data-start=\"1261\" data-end=\"1325\">\r\n<td data-start=\"1261\" data-end=\"1313\" data-col-size=\"md\">Passed 10+2 in any stream from a recognized board</td>\r\n<td data-col-size=\"sm\" data-start=\"1313\" data-end=\"1325\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1326\" data-end=\"1389\">\r\n<td data-start=\"1326\" data-end=\"1370\" data-col-size=\"md\">Appearing for Class 12 (where applicable)</td>\r\n<td data-col-size=\"sm\" data-start=\"1370\" data-end=\"1389\">May be Eligible</td>\r\n</tr>\r\n<tr data-start=\"1390\" data-end=\"1429\">\r\n<td data-start=\"1390\" data-end=\"1417\" data-col-size=\"md\">Equivalent qualification</td>\r\n<td data-col-size=\"sm\" data-start=\"1417\" data-end=\"1429\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1430\" data-end=\"1483\">\r\n<td data-start=\"1430\" data-end=\"1454\" data-col-size=\"md\">NIOS board candidates</td>\r\n<td data-col-size=\"sm\" data-start=\"1454\" data-end=\"1483\">Eligible (where accepted)</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1485\" data-end=\"1488\">\r\n<h1 data-section-id=\"1e13yky\" data-start=\"1490\" data-end=\"1531\">Minimum Qualification for BBA Admission</h1>\r\n<p data-start=\"1533\" data-end=\"1642\">Students should have completed <strong data-start=\"1564\" data-end=\"1586\">10+2 in any stream</strong> or an equivalent qualification from a recognized board.</p>\r\n<p data-start=\"1644\" data-end=\"1701\">This means students from the following streams can apply:</p>\r\n<ul data-start=\"1703\" data-end=\"1823\">\r\n<li data-section-id=\"v4h0lx\" data-start=\"1703\" data-end=\"1715\">Commerce</li>\r\n<li data-section-id=\"y83j8c\" data-start=\"1716\" data-end=\"1727\">Science</li>\r\n<li data-section-id=\"nmjua6\" data-start=\"1728\" data-end=\"1749\">Arts / Humanities</li>\r\n<li data-section-id=\"15nt8j1\" data-start=\"1750\" data-end=\"1772\">Vocational streams</li>\r\n<li data-section-id=\"1jg8qus\" data-start=\"1773\" data-end=\"1823\">Other equivalent senior secondary qualifications</li>\r\n</ul>\r\n<h3 data-section-id=\"mkcn1i\" data-start=\"1825\" data-end=\"1840\">Key Benefit</h3>\r\n<p data-start=\"1842\" data-end=\"1973\">Students do not need commerce background to pursue BBA. Even science and arts students can build careers in management through BBA.</p>\r\n<hr data-start=\"1975\" data-end=\"1978\">\r\n<h1 data-section-id=\"1jop22\" data-start=\"1980\" data-end=\"2024\">Can Appearing for Class 12 Students Apply?</h1>\r\n<p data-start=\"2026\" data-end=\"2170\">Many universities allow students who are <strong data-start=\"2067\" data-end=\"2093\">appearing for Class 12</strong> to apply, subject to final result submission within the prescribed timeline.</p>\r\n<p data-start=\"2172\" data-end=\"2248\">Students should check the latest admission rules at the time of application.</p>\r\n<hr data-start=\"2250\" data-end=\"2253\">\r\n<h1 data-section-id=\"1nhg85t\" data-start=\"2255\" data-end=\"2290\">Are NIOS Board Students Eligible?</h1>\r\n<p data-start=\"2292\" data-end=\"2429\">Yes, <strong data-start=\"2297\" data-end=\"2345\">NIOS board candidates are generally eligible</strong> when the qualification is recognized and accepted under university admission norms.</p>\r\n<hr data-start=\"2431\" data-end=\"2434\">\r\n<h1 data-section-id=\"1mrka60\" data-start=\"2436\" data-end=\"2464\">Why Choose BBA After 12th?</h1>\r\n<p data-start=\"2466\" data-end=\"2558\">BBA gives students an early start in business education compared to waiting until MBA stage.</p>\r\n<h3 data-section-id=\"1g98jhr\" data-start=\"2560\" data-end=\"2580\">Main Advantages:</h3>\r\n<ul data-start=\"2582\" data-end=\"2804\">\r\n<li data-section-id=\"asusfi\" data-start=\"2582\" data-end=\"2615\">Learn management skills early</li>\r\n<li data-section-id=\"19ruwvt\" data-start=\"2616\" data-end=\"2667\">Better communication and leadership development</li>\r\n<li data-section-id=\"17lvqc5\" data-start=\"2668\" data-end=\"2697\">Strong base for MBA later</li>\r\n<li data-section-id=\"4g7rst\" data-start=\"2698\" data-end=\"2740\">Internship and placement opportunities</li>\r\n<li data-section-id=\"9ned2e\" data-start=\"2741\" data-end=\"2776\">Career options after graduation</li>\r\n<li data-section-id=\"17jd67x\" data-start=\"2777\" data-end=\"2804\">Entrepreneurial knowledge</li>\r\n</ul>', '<p data-start=\"368\" data-end=\"715\">Choosing the right BBA program requires more than checking course subjects. Students should clearly understand the fee structure, payment flexibility, scholarship offers, and total affordability before taking admission. A transparent fee breakdown helps families plan budgets, compare colleges, and evaluate long-term return on investment (ROI).</p>\r\n<p data-start=\"717\" data-end=\"886\">This detailed guide explains the latest BBA semester fee, discounted payable amount, EMI options, student grant benefits, hidden charges, and smart admission strategies.</p>\r\n<hr data-start=\"888\" data-end=\"891\">\r\n<h1 data-section-id=\"1uznn6q\" data-start=\"893\" data-end=\"911\">BBA Fee Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"913\" data-end=\"1230\">\r\n<thead data-start=\"913\" data-end=\"939\">\r\n<tr data-start=\"913\" data-end=\"939\">\r\n<th class=\"\" data-start=\"913\" data-end=\"929\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"929\" data-end=\"939\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"951\" data-end=\"1230\">\r\n<tr data-start=\"951\" data-end=\"975\">\r\n<td data-start=\"951\" data-end=\"964\" data-col-size=\"sm\">Actual Fee</td>\r\n<td data-start=\"964\" data-end=\"975\" data-col-size=\"sm\">₹25,000</td>\r\n</tr>\r\n<tr data-start=\"976\" data-end=\"1017\">\r\n<td data-start=\"976\" data-end=\"993\" data-col-size=\"sm\">Applicable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"993\" data-end=\"1017\">₹20,400 per semester</td>\r\n</tr>\r\n<tr data-start=\"1018\" data-end=\"1041\">\r\n<td data-start=\"1018\" data-end=\"1034\" data-col-size=\"sm\">Student Grant</td>\r\n<td data-col-size=\"sm\" data-start=\"1034\" data-end=\"1041\">20%</td>\r\n</tr>\r\n<tr data-start=\"1042\" data-end=\"1092\">\r\n<td data-start=\"1042\" data-end=\"1069\" data-col-size=\"sm\">Examination Fee Included</td>\r\n<td data-col-size=\"sm\" data-start=\"1069\" data-end=\"1092\">₹2,000 per semester</td>\r\n</tr>\r\n<tr data-start=\"1093\" data-end=\"1139\">\r\n<td data-start=\"1093\" data-end=\"1112\" data-col-size=\"sm\">Registration Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1112\" data-end=\"1139\">₹1,000 (Non-refundable)</td>\r\n</tr>\r\n<tr data-start=\"1140\" data-end=\"1182\">\r\n<td data-start=\"1140\" data-end=\"1156\" data-col-size=\"sm\">Payment Modes</td>\r\n<td data-start=\"1156\" data-end=\"1182\" data-col-size=\"sm\">One-Time Payment / EMI</td>\r\n</tr>\r\n<tr data-start=\"1183\" data-end=\"1230\">\r\n<td data-start=\"1183\" data-end=\"1204\" data-col-size=\"sm\">Payment Preference</td>\r\n<td data-col-size=\"sm\" data-start=\"1204\" data-end=\"1230\">No-Cost EMI / Standard</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1232\" data-end=\"1235\">\r\n<h1 data-section-id=\"r8f7q9\" data-start=\"1237\" data-end=\"1275\">Current Discounted BBA Fee Structure</h1>\r\n<p data-start=\"1277\" data-end=\"1365\">Students can currently avail a <strong data-start=\"1308\" data-end=\"1329\">20% Student Grant</strong>, reducing the regular semester fee.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1367\" data-end=\"1510\">\r\n<thead data-start=\"1367\" data-end=\"1391\">\r\n<tr data-start=\"1367\" data-end=\"1391\">\r\n<th class=\"\" data-start=\"1367\" data-end=\"1381\" data-col-size=\"sm\">Particulars</th>\r\n<th class=\"\" data-start=\"1381\" data-end=\"1391\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1403\" data-end=\"1510\">\r\n<tr data-start=\"1403\" data-end=\"1438\">\r\n<td data-start=\"1403\" data-end=\"1427\" data-col-size=\"sm\">Original Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1427\" data-end=\"1438\">₹25,000</td>\r\n</tr>\r\n<tr data-start=\"1439\" data-end=\"1476\">\r\n<td data-start=\"1439\" data-end=\"1465\" data-col-size=\"sm\">Discounted Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1465\" data-end=\"1476\">₹20,400</td>\r\n</tr>\r\n<tr data-start=\"1477\" data-end=\"1510\">\r\n<td data-start=\"1477\" data-end=\"1500\" data-col-size=\"sm\">Savings Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"1500\" data-end=\"1510\">₹4,600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1512\" data-end=\"1588\"><strong data-start=\"1512\" data-end=\"1531\">Offer Validity:</strong> Till <strong data-start=\"1537\" data-end=\"1553\">9th May 2026</strong> (subject to terms and conditions).</p>\r\n<hr data-start=\"1590\" data-end=\"1593\">\r\n<h1 data-section-id=\"1da9b7l\" data-start=\"1595\" data-end=\"1624\">Amount Payable Per Semester</h1>\r\n<h2 data-section-id=\"1vzwcp3\" data-start=\"1626\" data-end=\"1647\">₹20,400 / Semester</h2>\r\n<p data-start=\"1649\" data-end=\"1714\">This is the current applicable semester fee after grant benefits.</p>\r\n<hr data-start=\"1716\" data-end=\"1719\">\r\n<h1 data-section-id=\"18kzs72\" data-start=\"1721\" data-end=\"1752\">Included and Excluded Charges</h1>\r\n<h2 data-section-id=\"c40zw2\" data-start=\"1754\" data-end=\"1781\">Included in Semester Fee</h2>\r\n<ul data-start=\"1783\" data-end=\"1868\">\r\n<li data-section-id=\"dhanzm\" data-start=\"1783\" data-end=\"1825\">Examination fee of ₹2,000 per semester</li>\r\n<li data-section-id=\"10nr766\" data-start=\"1826\" data-end=\"1868\">Academic tuition charges (as applicable)</li>\r\n</ul>\r\n<h2 data-section-id=\"ocwtce\" data-start=\"1870\" data-end=\"1889\">Excluded Charges</h2>\r\n<ul data-start=\"1891\" data-end=\"1990\">\r\n<li data-section-id=\"12c5wuz\" data-start=\"1891\" data-end=\"1946\">Initial registration fee of ₹1,000 (non-refundable)</li>\r\n<li data-section-id=\"1pe5f09\" data-start=\"1947\" data-end=\"1990\">Optional charges, if any applicable later</li>\r\n</ul>\r\n<hr data-start=\"1992\" data-end=\"1995\">\r\n<h1 data-section-id=\"1p7u5zq\" data-start=\"1997\" data-end=\"2030\">Eligible Countries for This Fee</h1>\r\n<p data-start=\"2032\" data-end=\"2080\">The above fee is applicable for applicants from:</p>\r\n<ul data-start=\"2082\" data-end=\"2155\">\r\n<li data-section-id=\"tgrdfn\" data-start=\"2082\" data-end=\"2091\">India</li>\r\n<li data-section-id=\"qjtdvt\" data-start=\"2092\" data-end=\"2105\">Sri Lanka</li>\r\n<li data-section-id=\"yxs3bg\" data-start=\"2106\" data-end=\"2116\">Bhutan</li>\r\n<li data-section-id=\"ef0w72\" data-start=\"2117\" data-end=\"2126\">Nepal</li>\r\n<li data-section-id=\"xi9ghh\" data-start=\"2127\" data-end=\"2141\">Bangladesh</li>\r\n<li data-section-id=\"1woqgfi\" data-start=\"2142\" data-end=\"2155\">Afghanistan</li>\r\n</ul>\r\n<hr data-start=\"2157\" data-end=\"2160\">\r\n<h1 data-section-id=\"x5a8d1\" data-start=\"2162\" data-end=\"2189\">Payment Options Available</h1>\r\n<p data-start=\"2191\" data-end=\"2271\">Students can choose payment options based on convenience and financial planning.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2273\" data-end=\"2493\">\r\n<thead data-start=\"2273\" data-end=\"2306\">\r\n<tr data-start=\"2273\" data-end=\"2306\">\r\n<th class=\"\" data-start=\"2273\" data-end=\"2290\" data-col-size=\"sm\">Payment Option</th>\r\n<th class=\"\" data-start=\"2290\" data-end=\"2306\" data-col-size=\"sm\">Suitable For</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2317\" data-end=\"2493\">\r\n<tr data-start=\"2317\" data-end=\"2372\">\r\n<td data-start=\"2317\" data-end=\"2331\" data-col-size=\"sm\">No-Cost EMI</td>\r\n<td data-col-size=\"sm\" data-start=\"2331\" data-end=\"2372\">Families wanting lower monthly burden</td>\r\n</tr>\r\n<tr data-start=\"2373\" data-end=\"2410\">\r\n<td data-start=\"2373\" data-end=\"2384\" data-col-size=\"sm\">Standard</td>\r\n<td data-col-size=\"sm\" data-start=\"2384\" data-end=\"2410\">Regular payment method</td>\r\n</tr>\r\n<tr data-start=\"2411\" data-end=\"2454\">\r\n<td data-start=\"2411\" data-end=\"2430\" data-col-size=\"sm\">One-Time Payment</td>\r\n<td data-col-size=\"sm\" data-start=\"2430\" data-end=\"2454\">Faster fee clearance</td>\r\n</tr>\r\n<tr data-start=\"2455\" data-end=\"2493\">\r\n<td data-start=\"2455\" data-end=\"2461\" data-col-size=\"sm\">EMI</td>\r\n<td data-start=\"2461\" data-end=\"2493\" data-col-size=\"sm\">Flexible installment payment&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', 'Medium', '<p data-start=\"372\" data-end=\"760\">The BBA (Bachelor of Business Administration) syllabus is designed to build strong business fundamentals, management understanding, communication skills, leadership ability, and practical corporate knowledge. It is one of the most preferred undergraduate management programs for students who want careers in marketing, finance, HR, operations, entrepreneurship, and business management.</p>\r\n<p data-start=\"762\" data-end=\"992\">A strong BBA curriculum gradually develops students from beginners into industry-ready professionals by combining management theory, accounting knowledge, communication skills, business law, projects, and specialization electives.</p>\r\n<p data-start=\"994\" data-end=\"1173\">This detailed semester-wise BBA syllabus helps students understand what they will study, what skills they will gain, and how each semester supports future jobs or MBA preparation.</p>\r\n<hr data-start=\"1175\" data-end=\"1178\">\r\n<h1 data-section-id=\"1vtp3zg\" data-start=\"1180\" data-end=\"1211\">BBA Course Structure Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1213\" data-end=\"1447\">\r\n<thead data-start=\"1213\" data-end=\"1234\">\r\n<tr data-start=\"1213\" data-end=\"1234\">\r\n<th class=\"\" data-start=\"1213\" data-end=\"1220\" data-col-size=\"sm\">Year</th>\r\n<th class=\"\" data-start=\"1220\" data-end=\"1234\" data-col-size=\"md\">Focus Area</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1245\" data-end=\"1447\">\r\n<tr data-start=\"1245\" data-end=\"1304\">\r\n<td data-start=\"1245\" data-end=\"1258\" data-col-size=\"sm\">First Year</td>\r\n<td data-col-size=\"md\" data-start=\"1258\" data-end=\"1304\">Business basics, communication, accounting</td>\r\n</tr>\r\n<tr data-start=\"1305\" data-end=\"1374\">\r\n<td data-start=\"1305\" data-end=\"1319\" data-col-size=\"sm\">Second Year</td>\r\n<td data-start=\"1319\" data-end=\"1374\" data-col-size=\"md\">Marketing, finance, law, projects, practical skills</td>\r\n</tr>\r\n<tr data-start=\"1375\" data-end=\"1447\">\r\n<td data-start=\"1375\" data-end=\"1388\" data-col-size=\"sm\">Final Year</td>\r\n<td data-start=\"1388\" data-end=\"1447\" data-col-size=\"md\">Specialization, e-commerce, electives, career readiness</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1449\" data-end=\"1452\">\r\n<h1 data-section-id=\"1l7ya9a\" data-start=\"1454\" data-end=\"1482\">BBA Semester Wise Syllabus</h1>\r\n<h2 data-section-id=\"1eqx326\" data-start=\"1484\" data-end=\"1519\">Semester 1: Business Foundations</h2>\r\n<p data-start=\"1521\" data-end=\"1643\">The first semester builds a basic understanding of business systems, management concepts, communication, and office tools.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1645\" data-end=\"1886\">\r\n<thead data-start=\"1645\" data-end=\"1676\">\r\n<tr data-start=\"1645\" data-end=\"1676\">\r\n<th class=\"\" data-start=\"1645\" data-end=\"1660\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"1660\" data-end=\"1676\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1687\" data-end=\"1886\">\r\n<tr data-start=\"1687\" data-end=\"1719\">\r\n<td data-start=\"1687\" data-end=\"1697\" data-col-size=\"sm\">EECO113</td>\r\n<td data-start=\"1697\" data-end=\"1719\" data-col-size=\"sm\">Business Economics</td>\r\n</tr>\r\n<tr data-start=\"1720\" data-end=\"1754\">\r\n<td data-start=\"1720\" data-end=\"1730\" data-col-size=\"sm\">EMGN303</td>\r\n<td data-start=\"1730\" data-end=\"1754\" data-col-size=\"sm\">Business Environment</td>\r\n</tr>\r\n<tr data-start=\"1755\" data-end=\"1805\">\r\n<td data-start=\"1755\" data-end=\"1765\" data-col-size=\"sm\">EMGN101</td>\r\n<td data-col-size=\"sm\" data-start=\"1765\" data-end=\"1805\">Business Organisation and Management</td>\r\n</tr>\r\n<tr data-start=\"1806\" data-end=\"1843\">\r\n<td data-start=\"1806\" data-end=\"1816\" data-col-size=\"sm\">ECAP279</td>\r\n<td data-start=\"1816\" data-end=\"1843\" data-col-size=\"sm\">Office Automation Tools</td>\r\n</tr>\r\n<tr data-start=\"1844\" data-end=\"1886\">\r\n<td data-start=\"1844\" data-end=\"1854\" data-col-size=\"sm\">EENG139</td>\r\n<td data-col-size=\"sm\" data-start=\"1854\" data-end=\"1886\">English Communication Skills</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"1888\" data-end=\"1908\">Skills Developed</h3>\r\n<ul data-start=\"1910\" data-end=\"2037\">\r\n<li data-section-id=\"7jrv2d\" data-start=\"1910\" data-end=\"1932\">Business awareness</li>\r\n<li data-section-id=\"zg6qr6\" data-start=\"1933\" data-end=\"1954\">Management basics</li>\r\n<li data-section-id=\"1rb2jty\" data-start=\"1955\" data-end=\"1981\">MS Office productivity</li>\r\n<li data-section-id=\"1w5bxb7\" data-start=\"1982\" data-end=\"2012\">Professional communication</li>\r\n<li data-section-id=\"1xmxdk3\" data-start=\"2013\" data-end=\"2037\">Economic understanding</li>\r\n</ul>\r\n<hr data-start=\"2039\" data-end=\"2042\">\r\n<h2 data-section-id=\"e8tqsy\" data-start=\"2044\" data-end=\"2082\">Semester 2: Ethics, HR &amp; Accounting</h2>\r\n<p data-start=\"2084\" data-end=\"2185\">The second semester introduces ethics, people management, finance basics, and advanced communication.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2187\" data-end=\"2422\">\r\n<thead data-start=\"2187\" data-end=\"2218\">\r\n<tr data-start=\"2187\" data-end=\"2218\">\r\n<th class=\"\" data-start=\"2187\" data-end=\"2202\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2202\" data-end=\"2218\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2229\" data-end=\"2422\">\r\n<tr data-start=\"2229\" data-end=\"2258\">\r\n<td data-start=\"2229\" data-end=\"2239\" data-col-size=\"sm\">EMGN253</td>\r\n<td data-col-size=\"sm\" data-start=\"2239\" data-end=\"2258\">Business Ethics</td>\r\n</tr>\r\n<tr data-start=\"2259\" data-end=\"2298\">\r\n<td data-start=\"2259\" data-end=\"2269\" data-col-size=\"sm\">EHRM101</td>\r\n<td data-start=\"2269\" data-end=\"2298\" data-col-size=\"sm\">Human Resource Management</td>\r\n</tr>\r\n<tr data-start=\"2299\" data-end=\"2333\">\r\n<td data-start=\"2299\" data-end=\"2309\" data-col-size=\"sm\">EACC105</td>\r\n<td data-col-size=\"sm\" data-start=\"2309\" data-end=\"2333\">Financial Accounting</td>\r\n</tr>\r\n<tr data-start=\"2334\" data-end=\"2370\">\r\n<td data-start=\"2334\" data-end=\"2344\" data-col-size=\"sm\">ECHE110</td>\r\n<td data-col-size=\"sm\" data-start=\"2344\" data-end=\"2370\">Environmental Sciences</td>\r\n</tr>\r\n<tr data-start=\"2371\" data-end=\"2422\">\r\n<td data-start=\"2371\" data-end=\"2381\" data-col-size=\"sm\">EENG140</td>\r\n<td data-start=\"2381\" data-end=\"2422\" data-col-size=\"sm\">Advanced English Communication Skills</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"7zaalc\" data-start=\"2424\" data-end=\"2453\">Why This Semester Matters</h3>\r\n<p data-start=\"2455\" data-end=\"2541\">Students begin learning how companies manage people, money, and responsible practices.</p>\r\n<hr data-start=\"2543\" data-end=\"2546\">\r\n<h2 data-section-id=\"xf0zbx\" data-start=\"2548\" data-end=\"2604\">Semester 3: Marketing, Analytics &amp; Community Learning</h2>\r\n<p data-start=\"2606\" data-end=\"2703\">This semester focuses on marketing, business research, statistics, costing, and applied learning.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2705\" data-end=\"3010\">\r\n<thead data-start=\"2705\" data-end=\"2736\">\r\n<tr data-start=\"2705\" data-end=\"2736\">\r\n<th class=\"\" data-start=\"2705\" data-end=\"2720\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2720\" data-end=\"2736\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2747\" data-end=\"3010\">\r\n<tr data-start=\"2747\" data-end=\"2784\">\r\n<td data-start=\"2747\" data-end=\"2757\" data-col-size=\"sm\">EMKT201</td>\r\n<td data-start=\"2757\" data-end=\"2784\" data-col-size=\"md\">Principles of Marketing</td>\r\n</tr>\r\n<tr data-start=\"2785\" data-end=\"2819\">\r\n<td data-start=\"2785\" data-end=\"2795\" data-col-size=\"sm\">EMGN206</td>\r\n<td data-start=\"2795\" data-end=\"2819\" data-col-size=\"md\">Research Methodology</td>\r\n</tr>\r\n<tr data-start=\"2820\" data-end=\"2869\">\r\n<td data-start=\"2820\" data-end=\"2830\" data-col-size=\"sm\">EQTT201</td>\r\n<td data-start=\"2830\" data-end=\"2869\" data-col-size=\"md\">Business Mathematics and Statistics</td>\r\n</tr>\r\n<tr data-start=\"2870\" data-end=\"2914\">\r\n<td data-start=\"2870\" data-end=\"2880\" data-col-size=\"sm\">EACC205</td>\r\n<td data-start=\"2880\" data-end=\"2914\" data-col-size=\"md\">Cost and Management Accounting</td>\r\n</tr>\r\n<tr data-start=\"2915\" data-end=\"2944\">\r\n<td data-start=\"2915\" data-end=\"2922\" data-col-size=\"sm\">GE-I</td>\r\n<td data-col-size=\"md\" data-start=\"2922\" data-end=\"2944\">Generic Elective I</td>\r\n</tr>\r\n<tr data-start=\"2945\" data-end=\"3010\">\r\n<td data-start=\"2945\" data-end=\"2955\" data-col-size=\"sm\">EMGN231</td>\r\n<td data-start=\"2955\" data-end=\"3010\" data-col-size=\"md\">Community Development Project / EPES201 Soft Skills</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"3012\" data-end=\"3032\">Skills Developed</h3>\r\n<ul data-start=\"3034\" data-end=\"3158\">\r\n<li data-section-id=\"b6emam\" data-start=\"3034\" data-end=\"3063\">Marketing strategy basics</li>\r\n<li data-section-id=\"1c4xxyv\" data-start=\"3064\" data-end=\"3088\">Research and surveys</li>\r\n<li data-section-id=\"o8l9bo\" data-start=\"3089\" data-end=\"3114\">Business calculations</li>\r\n<li data-section-id=\"uck381\" data-start=\"3115\" data-end=\"3132\">Cost analysis</li>\r\n<li data-section-id=\"b6npuv\" data-start=\"3133\" data-end=\"3158\">Personality development</li>\r\n</ul>\r\n<hr data-start=\"3160\" data-end=\"3163\">\r\n<h2 data-section-id=\"1xau1d5\" data-start=\"3165\" data-end=\"3207\">Semester 4: Law, Finance &amp; Project Work</h2>\r\n<p data-start=\"3209\" data-end=\"3307\">Students gain financial management knowledge, legal understanding, and practical project exposure.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3309\" data-end=\"3592\">\r\n<thead data-start=\"3309\" data-end=\"3340\">\r\n<tr data-start=\"3309\" data-end=\"3340\">\r\n<th class=\"\" data-start=\"3309\" data-end=\"3324\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3324\" data-end=\"3340\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3351\" data-end=\"3592\">\r\n<tr data-start=\"3351\" data-end=\"3377\">\r\n<td data-start=\"3351\" data-end=\"3361\" data-col-size=\"sm\">EBSL101</td>\r\n<td data-col-size=\"sm\" data-start=\"3361\" data-end=\"3377\">Business Law</td>\r\n</tr>\r\n<tr data-start=\"3378\" data-end=\"3428\">\r\n<td data-start=\"3378\" data-end=\"3388\" data-col-size=\"sm\">EFIN302</td>\r\n<td data-start=\"3388\" data-end=\"3428\" data-col-size=\"sm\">Fundamentals of Financial Management</td>\r\n</tr>\r\n<tr data-start=\"3429\" data-end=\"3460\">\r\n<td data-start=\"3429\" data-end=\"3437\" data-col-size=\"sm\">GE-II</td>\r\n<td data-start=\"3437\" data-end=\"3460\" data-col-size=\"sm\">Generic Elective II</td>\r\n</tr>\r\n<tr data-start=\"3461\" data-end=\"3499\">\r\n<td data-start=\"3461\" data-end=\"3469\" data-col-size=\"sm\">SEC-I</td>\r\n<td data-start=\"3469\" data-end=\"3499\" data-col-size=\"sm\">Skill Enhancement Course I</td>\r\n</tr>\r\n<tr data-start=\"3500\" data-end=\"3540\">\r\n<td data-start=\"3500\" data-end=\"3509\" data-col-size=\"sm\">SEC-II</td>\r\n<td data-col-size=\"sm\" data-start=\"3509\" data-end=\"3540\">Skill Enhancement Course II</td>\r\n</tr>\r\n<tr data-start=\"3541\" data-end=\"3592\">\r\n<td data-start=\"3541\" data-end=\"3551\" data-col-size=\"sm\">EMGN219</td>\r\n<td data-col-size=\"sm\" data-start=\"3551\" data-end=\"3592\">Project / Alternate GE Basket Courses</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"4dm6cm\" data-start=\"3594\" data-end=\"3625\">Why Semester 4 is Important</h3>\r\n<p data-start=\"3627\" data-end=\"3691\">Finance + law + project work creates strong employability value.</p>\r\n<hr data-start=\"3693\" data-end=\"3696\">\r\n<h2 data-section-id=\"1jotqtb\" data-start=\"3698\" data-end=\"3734\">Semester 5: Specialization Begins</h2>\r\n<p data-start=\"3736\" data-end=\"3827\">The fifth semester focuses on discipline-specific electives and research-oriented learning.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3829\" data-end=\"4082\">\r\n<thead data-start=\"3829\" data-end=\"3860\">\r\n<tr data-start=\"3829\" data-end=\"3860\">\r\n<th class=\"\" data-start=\"3829\" data-end=\"3844\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3844\" data-end=\"3860\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3871\" data-end=\"4082\">\r\n<tr data-start=\"3871\" data-end=\"3913\">\r\n<td data-start=\"3871\" data-end=\"3879\" data-col-size=\"sm\">DSE-I</td>\r\n<td data-start=\"3879\" data-end=\"3913\" data-col-size=\"sm\">Discipline Specific Elective I</td>\r\n</tr>\r\n<tr data-start=\"3914\" data-end=\"3958\">\r\n<td data-start=\"3914\" data-end=\"3923\" data-col-size=\"sm\">DSE-II</td>\r\n<td data-start=\"3923\" data-end=\"3958\" data-col-size=\"sm\">Discipline Specific Elective II</td>\r\n</tr>\r\n<tr data-start=\"3959\" data-end=\"3992\">\r\n<td data-start=\"3959\" data-end=\"3968\" data-col-size=\"sm\">GE-III</td>\r\n<td data-start=\"3968\" data-end=\"3992\" data-col-size=\"sm\">Generic Elective III</td>\r\n</tr>\r\n<tr data-start=\"3993\" data-end=\"4035\">\r\n<td data-start=\"3993\" data-end=\"4003\" data-col-size=\"sm\">SEC-III</td>\r\n<td data-start=\"4003\" data-end=\"4035\" data-col-size=\"sm\">Skill Enhancement Course III</td>\r\n</tr>\r\n<tr data-start=\"4036\" data-end=\"4082\">\r\n<td data-start=\"4036\" data-end=\"4046\" data-col-size=\"sm\">EMGN236</td>\r\n<td data-col-size=\"sm\" data-start=\"4046\" data-end=\"4082\">Term Paper / Alternate GE Course</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1l6ceg0\" data-start=\"4084\" data-end=\"4112\">Importance of Semester 5</h3>\r\n<p data-start=\"4114\" data-end=\"4160\">Elective choices often shape career direction.</p>\r\n<hr data-start=\"4162\" data-end=\"4165\">\r\n<h2 data-section-id=\"11miq96\" data-start=\"4167\" data-end=\"4217\">Semester 6: E-Commerce &amp; Final Career Readiness</h2>\r\n<p data-start=\"4219\" data-end=\"4313\">The final semester develops digital business understanding and advanced specialization skills.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"4315\" data-end=\"4560\">\r\n<thead data-start=\"4315\" data-end=\"4346\">\r\n<tr data-start=\"4315\" data-end=\"4346\">\r\n<th class=\"\" data-start=\"4315\" data-end=\"4330\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"4330\" data-end=\"4346\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"4357\" data-end=\"4560\">\r\n<tr data-start=\"4357\" data-end=\"4381\">\r\n<td data-start=\"4357\" data-end=\"4367\" data-col-size=\"sm\">EMGN358</td>\r\n<td data-col-size=\"sm\" data-start=\"4367\" data-end=\"4381\">E-commerce</td>\r\n</tr>\r\n<tr data-start=\"4382\" data-end=\"4427\">\r\n<td data-start=\"4382\" data-end=\"4404\" data-col-size=\"sm\">Generic Elective IV</td>\r\n<td data-col-size=\"sm\" data-start=\"4404\" data-end=\"4427\">Generic Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4428\" data-end=\"4474\">\r\n<td data-start=\"4428\" data-end=\"4438\" data-col-size=\"sm\">DSE-III</td>\r\n<td data-col-size=\"sm\" data-start=\"4438\" data-end=\"4474\">Discipline Specific Elective III</td>\r\n</tr>\r\n<tr data-start=\"4475\" data-end=\"4519\">\r\n<td data-start=\"4475\" data-end=\"4484\" data-col-size=\"sm\">DSE-IV</td>\r\n<td data-start=\"4484\" data-end=\"4519\" data-col-size=\"sm\">Discipline Specific Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4520\" data-end=\"4560\">\r\n<td data-start=\"4520\" data-end=\"4529\" data-col-size=\"sm\">SEC-IV</td>\r\n<td data-col-size=\"sm\" data-start=\"4529\" data-end=\"4560\">Skill Enhancement Course IV</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1oqapdp\" data-start=\"4562\" data-end=\"4588\">Why E-commerce Matters</h3>\r\n<p data-start=\"4590\" data-end=\"4685\">Modern businesses rely heavily on digital commerce, marketplaces, and online growth strategies.</p>\r\n<hr data-start=\"4687\" data-end=\"4690\">\r\n<h1 data-section-id=\"1ue5hih\" data-start=\"4692\" data-end=\"4726\">Popular BBA Specialization Areas</h1>\r\n<p data-start=\"4728\" data-end=\"4779\">Depending on elective options, students may choose:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"4781\" data-end=\"5096\">\r\n<thead data-start=\"4781\" data-end=\"4814\">\r\n<tr data-start=\"4781\" data-end=\"4814\">\r\n<th class=\"\" data-start=\"4781\" data-end=\"4798\" data-col-size=\"sm\">Specialization</th>\r\n<th class=\"\" data-start=\"4798\" data-end=\"4814\" data-col-size=\"sm\">Career Scope</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"4825\" data-end=\"5096\">\r\n<tr data-start=\"4825\" data-end=\"4875\">\r\n<td data-start=\"4825\" data-end=\"4837\" data-col-size=\"sm\">Marketing</td>\r\n<td data-col-size=\"sm\" data-start=\"4837\" data-end=\"4875\">Sales, branding, digital marketing</td>\r\n</tr>\r\n<tr data-start=\"4876\" data-end=\"4924\">\r\n<td data-start=\"4876\" data-end=\"4886\" data-col-size=\"sm\">Finance</td>\r\n<td data-start=\"4886\" data-end=\"4924\" data-col-size=\"sm\">Banking, accounting, analyst roles</td>\r\n</tr>\r\n<tr data-start=\"4925\" data-end=\"4964\">\r\n<td data-start=\"4925\" data-end=\"4930\" data-col-size=\"sm\">HR</td>\r\n<td data-col-size=\"sm\" data-start=\"4930\" data-end=\"4964\">Recruitment, talent management</td>\r\n</tr>\r\n<tr data-start=\"4965\" data-end=\"5015\">\r\n<td data-start=\"4965\" data-end=\"4990\" data-col-size=\"sm\">International Business</td>\r\n<td data-col-size=\"sm\" data-start=\"4990\" data-end=\"5015\">Export/import careers</td>\r\n</tr>\r\n<tr data-start=\"5016\" data-end=\"5056\">\r\n<td data-start=\"5016\" data-end=\"5029\" data-col-size=\"sm\">Operations</td>\r\n<td data-col-size=\"sm\" data-start=\"5029\" data-end=\"5056\">Supply chain, logistics</td>\r\n</tr>\r\n<tr data-start=\"5057\" data-end=\"5096\">\r\n<td data-start=\"5057\" data-end=\"5076\" data-col-size=\"sm\">Entrepreneurship</td>\r\n<td data-col-size=\"sm\" data-start=\"5076\" data-end=\"5096\">Startup building</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', NULL, '<p data-start=\"381\" data-end=\"660\">Placement support is one of the biggest factors students consider before choosing a BBA program. Since BBA is a career-oriented management degree, students expect not only academic learning but also real career opportunities, industry exposure, and professional growth support.</p>\r\n<p data-start=\"662\" data-end=\"937\"><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Lovely Professional University</span></span> Online offers placement support services designed to enhance students&rsquo; capabilities according to industry requirements, create career awareness, and motivate learners to develop additional employability skills beyond their core subjects.</p>\r\n<p data-start=\"939\" data-end=\"1094\">Through placement drives and career-focused initiatives, students can interact with recruiters, showcase their skills, and compete for promising job roles.</p>\r\n<p data-start=\"1096\" data-end=\"1239\">This guide explains BBA placement support, LPU Online career services, ROI value, career opportunities, and how students can maximize outcomes.</p>\r\n<hr data-start=\"1241\" data-end=\"1244\">\r\n<h1 data-section-id=\"1dvxdpq\" data-start=\"1246\" data-end=\"1294\">Why Placement Support Matters for BBA Students</h1>\r\n<p data-start=\"1296\" data-end=\"1334\">BBA students often aim for careers in:</p>\r\n<ul data-start=\"1336\" data-end=\"1458\">\r\n<li data-section-id=\"m6xjvw\" data-start=\"1336\" data-end=\"1349\">Marketing</li>\r\n<li data-section-id=\"1nwwpym\" data-start=\"1350\" data-end=\"1369\">Human Resources</li>\r\n<li data-section-id=\"1spyjc0\" data-start=\"1370\" data-end=\"1379\">Sales</li>\r\n<li data-section-id=\"4j8zvz\" data-start=\"1380\" data-end=\"1399\">Finance support</li>\r\n<li data-section-id=\"nyjb7y\" data-start=\"1400\" data-end=\"1414\">Operations</li>\r\n<li data-section-id=\"1mmgc6h\" data-start=\"1415\" data-end=\"1435\">Entrepreneurship</li>\r\n<li data-section-id=\"de0rj1\" data-start=\"1436\" data-end=\"1458\">Business development</li>\r\n</ul>\r\n<p data-start=\"1460\" data-end=\"1528\">However, recruiters usually look beyond degrees. They also evaluate:</p>\r\n<ul data-start=\"1530\" data-end=\"1658\">\r\n<li data-section-id=\"1mfo8p6\" data-start=\"1530\" data-end=\"1554\">Communication skills</li>\r\n<li data-section-id=\"yojgng\" data-start=\"1555\" data-end=\"1569\">Confidence</li>\r\n<li data-section-id=\"1pcanhh\" data-start=\"1570\" data-end=\"1589\">Problem solving</li>\r\n<li data-section-id=\"1qe7zuk\" data-start=\"1590\" data-end=\"1614\">Presentation ability</li>\r\n<li data-section-id=\"7jrv2d\" data-start=\"1615\" data-end=\"1637\">Business awareness</li>\r\n<li data-section-id=\"1yhs4vn\" data-start=\"1638\" data-end=\"1658\">Practical attitude</li>\r\n</ul>\r\n<p data-start=\"1660\" data-end=\"1709\">Placement support helps students bridge this gap.</p>\r\n<hr data-start=\"1711\" data-end=\"1714\">\r\n<h1 data-section-id=\"1bcaiax\" data-start=\"1716\" data-end=\"1759\">LPU Online BBA Placement Support Services</h1>\r\n<h2 data-section-id=\"18k74lo\" data-start=\"1761\" data-end=\"1783\">1. Placement Drives</h2>\r\n<p data-start=\"1785\" data-end=\"1894\">Placement drives create opportunities for students to interact directly with hiring companies and recruiters.</p>\r\n<h3 data-section-id=\"1iaul7c\" data-start=\"1896\" data-end=\"1909\">Benefits:</h3>\r\n<ul data-start=\"1911\" data-end=\"2044\">\r\n<li data-section-id=\"1ba7iat\" data-start=\"1911\" data-end=\"1934\">Direct job openings</li>\r\n<li data-section-id=\"1n7nkqq\" data-start=\"1935\" data-end=\"1957\">Recruiter exposure</li>\r\n<li data-section-id=\"gsbjid\" data-start=\"1958\" data-end=\"1987\">Real interview experience</li>\r\n<li data-section-id=\"1xisyh5\" data-start=\"1988\" data-end=\"2022\">Faster placement opportunities</li>\r\n<li data-section-id=\"olgn8y\" data-start=\"2023\" data-end=\"2044\">Networking benefits</li>\r\n</ul>\r\n<hr data-start=\"2046\" data-end=\"2049\">\r\n<h2 data-section-id=\"zmp5s0\" data-start=\"2051\" data-end=\"2084\">2. Career Guidance &amp; Awareness</h2>\r\n<p data-start=\"2086\" data-end=\"2191\">Many students complete graduation without career clarity. Placement support can help learners understand:</p>\r\n<ul data-start=\"2193\" data-end=\"2319\">\r\n<li data-section-id=\"kwb7fw\" data-start=\"2193\" data-end=\"2214\">Job market demand</li>\r\n<li data-section-id=\"8556gw\" data-start=\"2215\" data-end=\"2241\">Best entry-level roles</li>\r\n<li data-section-id=\"1lfq7n7\" data-start=\"2242\" data-end=\"2265\">Salary growth paths</li>\r\n<li data-section-id=\"1isgmgt\" data-start=\"2266\" data-end=\"2291\">Skill gaps to improve</li>\r\n<li data-section-id=\"17awifm\" data-start=\"2292\" data-end=\"2319\">Career planning after BBA</li>\r\n</ul>\r\n<hr data-start=\"2321\" data-end=\"2324\">\r\n<h2 data-section-id=\"eyxhxz\" data-start=\"2326\" data-end=\"2356\">3. Add-On Skill Development</h2>\r\n<p data-start=\"2358\" data-end=\"2466\">Modern hiring requires skills beyond academics. Students are encouraged to build extra capabilities such as:</p>\r\n<ul data-start=\"2468\" data-end=\"2630\">\r\n<li data-section-id=\"1mfo8p6\" data-start=\"2468\" data-end=\"2492\">Communication skills</li>\r\n<li data-section-id=\"1nzdt2d\" data-start=\"2493\" data-end=\"2517\">Interview confidence</li>\r\n<li data-section-id=\"100ww9o\" data-start=\"2518\" data-end=\"2541\">Presentation skills</li>\r\n<li data-section-id=\"iun1jq\" data-start=\"2542\" data-end=\"2558\">Excel basics</li>\r\n<li data-section-id=\"ca8xhb\" data-start=\"2559\" data-end=\"2587\">Digital marketing basics</li>\r\n<li data-section-id=\"1uh3hqe\" data-start=\"2588\" data-end=\"2607\">Team management</li>\r\n<li data-section-id=\"3tuzx6\" data-start=\"2608\" data-end=\"2630\">Leadership qualities</li>\r\n</ul>\r\n<hr data-start=\"2632\" data-end=\"2635\">\r\n<h2 data-section-id=\"yd933a\" data-start=\"2637\" data-end=\"2669\">4. Resume &amp; Interview Support</h2>\r\n<p data-start=\"2671\" data-end=\"2733\">Students often need help presenting themselves professionally.</p>\r\n<h3 data-section-id=\"5f2soq\" data-start=\"2735\" data-end=\"2759\">Support May Include:</h3>\r\n<ul data-start=\"2761\" data-end=\"2886\">\r\n<li data-section-id=\"1hew0fb\" data-start=\"2761\" data-end=\"2780\">Resume building</li>\r\n<li data-section-id=\"odu82\" data-start=\"2781\" data-end=\"2809\">HR interview preparation</li>\r\n<li data-section-id=\"hg8gpk\" data-start=\"2810\" data-end=\"2829\">Mock interviews</li>\r\n<li data-section-id=\"zm06bw\" data-start=\"2830\" data-end=\"2859\">Group discussion practice</li>\r\n<li data-section-id=\"824a0y\" data-start=\"2860\" data-end=\"2886\">Personal branding basics</li>\r\n</ul>\r\n<hr data-start=\"2888\" data-end=\"2891\">\r\n<h1 data-section-id=\"bq2d43\" data-start=\"2893\" data-end=\"2919\">Best Job Roles After BBA</h1>\r\n<p data-start=\"2921\" data-end=\"2992\">Depending on student skills and performance, opportunities may include:</p>\r\n<ul data-start=\"2994\" data-end=\"3389\">\r\n<li data-section-id=\"1jq1ghb\" data-start=\"2994\" data-end=\"3047\"><strong data-start=\"2996\" data-end=\"3019\">Marketing Executive</strong> &ndash; Branding and promotions</li>\r\n<li data-section-id=\"131p5c8\" data-start=\"3048\" data-end=\"3098\"><strong data-start=\"3050\" data-end=\"3069\">Sales Executive</strong> &ndash; Revenue generation roles</li>\r\n<li data-section-id=\"oeahyz\" data-start=\"3099\" data-end=\"3154\"><strong data-start=\"3101\" data-end=\"3117\">HR Executive</strong> &ndash; Recruitment and employee support</li>\r\n<li data-section-id=\"17u0jtq\" data-start=\"3155\" data-end=\"3222\"><strong data-start=\"3157\" data-end=\"3191\">Business Development Executive</strong> &ndash; Lead generation and growth</li>\r\n<li data-section-id=\"mpxu82\" data-start=\"3223\" data-end=\"3278\"><strong data-start=\"3225\" data-end=\"3249\">Operations Executive</strong> &ndash; Process management roles</li>\r\n<li data-section-id=\"1ej4wga\" data-start=\"3279\" data-end=\"3341\"><strong data-start=\"3281\" data-end=\"3316\">Customer Relationship Executive</strong> &ndash; Client support roles</li>\r\n<li data-section-id=\"1gnb8ar\" data-start=\"3342\" data-end=\"3389\"><strong data-start=\"3344\" data-end=\"3360\">Entrepreneur</strong> &ndash; Start own business venture</li>\r\n</ul>', NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 75000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
INSERT INTO `organisation_courses` (`id`, `organisation_id`, `campus_id`, `department_id`, `course_id`, `academic_unit_name`, `slug`, `entrance_exam_id`, `entrance_exam_ids`, `entrance_exam_category`, `mode`, `fees`, `duration`, `status`, `sort_order`, `created_at`, `updated_at`, `admission_process`, `provisional_admission`, `eligibility`, `fees_structure`, `roi`, `curriculum`, `career_prospects`, `placement_details`, `program_level_id`, `stream_offered_id`, `discipline_id`, `specialization_id`, `specialization_ids`, `rating`, `industrial_collaboration`, `internship_ranking`, `course_languages`, `total_fees`, `school_type`, `education_board`, `board_affiliation_number`, `affiliation_valid_from`, `affiliation_valid_to`, `medium_of_instruction`, `grade_range`, `streams_offered`, `student_strength`, `total_teachers`, `trained_teachers_percentage`, `student_teacher_ratio`, `special_educator_available`, `school_counsellor_available`, `average_class_size`, `assessment_pattern`, `homework_policy`, `parent_teacher_meet_frequency`, `remedial_classes_available`, `board_result_classes`, `average_board_result_percentage`, `highest_score`, `distinction_percentage`, `olympiad_participation`, `competitive_exam_preparation_support`, `annual_fee_range`, `admission_fee`, `transport_fee`, `hostel_fee`, `fee_payment_frequency`, `parent_app_available`, `attendance_tracking_available`, `sports_offered`, `arts_music_programs_available`, `clubs_and_societies`, `annual_events`, `delivery_mode`, `integrated_schooling_available`, `total_batches`, `average_batch_size`, `min_batch_size`, `max_batch_size`, `separate_batches_for_droppers`, `merit_based_batching`, `total_faculty_count`, `senior_faculty_count`, `average_faculty_experience_years`, `full_time_faculty_percentage`, `visiting_faculty_available`, `doubt_solving_mode`, `personal_mentorship_available`, `extra_classes_for_weak_students`, `parent_counselling_available`, `study_material_type`, `dpp_provided`, `test_series_available`, `tests_per_month`, `full_syllabus_tests_count`, `online_test_platform_available`, `results_years_available`, `total_selections_all_time`, `selections_last_year`, `highest_rank_achieved`, `average_selection_rate`, `result_verification_status`, `average_course_fee_range`, `installment_available`, `scholarship_available`, `refund_policy_available`, `verified_reviews_only`, `meta_title`, `meta_description`) VALUES
(233, 69, 'd67d3d73-4a79-4175-89f0-c61979138bac', '956f52ba-dcf0-4224-9a30-f9f785980fe3', 39, NULL, NULL, NULL, NULL, NULL, 'ONLINE', NULL, NULL, 1, 0, '2026-05-01 03:53:29', '2026-06-16 06:06:16', '<p data-start=\"354\" data-end=\"606\">Getting admission into an online degree program is now simple, fast, and fully digital. Students can complete registration, submit the application form, upload documents, pay fees, and receive final admission confirmation without visiting the campus.</p>\r\n<p data-start=\"608\" data-end=\"776\">Whether you are applying for BBA, BCA, MBA, MCA, BA, or other online programs, understanding the admission process helps avoid delays, mistakes, and last-minute stress.</p>\r\n<p data-start=\"778\" data-end=\"933\">This guide explains each stage of the online admission process, required documents, expert tips, common mistakes, and smart strategies for faster approval.</p>\r\n<hr data-start=\"935\" data-end=\"938\">\r\n<h1 data-section-id=\"6ukf47\" data-start=\"940\" data-end=\"968\">Admission Process Overview</h1>\r\n<p data-start=\"970\" data-end=\"1036\">The online admission process generally includes four major stages:</p>\r\n<ol data-start=\"1038\" data-end=\"1168\">\r\n<li data-section-id=\"nl6le3\" data-start=\"1038\" data-end=\"1055\">Registration</li>\r\n<li data-section-id=\"ylnmm2\" data-start=\"1056\" data-end=\"1084\">Online Application Form</li>\r\n<li data-section-id=\"101zuxd\" data-start=\"1085\" data-end=\"1125\">Document Verification by University</li>\r\n<li data-section-id=\"19bjzt6\" data-start=\"1126\" data-end=\"1168\">Student Registration and LMS Activation</li>\r\n</ol>\r\n<p data-start=\"1170\" data-end=\"1240\">Completing each step carefully ensures a smooth enrollment experience.</p>\r\n<hr data-start=\"1242\" data-end=\"1245\">\r\n<h1 data-section-id=\"52akem\" data-start=\"1247\" data-end=\"1269\">Step 1: Registration</h1>\r\n<p data-start=\"1271\" data-end=\"1342\">The first step is creating an account on the official admission portal.</p>\r\n<p data-start=\"1344\" data-end=\"1375\">Students usually need to enter:</p>\r\n<ul data-start=\"1377\" data-end=\"1458\">\r\n<li data-section-id=\"u7na1o\" data-start=\"1377\" data-end=\"1390\">Full Name</li>\r\n<li data-section-id=\"1dep5uz\" data-start=\"1391\" data-end=\"1408\">Mobile Number</li>\r\n<li data-section-id=\"36fvl5\" data-start=\"1409\" data-end=\"1421\">Email ID</li>\r\n<li data-section-id=\"4ligt3\" data-start=\"1422\" data-end=\"1438\">State / City</li>\r\n<li data-section-id=\"1imjdo9\" data-start=\"1439\" data-end=\"1458\">Preferred Program</li>\r\n</ul>\r\n<p data-start=\"1460\" data-end=\"1520\">After sign-up, pay the initial registration fee to continue.</p>\r\n<h3 data-section-id=\"1my1m11\" data-start=\"1522\" data-end=\"1536\">Expert Tip</h3>\r\n<p data-start=\"1538\" data-end=\"1660\">Use an active email ID and phone number because all important updates, fee receipts, and login credentials are sent there.</p>\r\n<h3 data-section-id=\"10clvjd\" data-start=\"1662\" data-end=\"1689\">Common Mistake to Avoid</h3>\r\n<p data-start=\"1691\" data-end=\"1760\">Wrong contact details may delay communication and admission approval.</p>\r\n<hr data-start=\"1762\" data-end=\"1765\">\r\n<h1 data-section-id=\"1vjt9r3\" data-start=\"1767\" data-end=\"1800\">Step 2: Online Application Form</h1>\r\n<p data-start=\"1802\" data-end=\"1870\">After registration, log in and complete the online application form.</p>\r\n<p data-start=\"1872\" data-end=\"1901\">Students may need to provide:</p>\r\n<ul data-start=\"1903\" data-end=\"2052\">\r\n<li data-section-id=\"1fxsuaa\" data-start=\"1903\" data-end=\"1923\">Personal details</li>\r\n<li data-section-id=\"19byrdb\" data-start=\"1924\" data-end=\"1951\">Academic qualifications</li>\r\n<li data-section-id=\"15di1ss\" data-start=\"1952\" data-end=\"1971\">Address details</li>\r\n<li data-section-id=\"yylsws\" data-start=\"1972\" data-end=\"1993\">Program selection</li>\r\n<li data-section-id=\"1nkv6b6\" data-start=\"1994\" data-end=\"2018\">Identity information</li>\r\n<li data-section-id=\"1e5lq9g\" data-start=\"2019\" data-end=\"2052\">Work experience (if applicable)</li>\r\n</ul>\r\n<p data-start=\"2054\" data-end=\"2127\">After form completion, pay the program fee and upload required documents.</p>\r\n<hr data-start=\"2129\" data-end=\"2132\">\r\n<h1 data-section-id=\"hchuex\" data-start=\"2134\" data-end=\"2177\">Documents Commonly Required for Admission</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2179\" data-end=\"2527\">\r\n<thead data-start=\"2179\" data-end=\"2201\">\r\n<tr data-start=\"2179\" data-end=\"2201\">\r\n<th class=\"\" data-start=\"2179\" data-end=\"2190\" data-col-size=\"sm\">Document</th>\r\n<th class=\"\" data-start=\"2190\" data-end=\"2201\" data-col-size=\"sm\">Purpose</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2212\" data-end=\"2527\">\r\n<tr data-start=\"2212\" data-end=\"2258\">\r\n<td data-start=\"2212\" data-end=\"2233\" data-col-size=\"sm\">Class 10 Marksheet</td>\r\n<td data-col-size=\"sm\" data-start=\"2233\" data-end=\"2258\">Basic academic record</td>\r\n</tr>\r\n<tr data-start=\"2259\" data-end=\"2308\">\r\n<td data-start=\"2259\" data-end=\"2280\" data-col-size=\"sm\">Class 12 Marksheet</td>\r\n<td data-col-size=\"sm\" data-start=\"2280\" data-end=\"2308\">Eligibility verification</td>\r\n</tr>\r\n<tr data-start=\"2309\" data-end=\"2369\">\r\n<td data-start=\"2309\" data-end=\"2346\" data-col-size=\"sm\">Graduation Marksheets (PG courses)</td>\r\n<td data-col-size=\"sm\" data-start=\"2346\" data-end=\"2369\">Qualification proof</td>\r\n</tr>\r\n<tr data-start=\"2370\" data-end=\"2415\">\r\n<td data-start=\"2370\" data-end=\"2391\" data-col-size=\"sm\">Degree Certificate</td>\r\n<td data-col-size=\"sm\" data-start=\"2391\" data-end=\"2415\">Final academic proof</td>\r\n</tr>\r\n<tr data-start=\"2416\" data-end=\"2452\">\r\n<td data-start=\"2416\" data-end=\"2427\" data-col-size=\"sm\">ID Proof</td>\r\n<td data-col-size=\"sm\" data-start=\"2427\" data-end=\"2452\">Identity verification</td>\r\n</tr>\r\n<tr data-start=\"2453\" data-end=\"2494\">\r\n<td data-start=\"2453\" data-end=\"2475\" data-col-size=\"sm\">Passport Size Photo</td>\r\n<td data-start=\"2475\" data-end=\"2494\" data-col-size=\"sm\">Student profile</td>\r\n</tr>\r\n<tr data-start=\"2495\" data-end=\"2527\">\r\n<td data-start=\"2495\" data-end=\"2507\" data-col-size=\"sm\">Signature</td>\r\n<td data-start=\"2507\" data-end=\"2527\" data-col-size=\"sm\">Official records</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"jt31xg\" data-start=\"2529\" data-end=\"2547\">Smart Strategy</h3>\r\n<p data-start=\"2549\" data-end=\"2631\">Keep clear scanned copies ready in PDF/JPG format before starting the application.</p>\r\n<hr data-start=\"2633\" data-end=\"2636\">\r\n<h1 data-section-id=\"ln8rck\" data-start=\"2638\" data-end=\"2683\">Step 3: Document Verification by University</h1>\r\n<p data-start=\"2685\" data-end=\"2773\">After submission, the university reviews the application details and uploaded documents.</p>\r\n<h3 data-section-id=\"131lww1\" data-start=\"2775\" data-end=\"2809\">Verification Usually Includes:</h3>\r\n<ul data-start=\"2811\" data-end=\"2937\">\r\n<li data-section-id=\"v9ifvn\" data-start=\"2811\" data-end=\"2832\">Eligibility check</li>\r\n<li data-section-id=\"1dlv2x\" data-start=\"2833\" data-end=\"2857\">Marksheet validation</li>\r\n<li data-section-id=\"27zx9a\" data-start=\"2858\" data-end=\"2883\">Name and DOB matching</li>\r\n<li data-section-id=\"1qa0omz\" data-start=\"2884\" data-end=\"2912\">Fee payment confirmation</li>\r\n<li data-section-id=\"11cu4zw\" data-start=\"2913\" data-end=\"2937\">Document quality check</li>\r\n</ul>\r\n<p data-start=\"2939\" data-end=\"3030\">If corrections are required, students may receive updates by email or portal notifications.</p>\r\n<h3 data-section-id=\"1mcxn79\" data-start=\"3032\" data-end=\"3060\">Hidden Reasons for Delay</h3>\r\n<p data-start=\"3062\" data-end=\"3098\">Most admission delays happen due to:</p>\r\n<ul data-start=\"3100\" data-end=\"3229\">\r\n<li data-section-id=\"1ax6vdu\" data-start=\"3100\" data-end=\"3119\">Blurred uploads</li>\r\n<li data-section-id=\"1or8hu8\" data-start=\"3120\" data-end=\"3141\">Missing documents</li>\r\n<li data-section-id=\"qew425\" data-start=\"3142\" data-end=\"3168\">Wrong spelling in name</li>\r\n<li data-section-id=\"5d3n7a\" data-start=\"3169\" data-end=\"3199\">Incorrect academic details</li>\r\n<li data-section-id=\"1g5vvd6\" data-start=\"3200\" data-end=\"3229\">Incomplete application form</li>\r\n</ul>\r\n<hr data-start=\"3231\" data-end=\"3234\">\r\n<h1 data-section-id=\"1fuepgv\" data-start=\"3236\" data-end=\"3285\">Step 4: Student Registration and LMS Activation</h1>\r\n<p data-start=\"3287\" data-end=\"3400\">After successful verification, final admission is confirmed. Students then receive LMS credentials through email.</p>\r\n<h3 data-section-id=\"1k7bjc6\" data-start=\"3402\" data-end=\"3431\">Students Usually Receive:</h3>\r\n<ul data-start=\"3433\" data-end=\"3526\">\r\n<li data-section-id=\"el5erz\" data-start=\"3433\" data-end=\"3454\">Enrollment Number</li>\r\n<li data-section-id=\"f73c3w\" data-start=\"3455\" data-end=\"3469\">Student ID</li>\r\n<li data-section-id=\"17cwsxh\" data-start=\"3470\" data-end=\"3497\">LMS Username &amp; Password</li>\r\n<li data-section-id=\"1w9uwii\" data-start=\"3498\" data-end=\"3526\">Course access instructions</li>\r\n</ul>\r\n<h3 data-section-id=\"uttsmo\" data-start=\"3528\" data-end=\"3544\">LMS Benefits</h3>\r\n<p data-start=\"3546\" data-end=\"3599\">The Learning Management System helps students access:</p>\r\n<ul data-start=\"3601\" data-end=\"3702\">\r\n<li data-section-id=\"8imkcm\" data-start=\"3601\" data-end=\"3617\">Live classes</li>\r\n<li data-section-id=\"1d3fguj\" data-start=\"3618\" data-end=\"3639\">Recorded lectures</li>\r\n<li data-section-id=\"12a9mov\" data-start=\"3640\" data-end=\"3659\">Study materials</li>\r\n<li data-section-id=\"1f7qwlk\" data-start=\"3660\" data-end=\"3675\">Assignments</li>\r\n<li data-section-id=\"cq9jk1\" data-start=\"3676\" data-end=\"3687\">Notices</li>\r\n<li data-section-id=\"1ick1y3\" data-start=\"3688\" data-end=\"3702\">Exam updates</li>\r\n</ul>\r\n<hr data-start=\"3704\" data-end=\"3707\">\r\n<h1 data-section-id=\"16c9ce8\" data-start=\"3709\" data-end=\"3740\">Why Early Admission is Better</h1>\r\n<p data-start=\"3742\" data-end=\"3782\">Applying early offers multiple benefits:</p>\r\n<ul data-start=\"3784\" data-end=\"3920\">\r\n<li data-section-id=\"bb1h4j\" data-start=\"3784\" data-end=\"3811\">Faster approval process</li>\r\n<li data-section-id=\"1qim1fu\" data-start=\"3812\" data-end=\"3840\">Better seat availability</li>\r\n<li data-section-id=\"im1sd2\" data-start=\"3841\" data-end=\"3870\">More time for corrections</li>\r\n<li data-section-id=\"n9yjsx\" data-start=\"3871\" data-end=\"3893\">Early class access</li>\r\n<li data-section-id=\"1bezgb6\" data-start=\"3894\" data-end=\"3920\">Smooth academic planning</li>\r\n</ul>', 1, '<p data-start=\"379\" data-end=\"746\">BCA (Bachelor of Computer Applications) is one of the most popular undergraduate programs for students who want careers in software development, web development, data analytics, cybersecurity, cloud computing, and the IT industry. Before applying, students should clearly understand the latest BCA eligibility criteria, accepted qualifications, and admission rules.</p>\r\n<p data-start=\"748\" data-end=\"965\">One of the biggest advantages of BCA is that students from <strong data-start=\"807\" data-end=\"830\">any academic stream</strong> can usually apply. This means commerce, science, arts, and vocational students can all pursue a technology-focused career through BCA.</p>\r\n<p data-start=\"967\" data-end=\"1104\">This detailed guide explains complete BCA eligibility, who can apply, future career value, common mistakes, and smart admission strategy.</p>\r\n<hr data-start=\"1106\" data-end=\"1109\">\r\n<h1 data-section-id=\"81gjrv\" data-start=\"1111\" data-end=\"1146\">BCA Eligibility Criteria Overview</h1>\r\n<p data-start=\"1148\" data-end=\"1237\">Candidates are generally eligible for BCA admission if they meet the following condition:</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1239\" data-end=\"1508\">\r\n<thead data-start=\"1239\" data-end=\"1275\">\r\n<tr data-start=\"1239\" data-end=\"1275\">\r\n<th class=\"\" data-start=\"1239\" data-end=\"1253\" data-col-size=\"md\">Requirement</th>\r\n<th class=\"\" data-start=\"1253\" data-end=\"1275\" data-col-size=\"sm\">Eligibility Status</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1286\" data-end=\"1508\">\r\n<tr data-start=\"1286\" data-end=\"1350\">\r\n<td data-start=\"1286\" data-end=\"1338\" data-col-size=\"md\">Passed 10+2 in any stream from a recognized board</td>\r\n<td data-col-size=\"sm\" data-start=\"1338\" data-end=\"1350\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1351\" data-end=\"1414\">\r\n<td data-start=\"1351\" data-end=\"1395\" data-col-size=\"md\">Appearing for Class 12 (where applicable)</td>\r\n<td data-col-size=\"sm\" data-start=\"1395\" data-end=\"1414\">May be Eligible</td>\r\n</tr>\r\n<tr data-start=\"1415\" data-end=\"1454\">\r\n<td data-start=\"1415\" data-end=\"1442\" data-col-size=\"md\">Equivalent qualification</td>\r\n<td data-col-size=\"sm\" data-start=\"1442\" data-end=\"1454\">Eligible</td>\r\n</tr>\r\n<tr data-start=\"1455\" data-end=\"1508\">\r\n<td data-start=\"1455\" data-end=\"1479\" data-col-size=\"md\">NIOS board candidates</td>\r\n<td data-col-size=\"sm\" data-start=\"1479\" data-end=\"1508\">Eligible (where accepted)</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1510\" data-end=\"1513\">\r\n<h1 data-section-id=\"8hwyk3\" data-start=\"1515\" data-end=\"1556\">Minimum Qualification for BCA Admission</h1>\r\n<p data-start=\"1558\" data-end=\"1667\">Students should have completed <strong data-start=\"1589\" data-end=\"1611\">10+2 in any stream</strong> or an equivalent qualification from a recognized board.</p>\r\n<p data-start=\"1669\" data-end=\"1726\">This means students from the following streams can apply:</p>\r\n<ul data-start=\"1728\" data-end=\"1848\">\r\n<li data-section-id=\"y83j8c\" data-start=\"1728\" data-end=\"1739\">Science</li>\r\n<li data-section-id=\"v4h0lx\" data-start=\"1740\" data-end=\"1752\">Commerce</li>\r\n<li data-section-id=\"nmjua6\" data-start=\"1753\" data-end=\"1774\">Arts / Humanities</li>\r\n<li data-section-id=\"15nt8j1\" data-start=\"1775\" data-end=\"1797\">Vocational streams</li>\r\n<li data-section-id=\"1jg8qus\" data-start=\"1798\" data-end=\"1848\">Other equivalent senior secondary qualifications</li>\r\n</ul>\r\n<h3 data-section-id=\"mkcn1i\" data-start=\"1850\" data-end=\"1865\">Key Benefit</h3>\r\n<p data-start=\"1867\" data-end=\"1955\">Students do not need science or computer background to begin a career in IT through BCA.</p>\r\n<hr data-start=\"1957\" data-end=\"1960\">\r\n<h1 data-section-id=\"1jop22\" data-start=\"1962\" data-end=\"2006\">Can Appearing for Class 12 Students Apply?</h1>\r\n<p data-start=\"2008\" data-end=\"2152\">Many universities allow students who are <strong data-start=\"2049\" data-end=\"2075\">appearing for Class 12</strong> to apply, subject to final result submission within the prescribed timeline.</p>\r\n<p data-start=\"2154\" data-end=\"2223\">Students should verify the latest admission rules during application.</p>\r\n<hr data-start=\"2225\" data-end=\"2228\">\r\n<h1 data-section-id=\"1nhg85t\" data-start=\"2230\" data-end=\"2265\">Are NIOS Board Students Eligible?</h1>\r\n<p data-start=\"2267\" data-end=\"2394\">Yes, <strong data-start=\"2272\" data-end=\"2320\">NIOS board candidates are generally eligible</strong> when the qualification is recognized and accepted under university norms.</p>\r\n<hr data-start=\"2396\" data-end=\"2399\">\r\n<h1 data-section-id=\"1qf1lg9\" data-start=\"2401\" data-end=\"2429\">Why Choose BCA After 12th?</h1>\r\n<p data-start=\"2431\" data-end=\"2534\">BCA gives students an early start in technology education and prepares them for modern digital careers.</p>\r\n<h3 data-section-id=\"1g98jhr\" data-start=\"2536\" data-end=\"2556\">Main Advantages:</h3>\r\n<ul data-start=\"2558\" data-end=\"2795\">\r\n<li data-section-id=\"152lpl4\" data-start=\"2558\" data-end=\"2599\">Learn programming and software basics</li>\r\n<li data-section-id=\"16nlg89\" data-start=\"2600\" data-end=\"2636\">Build IT career foundation early</li>\r\n<li data-section-id=\"1ymus1s\" data-start=\"2637\" data-end=\"2680\">Strong pathway to MCA or higher studies</li>\r\n<li data-section-id=\"1o1db1f\" data-start=\"2681\" data-end=\"2714\">Growing demand in tech sector</li>\r\n<li data-section-id=\"1c49spu\" data-start=\"2715\" data-end=\"2759\">Placement opportunities after graduation</li>\r\n<li data-section-id=\"r3q4le\" data-start=\"2760\" data-end=\"2795\">Startup and freelancing potential</li>\r\n</ul>\r\n<hr data-start=\"2797\" data-end=\"2800\">\r\n<h1 data-section-id=\"gx4e59\" data-start=\"2802\" data-end=\"2826\">Who Should Choose BCA?</h1>\r\n<p data-start=\"2828\" data-end=\"2868\">BCA is ideal for students interested in:</p>\r\n<ul data-start=\"2870\" data-end=\"3021\">\r\n<li data-section-id=\"b8ecgh\" data-start=\"2870\" data-end=\"2898\">Computers and technology</li>\r\n<li data-section-id=\"1rcoh6f\" data-start=\"2899\" data-end=\"2934\">Coding and software development</li>\r\n<li data-section-id=\"15ecpu3\" data-start=\"2935\" data-end=\"2954\">Web development</li>\r\n<li data-section-id=\"1kvym5q\" data-start=\"2955\" data-end=\"2973\">Data analytics</li>\r\n<li data-section-id=\"j9hbe9\" data-start=\"2974\" data-end=\"2991\">Cybersecurity</li>\r\n<li data-section-id=\"sf7wwo\" data-start=\"2992\" data-end=\"3021\">IT careers after graduation</li>\r\n</ul>', '<p data-start=\"352\" data-end=\"704\">Choosing the right BCA program is not only about syllabus and placements. Students should also understand the complete fee structure, payment flexibility, scholarship benefits, and total affordability before taking admission. A clear fee breakdown helps families plan finances, compare universities, and evaluate long-term return on investment (ROI).</p>\r\n<p data-start=\"706\" data-end=\"875\">This detailed guide explains the latest BCA semester fee, discounted payable amount, EMI options, student grant benefits, hidden charges, and smart admission strategies.</p>\r\n<hr data-start=\"877\" data-end=\"880\">\r\n<h1 data-section-id=\"o1fzxf\" data-start=\"882\" data-end=\"900\">BCA Fee Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"902\" data-end=\"1219\">\r\n<thead data-start=\"902\" data-end=\"928\">\r\n<tr data-start=\"902\" data-end=\"928\">\r\n<th class=\"\" data-start=\"902\" data-end=\"918\" data-col-size=\"sm\">Fee Component</th>\r\n<th class=\"\" data-start=\"918\" data-end=\"928\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"940\" data-end=\"1219\">\r\n<tr data-start=\"940\" data-end=\"964\">\r\n<td data-start=\"940\" data-end=\"953\" data-col-size=\"sm\">Actual Fee</td>\r\n<td data-start=\"953\" data-end=\"964\" data-col-size=\"sm\">₹25,000</td>\r\n</tr>\r\n<tr data-start=\"965\" data-end=\"1006\">\r\n<td data-start=\"965\" data-end=\"982\" data-col-size=\"sm\">Applicable Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"982\" data-end=\"1006\">₹20,400 per semester</td>\r\n</tr>\r\n<tr data-start=\"1007\" data-end=\"1030\">\r\n<td data-start=\"1007\" data-end=\"1023\" data-col-size=\"sm\">Student Grant</td>\r\n<td data-col-size=\"sm\" data-start=\"1023\" data-end=\"1030\">20%</td>\r\n</tr>\r\n<tr data-start=\"1031\" data-end=\"1081\">\r\n<td data-start=\"1031\" data-end=\"1058\" data-col-size=\"sm\">Examination Fee Included</td>\r\n<td data-col-size=\"sm\" data-start=\"1058\" data-end=\"1081\">₹2,000 per semester</td>\r\n</tr>\r\n<tr data-start=\"1082\" data-end=\"1128\">\r\n<td data-start=\"1082\" data-end=\"1101\" data-col-size=\"sm\">Registration Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1101\" data-end=\"1128\">₹1,000 (Non-refundable)</td>\r\n</tr>\r\n<tr data-start=\"1129\" data-end=\"1171\">\r\n<td data-start=\"1129\" data-end=\"1145\" data-col-size=\"sm\">Payment Modes</td>\r\n<td data-col-size=\"sm\" data-start=\"1145\" data-end=\"1171\">One-Time Payment / EMI</td>\r\n</tr>\r\n<tr data-start=\"1172\" data-end=\"1219\">\r\n<td data-start=\"1172\" data-end=\"1193\" data-col-size=\"sm\">Payment Preference</td>\r\n<td data-col-size=\"sm\" data-start=\"1193\" data-end=\"1219\">No-Cost EMI / Standard</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1221\" data-end=\"1224\">\r\n<h1 data-section-id=\"1jzhem8\" data-start=\"1226\" data-end=\"1264\">Current Discounted BCA Fee Structure</h1>\r\n<p data-start=\"1266\" data-end=\"1354\">Students can currently avail a <strong data-start=\"1297\" data-end=\"1318\">20% Student Grant</strong>, reducing the regular semester fee.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1356\" data-end=\"1499\">\r\n<thead data-start=\"1356\" data-end=\"1380\">\r\n<tr data-start=\"1356\" data-end=\"1380\">\r\n<th class=\"\" data-start=\"1356\" data-end=\"1370\" data-col-size=\"sm\">Particulars</th>\r\n<th class=\"\" data-start=\"1370\" data-end=\"1380\" data-col-size=\"sm\">Amount</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1392\" data-end=\"1499\">\r\n<tr data-start=\"1392\" data-end=\"1427\">\r\n<td data-start=\"1392\" data-end=\"1416\" data-col-size=\"sm\">Original Semester Fee</td>\r\n<td data-col-size=\"sm\" data-start=\"1416\" data-end=\"1427\">₹25,000</td>\r\n</tr>\r\n<tr data-start=\"1428\" data-end=\"1465\">\r\n<td data-start=\"1428\" data-end=\"1454\" data-col-size=\"sm\">Discounted Semester Fee</td>\r\n<td data-start=\"1454\" data-end=\"1465\" data-col-size=\"sm\">₹20,400</td>\r\n</tr>\r\n<tr data-start=\"1466\" data-end=\"1499\">\r\n<td data-start=\"1466\" data-end=\"1489\" data-col-size=\"sm\">Savings Per Semester</td>\r\n<td data-col-size=\"sm\" data-start=\"1489\" data-end=\"1499\">₹4,600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<p data-start=\"1501\" data-end=\"1577\"><strong data-start=\"1501\" data-end=\"1520\">Offer Validity:</strong> Till <strong data-start=\"1526\" data-end=\"1542\">9th May 2026</strong> (subject to terms and conditions).</p>\r\n<hr data-start=\"1579\" data-end=\"1582\">\r\n<h1 data-section-id=\"1da9b7l\" data-start=\"1584\" data-end=\"1613\">Amount Payable Per Semester</h1>\r\n<h2 data-section-id=\"1vzwcp3\" data-start=\"1615\" data-end=\"1636\">₹20,400 / Semester</h2>\r\n<p data-start=\"1638\" data-end=\"1703\">This is the current applicable semester fee after grant benefits.</p>\r\n<hr data-start=\"1705\" data-end=\"1708\">\r\n<h1 data-section-id=\"18kzs72\" data-start=\"1710\" data-end=\"1741\">Included and Excluded Charges</h1>\r\n<h2 data-section-id=\"c40zw2\" data-start=\"1743\" data-end=\"1770\">Included in Semester Fee</h2>\r\n<ul data-start=\"1772\" data-end=\"1857\">\r\n<li data-section-id=\"dhanzm\" data-start=\"1772\" data-end=\"1814\">Examination fee of ₹2,000 per semester</li>\r\n<li data-section-id=\"10nr766\" data-start=\"1815\" data-end=\"1857\">Academic tuition charges (as applicable)</li>\r\n</ul>\r\n<h2 data-section-id=\"ocwtce\" data-start=\"1859\" data-end=\"1878\">Excluded Charges</h2>\r\n<ul data-start=\"1880\" data-end=\"1974\">\r\n<li data-section-id=\"12c5wuz\" data-start=\"1880\" data-end=\"1935\">Initial registration fee of ₹1,000 (non-refundable)</li>\r\n<li data-section-id=\"3te4rn\" data-start=\"1936\" data-end=\"1974\">Optional charges if applicable later</li>\r\n</ul>\r\n<hr data-start=\"1976\" data-end=\"1979\">\r\n<h1 data-section-id=\"1p7u5zq\" data-start=\"1981\" data-end=\"2014\">Eligible Countries for This Fee</h1>\r\n<p data-start=\"2016\" data-end=\"2064\">The above fee is applicable for applicants from:</p>\r\n<ul data-start=\"2066\" data-end=\"2139\">\r\n<li data-section-id=\"tgrdfn\" data-start=\"2066\" data-end=\"2075\">India</li>\r\n<li data-section-id=\"qjtdvt\" data-start=\"2076\" data-end=\"2089\">Sri Lanka</li>\r\n<li data-section-id=\"yxs3bg\" data-start=\"2090\" data-end=\"2100\">Bhutan</li>\r\n<li data-section-id=\"ef0w72\" data-start=\"2101\" data-end=\"2110\">Nepal</li>\r\n<li data-section-id=\"xi9ghh\" data-start=\"2111\" data-end=\"2125\">Bangladesh</li>\r\n<li data-section-id=\"1woqgfi\" data-start=\"2126\" data-end=\"2139\">Afghanistan</li>\r\n</ul>\r\n<hr data-start=\"2141\" data-end=\"2144\">\r\n<h1 data-section-id=\"x5a8d1\" data-start=\"2146\" data-end=\"2173\">Payment Options Available</h1>\r\n<p data-start=\"2175\" data-end=\"2236\">Students can choose payment options according to convenience.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2238\" data-end=\"2437\">\r\n<thead data-start=\"2238\" data-end=\"2271\">\r\n<tr data-start=\"2238\" data-end=\"2271\">\r\n<th class=\"\" data-start=\"2238\" data-end=\"2255\" data-col-size=\"sm\">Payment Option</th>\r\n<th class=\"\" data-start=\"2255\" data-end=\"2271\" data-col-size=\"sm\">Suitable For</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2282\" data-end=\"2437\">\r\n<tr data-start=\"2282\" data-end=\"2320\">\r\n<td data-start=\"2282\" data-end=\"2296\" data-col-size=\"sm\">No-Cost EMI</td>\r\n<td data-col-size=\"sm\" data-start=\"2296\" data-end=\"2320\">Lower monthly burden</td>\r\n</tr>\r\n<tr data-start=\"2321\" data-end=\"2356\">\r\n<td data-start=\"2321\" data-end=\"2332\" data-col-size=\"sm\">Standard</td>\r\n<td data-col-size=\"sm\" data-start=\"2332\" data-end=\"2356\">Regular payment mode</td>\r\n</tr>\r\n<tr data-start=\"2357\" data-end=\"2401\">\r\n<td data-start=\"2357\" data-end=\"2376\" data-col-size=\"sm\">One-Time Payment</td>\r\n<td data-col-size=\"sm\" data-start=\"2376\" data-end=\"2401\">Faster fee completion</td>\r\n</tr>\r\n<tr data-start=\"2402\" data-end=\"2437\">\r\n<td data-start=\"2402\" data-end=\"2408\" data-col-size=\"sm\">EMI</td>\r\n<td data-col-size=\"sm\" data-start=\"2408\" data-end=\"2437\">Flexible installment plan</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', 'Medium', '<p data-start=\"382\" data-end=\"763\">The BCA (Bachelor of Computer Applications) syllabus is designed to build strong foundations in programming, databases, networking, software development, web technologies, and emerging technologies. It is one of the best undergraduate degrees for students who want careers in software engineering, app development, data analytics, cybersecurity, cloud computing, and IT services.</p>\r\n<p data-start=\"765\" data-end=\"963\">A strong BCA curriculum gradually transforms beginners into industry-ready professionals by combining theory, practical coding, projects, communication skills, electives, and specialization choices.</p>\r\n<p data-start=\"965\" data-end=\"1152\">This detailed semester-wise BCA syllabus helps students understand what they will study, what skills they will gain, and how each semester supports future jobs or higher studies like MCA.</p>\r\n<hr data-start=\"1154\" data-end=\"1157\">\r\n<h1 data-section-id=\"14j74b1\" data-start=\"1159\" data-end=\"1190\">BCA Course Structure Overview</h1>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1192\" data-end=\"1447\">\r\n<thead data-start=\"1192\" data-end=\"1213\">\r\n<tr data-start=\"1192\" data-end=\"1213\">\r\n<th class=\"\" data-start=\"1192\" data-end=\"1199\" data-col-size=\"sm\">Year</th>\r\n<th class=\"\" data-start=\"1199\" data-end=\"1213\" data-col-size=\"md\">Focus Area</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1224\" data-end=\"1447\">\r\n<tr data-start=\"1224\" data-end=\"1297\">\r\n<td data-start=\"1224\" data-end=\"1237\" data-col-size=\"sm\">First Year</td>\r\n<td data-col-size=\"md\" data-start=\"1237\" data-end=\"1297\">Computer fundamentals, programming basics, communication</td>\r\n</tr>\r\n<tr data-start=\"1298\" data-end=\"1376\">\r\n<td data-start=\"1298\" data-end=\"1312\" data-col-size=\"sm\">Second Year</td>\r\n<td data-start=\"1312\" data-end=\"1376\" data-col-size=\"md\">Web development, operating systems, AI, software engineering</td>\r\n</tr>\r\n<tr data-start=\"1377\" data-end=\"1447\">\r\n<td data-start=\"1377\" data-end=\"1390\" data-col-size=\"sm\">Final Year</td>\r\n<td data-start=\"1390\" data-end=\"1447\" data-col-size=\"md\">Specialization, projects, electives, career readiness</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<hr data-start=\"1449\" data-end=\"1452\">\r\n<h1 data-section-id=\"1u7smy7\" data-start=\"1454\" data-end=\"1482\">BCA Semester Wise Syllabus</h1>\r\n<h2 data-section-id=\"3i00xm\" data-start=\"1484\" data-end=\"1527\">Semester 1: IT &amp; Programming Foundations</h2>\r\n<p data-start=\"1529\" data-end=\"1643\">The first semester builds the basic computer science foundation required for future coding and technical subjects.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1645\" data-end=\"1891\">\r\n<thead data-start=\"1645\" data-end=\"1676\">\r\n<tr data-start=\"1645\" data-end=\"1676\">\r\n<th class=\"\" data-start=\"1645\" data-end=\"1660\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"1660\" data-end=\"1676\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1687\" data-end=\"1891\">\r\n<tr data-start=\"1687\" data-end=\"1739\">\r\n<td data-start=\"1687\" data-end=\"1697\" data-col-size=\"sm\">ECAP170</td>\r\n<td data-start=\"1697\" data-end=\"1739\" data-col-size=\"sm\">Fundamentals of Information Technology</td>\r\n</tr>\r\n<tr data-start=\"1740\" data-end=\"1777\">\r\n<td data-start=\"1740\" data-end=\"1750\" data-col-size=\"sm\">ECAP172</td>\r\n<td data-col-size=\"sm\" data-start=\"1750\" data-end=\"1777\">Programming Methodology</td>\r\n</tr>\r\n<tr data-start=\"1778\" data-end=\"1811\">\r\n<td data-start=\"1778\" data-end=\"1788\" data-col-size=\"sm\">EMTH136</td>\r\n<td data-start=\"1788\" data-end=\"1811\" data-col-size=\"sm\">Discrete Structures</td>\r\n</tr>\r\n<tr data-start=\"1812\" data-end=\"1854\">\r\n<td data-start=\"1812\" data-end=\"1822\" data-col-size=\"sm\">EENG139</td>\r\n<td data-col-size=\"sm\" data-start=\"1822\" data-end=\"1854\">English Communication Skills</td>\r\n</tr>\r\n<tr data-start=\"1855\" data-end=\"1891\">\r\n<td data-start=\"1855\" data-end=\"1865\" data-col-size=\"sm\">ECHE110</td>\r\n<td data-col-size=\"sm\" data-start=\"1865\" data-end=\"1891\">Environmental Sciences</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"1893\" data-end=\"1913\">Skills Developed</h3>\r\n<ul data-start=\"1915\" data-end=\"2033\">\r\n<li data-section-id=\"d35oli\" data-start=\"1915\" data-end=\"1934\">Computer basics</li>\r\n<li data-section-id=\"1tee75c\" data-start=\"1935\" data-end=\"1953\">Logic building</li>\r\n<li data-section-id=\"16plaoj\" data-start=\"1954\" data-end=\"1983\">Intro programming mindset</li>\r\n<li data-section-id=\"1hb0syu\" data-start=\"1984\" data-end=\"2010\">Mathematical reasoning</li>\r\n<li data-section-id=\"qc877u\" data-start=\"2011\" data-end=\"2033\">Communication skills</li>\r\n</ul>\r\n<hr data-start=\"2035\" data-end=\"2038\">\r\n<h2 data-section-id=\"d8klyh\" data-start=\"2040\" data-end=\"2076\">Semester 2: Core Computer Systems</h2>\r\n<p data-start=\"2078\" data-end=\"2175\">Students move into databases, object-oriented programming, networking, and hardware architecture.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2177\" data-end=\"2429\">\r\n<thead data-start=\"2177\" data-end=\"2208\">\r\n<tr data-start=\"2177\" data-end=\"2208\">\r\n<th class=\"\" data-start=\"2177\" data-end=\"2192\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2192\" data-end=\"2208\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2219\" data-end=\"2429\">\r\n<tr data-start=\"2219\" data-end=\"2260\">\r\n<td data-start=\"2219\" data-end=\"2229\" data-col-size=\"sm\">ECAP200</td>\r\n<td data-col-size=\"sm\" data-start=\"2229\" data-end=\"2260\">Database Management Systems</td>\r\n</tr>\r\n<tr data-start=\"2261\" data-end=\"2302\">\r\n<td data-start=\"2261\" data-end=\"2271\" data-col-size=\"sm\">ECAP202</td>\r\n<td data-col-size=\"sm\" data-start=\"2271\" data-end=\"2302\">Object Oriented Programming</td>\r\n</tr>\r\n<tr data-start=\"2303\" data-end=\"2334\">\r\n<td data-start=\"2303\" data-end=\"2313\" data-col-size=\"sm\">ECAP256</td>\r\n<td data-col-size=\"sm\" data-start=\"2313\" data-end=\"2334\">Computer Networks</td>\r\n</tr>\r\n<tr data-start=\"2335\" data-end=\"2377\">\r\n<td data-start=\"2335\" data-end=\"2345\" data-col-size=\"sm\">ECAP268</td>\r\n<td data-col-size=\"sm\" data-start=\"2345\" data-end=\"2377\">Computer System Architecture</td>\r\n</tr>\r\n<tr data-start=\"2378\" data-end=\"2429\">\r\n<td data-start=\"2378\" data-end=\"2388\" data-col-size=\"sm\">EENG140</td>\r\n<td data-start=\"2388\" data-end=\"2429\" data-col-size=\"sm\">Advanced English Communication Skills</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"7zaalc\" data-start=\"2431\" data-end=\"2460\">Why This Semester Matters</h3>\r\n<p data-start=\"2462\" data-end=\"2539\">These subjects are highly valuable for software development and IT job roles.</p>\r\n<hr data-start=\"2541\" data-end=\"2544\">\r\n<h2 data-section-id=\"19c1amk\" data-start=\"2546\" data-end=\"2596\">Semester 3: Web Development &amp; Operating Systems</h2>\r\n<p data-start=\"2598\" data-end=\"2709\">This semester introduces web programming, data structures, operating systems, and practical development skills.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"2711\" data-end=\"2955\">\r\n<thead data-start=\"2711\" data-end=\"2742\">\r\n<tr data-start=\"2711\" data-end=\"2742\">\r\n<th class=\"\" data-start=\"2711\" data-end=\"2726\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"2726\" data-end=\"2742\" data-col-size=\"md\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"2753\" data-end=\"2955\">\r\n<tr data-start=\"2753\" data-end=\"2798\">\r\n<td data-start=\"2753\" data-end=\"2763\" data-col-size=\"sm\">ECAP214</td>\r\n<td data-col-size=\"md\" data-start=\"2763\" data-end=\"2798\">Fundamentals of Web Programming</td>\r\n</tr>\r\n<tr data-start=\"2799\" data-end=\"2828\">\r\n<td data-start=\"2799\" data-end=\"2809\" data-col-size=\"sm\">ECAP267</td>\r\n<td data-col-size=\"md\" data-start=\"2809\" data-end=\"2828\">Data Structures</td>\r\n</tr>\r\n<tr data-start=\"2829\" data-end=\"2894\">\r\n<td data-start=\"2829\" data-end=\"2839\" data-col-size=\"sm\">ECAP462</td>\r\n<td data-col-size=\"md\" data-start=\"2839\" data-end=\"2894\">Community Development Project / EPES201 Soft Skills</td>\r\n</tr>\r\n<tr data-start=\"2895\" data-end=\"2925\">\r\n<td data-start=\"2895\" data-end=\"2905\" data-col-size=\"sm\">ECAP560</td>\r\n<td data-start=\"2905\" data-end=\"2925\" data-col-size=\"md\">Operating System</td>\r\n</tr>\r\n<tr data-start=\"2926\" data-end=\"2955\">\r\n<td data-start=\"2926\" data-end=\"2933\" data-col-size=\"sm\">GE-I</td>\r\n<td data-col-size=\"md\" data-start=\"2933\" data-end=\"2955\">Generic Elective I</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1ejbzus\" data-start=\"2957\" data-end=\"2977\">Skills Developed</h3>\r\n<ul data-start=\"2979\" data-end=\"3090\">\r\n<li data-section-id=\"3a4u2b\" data-start=\"2979\" data-end=\"3006\">Website creation basics</li>\r\n<li data-section-id=\"10xrbfj\" data-start=\"3007\" data-end=\"3038\">Efficient coding structures</li>\r\n<li data-section-id=\"19sbv49\" data-start=\"3039\" data-end=\"3063\">System understanding</li>\r\n<li data-section-id=\"tcxddf\" data-start=\"3064\" data-end=\"3090\">Teamwork and soft skills</li>\r\n</ul>\r\n<hr data-start=\"3092\" data-end=\"3095\">\r\n<h2 data-section-id=\"ar6xie\" data-start=\"3097\" data-end=\"3158\">Semester 4: Software Engineering &amp; Artificial Intelligence</h2>\r\n<p data-start=\"3160\" data-end=\"3214\">Students enter modern and advanced areas of computing.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3216\" data-end=\"3444\">\r\n<thead data-start=\"3216\" data-end=\"3247\">\r\n<tr data-start=\"3216\" data-end=\"3247\">\r\n<th class=\"\" data-start=\"3216\" data-end=\"3231\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3231\" data-end=\"3247\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3258\" data-end=\"3444\">\r\n<tr data-start=\"3258\" data-end=\"3292\">\r\n<td data-start=\"3258\" data-end=\"3268\" data-col-size=\"sm\">ECAP509</td>\r\n<td data-start=\"3268\" data-end=\"3292\" data-col-size=\"sm\">Software Engineering</td>\r\n</tr>\r\n<tr data-start=\"3293\" data-end=\"3330\">\r\n<td data-start=\"3293\" data-end=\"3303\" data-col-size=\"sm\">ECAP653</td>\r\n<td data-col-size=\"sm\" data-start=\"3303\" data-end=\"3330\">Artificial Intelligence</td>\r\n</tr>\r\n<tr data-start=\"3331\" data-end=\"3373\">\r\n<td data-start=\"3331\" data-end=\"3339\" data-col-size=\"sm\">DSE-I</td>\r\n<td data-col-size=\"sm\" data-start=\"3339\" data-end=\"3373\">Discipline Specific Elective I</td>\r\n</tr>\r\n<tr data-start=\"3374\" data-end=\"3412\">\r\n<td data-start=\"3374\" data-end=\"3382\" data-col-size=\"sm\">SEC-I</td>\r\n<td data-start=\"3382\" data-end=\"3412\" data-col-size=\"sm\">Skill Enhancement Course I</td>\r\n</tr>\r\n<tr data-start=\"3413\" data-end=\"3444\">\r\n<td data-start=\"3413\" data-end=\"3421\" data-col-size=\"sm\">GE-II</td>\r\n<td data-col-size=\"sm\" data-start=\"3421\" data-end=\"3444\">Generic Elective II</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"6gal4w\" data-start=\"3446\" data-end=\"3476\">Why Semester 4 is Powerful</h3>\r\n<p data-start=\"3478\" data-end=\"3542\">AI and software engineering greatly increase industry relevance.</p>\r\n<hr data-start=\"3544\" data-end=\"3547\">\r\n<h2 data-section-id=\"d4e16y\" data-start=\"3549\" data-end=\"3599\">Semester 5: Practical Learning &amp; Specialization</h2>\r\n<p data-start=\"3601\" data-end=\"3679\">This semester focuses on electives, skill courses, and field project exposure.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"3681\" data-end=\"3940\">\r\n<thead data-start=\"3681\" data-end=\"3712\">\r\n<tr data-start=\"3681\" data-end=\"3712\">\r\n<th class=\"\" data-start=\"3681\" data-end=\"3696\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"3696\" data-end=\"3712\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"3723\" data-end=\"3940\">\r\n<tr data-start=\"3723\" data-end=\"3767\">\r\n<td data-start=\"3723\" data-end=\"3732\" data-col-size=\"sm\">DSE-II</td>\r\n<td data-start=\"3732\" data-end=\"3767\" data-col-size=\"sm\">Discipline Specific Elective II</td>\r\n</tr>\r\n<tr data-start=\"3768\" data-end=\"3814\">\r\n<td data-start=\"3768\" data-end=\"3778\" data-col-size=\"sm\">DSE-III</td>\r\n<td data-col-size=\"sm\" data-start=\"3778\" data-end=\"3814\">Discipline Specific Elective III</td>\r\n</tr>\r\n<tr data-start=\"3815\" data-end=\"3855\">\r\n<td data-start=\"3815\" data-end=\"3824\" data-col-size=\"sm\">SEC-II</td>\r\n<td data-col-size=\"sm\" data-start=\"3824\" data-end=\"3855\">Skill Enhancement Course II</td>\r\n</tr>\r\n<tr data-start=\"3856\" data-end=\"3889\">\r\n<td data-start=\"3856\" data-end=\"3865\" data-col-size=\"sm\">GE-III</td>\r\n<td data-col-size=\"sm\" data-start=\"3865\" data-end=\"3889\">Generic Elective III</td>\r\n</tr>\r\n<tr data-start=\"3890\" data-end=\"3940\">\r\n<td data-start=\"3890\" data-end=\"3900\" data-col-size=\"sm\">ECAP463</td>\r\n<td data-col-size=\"sm\" data-start=\"3900\" data-end=\"3940\">Field Project / Alternate GE Courses</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1l6ceg0\" data-start=\"3942\" data-end=\"3970\">Importance of Semester 5</h3>\r\n<p data-start=\"3972\" data-end=\"4036\">Projects often become your placement interview discussion point.</p>\r\n<hr data-start=\"4038\" data-end=\"4041\">\r\n<h2 data-section-id=\"5k4ij4\" data-start=\"4043\" data-end=\"4082\">Semester 6: Final Career Preparation</h2>\r\n<p data-start=\"4084\" data-end=\"4186\">The final semester focuses on advanced electives, employability skills, and research/application work.</p>\r\n<div class=\"TyagGW_tableContainer\">\r\n<div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"4188\" data-end=\"4451\">\r\n<thead data-start=\"4188\" data-end=\"4219\">\r\n<tr data-start=\"4188\" data-end=\"4219\">\r\n<th class=\"\" data-start=\"4188\" data-end=\"4203\" data-col-size=\"sm\">Subject Code</th>\r\n<th class=\"\" data-start=\"4203\" data-end=\"4219\" data-col-size=\"sm\">Subject Name</th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"4230\" data-end=\"4451\">\r\n<tr data-start=\"4230\" data-end=\"4274\">\r\n<td data-start=\"4230\" data-end=\"4239\" data-col-size=\"sm\">DSE-IV</td>\r\n<td data-start=\"4239\" data-end=\"4274\" data-col-size=\"sm\">Discipline Specific Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4275\" data-end=\"4317\">\r\n<td data-start=\"4275\" data-end=\"4285\" data-col-size=\"sm\">SEC-III</td>\r\n<td data-col-size=\"sm\" data-start=\"4285\" data-end=\"4317\">Skill Enhancement Course III</td>\r\n</tr>\r\n<tr data-start=\"4318\" data-end=\"4358\">\r\n<td data-start=\"4318\" data-end=\"4327\" data-col-size=\"sm\">SEC-IV</td>\r\n<td data-start=\"4327\" data-end=\"4358\" data-col-size=\"sm\">Skill Enhancement Course IV</td>\r\n</tr>\r\n<tr data-start=\"4359\" data-end=\"4404\">\r\n<td data-start=\"4359\" data-end=\"4381\" data-col-size=\"sm\">Generic Elective IV</td>\r\n<td data-col-size=\"sm\" data-start=\"4381\" data-end=\"4404\">Generic Elective IV</td>\r\n</tr>\r\n<tr data-start=\"4405\" data-end=\"4451\">\r\n<td data-start=\"4405\" data-end=\"4415\" data-col-size=\"sm\">ECAP464</td>\r\n<td data-start=\"4415\" data-end=\"4451\" data-col-size=\"sm\">Term Paper / Alternate GE Course</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<h3 data-section-id=\"1clpjtf\" data-start=\"4453\" data-end=\"4479\">Final Semester Benefit</h3>\r\n<p data-start=\"4481\" data-end=\"4569\">Students become job-ready with projects, specialization knowledge, and practical skills.</p>', NULL, '<p data-start=\"390\" data-end=\"658\">Placement support is one of the most important factors students consider before choosing a BCA program. Since BCA is a career-focused technology degree, students expect not only academics but also real job opportunities, industry exposure, and employability support.</p>\r\n<p data-start=\"660\" data-end=\"945\"><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Lovely Professional University</span></span> Online offers placement support services designed to enhance students&rsquo; capabilities according to career requirements, create awareness about professional opportunities, and motivate learners to develop add-on skills beyond their academic subjects.</p>\r\n<p data-start=\"947\" data-end=\"1117\">Through placement drives and career initiatives, students can interact with recruiters, showcase their skills, and compete for promising IT and business technology roles.</p>\r\n<p data-start=\"1119\" data-end=\"1262\">This guide explains BCA placement support, LPU Online career services, ROI value, career opportunities, and how students can maximize outcomes.</p>\r\n<hr data-start=\"1264\" data-end=\"1267\">\r\n<h1 data-section-id=\"yvls4v\" data-start=\"1269\" data-end=\"1317\">Why Placement Support Matters for BCA Students</h1>\r\n<p data-start=\"1319\" data-end=\"1356\">BCA students often target careers in:</p>\r\n<ul data-start=\"1358\" data-end=\"1495\">\r\n<li data-section-id=\"1mac9zo\" data-start=\"1358\" data-end=\"1382\">Software development</li>\r\n<li data-section-id=\"15ecpu3\" data-start=\"1383\" data-end=\"1402\">Web development</li>\r\n<li data-section-id=\"ls6n5m\" data-start=\"1403\" data-end=\"1417\">IT support</li>\r\n<li data-section-id=\"1kvym5q\" data-start=\"1418\" data-end=\"1436\">Data analytics</li>\r\n<li data-section-id=\"j9hbe9\" data-start=\"1437\" data-end=\"1454\">Cybersecurity</li>\r\n<li data-section-id=\"1nx8gmu\" data-start=\"1455\" data-end=\"1472\">Cloud support</li>\r\n<li data-section-id=\"tsvs9p\" data-start=\"1473\" data-end=\"1495\">Technical operations</li>\r\n</ul>\r\n<p data-start=\"1497\" data-end=\"1563\">However, recruiters usually look beyond degrees. They also assess:</p>\r\n<ul data-start=\"1565\" data-end=\"1691\">\r\n<li data-section-id=\"1tlq536\" data-start=\"1565\" data-end=\"1582\">Coding skills</li>\r\n<li data-section-id=\"tfxkh3\" data-start=\"1583\" data-end=\"1610\">Problem solving ability</li>\r\n<li data-section-id=\"1mfo8p6\" data-start=\"1611\" data-end=\"1635\">Communication skills</li>\r\n<li data-section-id=\"1onq25j\" data-start=\"1636\" data-end=\"1657\">Project portfolio</li>\r\n<li data-section-id=\"yojgng\" data-start=\"1658\" data-end=\"1672\">Confidence</li>\r\n<li data-section-id=\"18igtp4\" data-start=\"1673\" data-end=\"1691\">Teamwork mindset</li>\r\n</ul>\r\n<p data-start=\"1693\" data-end=\"1785\">Placement support helps students bridge the gap between academics and industry expectations.</p>\r\n<hr data-start=\"1787\" data-end=\"1790\">\r\n<h1 data-section-id=\"tw2pgo\" data-start=\"1792\" data-end=\"1835\">LPU Online BCA Placement Support Services</h1>\r\n<h2 data-section-id=\"18k74lo\" data-start=\"1837\" data-end=\"1859\">1. Placement Drives</h2>\r\n<p data-start=\"1861\" data-end=\"1946\">Placement drives help students connect directly with hiring companies and recruiters.</p>\r\n<h3 data-section-id=\"1iaul7c\" data-start=\"1948\" data-end=\"1961\">Benefits:</h3>\r\n<ul data-start=\"1963\" data-end=\"2102\">\r\n<li data-section-id=\"1rrxafr\" data-start=\"1963\" data-end=\"1989\">Access to job openings</li>\r\n<li data-section-id=\"6ji9pn\" data-start=\"1990\" data-end=\"2015\">Recruiter interaction</li>\r\n<li data-section-id=\"gsbjid\" data-start=\"2016\" data-end=\"2045\">Real interview experience</li>\r\n<li data-section-id=\"1or2gyq\" data-start=\"2046\" data-end=\"2075\">Better placement exposure</li>\r\n<li data-section-id=\"1w9y0p5\" data-start=\"2076\" data-end=\"2102\">Networking opportunities</li>\r\n</ul>\r\n<hr data-start=\"2104\" data-end=\"2107\">\r\n<h2 data-section-id=\"zmp5s0\" data-start=\"2109\" data-end=\"2142\">2. Career Guidance &amp; Awareness</h2>\r\n<p data-start=\"2144\" data-end=\"2260\">Many students know computers but are unclear about career direction. Placement support can help students understand:</p>\r\n<ul data-start=\"2262\" data-end=\"2402\">\r\n<li data-section-id=\"5zq2lo\" data-start=\"2262\" data-end=\"2290\">Best job roles after BCA</li>\r\n<li data-section-id=\"lxzzts\" data-start=\"2291\" data-end=\"2320\">Skill demand in IT market</li>\r\n<li data-section-id=\"1lfq7n7\" data-start=\"2321\" data-end=\"2344\">Salary growth paths</li>\r\n<li data-section-id=\"13g78ty\" data-start=\"2345\" data-end=\"2378\">Future study options like MCA</li>\r\n<li data-section-id=\"1vmie03\" data-start=\"2379\" data-end=\"2402\">Industry expectations</li>\r\n</ul>\r\n<hr data-start=\"2404\" data-end=\"2407\">\r\n<h2 data-section-id=\"eyxhxz\" data-start=\"2409\" data-end=\"2439\">3. Add-On Skill Development</h2>\r\n<p data-start=\"2441\" data-end=\"2559\">Modern tech hiring depends heavily on practical skills. Students are encouraged to develop extra capabilities such as:</p>\r\n<ul data-start=\"2561\" data-end=\"2685\">\r\n<li data-section-id=\"1srenkl\" data-start=\"2561\" data-end=\"2578\">Python basics</li>\r\n<li data-section-id=\"1wsinul\" data-start=\"2579\" data-end=\"2594\">Java basics</li>\r\n<li data-section-id=\"177lgg6\" data-start=\"2595\" data-end=\"2602\">SQL</li>\r\n<li data-section-id=\"c2867\" data-start=\"2603\" data-end=\"2612\">Excel</li>\r\n<li data-section-id=\"1mfo8p6\" data-start=\"2613\" data-end=\"2637\">Communication skills</li>\r\n<li data-section-id=\"1hrlil9\" data-start=\"2638\" data-end=\"2662\">Aptitude preparation</li>\r\n<li data-section-id=\"yr6r51\" data-start=\"2663\" data-end=\"2685\">Interview confidence</li>\r\n</ul>\r\n<hr data-start=\"2687\" data-end=\"2690\">\r\n<h2 data-section-id=\"1anskog\" data-start=\"2692\" data-end=\"2728\">4. Resume &amp; Interview Preparation</h2>\r\n<p data-start=\"2730\" data-end=\"2794\">Students often need help presenting their skills professionally.</p>\r\n<h3 data-section-id=\"5f2soq\" data-start=\"2796\" data-end=\"2820\">Support May Include:</h3>\r\n<ul data-start=\"2822\" data-end=\"2945\">\r\n<li data-section-id=\"1ewtugo\" data-start=\"2822\" data-end=\"2841\">Resume creation</li>\r\n<li data-section-id=\"hg8gpk\" data-start=\"2842\" data-end=\"2861\">Mock interviews</li>\r\n<li data-section-id=\"1uf9y5l\" data-start=\"2862\" data-end=\"2886\">HR round preparation</li>\r\n<li data-section-id=\"sbvqbf\" data-start=\"2887\" data-end=\"2917\">Technical interview basics</li>\r\n<li data-section-id=\"1a5ayoc\" data-start=\"2918\" data-end=\"2945\">Group discussion practice</li>\r\n</ul>\r\n<hr data-start=\"2947\" data-end=\"2950\">\r\n<h1 data-section-id=\"bq2d1e\" data-start=\"2952\" data-end=\"2978\">Best Job Roles After BCA</h1>\r\n<p data-start=\"2980\" data-end=\"3062\">Depending on student skills, projects, and performance, opportunities may include:</p>\r\n<ul data-start=\"3064\" data-end=\"3451\">\r\n<li data-section-id=\"jlmvw3\" data-start=\"3064\" data-end=\"3124\"><strong data-start=\"3066\" data-end=\"3088\">Software Developer</strong> &ndash; Builds applications and systems</li>\r\n<li data-section-id=\"1f8mtla\" data-start=\"3125\" data-end=\"3177\"><strong data-start=\"3127\" data-end=\"3144\">Web Developer</strong> &ndash; Creates websites and portals</li>\r\n<li data-section-id=\"fi46k2\" data-start=\"3178\" data-end=\"3232\"><strong data-start=\"3180\" data-end=\"3211\">Technical Support Executive</strong> &ndash; IT support roles</li>\r\n<li data-section-id=\"t6fh04\" data-start=\"3233\" data-end=\"3275\"><strong data-start=\"3235\" data-end=\"3248\">QA Tester</strong> &ndash; Software testing roles</li>\r\n<li data-section-id=\"188z031\" data-start=\"3276\" data-end=\"3333\"><strong data-start=\"3278\" data-end=\"3308\">Data Analyst (Entry Level)</strong> &ndash; Data reporting roles</li>\r\n<li data-section-id=\"q4rnxk\" data-start=\"3334\" data-end=\"3390\"><strong data-start=\"3336\" data-end=\"3363\">Cybersecurity Associate</strong> &ndash; Security support roles</li>\r\n<li data-section-id=\"1388brv\" data-start=\"3391\" data-end=\"3451\"><strong data-start=\"3393\" data-end=\"3420\">Cloud Support Associate</strong> &ndash; Basic cloud operations roles</li>\r\n</ul>', NULL, NULL, NULL, NULL, NULL, 4.0, NULL, NULL, '[\"1\"]', 100000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '0', '0', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, NULL, 0, 0, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, NULL);
